// ── PORTRAIT SETUP MODAL ─────────────────────────────────────────────────────
// Minimal modal for setting up couple portrait (avatars + initials).
function PortraitSetup({ userName, partnerName, existing, onSave, onClose }) {
  const [p1Init, setP1Init] = useState(existing?.p1?.initial || (userName?.[0] || "A"));
  const [p2Init, setP2Init] = useState(existing?.p2?.initial || (partnerName?.[0] || "B"));
  const COLORS = ["#E8673A","#9B5DE5","#1B5FE8","#10b981","#F59E0B","#EC4899"];
  const [p1Color, setP1Color] = useState(existing?.p1?.color || COLORS[0]);
  const [p2Color, setP2Color] = useState(existing?.p2?.color || COLORS[1]);

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", zIndex: 9999, display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem" }} onClick={onClose}>
      <div onClick={e => e.stopPropagation()} style={{ background: "white", borderRadius: 20, padding: "2rem", maxWidth: 400, width: "100%", fontFamily: "'DM Sans', sans-serif" }}>
        <h3 style={{ fontSize: "1.1rem", fontWeight: 700, color: "#1C1C1E", marginBottom: "1.5rem" }}>Your couple portrait</h3>
        {[{name: userName, init: p1Init, setInit: setP1Init, color: p1Color, setColor: setP1Color},
          {name: partnerName, init: p2Init, setInit: setP2Init, color: p2Color, setColor: setP2Color}].map((p, i) => (
          <div key={i} style={{ marginBottom: "1.25rem" }}>
            <div style={{ fontSize: "0.72rem", letterSpacing: "0.08em", textTransform: "uppercase", color: "#999", marginBottom: "0.5rem" }}>{p.name}</div>
            <div style={{ display: "flex", alignItems: "center", gap: "1rem" }}>
              <div style={{ width: 44, height: 44, borderRadius: "50%", background: p.color, display: "flex", alignItems: "center", justifyContent: "center", color: "white", fontSize: "1.2rem", fontWeight: 700 }}>{(p.init || "?")[0].toUpperCase()}</div>
              <div style={{ display: "flex", gap: "0.4rem", flexWrap: "wrap" }}>
                {COLORS.map(c => <div key={c} onClick={() => p.setColor(c)} style={{ width: 20, height: 20, borderRadius: "50%", background: c, cursor: "pointer", outline: p.color === c ? "3px solid " + c : "none", outlineOffset: 2 }} />)}
              </div>
            </div>
          </div>
        ))}
        <div style={{ display: "flex", gap: "0.75rem", marginTop: "1.5rem" }}>
          <button onClick={onClose} style={{ flex: 1, padding: "0.65rem", borderRadius: 10, border: "1.5px solid #E5E2DC", background: "transparent", cursor: "pointer", fontSize: "0.85rem" }}>Cancel</button>
          <button onClick={() => { onSave({ p1: { initial: p1Init, color: p1Color }, p2: { initial: p2Init, color: p2Color } }); onClose(); }} style={{ flex: 1, padding: "0.65rem", borderRadius: 10, border: "none", background: "linear-gradient(135deg,#E8673A,#1B5FE8)", color: "white", cursor: "pointer", fontWeight: 600, fontSize: "0.85rem" }}>Save</button>
        </div>
      </div>
    </div>
  );
}



// ── DIM SHIFT TEXT ─────────────────────────────────────────────────────────
// 15 unique "One shift that helps" responses per dimension,
// based on where each partner scores (5 buckets × 5 buckets = 15 unordered combos).
// pos: 0=strongly A, 1=lean A, 2=middle, 3=lean B, 4=strongly B

// alignedAdvice and getDimShift moved to api/_lib/dimension-copy.js so the
// app can render the same words. Imported at the top of this file.



// ── EXPECTATIONS CATEGORY CONVO STARTERS (by couple type) ────────────────────
// One conversation starter / "what to keep in mind" per category per couple type.
// 10 types × 5 categories = 50 unique prompts.
const EXP_CAT_STARTERS = EXP_CAT_STARTERS_SHARED;


// ── EXPECTATIONS EXERCISE DATA CONSTANTS ────────────────────────────────────

// Moved to api/_questions.js so /api/questions can serve the same options.


// Substitute partner-name placeholders in expectation question / item labels.
// The Extended Family responsibility items and Life & Values per-family
// questions both reference each partner's family using {userName} and
// {partnerName} placeholders. Storage keys are stable (placeholders kept
// raw); only display strings are substituted at render time.
// substName moved to api/_questions.js, imported above.

// Extended-family responsibility items and the two "involvement" life questions
// are person-relative: each partner answers about THEIR OWN family under the
// {userName} key and the OTHER partner's family under the {partnerName} key. So a
// partner's answer about "my family" is stored under their {partnerName} key.
// When reading the PARTNER's answer we swap the placeholders so both align to the
// same real family. Identity for every non-family key / id (they have no
// placeholders), so this is safe to apply to every partner-answer read.
// mirrorRespKey and mirrorLifeId now come from api/_lib/expectations.js, which
// is also where the app gets them. Imported at the top of this file.

// RESPONSIBILITY_CATEGORIES now lives in api/_questions.js (single source of truth).

// FIXED_CATS is the same structure — used for sidebar navigation in results
// Options arrays mirror the source-of-truth in scripts/_expectations_variants.mjs
// LIFE_QUESTIONS now lives in api/_questions.js (single source of truth).


// The six display categories for Expectations results, from api/_questions.js.
//
// This was built here, and api/_lib/results-sections.js built the section
// registry from RESPONSIBILITY_CATEGORIES, which is five. So this nav offered
// exp-convo-5 for Life & Values and that section did not exist, which is why
// the link fell through to the storycards. One list now, and the app gets the
// page it never had.
const FIXED_CATS = EXPECTATIONS_CATEGORIES;

// Revisited version (same questions — could be extended later)
const LIFE_QUESTIONS_REVISITED = LIFE_QUESTIONS;

// Anniversary version — same core questions for returning couples
const LIFE_QUESTIONS_ANNIVERSARY = LIFE_QUESTIONS;


// ── DIMENSION SCORING ────────────────────────────────────────────────────────
// Maps ex1Answers to named average scores per dimension.
// Question counts per dimension are uneven; listening has 1 (flagged for
// methodology review with the LMFT). avg returns 3 (neutral) when no answers
// are present so partial completion still produces a usable score, and
// `valenceUnknown` flag is set on the result so callers can surface that
// the score is low-confidence.
function calcDimScores(answers) {
  if (!answers) return {};
  // Mirrors calcDimScores in api/_type-engine.js. Questions inside a dimension
  // are weighted by QUESTION_WEIGHTS there, imported here rather than restated
  // so the two cannot drift: that duplication is what let the admin dashboard
  // and the results pages disagree in the past.
  //
  // st1's a/b display order is reversed vs its dimension orientation, so it
  // options run withdraw->seek, so both are flipped (6 - v).
  const FLIPPED = new Set(['st1']);
  const score = (dim, ...keys) => {
    const w = QUESTION_WEIGHTS[dim] || null;
    const parts = keys
      .map(k => {
        const raw = answers[k];
        if (raw == null || isNaN(raw)) return null;
        const v = FLIPPED.has(k) ? (6 - Number(raw)) : Number(raw);
        return { v, w: w ? (w[k] ?? 0) : 1 };
      })
      .filter(x => x != null && !isNaN(x.v));
    // Renormalise over what was actually answered, so a partly answered
    // dimension stays on the right scale.
    const totalW = parts.reduce((s, x) => s + x.w, 0);
    // 3 (neutral) when nothing is answered, matching the previous behaviour of
    // this mirror. The engine returns null; this one is used for display where
    // a position is always needed.
    return (parts.length && totalW > 0)
      ? parts.reduce((s, x) => s + x.v * x.w, 0) / totalW
      : 3;
  };
  return {
    energy:      score('energy', 'en4', 'en6'),
    expression:  score('expression', 'ex6', 'ex7', 'ex8'),
    reassurance: score('reassurance', 'rs1', 'rs3'),
    love:        score('love', 'lv1', 'lv2'),
    bids:        score('bids', 'bd1', 'bd3', 'bd4'),
    needs:       score('needs', 'nd1', 'nd5'),
    conflict:    score('conflict', 'cf1', 'cf2', 'cf3', 'st1'),
    repair:      score('repair', 'rp2', 'rp3', 'rp6'),
    feedback:    score('feedback', 'fb2', 'fb5'),
    listening:   score('listening', 'ls1', 'ls3'),
  };
}

// ── WORKBOOK PAYLOAD BUILDER ────────────────────────────────────────────────
// Builds the full payload for /api/generate-workbook. Centralizes the data
// contract so both auto-fulfill (post-checkout) and manual-download
// (dashboard) call sites use identical shapes. Phase 5a: adds responsibility
// items and full life-question data alongside the existing legacy expGaps
// for backward compatibility with older renderers.
//
// Inputs:
//   userName, partnerName       - strings
//   ex1Answers, partnerEx1      - dim score answers (raw 1-5 by question id)
//   ex2Answers, partnerEx2      - { responsibilities: {...}, life: {...} }
//   coupleType                  - couple type object or null
//
// Output: payload ready to JSON.stringify and POST.
// Expectations similarity scoring moved to api/_lib/expectations-alignment.js.
// It used to be mirrored here, with a comment asking whoever changed one copy
// to remember the other. Imported at the top of this file.



// ── PERSONALITY FEEDBACK GENERATOR ──────────────────────────────────────────
// Produces one feedback object per dimension comparing two score objects.
function generatePersonalityFeedback(myS, partS, userName, partnerName, content) {
  // Was a third hand-written list, in a third order. Everything downstream
  // re-sorts for display, so the order here never mattered and the set always
  // did.
  const dims = DIMENSION_DISPLAY_ORDER;
  return dims.map(dim => {
    const myScore   = myS[dim]   ?? 3;
    const partScore = partS[dim] ?? 3;
    const gap = Math.abs(myScore - partScore);
    const isStrength    = gap <= 0.75;
    const isNote        = gap > 0.75 && gap <= 1.5;
    const isOpportunity = gap > 1.5;
    const meta = DIM_META[dim] || { label: dim, color: "#9B5DE5", ends: ["—","—"] };
    const myEnd   = myScore   < 3 ? (meta.ends?.[0] ?? "one way") : (meta.ends?.[1] ?? "another way");
    const partEnd = partScore < 3 ? (meta.ends?.[0] ?? "one way") : (meta.ends?.[1] ?? "another way");
    const isSame  = myEnd === partEnd;
    return {
      dim,
      gap,
      myScore,
      partScore,
      isStrength,
      isNote,
      isOpportunity,
      strengthText: (isStrength || isNote)
        ? (isSame
          ? `You and ${partnerName} both tend toward the ${myEnd.toLowerCase()} end of ${meta.label.toLowerCase()}.`
          : `Even with slightly different scores, you and ${partnerName} navigate ${meta.label.toLowerCase()} in compatible ways.`)
        : null,
      insightText: isOpportunity
        ? `${userName} tends ${myEnd.toLowerCase()} while ${partnerName} tends ${partEnd.toLowerCase()} on ${meta.label.toLowerCase()}.`
        : isNote
        ? `You're close but not identical here, ${meta.label.toLowerCase()} shows a small but real difference.`
        : null,
      adviceText: (isOpportunity || isNote)
        ? getDimShift(dim, myScore, partScore, userName, partnerName, content)
        : null,
    };
  });
}

/**
 * The page anything opens on: a results chapter, or an exercise.
 *
 * ── WHY ONE COMPONENT ─────────────────────────────────────────────────────
 * Ellie: "Mirror cover pages for exercises and results on both web and app."
 *
 * The app draws both from one CoverPage. This is its counterpart, so the
 * website is not a second opinion about what a cover looks like: a gradient
 * rule around a cream card, the chapter's mark over a glow, and whatever the
 * page puts under it.
 *
 * The glow is many faint rings rather than one translucent disc, which is what
 * Ellie asked for after seeing the first attempt: "can we make the glow more
 * subtle, like a tint that disperses gently? Right now it looks like a circle."
 * A radial gradient is the browser's version of the app's stack of rings.
 *
 * Every word on it comes from a caller, and every caller takes its words from a
 * module both surfaces read. Nothing here is copy.
 */
function CoverCard({ accent, icon = "\u25C9", children, minHeight = "min(72vh, 620px)" }) {
  return (
    <div style={{ borderRadius: 26, padding: 1.5, background: "linear-gradient(135deg, #E8673A, #9B5DE5, #1B5FE8)" }}>
      <div style={{
        borderRadius: 25, background: C.cream, minHeight,
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        padding: "3rem 2rem", textAlign: "center",
      }}>
        <div style={{
          width: 132, height: 132, borderRadius: "50%", display: "flex",
          alignItems: "center", justifyContent: "center", marginBottom: "1.75rem", flexShrink: 0,
          background: `radial-gradient(circle, ${accent}22 0%, ${accent}14 35%, ${accent}08 55%, transparent 72%)`,
        }}>
          <span style={{ fontSize: "3.2rem", color: accent, lineHeight: 1 }}>{icon}</span>
        </div>
        {children}
      </div>
    </div>
  );
}

/**
 * An exercise's opening page, which is a cover with the exercise's own words in
 * it. The words are api/_lib/exercise-intro.js, which is what the app is served
 * through /api/questions, so the two surfaces open an exercise identically.
 */
function ExerciseCover({ accent, eyebrow, intro, onBegin }) {
  return (
    <div style={{ maxWidth: 560, margin: "0 auto", padding: "1.5rem 1rem 2rem" }}>
      <link href={FONT_LINK} rel="stylesheet" />
      <CoverCard accent={accent}>
        {eyebrow ? (
          <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: accent, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.75rem" }}>{eyebrow}</div>
        ) : null}
        <h2 style={{ fontFamily: HFONT, fontSize: "clamp(1.5rem, 4vw, 2rem)", fontWeight: 700, color: C.ink, lineHeight: 1.2, margin: 0, maxWidth: 420 }}>{intro.title}</h2>
        {intro.body.map(para => (
          <p key={para.slice(0, 24)} style={{ fontSize: "0.9rem", color: C.muted, fontFamily: BFONT, fontWeight: 300, lineHeight: 1.7, marginTop: "1.25rem", marginBottom: 0, maxWidth: 420 }}>
            {para}
          </p>
        ))}
        {intro.note ? (
          <p style={{ fontSize: "0.78rem", color: C.muted, fontFamily: BFONT, lineHeight: 1.6, marginTop: "1.5rem", marginBottom: 0, maxWidth: 420 }}>{intro.note}</p>
        ) : null}
        <button onClick={onBegin}
          style={{ marginTop: "2.25rem", background: accent, color: "white", border: "none", borderRadius: 999, padding: "0.85rem 2.25rem", fontSize: "0.8rem", fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase", fontFamily: BFONT, cursor: "pointer" }}>
          {intro.cta}
        </button>
      </CoverCard>
    </div>
  );
}

/**
 * The app's tab bar, along the top of the dashboard.
 *
 * ── WHY THE SITE HAS ONE NOW ──────────────────────────────────────────────
 * Ellie: "Maybe we mirror the app on the site, and have the site's dashboard
 * use the app's bottom nav as the top toolbar, and have every page be exactly
 * mirrored... That way we lose no content and updates to either site or web are
 * easy to make."
 *
 * That is the argument this codebase is built on: one set of decisions rather
 * than two. The dashboard was three numbered steps, a spine the app does not
 * have, so every change to either surface had to be translated first. It is
 * these four now, in the app's order, and the steps are gone at her word: "yes,
 * it replaces the step 1, 2, 3 spine".
 *
 * Nothing was dropped. The exercises are Insights, the results card is Home the
 * way the app shows it, the tools and the reading are Learn, and Notes was a
 * page here that nothing linked to.
 *
 * ── WHAT IS DELIBERATELY NOT MIRRORED ─────────────────────────────────────
 * The exercises keep their own layouts and Insights keeps its left nav, both
 * because she said so. A phone has one column and a laptop does not, and
 * copying that would be mirroring the constraint rather than the design.
 *
 * At the top rather than the bottom, because a thumb is not the input here.
 */
const DASH_TABS = [
  { id: "home", label: "Home" },
  { id: "insights", label: "Insights" },
  { id: "learn", label: "Learn" },
  { id: "notes", label: "Notes" },
];

function DashTabs({ active, onChange, isMobile }) {
  return (
    <div style={{
      display: "flex", gap: isMobile ? "0.25rem" : "0.5rem", padding: "0.35rem",
      background: "rgba(255,255,255,0.10)", border: "1px solid rgba(255,255,255,0.18)",
      borderRadius: 999, marginBottom: 0, width: "fit-content",
    }}>
      {DASH_TABS.map((t) => {
        const on = active === t.id;
        return (
          <button key={t.id} onClick={() => onChange(t.id)}
            aria-current={on ? "page" : undefined}
            style={{
              background: on ? "rgba(255,255,255,0.92)" : "transparent",
              color: on ? "#1E1A35" : "rgba(255,255,255,0.82)",
              border: "none", borderRadius: 999,
              padding: isMobile ? "0.5rem 0.8rem" : "0.55rem 1.15rem",
              fontFamily: BFONT, fontSize: isMobile ? "0.72rem" : "0.78rem",
              fontWeight: 700, cursor: "pointer", whiteSpace: "nowrap",
              transition: "background .15s, color .15s",
            }}>
            {t.label}
          </button>
        );
      })}
    </div>
  );
}

/**
 * The app's Home, on the website.
 *
 * ── WHAT "MIRROR" MEANT ───────────────────────────────────────────────────
 * Ellie: "I want the site pages to mirror the app pages with regards to
 * content, formatting, and everything else. You can adapt the size of the
 * content to better-fit a website, but I want the content and look and feel to
 * be exactly the same."
 *
 * The first attempt moved the site's existing blocks behind a tab bar, which
 * mirrored the navigation and nothing else. Her answer was "This is terrible",
 * and she was right: the sections were the app's names over the website's
 * screens.
 *
 * So this is the app's screen. The blue ground with cream holding past halfway,
 * the greeting as the page's own line, four square links, and two prompt cards
 * on a cream panel. The only thing adapted is width: the links are a row of
 * four rather than a wrapped grid, and the cards sit side by side with room to
 * breathe, because a laptop is not a phone. Nothing is added and nothing is
 * left out.
 *
 * The greeting and the two cards come from /api/home, the same payload and the
 * same priority engine the app draws. See homeFeed above.
 */
/**
 * The app's Learn tab, lower half: the sheet that lifts over the ground.
 *
 * ── WHY IT IS SHAPED LIKE THIS ────────────────────────────────────────────
 * Ellie: "Can the learn page have the layout/design of the image with the
 * books, with a gradient page bg that lists the resources and the insight, then
 * what looks like a tab pulling up over the page down below with the in
 * practice articles?"
 *
 * So the reading is not a section of the page, it is a panel coming up over it:
 * a large radius on the top two corners only, full width, and no bottom at all,
 * because in the reference it runs off the end of the screen rather than
 * finishing. The grab line is what says it lifts.
 *
 * Her words for the inside of it, which the app follows and this now does too:
 * the two pills are Saved and Read, the heading is In Practice, the line under
 * it is Featured publications, and "Featured publications should be grey tiles".
 * The search box says "Search articles" in grey that disappears once you type.
 *
 * ── WHAT WAS HERE BEFORE ──────────────────────────────────────────────────
 * A small caps eyebrow reading "From In Practice" and a grid of translucent
 * tiles on the blue. Same twelve articles, so the inventory check passed, and
 * nothing about it looked like the app. Ellie: "neither is content or layout."
 */
/**
 * The Insights tab's menu, as the app draws it.
 *
 * ── WHAT WAS WRONG ────────────────────────────────────────────────────────
 * Ellie: "Menu looks bad, doesn't look like app screen at all. this bg is full
 * bleed and the menu doesn't have the icons or indents. Also, clicked on menu
 * items and everything took me to the storycards."
 *
 * The last one first, because it was a real break: the rows opened
 * `group.id`, and a group id is not a page. `comm`, `exp`, `reflection`,
 * `intimacy` and `conflict` are headings over pages called `comm-cover`,
 * `comm-overview` and so on, so every one of them failed validation and fell
 * back to Highlights. The app opens `children[0]`, which is the section's cover
 * page, and so does this now.
 *
 * ── THE SHAPE, WHICH IS ALL HERS ──────────────────────────────────────────
 * "Can we please remove hairline dividers, put a bullet to the left of
 * highlights, couple type, exercise results, and what comes next." So those
 * four carry a bullet and sit on the page's own left edge.
 *
 * "I want exercise results title to be listed left-aligned with highlights and
 * couple type, and I want the content in that section indented further right
 * than that." So the five exercises step in by the width of the bullet column.
 *
 * "Maybe only the exercises have icons?" So they do, and nothing else does.
 *
 * "the tiles on landing page should just be shaded lightly with the attune
 * gradient but the icon should match the color of the exercise." The colour is
 * in the icon and nowhere else.
 *
 * The three measurements are computed from one number here for the reason the
 * app's menu gives: they were 24 + 24 + 16 written out in four places and the
 * heading ended up on a different left edge from the two names it matches.
 */
const NAV_ICON_COL = 24;
const NAV_GAP = 16;
/* The caret's column. Fixed, so the arrows line up down the menu and every
   label ends at the same place whether its section has pages or not. */
const NAV_CARET_COL = 28;

/** Only the exercises, the way the app has it. Keyed by the server's group id. */
const NAV_ICONS = {
  /* Ellie: "re-draw the icons to match the icons on the menu in the app."
     The app uses SF Symbols: bubble.left.and.bubble.right, brain, book, heart
     and arrow.triangle.branch. These are those five, drawn at one weight with
     round caps and joins, which is what makes a set look like SF Symbols
     rather than like five icons from five places. */
  comm: (c, size = 21) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M2.8 7.2a2.4 2.4 0 0 1 2.4-2.4h7.2a2.4 2.4 0 0 1 2.4 2.4v3.2a2.4 2.4 0 0 1-2.4 2.4H7.6l-3.2 2.4v-2.5a2.4 2.4 0 0 1-1.6-2.3z" />
      <path d="M17.2 9.6h1.6a2.4 2.4 0 0 1 2.4 2.4v3.2a2.4 2.4 0 0 1-1.6 2.3v2.5l-3.2-2.4h-4.8a2.4 2.4 0 0 1-2.3-1.7" />
    </svg>
  ),
  exp: (c, size = 21) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M12 5.4a2.7 2.7 0 0 0-4.8-.5A2.5 2.5 0 0 0 4.4 8a2.6 2.6 0 0 0-.5 4 2.6 2.6 0 0 0 .9 3.9 2.7 2.7 0 0 0 3.3 2.6 2.6 2.6 0 0 0 3.9-1.3Z" />
      <path d="M12 5.4a2.7 2.7 0 0 1 4.8-.5A2.5 2.5 0 0 1 19.6 8a2.6 2.6 0 0 1 .5 4 2.6 2.6 0 0 1-.9 3.9 2.7 2.7 0 0 1-3.3 2.6 2.6 2.6 0 0 1-3.9-1.3Z" />
      <path d="M12 5.4v12.8" />
    </svg>
  ),
  reflection: (c, size = 21) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M12 6.8C10.4 5.3 8.2 4.6 5.4 4.8A1.2 1.2 0 0 0 4.3 6v10.3a1.2 1.2 0 0 0 1.3 1.2c2.5-.2 4.6.4 6.4 1.7" />
      <path d="M12 6.8c1.6-1.5 3.8-2.2 6.6-2a1.2 1.2 0 0 1 1.1 1.2v10.3a1.2 1.2 0 0 1-1.3 1.2c-2.5-.2-4.6.4-6.4 1.7" />
      <path d="M12 6.8v12.4" />
    </svg>
  ),
  intimacy: (c, size = 21) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M12 20.3S3.8 15.1 3.8 9.6a4.4 4.4 0 0 1 8.2-2.3 4.4 4.4 0 0 1 8.2 2.3c0 5.5-8.2 10.7-8.2 10.7Z" />
    </svg>
  ),
  conflict: (c, size = 21) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M12 21v-6.6" />
      <path d="M12 14.4 6.2 8.6V4.4" />
      <path d="m12 14.4 5.8-5.8V4.4" />
      <path d="M3.6 6.8 6.2 4.2l2.6 2.6" />
      <path d="M15.2 6.8l2.6-2.6 2.6 2.6" />
    </svg>
  ),
};

function AppInsightsMenu({ groups, isMobile, onOpen, eyebrow }) {
  /**
   * Which group is open, if any.
   *
   * ── THE ARROW PROMISED SOMETHING NOBODY BUILT ───────────────────────────
   * Ellie: "Dropdown arrows on site's insights menu don't work." They did not:
   * the caret was aria-hidden decoration inside the row's own button, so it
   * looked like a disclosure and behaved like part of the label.
   *
   * Every one of these groups has pages under it. Communication has four,
   * Expectations has seven, and before this the only way to reach one was to
   * open the section and page through. The caret is what it looked like now.
   *
   * One at a time: this is a list of eight, and two open at once on a phone
   * pushes the rest off the panel.
   */
  const [openGroup, setOpenGroup] = useState(null);
  /* Shared out over whatever height the panel has. See the panel's own note. */
  const LABEL_LEFT = 0;
  /**
   * Ellie: "further indent the exercise results rows (with their icon and
   * title)". The icon moves with the title rather than staying in a column of
   * its own, which is what "with their icon" is asking for: the whole row steps
   * in, not just the words.
   */
  const EXERCISE_LEFT = NAV_ICON_COL + NAV_GAP * 2;

  /**
   * No bullet, and no column where one was.
   *
   * Ellie: "remove the bullet points from the insights menu". She asked for
   * them in the app a while back and has changed her mind here; the app keeps
   * its own. The spacer goes with them, because a column held open for a dot
   * that is not drawn is the indent she then has to ask me to remove.
   */

  return (
    <div style={{
      flex: 1, minHeight: 0, display: "flex", flexDirection: "column",
      justifyContent: "space-between",
    }}>
      {groups.map((g, i) => {
        const kids = g.children || [];
        const icon = NAV_ICONS[g.id];
        const isExercise = Boolean(icon);
        const firstExercise = isExercise && !NAV_ICONS[groups[i - 1]?.id];
        return (
          <div key={g.id}>
            {firstExercise ? (
              <div style={{
                display: "flex", alignItems: "center", gap: NAV_GAP,
                paddingTop: isMobile ? "1rem" : "1.25rem", paddingBottom: "0.35rem",
                paddingLeft: LABEL_LEFT,
              }}>
                <span style={{
                  fontSize: "0.58rem", letterSpacing: "0.22em", textTransform: "uppercase",
                  color: "#A66534", fontWeight: 700, fontFamily: BFONT,
                }}>
                  {eyebrow}
                </span>
              </div>
            ) : null}
            {/* ── THE CARET SITS ON ITS OWN ROW, NOT OVER THE GROUP ────────
                Ellie: "arrows are not evenly spaced, comms doesn't line up with
                it's row the same way the others do."

                It was absolutely positioned against the group's box, and a
                group's box is not a row: Communication is the first exercise so
                it carries the "Exercise results" eyebrow, and an open group
                carries its children. Centring on that box put the caret
                somewhere different on every row, and furthest off on the one
                row with a heading above it.

                A flex row instead. The label takes the space, the caret takes a
                fixed column, and a group with no pages holds that column open
                so every label ends at the same place and the carets line up. */}
            <div style={{ display: "flex", alignItems: "center" }}>
            <button
              onClick={() => onOpen(kids.length ? kids[0].id : g.id)}
              aria-label={g.label}
              style={{
                display: "flex", alignItems: "center", gap: NAV_GAP, flex: 1, minWidth: 0,
                background: "transparent", border: "none", cursor: "pointer",
                textAlign: "left", fontFamily: HFONT, color: C.ink,
                paddingTop: isExercise ? "0.45rem" : "0.5rem",
                paddingBottom: isExercise ? "0.45rem" : "0.5rem",
                minHeight: 0, flexShrink: 1,
                paddingLeft: isExercise ? EXERCISE_LEFT : LABEL_LEFT,
                paddingRight: 0,
              }}>
              {isExercise ? (
                <span aria-hidden="true" style={{
                  width: NAV_ICON_COL, display: "inline-flex", alignItems: "center",
                  justifyContent: "flex-start", flexShrink: 0,
                }}>
                  {icon(g.color || "#E8673A")}
                </span>
              ) : null}
              <span style={{
                flex: 1,
                fontSize: isExercise
                  ? (isMobile ? "1rem" : "1.1rem")
                  : (isMobile ? "1.2rem" : "1.35rem"),
                fontWeight: 700, lineHeight: 1.2, letterSpacing: "-0.01em",
              }}>
                {g.label}
              </span>
            </button>
            {/* The caret is its own control. Inside the row's button it could
                only ever do what the row does, which is why it did nothing. */}
            {kids.length ? (
              <button
                type="button"
                onClick={() => setOpenGroup((cur) => (cur === g.id ? null : g.id))}
                aria-expanded={openGroup === g.id}
                aria-label={`${openGroup === g.id ? "Hide" : "Show"} the pages under ${g.label}`}
                style={{
                  width: NAV_CARET_COL, flexShrink: 0,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  background: "transparent", border: "none", cursor: "pointer",
                  color: "#A8997F", fontSize: "0.68rem", lineHeight: 1, padding: 0,
                  transform: openGroup === g.id ? "rotate(180deg)" : "none",
                  transformOrigin: "center",
                }}>
                &#9662;
              </button>
            ) : (
              /* The column stays open so every label ends in the same place. */
              <span aria-hidden="true" style={{ width: NAV_CARET_COL, flexShrink: 0 }} />
            )}
            </div>
            {openGroup === g.id ? (
              /* The pages under this section, each opening its own. The cover
                 is left out: it is what the row itself opens. */
              <div style={{ paddingLeft: (isExercise ? EXERCISE_LEFT : LABEL_LEFT) + NAV_ICON_COL + NAV_GAP, paddingBottom: "0.35rem" }}>
                {kids.filter((ch) => !ch.cover).map((ch) => (
                  <button
                    key={ch.id}
                    type="button"
                    onClick={() => onOpen(ch.id)}
                    style={{
                      display: "block", width: "100%", textAlign: "left",
                      background: "transparent", border: "none", cursor: "pointer",
                      fontFamily: BFONT, color: C.muted, fontSize: isMobile ? "0.82rem" : "0.88rem",
                      padding: "0.3rem 0", lineHeight: 1.3,
                    }}>
                    {ch.label}
                  </button>
                ))}
              </div>
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

/**
 * Exported so a browser check can measure it.
 *
 * The Learn tab is inside the signed-in dashboard, so the peek it reports is
 * the one number on that page nothing could verify: the insight above it is
 * sized from it, and Ellie has reported the insight cut off or the peek cut off
 * three times. check-learn-peek mounts this with the real article list and
 * measures what it says its head is against what the head actually comes to.
 */
/**
 * The three colours the app's In Practice card is set in.
 *
 * TILE_GREY is the featured tile's ground, mutedInk is the meta line under a
 * title and orange is the accent the minutes are set in. They are hex here
 * because they come from attune-theme.ts and the website cannot import a .ts
 * out of attune-app: that is what broke the Vercel deploy for two commits.
 * check-card-tints holds all three to the app's own values.
 */
const TILE_GREY = "#EFECE7";
const MUTED_INK = "#7A6753";
const ACCENT = "#E8673A";

/**
 * ── AN ARTICLE, READ WITHOUT LEAVING YOUR ACCOUNT ─────────────────────────
 * Ellie: "When I am in my learn tab and click an article, I don't want it to
 * sign the user out of their account."
 *
 * Nothing was signing anyone out. Measured in a browser: a visit to a static In
 * Practice page and back leaves every `sb-` and `attune_` key in place. What
 * happened is that the tile was a link to /practice/<slug>, which is a
 * marketing page with the marketing nav on it, so one tap left the dashboard,
 * dropped the signed-in chrome and offered "Sign in" in the corner. It reads as
 * being signed out because everything that says you are signed in is gone.
 *
 * The app has read these in-app since its bodies were generated. This is the
 * same bodies, drawn here, so Learn keeps you where you are. The link still
 * works as a link: a middle click or a new tab opens the public page, which is
 * what a reader expects of an article and what search engines follow.
 */
function LearnArticle({ article, isMobile, onBack }) {
  const body = IN_PRACTICE_BODIES[article.slug] || null;
  const H = { fontFamily: HFONT, color: C.ink };
  return (
    <div style={{ maxWidth: 680, margin: "0 auto", paddingBottom: "3rem" }}>
      <button
        type="button"
        onClick={onBack}
        style={{
          display: "inline-flex", alignItems: "center", gap: "0.45rem",
          background: "transparent", border: "none", padding: "0.25rem 0",
          cursor: "pointer", fontFamily: BFONT, fontSize: "0.78rem",
          fontWeight: 700, color: C.clay, marginBottom: "1.25rem",
        }}>
        &larr; In Practice
      </button>
      <h1 style={{ ...H, fontWeight: 700, fontSize: isMobile ? "1.6rem" : "2.1rem", lineHeight: 1.12, letterSpacing: "-0.02em", margin: 0 }}>
        {body?.pageTitle || article.title}
      </h1>
      {article.readMinutes ? (
        <p style={{ fontFamily: BFONT, fontSize: "0.78rem", color: ACCENT, margin: "0.5rem 0 0" }}>
          {`${article.readMinutes} min read`}
        </p>
      ) : null}
      {body?.intro ? (
        <p style={{ fontFamily: BFONT, fontSize: isMobile ? "0.96rem" : "1.02rem", lineHeight: 1.65, color: C.ink, margin: "1.25rem 0 0" }}>
          {body.intro}
        </p>
      ) : null}
      {/* The four shapes api/_in-practice-bodies.js generates. An unknown
          block is drawn as a paragraph rather than dropped: a reader losing a
          sentence is worse than one reading it in the wrong size. */}
      {(body?.blocks || []).map((b) => {
        if (b.type === "heading") {
          return (
            <h2 key={b.id} style={{ ...H, fontWeight: 700, fontSize: isMobile ? "1.15rem" : "1.3rem", lineHeight: 1.25, margin: "2rem 0 0.6rem" }}>
              {b.text}
            </h2>
          );
        }
        if (b.type === "quote") {
          return (
            <blockquote key={b.id} style={{ margin: "1.5rem 0", paddingLeft: "1.1rem", borderLeft: `3px solid ${C.clay}` }}>
              <p style={{ fontFamily: HFONT, fontSize: isMobile ? "1.05rem" : "1.18rem", lineHeight: 1.5, color: C.ink, margin: 0 }}>
                {b.text}
              </p>
              {b.source ? (
                <p style={{ fontFamily: BFONT, fontSize: "0.78rem", color: MUTED_INK, margin: "0.5rem 0 0" }}>{b.source}</p>
              ) : null}
            </blockquote>
          );
        }
        if (b.type === "prompt") {
          return (
            /* The block's own label, and nothing when it has none. The first
               version printed "Try this" over every one of these, which put
               five identical eyebrows in a row on one article and invented a
               label the product does not use. The app draws `block.label` and
               says in its own note that the website does too; fourteen of these
               blocks carry one, and the rest are callouts with no heading.
               `source` is drawn for the same reason: a claim that cites its
               work loses the citation if only the sentence is taken. */
            <div key={b.id} style={{ margin: "1.5rem 0", background: "#F7F2EA", borderRadius: 14, padding: "1rem 1.1rem", borderLeft: `4px solid ${C.clay}` }}>
              {b.label ? (
                <div style={{ fontFamily: BFONT, fontSize: "0.56rem", letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 700, color: C.clay, marginBottom: "0.4rem" }}>
                  {b.label}
                </div>
              ) : null}
              <p style={{ fontFamily: BFONT, fontSize: "0.95rem", lineHeight: 1.6, color: C.ink, margin: 0 }}>{b.text}</p>
              {b.source ? (
                <p style={{ fontFamily: BFONT, fontSize: "0.76rem", fontStyle: "italic", color: MUTED_INK, margin: "0.5rem 0 0" }}>{b.source}</p>
              ) : null}
            </div>
          );
        }
        return (
          <p key={b.id} style={{ fontFamily: BFONT, fontSize: isMobile ? "0.96rem" : "1.02rem", lineHeight: 1.7, color: C.ink, margin: "1rem 0 0" }}>
            {b.text}
          </p>
        );
      })}
      {!body ? (
        <p style={{ fontFamily: BFONT, fontSize: "0.92rem", lineHeight: 1.6, color: MUTED_INK, marginTop: "1.5rem" }}>
          This one opens on the site.{" "}
          <a href={article.path} style={{ color: ACCENT }}>Read it there</a>.
        </p>
      ) : null}
    </div>
  );
}

export function AppLearnReading({
  articles, isMobile, savedCount, readCount, onPeek,
  /**
   * What this reader has saved and read, by slug, and how to change it.
   *
   * Ellie: "I want the site's in practice to look exactly like the app's... the
   * app uses different font colors and has more text indicating whether
   * something's been read."
   *
   * The app has had both since In Practice shipped, from /api/posts, which
   * answers with `saved` and `read` per piece for the reader asking. This
   * surface passed zero for both counts and drew neither, so nothing on the
   * website had ever said whether you had read something.
   *
   * Defaulted so the component still mounts on its own, which is how
   * check-learn-peek measures it without an account.
   */
  state = null, onToggleSave = null, onOpenArticle = null,
}) {
  const [query, setQuery] = useState("");
  /**
   * The head: the grab line, the two pills, the heading, the line under it and
   * the search box. Everything below is meant to be off the screen until
   * someone scrolls, which is what "peek" means on the app's Learn tab.
   *
   * Measured rather than assumed, and re-measured when the window changes,
   * because the heading wraps at narrow widths and a peek computed from a
   * number would be wrong on exactly the screens where it matters.
   */
  const headRef = useRef(null);
  useEffect(() => {
    const el = headRef.current;
    if (!el || !onPeek) return undefined;
    /* The grab line and the padding above it are part of what shows, so they
       are part of the peek: the app adds GRAB_LINE_H and a spacing unit to its
       own measured head for the same reason. Measured from the sheet's top
       rather than added as a number. */
    const report = () => {
      const sheet = el.closest('[data-block="app-learn/reading"]');
      const top = sheet ? sheet.getBoundingClientRect().top : el.getBoundingClientRect().top;
      onPeek(Math.round(el.getBoundingClientRect().bottom - top));
    };
    report();
    if (typeof ResizeObserver === "undefined") return undefined;
    const ro = new ResizeObserver(report);
    ro.observe(el);
    return () => ro.disconnect();
  }, [onPeek]);
  const q = query.trim().toLowerCase();
  const shown = q
    ? articles.filter((a) => `${a.title} ${shelfFor(a)}`.toLowerCase().includes(q))
    : articles;

  /**
   * The shelves, in the order POST_CATEGORIES gives them, each with what is on
   * it. Derived from shelfFor rather than from a label on the article, which is
   * the same call /api/posts makes for the app.
   */
  const shelves = (() => {
    const byShelf = new Map();
    for (const a of shown.slice(4)) {
      const shelf = shelfFor(a);
      if (!byShelf.has(shelf)) byShelf.set(shelf, []);
      byShelf.get(shelf).push(a);
    }
    return POST_CATEGORIES.filter((c) => byShelf.has(c)).map((c) => [c, byShelf.get(c)]);
  })();

  /** Where this piece stands with this reader, if the feed has arrived. */
  const stateOf = (slug) => (state && state[slug]) || null;

  /**
   * The bookmark, which is the same control in both places the app draws it.
   *
   * Filled and in the accent when saved, outlined and quiet when not. It was an
   * outline that never changed and was not a button, so the website had a
   * drawing of the app's control rather than the control.
   */
  const bookmark = (a, size, pos) => {
    const saved = !!stateOf(a.slug)?.saved;
    return (
      <button
        type="button"
        aria-pressed={saved}
        aria-label={saved ? `Remove ${a.title} from saved` : `Save ${a.title}`}
        onClick={(e) => { e.preventDefault(); e.stopPropagation(); if (onToggleSave) onToggleSave(a); }}
        disabled={!onToggleSave}
        style={{
          position: "absolute", ...pos, padding: 4, lineHeight: 0,
          background: pos.round ? "rgba(255,253,249,0.92)" : "transparent",
          border: "none", borderRadius: pos.round ? "50%" : 6,
          width: pos.round ? 30 : undefined, height: pos.round ? 30 : undefined,
          display: "flex", alignItems: "center", justifyContent: "center",
          cursor: onToggleSave ? "pointer" : "default",
        }}>
        <svg width={size} height={size} viewBox="0 0 24 24"
          fill={saved ? ACCENT : "none"} stroke={saved ? ACCENT : "#A8937B"}
          strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M6 3h12a1 1 0 0 1 1 1v17l-7-4-7 4V4a1 1 0 0 1 1-1z" />
        </svg>
      </button>
    );
  };

  /**
   * ── THE FOUR FEATURED, AS THE APP DRAWS THEM ──────────────────────────
   * Grey, not tinted. Ellie, of the app: "Featured publications should be grey
   * tiles not colored. The shelves' colours are on the full cards below, where
   * they mean which shelf; four of them in a grid up here was a palette rather
   * than a signal."
   *
   * And the title sits at the FOOT of the tile, not the head: "Sneak peek
   * article tiles should fit the full name of the article, not cut them off",
   * so the tile is sized by its title rather than the title cut to the tile.
   * The website had the title at the top in 12.8pt at normal weight; the app
   * sets it at 11 over 14, bold, bottom aligned, with no minutes under it.
   */
  const featured = (a) => (
    <a key={a.slug} href={a.path}
      onClick={(e) => { if (!onOpenArticle) return; e.preventDefault(); onOpenArticle(a); }}
      style={{
      display: "flex", flexDirection: "column", justifyContent: "flex-end",
      /* ── AND SMALLER, BECAUSE THESE ARE THE PEEK ───────────────────
         Ellie: "these tiles feel too big." These four are also the tallest
         part of the sheet's head, and the head IS the peek, so every point
         here is a point off the quotation's budget on the page above. At 88,
         matching the app's, the peek came to 216 and there was not enough room
         left on a laptop to set the insight at any size the floor allows. The
         app does not pay that because it has no 250 point banner over it. */
      background: TILE_GREY, borderRadius: 14, padding: "0.5rem",
      textDecoration: "none", position: "relative", minHeight: 54,
    }}>
      {bookmark(a, 15, { top: 4, right: 4 })}
      <span style={{
        display: "block", fontFamily: BFONT, fontSize: 11, lineHeight: "14px",
        fontWeight: 700, color: C.ink, paddingRight: "1.1rem",
      }}>
        {a.title}
      </span>
    </a>
  );

  /**
   * ── ONE ARTICLE, AS A CARD ────────────────────────────────────────────
   * The app's PostCard, which Ellie asked for with the Natural Cycles app
   * open: "I want articles to have a little image like the natural cycles
   * app... I like that natural cycles has a little 'article' box on the image."
   *
   * So: a white card lifted off the ground, an illustration box carrying the
   * label and the bookmark, the title held to two lines, and how long it takes.
   * The website drew a flat grey rectangle 66 tall with the title and the
   * minutes in it, which is none of that.
   *
   * The ground is the shelf's tint, from lib/card-tints.js, which is the same
   * module the app reads so the two cannot paint one shelf two colours.
   */
  const tile = (a) => {
    const st = stateOf(a.slug);
    const ground = cardGround(a.heroColor || null, POST_CATEGORIES.indexOf(shelfFor(a)));
    return (
      <a
        key={a.slug}
        href={a.path}
        /* preventDefault only when there is somewhere in-dashboard to open it.
           Mounted on its own, as the gates do, the link still navigates. */
        onClick={(e) => { if (!onOpenArticle) return; e.preventDefault(); onOpenArticle(a); }}
        style={{
          /* ── THE WHOLE TILE IS SHADED ────────────────────────────────
             Ellie: "the shading behind each tile needs to not have a hard
             cutoff at the margins, it looks weird. Just shade the tile."

             It was a 132 point band of the shelf's tint across the top with
             white under it, which is the app's card, where the band is an
             illustration box waiting for illustrations. On a row of small
             tiles it read as a stripe that stopped dead rather than as a
             picture. The tint is the tile's own ground now and there is no
             edge inside it to cut off.

             ── AND SMALLER ─────────────────────────────────────────────
             "Also, these tiles feel too big." The picture area was 132 and
             is 72; the title is 15 over 20 rather than 16 over 22; the
             padding is 12 rather than 16. About two thirds of the height. */
          /* ── THE TINT IS THE PICTURE, NOT THE TILE ───────────────────
             Shading the whole tile was my reading of "just shade the tile" and
             it was the wrong one. Ellie: "Undo this. I like the way the app
             looks. Also, I want each tile to have shading behind it, but I
             don't want shading on each row the way you have it currently."

             Both halves of that. A tile tinted end to end makes a shelf read as
             a band of colour, because every tile on one shelf is one colour and
             they sit in a row: the shading was on the ROW. Confined to the
             picture area it is a card with an illustration, which is the app's,
             and the shading behind each tile is the shadow it floats on. */
          display: "block", background: "white", borderRadius: 18, overflow: "hidden",
          textDecoration: "none", boxShadow: "0 6px 14px rgba(42,27,16,0.10)",
        }}>
        <div style={{ height: 72, background: ground, position: "relative" }}>
          {/* The mark, quietly, so a tile with no illustration still looks
              like something rather than like something missing. */}
          <span aria-hidden="true" style={{
            position: "absolute", right: 10, bottom: 8, opacity: 0.2, lineHeight: 0,
          }}>
            <AttuneMark width={40} />
          </span>
          {/* The label, so a reader knows what kind of thing they are about to
              open before they read the title. */}
          <span style={{
            position: "absolute", top: 8, left: 8,
            background: "rgba(255,253,249,0.92)", borderRadius: 7,
            padding: "2px 7px", fontFamily: BFONT, fontSize: 8, fontWeight: 700,
            letterSpacing: "0.16em", textTransform: "uppercase", color: C.ink,
          }}>
            Article
          </span>
          {bookmark(a, 13, { top: 8, right: 8, round: true })}
        </div>
        <div style={{ padding: "0.75rem" }}>
          {/* Two lines whether or not it needs them: a one line title beside a
              two line one is a ragged edge, which is why the app gives it a
              minimum rather than letting the tile size itself. */}
          <span style={{
            display: "-webkit-box", WebkitBoxOrient: "vertical", WebkitLineClamp: 2,
            overflow: "hidden", fontFamily: BFONT, fontSize: 15, lineHeight: "20px",
            fontWeight: 700, color: C.ink, minHeight: 40,
          }}>
            {a.title}
          </span>
          <span style={{
            display: "block", fontFamily: BFONT, fontSize: 12, lineHeight: "17px",
            color: MUTED_INK, marginTop: "0.35rem",
          }}>
            {a.readMinutes ? (
              <span style={{ color: ACCENT }}>{`${a.readMinutes} min read`}</span>
            ) : null}
            {st?.read ? "  \u00b7  Read" : ""}
          </span>
        </div>
      </a>
    );
  };

  const pill = (label, n) => (
    <span style={{
      background: "#F2EDE6", borderRadius: 999, padding: "0.3rem 0.8rem",
      fontFamily: BFONT, fontSize: "0.74rem", color: "#6B5B4A", whiteSpace: "nowrap",
    }}>
      {label} <span style={{ color: "#A8937B", fontWeight: 700 }}>{n}</span>
    </span>
  );

  return (
    /* block: app-learn/reading */
    <div data-block="app-learn/reading" style={{
      /* No top margin. The website's dashboard spends about 250 points on a
         banner the app does not have, so every point above the sheet is a point
         off the peek, and a gap here was the easiest one to give back. */
      marginTop: 0,
      marginLeft: isMobile ? "-1.25rem" : "-2rem",
      marginRight: isMobile ? "-1.25rem" : "-2rem",
      background: "white", borderRadius: "34px 34px 0 0",
      /* ── EVERY POINT IN HERE IS A POINT OFF THE INSIGHT ────────────
         Ellie, asked which of the four things competing for this screen
         should give: "Shorter peek is fine." The peek is this sheet's head,
         so the saving is taken out of the lid, the type and the spacing in
         it, and the four featured tiles, rather than out of any one of them
         alone. 190 points to 139. */
      padding: isMobile ? "0.6rem 1.25rem 3rem" : "0.65rem 2rem 3.5rem",
      boxShadow: "0 -10px 30px rgba(14,11,7,0.10)",
    }}>
      {/* Ellie: "Add some shading on the learn page bottom tile." The grab line
          above it is what makes the panel read as lifted rather than as a box. */}
      {/* Ellie: "Add some shading on the learn page bottom tile." The grab line
          above the head is what makes the panel read as lifted rather than as a
          box. It sits outside the measured head on purpose: the app counts it
          separately too. */}
      <div style={{
        width: 46, height: 4, borderRadius: 2, background: "#E8673A",
        margin: "0 auto 0.45rem",
      }} />

      {/* ── THE HEAD IS A ROW, AS IT IS IN THE APP ────────────────────────
          Ellie: "In practice section should be formatted the same way as the
          app's", and "Content on this page needs to be resized so that the in
          practice section has the same peek as the app does."

          Those are one thing. The app's head is a row: the pills, the heading,
          the line under it and the search in a left column, with four featured
          articles in a 2x2 grid beside them. It measures that row and the peek
          is its height, so the two asks are the same ask.

          This had the same parts stacked, which made the head much shorter and
          the peek with it, and no amount of adjusting the gap above would have
          matched while the shape underneath was different.

          Ellie, on the app: "Search articles bar should be bottom aligned with
          the bottom 2 featured articles." The column is as tall as the grid
          beside it and the search sits at its foot. */}
      <div
        ref={headRef}
        /* Named so a browser check can measure the peek where it sits on the
           page, rather than only asking the sheet what it reported. */
        data-learn-head=""
        style={{
        display: "flex", flexDirection: "row", gap: isMobile ? "0.75rem" : "1.25rem",
        alignItems: "stretch",
      }}>
        <div style={{ flex: "1 1 0", display: "flex", flexDirection: "column", minWidth: 0 }}>
          <div style={{ display: "flex", gap: "0.5rem", marginBottom: "0.6rem" }}>
            {pill("Saved", savedCount)}
            {pill("Read", readCount)}
          </div>

          <h2 style={{
            fontFamily: HFONT, fontWeight: 700, color: C.ink, margin: 0,
            fontSize: isMobile ? "1.55rem" : "1.9rem", lineHeight: 1.05, letterSpacing: "-0.02em",
          }}>
            In Practice
          </h2>
          <p style={{
            fontFamily: BFONT, fontSize: isMobile ? "0.82rem" : "0.88rem", color: "#8A7A66",
            margin: "0.25rem 0 0",
          }}>
            Featured publications
          </p>

          {/* Pushed to the foot of the column, which is what bottom-aligns it
              with the lower two cards beside it. */}
          <label style={{ display: "block", marginTop: "auto", paddingTop: "0.5rem" }}>
            <span style={{ position: "absolute", left: -9999 }}>Search articles</span>
            <span style={{
              display: "flex", alignItems: "center", gap: "0.5rem",
              background: "#F5F1EA", borderRadius: 999,
              padding: isMobile ? "0.45rem 0.8rem" : "0.5rem 0.9rem",
            }}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#A8937B"
                strokeWidth="2" strokeLinecap="round" aria-hidden="true">
                <circle cx="11" cy="11" r="7" /><path d="M20 20l-3.5-3.5" />
              </svg>
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Search articles"
                style={{
                  border: "none", background: "transparent", outline: "none",
                  fontFamily: BFONT, fontSize: "0.85rem", color: C.ink, width: "100%",
                  minWidth: 0,
                }}
              />
            </span>
          </label>
        </div>

        {/* Four, in a 2x2, beside the column. The rest are below the fold, which
            is what makes this a peek rather than a page. */}
        <div style={{
          flex: "1 1 0", display: "grid", gridTemplateColumns: "1fr 1fr",
          gap: "0.5rem", minWidth: 0,
        }}>
          {shown.slice(0, 4).map((a) => featured(a))}
        </div>
      </div>

      {/* ── BELOW THE FOLD, BY SHELF ──────────────────────────────────────
          Ellie: "the in practice section doesn't contain all of the articles
          organized like the app does. Please match the app."

          The app's words for the shape, from when she asked for it there: "have
          them organized in sections with eyebrow text for each section... Each
          section should have articles side by side, and users can swipe to see
          them." So: an eyebrow naming the shelf, and a row that scrolls
          sideways under it.

          The shelves come from shelfFor, which is what /api/posts sends the app,
          rather than from each article's own label. Two of the twelve used to
          carry a label that disagreed with their shelf, which is why the label
          stopped living on the article.

          A shelf with nothing on it is not drawn, which is also why this maps
          over what is there rather than over the four names. While a search is
          running the shelves hold only what matched. */}
      {shown.length > 4 && (
        <div style={{ marginTop: "1.5rem" }}>
          {shelves.map(([shelf, items]) => (
            <div key={shelf} style={{ marginBottom: "1.5rem" }}>
              {/* ── THE EYEBROW OPENS THE SHELF ───────────────────────────
                  Ellie: "I'm not seeing the option to open each section's full
                  list of articles, etc." The app's shelf heading is a row with
                  an arrow on the right that opens that shelf as a page of its
                  own; this drew the name and nothing else.

                  The website has no shelf page, so the arrow filters this list
                  to that shelf, which is the same answer in the shape this
                  surface has: one shelf, everything on it, and a way back. */}
              <button
                type="button"
                onClick={() => setQuery(query === shelf ? "" : shelf)}
                aria-label={`See everything in ${shelf}`}
                style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  width: "100%", background: "transparent", border: "none", padding: 0,
                  cursor: "pointer", marginBottom: "0.6rem",
                }}>
                {/* Ellie: "I'd like for the app and site to list the count of
                    articles next to each section title." The app draws the same
                    two words from the same list. */}
                <span style={{
                  fontSize: "0.58rem", letterSpacing: "0.2em", textTransform: "uppercase",
                  fontWeight: 700, fontFamily: BFONT, color: "#A89C8C",
                }}>
                  {shelf}
                  <span style={{ color: "#C3B7A6", marginLeft: "0.5rem", letterSpacing: "0.08em" }}>
                    {items.length}
                  </span>
                </span>
                <span style={{ color: C.clay, fontSize: "0.9rem", lineHeight: 1 }}>
                  {query === shelf ? "\u00D7" : "\u2192"}
                </span>
              </button>
              {/* Side by side, and it scrolls. The app's row is a horizontal
                  ScrollView; this is the same thing a browser already does. */}
              <div style={{
                /* ── ROOM FOR THE SHADOW TO FINISH ───────────────────────
                   Ellie: "Still a hard line on the bottom of the shadow, I
                   want it to fade like a regular shadow backing."

                   It was fading. It was being cut. `overflow-x: auto` makes
                   overflow-y compute to auto as well rather than staying
                   visible, so this row clips what its children draw outside
                   it, and a card's shadow is `0 6px 14px`: it reaches twenty
                   points below the card and the row allowed five and a half.
                   The straight edge was this container, at the exact point
                   the blur was still at most of its strength.

                   So the padding is the shadow's own reach, top and bottom,
                   which is what it needs to end on its own. */
                display: "flex", gap: "0.5rem", overflowX: "auto",
                paddingTop: 10, paddingBottom: 22,
                /* Sideways too, and pulled back out by the same amount so the
                   first card still lines up with the heading above it. The
                   blur is 14 in every direction, so the first card's left edge
                   and the last card's right edge were cut the same way the
                   bottoms were. */
                paddingLeft: 14, paddingRight: 14, marginLeft: -14, marginRight: -14,
                scrollbarWidth: "thin",
              }}>
                {items.map((a) => (
                  <div key={a.slug} style={{ flex: "0 0 auto", width: isMobile ? 158 : 186 }}>
                    {tile(a)}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
      {!shown.length && (
        <p style={{ fontFamily: BFONT, fontSize: "0.85rem", color: "#8A7A66", marginTop: "1rem" }}>
          Nothing matches that.
        </p>
      )}
    </div>
  );
}

/**
 * Exported so a browser check can render the real thing.
 *
 * Ellie has now reported this tile wrong three times and two of my fixes were
 * wrong, both because I measured something that was not this component: first a
 * hand-written page with the same CSS, then nothing at all, because the
 * dashboard needs an account and ?demo=1 on it renders blank. A component that
 * can only be checked by being signed in is a component nothing checks.
 *
 * See check-prompt-tiles.mjs, which mounts this with a stub payload and
 * measures the cards at several window sizes.
 */
export function AppHome({ feed, isMobile, userName, onQuick, onCard, children }) {
  /**
   * ── THE PICTURE IS A ROUNDED SQUARE, AND THE WIDTH COMES FROM THE HEIGHT ─
   * Ellie, of this tile on her desktop: "Home page action prompt tiles are
   * rendering incorrectly on my desktop", and then "Still messed up."
   *
   * The picture was taking whatever height the card had left, which on a 330
   * wide card is a letterbox. She had already rejected exactly that in the app:
   * "I want white boxes holding rounded square images with the text under it,
   * right now the image takes up the full top half of the tile rather than
   * being its own rounded square."
   *
   * A square picture makes the card as tall as it is wide, plus the words, and
   * this page must not scroll. So the width has to come from the height:
   *
   *     card width = the room these cards have  -  the words under the picture
   *
   * ── WHY MEASURED AND NOT A CONTAINER QUERY ─────────────────────────────
   * The first version did this in CSS with `container-type: size`, which is the
   * same arithmetic and needs every ancestor between here and the window to
   * have a definite height. I could not get this screen in front of a browser
   * to find out whether they do: it needs an account, and `?demo=1` on it
   * renders blank rather than a dashboard. A layout whose correctness depends
   * on a chain I cannot check is a bad bet, and she had already told me once
   * that it was still wrong.
   *
   * One measured number has no chain. Before the first measurement the card
   * takes the whole cell and the picture fills what is left, which is what it
   * did before any of this, so the worst case is the old layout rather than a
   * broken one.
   */
  const promptsRef = useRef(null);
  const [promptsH, setPromptsH] = useState(0);
  useEffect(() => {
    const el = promptsRef.current;
    if (!el || typeof ResizeObserver === "undefined") return undefined;
    const ro = new ResizeObserver((entries) => {
      const h = Math.round(entries[0].contentRect.height);
      setPromptsH((prev) => (Math.abs(prev - h) > 1 ? h : prev));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  /**
   * 120 is the words under the picture, and it is measured rather than added
   * up: rendered at four heights the card comes out 108 taller than its
   * picture every time, which is the two clamped lines, the hairline and the
   * padding. 120 leaves a dozen in hand.
   *
   * 200 is a floor. Without it a short window makes a card small enough to look
   * like a mistake, and the better trade there is a picture that gives up its
   * square: the card is capped at the cell, so the picture shrinks rather than
   * the card overflowing or the page scrolling.
   */
  const cardW = promptsH ? Math.max(200, promptsH - 120) : 0;
  const cardStyle = cardW
    ? { width: cardW, maxWidth: "100%", maxHeight: "100%" }
    : { width: "100%" };
  const picStyle = cardW
    ? { aspectRatio: "1 / 1", flex: "0 1 auto", minHeight: 0 }
    : { flex: "1 1 auto", minHeight: 0 };

  /**
   * ── `secondary` IS A LIST, NOT A CARD ───────────────────────────────────
   * Ellie, with a screenshot: "A few problems with this page. Formatting is
   * off." The second card was an empty tinted square with no words in it.
   *
   * /api/home sends `secondary` as an array: nextActions returns
   * `withApp.slice(1, 4)`. This read it as one card, so the second tile was
   * rendering an Array: `card.title` undefined, `card.body` undefined,
   * `card.tint` undefined, and a card-shaped box with nothing in it. Nothing
   * errored, because every one of those is a perfectly ordinary undefined.
   *
   * The app has always indexed `secondary[0]`. Two readings of one payload, and
   * only one of them was right.
   *
   * It survived my own screenshots because the stub I was rendering against
   * sent an object, which is the mistake this file warns about in another
   * place: a fixture that is not the shape of the thing it stands in for.
   */
  const cards = [
    feed?.primary,
    ...(Array.isArray(feed?.secondary) ? feed.secondary : [feed?.secondary]),
  ].filter(Boolean).slice(0, 2);
  /**
   * ── THE SHAPE IS THERE BEFORE THE WORDS ARE ─────────────────────────────
   * Ellie: "Has done the same weird thing each time I open, the formatting
   * loads then completely changes."
   *
   * The two cards come from /api/home, which takes a round trip. Until it
   * landed this drew the tiles and an empty tile, then the cards arrived and
   * everything below them moved. Two placeholders hold the same space, so what
   * changes when the payload lands is the words inside them and nothing else.
   */
  const placeholders = feed ? [] : [{ id: "_a" }, { id: "_b" }];
  /**
   * The app's four, in the app's order, with the app's labels.
   *
   * "Action plans" carries its own line break for the reason the app gives:
   * Ellie asked for it "split into 2 lines to match the other quick access
   * tiles", and at this width it is the only one of the four that would sit on
   * a single line if left to wrap.
   */
  const QUICK = [
    { id: "insight", label: "Insight of\nthe day", icon: QuickIcons.brain },
    { id: "plan", label: "Action\nplans", icon: QuickIcons.signpost },
    { id: "highlights", label: "Results\nhighlights", icon: QuickIcons.sparkles },
    { id: "journal", label: "Relationship\njournal", icon: QuickIcons.book },
  ];
  return (
    /* ── IT FITS, IT DOES NOT SCROLL ──────────────────────────────────────
       Ellie: "Home page should not be scroll-able... resize those so they fit
       appropriately no matter the size of the window. That way the blue
       gradient will be visible on that page as well."

       So the column is the height it is given and nothing inside it overflows:
       the links keep their own size, the tile takes the rest, and the two cards
       inside the tile are allowed to shrink. `minHeight: 0` on the tile is what
       lets that happen at all, because a flex child will not shrink below its
       content without it, and that is what pushes a page into scrolling. */
    <div style={{
      display: "flex", flexDirection: "column", gap: isMobile ? "1rem" : "1.5rem",
      height: "100%", minHeight: 0, overflow: "hidden",
    }}>
      {/* ── NO GREETING HERE ──────────────────────────────────────────────
          Ellie: "Remove good evening hero, site has a banner and that's
          enough." The banner above already carries both their names and a line
          under them, so the greeting was the page saying hello twice.

          It is still drawn in the app, where there is no banner, and it still
          comes from the same /api/home payload. The block marker goes with it,
          because a marker for something this surface does not draw is the
          inventory check telling us the two agree when they do not. */}

      {/* ── FOUR ACROSS, BARELY THERE, ICON ABOVE THE NAME ─────────────────
          Ellie, about these squares in the app: "the four boxes should be
          barely visible, and have barely any space between them... The text
          should be inside of the squares", then "Icons in the 4 smaller tiles
          should be larger, centered, and middle-aligned in the space above the
          text. Text in 4 boxes should be split to two lines and should be
          centered in the tile and moved up slightly."

          This was a 2x2 grid of text with no icons at all on a phone-width
          screen, which is why she said the layout was not the same. It is now
          the app's: one row of four whatever the width, the app's own fill of
          three per cent ink, its radius, its aspect, the icon centred in
          everything above the label and the label centred under it on two
          lines at 78 per cent of the square. */}
      {/* block: app-home/quick-links */}
      <div data-block="app-home/quick-links" style={{
        display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 2,
      }}>
        {QUICK.map((q) => (
          <button key={q.id} onClick={() => onQuick(q.id)}
            aria-label={q.label.replace("\n", " ")}
            style={{
              background: "rgba(14,11,7,0.045)", border: "none",
              borderRadius: 14, aspectRatio: "0.92",
              /* The app's tile is about 92 points wide on a 390 point screen.
                 A quarter of a 680px column is 170, which at this aspect comes
                 to 185 tall and is most of why Home did not fit on a laptop.
                 Capped, so they stay the size they are on a phone. */
              maxHeight: 132,
              padding: "0.5rem 0.25rem 0.75rem", cursor: "pointer",
              fontFamily: BFONT, display: "flex", flexDirection: "column",
              alignItems: "center", justifyContent: "flex-end",
            }}>
            <span style={{
              flex: 1, display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              {q.icon()}
            </span>
            {/* Ellie: "no matter the width of the window, the quick access
                tile labels should be split to 2 lines." So the break is in the
                label rather than left to the wrap, which is what the app does
                with "Action plans", and the box is two lines tall whether the
                second one has words in it or not. */}
            <span style={{
              fontSize: 11, lineHeight: "14px", color: C.muted,
              textAlign: "center", width: "86%", whiteSpace: "pre-line",
              minHeight: 28,
            }}>
              {q.label}
            </span>
          </button>
        ))}
      </div>

      {/* ── THE CREAM TILE ─────────────────────────────────────────────────
          Rounded at the top and running off the bottom of the page, which is
          how the app draws it: the tile is where the page ends rather than a
          card floating on it.

          ── EVERYTHING BELOW THE LINKS IS ON IT ──────────────────────────
          Ellie: "neither is content or layout." In the app, Home is a ground
          with one cream tile, and everything under the greeting and the four
          links lives inside it: the alerts, the two prompt cards, all of it.
          Here the tile held only the two cards and every other block on the
          dashboard sat straight on the ground, which nobody noticed while the
          ground was a flat colour. Once it was painted the way the app paints
          it, the alerts and the step list were reading against indigo.

          So the rest of the Home tab comes in as children and sits on the tile.
          It runs full width, which is why the side margins are taken back off:
          the app's tile goes edge to edge. */}
      {/* block: app-home/prompts */}
      {/* ── NO CREAM TILE UNDER THE PROMPTS ───────────────────────────────
          Ellie: "the two action prompt tiles are on a cream tile so I can't see
          the blue behind it."

          The tile was here because the app has one. On the app it is the foot
          of a phone screen and the ground still shows above and below it; here
          it filled the rest of a laptop window and the gradient she asked for
          was behind it rather than visible. The two cards are white tiles of
          their own, which is what she asked for on the app in the first place:
          "The two action prompts on the homepage should be in their own white
          tiles." They are enough on their own. */}
      <div data-block="app-home/prompts" style={{
        padding: isMobile ? "0.25rem 0 1.5rem" : "0.5rem 0 2rem",
        /* No `marginTop: auto`. An auto margin absorbs the free space in a flex
           column, so the tile was told to take what is left and simultaneously
           given nothing left to take: its own content then set its height and
           it ran off the bottom of the window. */
        /* Takes what is left and is allowed to give it back. Without
           `minHeight: 0` a flex child refuses to shrink under its content,
           which is what made this page scroll. */
        flex: "1 1 auto", minHeight: 0, display: "flex", flexDirection: "column",
      }}>
        {/* ── ALERTS, ABOVE THE CARDS ─────────────────────────────────────
            Ellie: "Add partner joined as an alert row to app and site."

            The app puts unread alerts at the top of this tile, as rows, and
            the website had a banner for one of them and nothing for the rest.
            Same rows, same payload, same place. They stay out of the height
            the cards are given: an alert is news and the cards are the page.

            `alerts` is the one thing on Home that is not the four links or the
            two prompts, and it is there because she asked for it by name. */}
        {(feed?.alerts || []).length ? (
          <div style={{ display: "flex", flexDirection: "column", gap: "0.4rem", marginBottom: "0.75rem", flexShrink: 0 }}>
            {feed.alerts.slice(0, 3).map((a) => (
              <button key={a.id} onClick={() => onCard(a)}
                style={{
                  display: "flex", alignItems: "flex-start", gap: "0.6rem", width: "100%",
                  background: "#EEF2FC", border: "1px solid #DCE4F6", borderRadius: 12,
                  padding: "0.6rem 0.75rem", textAlign: "left", cursor: "pointer",
                  fontFamily: BFONT,
                }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#1B5FE8"
                  strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"
                  style={{ flexShrink: 0, marginTop: 2 }}>
                  <path d="M18 8a6 6 0 1 0-12 0c0 7-3 9-3 9h18s-3-2-3-9" /><path d="M13.7 21a2 2 0 0 1-3.4 0" />
                </svg>
                <span style={{ minWidth: 0 }}>
                  <span style={{ display: "block", fontSize: "0.82rem", fontWeight: 700, color: C.ink, lineHeight: 1.3 }}>
                    {a.title}
                  </span>
                  {a.body ? (
                    <span style={{ display: "block", fontSize: "0.76rem", color: C.muted, lineHeight: 1.4 }}>
                      {a.body}
                    </span>
                  ) : null}
                </span>
              </button>
            ))}
          </div>
        ) : null}

        {/* Two across, on a phone as well. The app puts them side by side at
            390 points wide and stacking them here was the layout differing from
            the app on the one screen Ellie looks at most. */}
        <style>{`
          .ah-cell { min-width: 0; display: flex; align-items: flex-start; }
          /* ── THE PICTURE PAYS FOR ITS OWN PADDING ────────────────────────
             Ellie, third report on this tile: "Still no buffer between the
             inner square and the right edge of the tile."

             The card is border-box and the picture was content-box, so the
             picture's own half-rem of padding, which holds the mark off the
             corner, was added OUTSIDE its 100% width. Sixteen points wider than
             the box it sits in: a full gap on the left, none on the right, and
             it looked like a padding someone forgot rather than one counted
             twice. Measured at 270 declared and 286 drawn.

             Both halves here. The card too, because a width means two
             different things under the two models and the arithmetic that
             sizes this one is written in border-box terms.

             No backticks in this comment: it lives inside a template literal,
             so one closes the string and the build fails on the next word. */
          .ah-card, .ah-pic, .ah-pic * { box-sizing: border-box; }
          /* The pair hugs the middle rather than each card floating in its own
             half, which is how the app has them: side by side with one gap. */
          .ah-cell:nth-child(odd) { justify-content: flex-end; }
          .ah-cell:nth-child(even) { justify-content: flex-start; }
        `}</style>
        <div ref={promptsRef} style={{
          display: "grid", gridTemplateColumns: "1fr 1fr",
          gap: isMobile ? "0.65rem" : "1.1rem",
          /* A row with a definite height. Without it the row sizes to its
             content and the cards size to the row, and the two wait for each
             other: the first version of this drew a 34px card. */
          gridTemplateRows: "minmax(0, 1fr)",
          flex: "1 1 auto", minHeight: 0,
        }}>
          {placeholders.map((p) => (
            <div key={p.id} className="ah-cell">
            <div aria-hidden="true" className="ah-card" style={{
              ...cardStyle,
              background: "white", border: "1px solid #EFE7DC", borderRadius: 18,
              padding: isMobile ? "0.85rem" : "1rem",
              display: "flex", flexDirection: "column", minHeight: 0, overflow: "hidden",
            }}>
              <div className="ah-pic" style={{
                ...picStyle,
                width: "100%", borderRadius: 12,
                background: "#F6F1EA", marginBottom: "0.7rem",
                /* ── THE MARK SITS IN THE CORNER, AS IT DOES IN THE APP ──
                   Ellie: "Home page action prompt tiles on web are missing the
                   hairline below the hero and the mark in the image box."

                   Her words for the app's version: "just a shaded square with
                   an attune logo in the bottom right". The box was the shade
                   and not the logo. */
                display: "flex", alignItems: "flex-end", justifyContent: "flex-end",
                padding: "0.5rem",
              }}>
                <AttuneMark width={34} style={{ opacity: 0.5 }} />
              </div>
              <div style={{ height: "1.1rem", borderRadius: 5, background: "#F2EDE6", marginBottom: "0.45rem" }} />
              <div style={{ height: "0.7rem", borderRadius: 4, background: "#F6F1EA", width: "80%" }} />
            </div>
            </div>
          ))}
          {cards.map((card, cardIdx) => (
            <div key={card.id} className="ah-cell">
            <button onClick={() => onCard(card)} className="ah-card"
              style={{
                ...cardStyle,
                background: "white", border: "1px solid #EFE7DC", borderRadius: 18,
                padding: isMobile ? "0.85rem" : "1rem", textAlign: "left",
                cursor: "pointer", fontFamily: BFONT,
                display: "flex", flexDirection: "column", minHeight: 0, overflow: "hidden",
              }}>
              {/* The square an image goes in. Tinted until the artwork exists,
                  which is what the list in TASKS.md O506 is for. */}
              {/* The picture is what gives way on a short window: it keeps
                  its square while there is room and shrinks before the words
                  do, because a card whose title is cut off is a card that has
                  stopped working. */}
              <div className="ah-pic" style={{
                ...picStyle,
                width: "100%", borderRadius: 12,
                /* ── THE PAYLOAD HAS NEVER CARRIED A TINT ──────────────
                   This read `card.tint`, and nothing on the server has ever
                   set one: `git log -S tint` over api/_lib/next-action.js and
                   api/home.js returns nothing. So both prompts fell to the
                   same fallback and the pair was one colour here while the app
                   alternates two. The same shape as `secondary` being an array
                   rather than a card: a field read off the app's payload that
                   the payload does not have, and an undefined property is a
                   default rather than an error. See cardTint. */
                background: cardTint(cardIdx), marginBottom: "0.7rem",
                /* The square is in picStyle, and it only arrives once the card's
                   width is known. This used to carry `flex: 1 1 auto` with a
                   note saying an aspect ratio could not be used because a
                   definite height does not shrink. That was true and the
                   conclusion was wrong: the answer is to make the width
                   definite first, which is what the measurement is for. */
                /* ── THE MARK SITS IN THE CORNER, AS IT DOES IN THE APP ──
                   Ellie: "Home page action prompt tiles on web are missing the
                   hairline below the hero and the mark in the image box."

                   Her words for the app's version: "just a shaded square with
                   an attune logo in the bottom right". The box was the shade
                   and not the logo. */
                display: "flex", alignItems: "flex-end", justifyContent: "flex-end",
                padding: "0.5rem",
              }}>
                <AttuneMark width={34} style={{ opacity: 0.5 }} />
              </div>
              {/* ── CLAMPED, SO IT ENDS RATHER THAN BEING SLICED ──────────
                  Ellie, with a screenshot of a laptop window: "Doesn't fit on
                  one screen." The page is the window now and nothing overflows
                  it, but on a short window the card had more words than room
                  and cut one off mid-line, which looks like the page is broken
                  rather than like a card that is full.

                  Two lines each, ending in an ellipsis. The whole sentence is
                  on the page the card opens. */}
              <div style={{
                fontFamily: HFONT, fontSize: isMobile ? "1rem" : "1.1rem", fontWeight: 700,
                color: C.ink, lineHeight: 1.2, marginBottom: "0.4rem",
                display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical",
                overflow: "hidden", flexShrink: 0, minHeight: "2.4em",
              }}>
                {card.title}
              </div>
              {/* The app draws a hairline between the title and the line under
                  it. Ellie asked for it there by name: "The two larger tiles
                  within that one also have a border." */}
              <div style={{ height: 1, background: C.stone, margin: "0 0 0.55rem", flexShrink: 0 }} />
              {/* Ellie: "if the action prompt text splits to 2 lines, it must
                  do it on both tiles so that the formatting is the same for
                  each." Clamping alone does not do that: a one-line body stays
                  one line and the two cards end up different heights. A minimum
                  of two lines holds the shape whether the words fill it or
                  not. */}
              <div style={{
                fontSize: "0.82rem", color: C.muted, lineHeight: 1.45,
                display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical",
                /* Two lines of THIS leading, which is 2 x 1.45. It was 2.4em,
                   borrowed from the title above it where the leading is 1.2, so
                   a one-line body reserved less than a two-line body used and
                   the pair came out seven points apart. Exactly what the
                   minimum was added to stop: Ellie, "if the action prompt text
                   splits to 2 lines, it must do it on both tiles so that the
                   formatting is the same for each." */
                overflow: "hidden", flexShrink: 0, minHeight: "2.9em",
              }}>
                {card.body}
              </div>
            </button>
            </div>
          ))}
        </div>
        {children ? (
          <div style={{
            display: "flex", flexDirection: "column",
            gap: isMobile ? "1rem" : "1.25rem",
            marginTop: isMobile ? "1.25rem" : "1.5rem",
          }}>
            {children}
          </div>
        ) : null}
      </div>
    </div>
  );
}

// ── OVERALL PAIRING LABEL ────────────────────────────────────────────────────
/**
 * ── ONE BANDING OF THE AVERAGE GAP ──────────────────────────────────────────
 * This set of cut points was right and it was not the only set. The gapTier
 * expression further down banded the same number at 1.0, 1.8 and 2.5 before
 * sending it to the tracker, so the admin counted a couple as more aligned
 * than this told them they were, on 19% of the range. Both come from
 * _lib/pairing.js now, whose bands are multiples of the STRENGTH threshold
 * these numbers already were.
 */
function overallPairingLabel(avgGap) {
  return pairingLabel(avgGap);
}

// ── DERIVE COUPLE TYPE FROM EXERCISE ─────────────────────────────────────────
// Wraps deriveNewCoupleType; alignPct is available for future weighting.
function deriveCoupleTypeFromExercise(myS, partS, alignPct) {
  try { return deriveNewCoupleType(myS, partS); } catch { return null; }
}

// ── COUPLE PORTRAIT RENDERER ─────────────────────────────────────────────────
// Renders a pair of avatar silhouettes. Used in portrait display cards.
function mkCouple(p1, p2, wide, id) {
  if (!p1 && !p2) return null;
  const size = wide ? 36 : 28;
  const grad = "linear-gradient(135deg,#E8673A,#9B5DE5,#1B5FE8)";
  const avatar = (p, label) => (
    <div key={label} style={{ width: size, height: size, borderRadius: "50%",
      background: p?.color || grad, display: "flex", alignItems: "center",
      justifyContent: "center", fontSize: size * 0.42, color: "white",
      fontWeight: 700, fontFamily: "'DM Sans',sans-serif", flexShrink: 0 }}>
      {p?.initial || (label === "p1" ? "A" : "B")}
    </div>
  );
  return (
    <div style={{ display: "flex", gap: 4 }}>
      {avatar(p1, "p1")}
      {avatar(p2, "p2")}
    </div>
  );
}


// ── SIDE NAV WRAPPER ─────────────────────────────────────────────────────────
// Wraps results content with a sticky left sidebar showing step navigation.
function WithSideNav({ navItems = [], currentStep, onGo, accent = "#9B5DE5", children }) {
  return (
    <div style={{ display: "flex", alignItems: "flex-start", gap: 0, minHeight: "100vh" }}>
      {/* Sidebar */}
      <div className="desktop-sidebar" style={{
        width: 220, flexShrink: 0, position: "sticky", top: 0, height: "100vh",
        overflowY: "auto", background: "white", borderRight: "1px solid #E5E2DC",
        padding: "1.5rem 0", display: "flex", flexDirection: "column", gap: 2,
      }}>
        {navItems.map((item, i) => {
          const active = currentStep === i;
          const done   = currentStep > i;
          return (
            <button key={i} onClick={() => onGo(i)} style={{
              display: "flex", alignItems: "center", gap: "0.6rem",
              padding: "0.55rem 1.1rem", background: active ? (accent + "12") : "transparent",
              border: "none", cursor: "pointer", textAlign: "left", width: "100%",
              borderLeft: active ? ("3px solid " + accent) : "3px solid transparent",
              transition: "all 0.15s",
            }}>
              <span style={{
                width: 20, height: 20, borderRadius: "50%", flexShrink: 0,
                background: done ? accent : active ? accent : "#E5E2DC",
                display: "flex", alignItems: "center", justifyContent: "center",
                fontSize: "0.6rem", color: "white", fontWeight: 700,
              }}>
                {done ? "✓" : (i + 1)}
              </span>
              <span style={{
                fontSize: "0.78rem", fontFamily: "'DM Sans', sans-serif",
                color: active ? accent : done ? "#555" : "#999",
                fontWeight: active ? 600 : 400, lineHeight: 1.3,
              }}>
                {item.label || item}
              </span>
            </button>
          );
        })}
      </div>
      {/* Content */}
      <div style={{ flex: 1, minWidth: 0 }}>
        {children}
      </div>
    </div>
  );
}


// ── EXERCISE 01: COMMUNICATION EXERCISE ─────────────────────────────────────
// Shows PERSONALITY_QUESTIONS one at a time. Each question has two poles (a/b).
// User picks from a 5-point scale: 1=strongly a, 3=middle, 5=strongly b.
// On completion, calls onComplete(answers) with full dimension key map.
// Comms exercise with the 5 partner-view items interleaved after their self
// counterpart (Proposal B). Only used when PARTNER_VIEW_ENABLED.
// Two-part comms exercise: Part 1 asks all questions about yourself, Part 2 (after
// a break screen) re-asks the same set about your partner, storing under pv_<id>.
// Assembly moved to api/_questions.js as twoPartEx1(), so the app is handed
// the same list in the same order with the same answer keys. Two surfaces
// building this separately is two ways to write answers that do not score the
// same.
const TWO_PART_EX1 = twoPartEx1();
function Exercise01Flow({ userName, partnerName, onComplete, skipIntro = false, fresh = false }) {
  const questions = PARTNER_VIEW_ENABLED ? TWO_PART_EX1 : PERSONALITY_QUESTIONS;

  // Mid-exercise persistence: save after each answer, hydrate on mount.
  // Under key attune_ex1_progress so final submission's attune_ex1 stays
  // distinct. Cleared after onComplete runs. In fresh preview mode (admin
  // ?fresh=1) we ignore any saved progress so the reviewer always starts at
  // question 1 and sees the full set, including the partner-view questions.
  const [idx, setIdx] = useState(() => {
    if (fresh) return 0;
    try {
      const raw = localStorage.getItem('attune_ex1_progress');
      if (!raw) return 0;
      const saved = JSON.parse(raw);
      return typeof saved?.idx === 'number' ? saved.idx : 0;
    } catch { return 0; }
  });
  const [answers, setAnswers] = useState(() => {
    if (fresh) return {};
    try {
      const raw = localStorage.getItem('attune_ex1_progress');
      if (!raw) return {};
      const saved = JSON.parse(raw);
      return saved?.answers || {};
    } catch { return {}; }
  });
  const [chosen, setChosen] = useState(null); // current question selection

  // Combined intro phase. Skipped when:
  //   (a) skipIntro=true — Partner B's wrapper already showed its own intro
  //   (b) user has saved progress (hydrated idx > 0 or any answers) — resume
  const hasProgress = idx > 0 || Object.keys(answers).length > 0;
  const [phase, setPhase] = useState((skipIntro || hasProgress) ? 'questions' : 'intro');

  // On first render after hydration, if the current question already has a
  // saved answer (user refreshed after Next but before selecting again),
  // pre-fill so they can see what they picked.
  useEffect(() => {
    if (answers[questions[idx]?.answerKey] !== undefined && chosen === null) {
      setChosen(answers[questions[idx].answerKey]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The opening page, from the module both surfaces read.
  const ex1Intro = exerciseIntro('ex1', { partner: partnerName });

  // ── Combined intro (Exercise 01 + 02 preview) — matches Partner B copy ─
  if (phase === 'intro') {
    return (
      <div style={{ maxWidth: 560, margin: "0 auto", padding: "1.5rem 1rem 2rem", animation: "fadeIn 0.5s ease" }}>
        <link href={FONT_LINK} rel="stylesheet" />
        <style>{'@keyframes fadeIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}'}</style>
        {/* The cover, with this page's own contents inside it. Ellie: "Mirror
            cover pages for exercises and results on both web and app." The two
            preview tiles stay: they say what the next twenty minutes hold,
            which is content rather than chrome, and nothing asked for them to
            go. */}
        <CoverCard accent="#E8673A" minHeight="auto">
        <p style={{ fontSize: "0.62rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#E8673A", fontWeight: 700, fontFamily: font.body, marginBottom: "1rem" }}>
          {userName} &amp; {partnerName}
        </p>
        <p style={{ fontFamily: font.display, fontSize: "clamp(1.6rem, 5vw, 2.2rem)", fontWeight: 700, color: C.ink, lineHeight: 1.1, marginBottom: "1.25rem" }}>
          {ex1Intro.title}
        </p>
        {ex1Intro.body.map(para => (
          <p key={para.slice(0, 24)} style={{ fontSize: "0.92rem", color: C.muted, fontFamily: font.body, lineHeight: 1.75, marginBottom: "1.75rem" }}>
            {para}
          </p>
        ))}
        <div style={{ display: "flex", gap: "0.85rem", marginBottom: "1.75rem", flexWrap: "wrap" }}>
          {[
            { num: '01', title: 'Communication', color: '#E8673A', desc: PERSONALITY_QUESTIONS.length + ' questions, about you and your partner' },
            { num: '02', title: 'Expectations',  color: '#1B5FE8', desc: 'Responsibilities & life' },
          ].map(e => (
            <div key={e.num} style={{ flex: "1 1 180px", background: C.warm, border: `1.5px solid ${e.color}33`, borderRadius: 12, padding: "0.9rem 1rem" }}>
              <div style={{ fontSize: "0.56rem", letterSpacing: "0.18em", color: e.color, fontWeight: 700, fontFamily: font.body, textTransform: "uppercase", marginBottom: "0.3rem" }}>Exercise {e.num}</div>
              <div style={{ fontFamily: font.display, fontSize: "0.95rem", fontWeight: 700, color: C.ink, marginBottom: "0.2rem" }}>{e.title}</div>
              <div style={{ fontSize: "0.7rem", color: C.muted, fontFamily: font.body }}>{e.desc}</div>
            </div>
          ))}
        </div>
        <button onClick={() => setPhase('questions')}
          style={{ background: "linear-gradient(135deg, #E8673A, #1B5FE8)", color: "white", border: "none", padding: "0.85rem 2.25rem", fontSize: "0.8rem", letterSpacing: "0.08em", textTransform: "uppercase", cursor: "pointer", fontFamily: font.body, borderRadius: 999, fontWeight: 700 }}>
          {ex1Intro.cta}
        </button>
        </CoverCard>
      </div>
    );
  }

  const q = questions[idx];
  const total = questions.length;
  const progress = Math.round((idx / total) * 100);
  const qCount = questions.filter(x => !x.__partBreak).length;
  const answeredNum = questions.slice(0, idx + 1).filter(x => !x.__partBreak).length;

  const pick = (val) => {
    setChosen(val);
  };

  const next = () => {
    if (chosen === null) return;
    const updated = { ...answers, [q.answerKey || q.id]: chosen };
    if (idx + 1 < total) {
      setAnswers(updated);
      const nextIdx = idx + 1;
      // Restore the stored answer rather than blanking. Walking back and then
      // forward again used to clear each selection on the way, and next() will
      // not advance with a null selection, so the user was forced to re-answer
      // questions they had already answered.
      setChosen(updated[questions[nextIdx]?.answerKey] ?? null);
      setIdx(nextIdx);
      // Persist after each answer so refresh resumes mid-exercise. Skipped in
      // fresh preview mode so an admin walkthrough never overwrites a real
      // user's saved progress in the same browser.
      if (!fresh) {
        try { localStorage.setItem('attune_ex1_progress', JSON.stringify({ answers: updated, idx: nextIdx })); } catch {}
        /* And sync to server so resume works cross-device (debounced).
           The ANSWERS, not { answers, idx }. localStorage above keeps the idx
           because this browser resumes from it; the server copy is read by the
           app, which finds its own place from the first unanswered question, and
           handing it the wrapper made the wrapper look like the answers. Two of
           the three exercises here already sent the bare answers. */
        syncProgressCrossDevice(1, updated);
      }
    } else {
      // Clear progress cache — final result goes to attune_ex1 (done by onComplete)
      try { localStorage.removeItem('attune_ex1_progress'); } catch {}
      // Only submit answered keys — calcDimScores handles missing keys gracefully
      // by averaging only what exists (no synthetic 3s that dilute real answers)
      onComplete(updated);
    }
  };

  const back = () => {
    if (idx === 0) return;
    // Going back never erases an answer. This used to delete the CURRENT
    // question's answer on the way back, so stepping 4 → 3 → 2 wiped question 3
    // (it was "current" on the second press) and the selection was gone when you
    // walked forward again. Just move, and re-select what's already stored.
    const prevIdx = idx - 1;
    setIdx(prevIdx);
    setChosen(answers[questions[prevIdx].answerKey] ?? null);
    if (!fresh) {
      try { localStorage.setItem('attune_ex1_progress', JSON.stringify({ answers, idx: prevIdx })); } catch {}
    }
  };

  const SCALE = EX1_SCALE;

  if (q?.__partBreak) {
    return (
      <div style={{ minHeight: "100vh", background: "#FBF8F3", fontFamily: "'DM Sans', sans-serif" }}>
        <link href={FONT_LINK} rel="stylesheet" />
        <div style={{ height: 3, background: "#E5E2DC" }}><div style={{ height: "100%", width: progress + "%", background: "linear-gradient(90deg,#E8673A,#1B5FE8)" }} /></div>
        <div style={{ maxWidth: 520, margin: "0 auto", padding: "3.5rem 1.5rem 2rem", animation: "fadeIn 0.5s ease" }}>
          <p style={{ fontFamily: font.display, fontSize: "clamp(1.5rem, 5vw, 2rem)", fontWeight: 700, color: C.ink, lineHeight: 1.15, marginBottom: "1.25rem" }}>{PART_TWO.ex1}</p>
          <button onClick={() => { const ni = idx + 1; setIdx(ni); setChosen(answers[questions[ni]?.answerKey] ?? null); if (!fresh) { try { localStorage.setItem('attune_ex1_progress', JSON.stringify({ answers, idx: ni })); } catch {} } }} style={{ background: "linear-gradient(135deg,#E8673A,#1B5FE8)", color: "white", border: "none", padding: "0.95rem 2rem", borderRadius: 10, cursor: "pointer", fontFamily: font.body, fontSize: "0.95rem", fontWeight: 600, minHeight: 48 }}>Continue →</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: "#FBF8F3", fontFamily: "'DM Sans', sans-serif" }}>
      <link href={FONT_LINK} rel="stylesheet" />
      {/* Progress bar */}
      <div style={{ height: 3, background: "#E5E2DC" }}>
        <div style={{ height: "100%", width: progress + "%", background: "linear-gradient(90deg,#E8673A,#1B5FE8)", transition: "width 0.3s" }} />
      </div>

      <div style={{ maxWidth: 600, margin: "0 auto", padding: "3rem 1.5rem 6rem" }}>
        {/* Anonymous storage banner — only renders when no logged-in account */}
        <AnonymousStorageBanner />
        {/* Resume toast — fires once when the component mounts with saved progress */}
        <ResumeToast show={hasProgress} message={`You're on question ${answeredNum} of ${qCount}.`} />
        {/* Header */}
        <div style={{ marginBottom: "2rem" }}>
          <p style={{ fontSize: "0.72rem", letterSpacing: "0.1em", textTransform: "uppercase", color: "#999", fontFamily: "'DM Sans', sans-serif", marginBottom: "0.4rem" }}>
            Question {answeredNum} of {qCount}
          </p>
          <p style={{ fontSize: "1.25rem", fontWeight: 600, color: "#1C1C1E", fontFamily: "'Playfair Display', serif", lineHeight: 1.4, margin: 0 }}>
            {q.partnerView
              ? q.text.split(/(your partner)/i).map((seg, i) => (/^your partner$/i.test(seg) ? <em key={i}>{seg}</em> : <React.Fragment key={i}>{seg}</React.Fragment>))
              : q.text}
          </p>
        </div>

        {/* Two poles */}
        <div style={{ display: "flex", gap: "1rem", marginBottom: "2rem" }}>
          {[{ label: "A", text: q.a, side: "left" }, { label: "B", text: q.b, side: "right" }].map(pole => (
            <div key={pole.label} style={{
              flex: 1, padding: "1rem 1.1rem", background: "white",
              border: "1.5px solid #E5E2DC", borderRadius: 12,
            }}>
              <span style={{ fontSize: "0.65rem", letterSpacing: "0.1em", textTransform: "uppercase", color: "#9B5DE5", fontWeight: 700, display: "block", marginBottom: "0.4rem" }}>{pole.label}</span>
              <p style={{ fontSize: "0.88rem", color: "#3C3C43", lineHeight: 1.6, margin: 0 }}>{pole.text}</p>
            </div>
          ))}
        </div>

        {/* 5-point scale. One row on every screen size: equal-width buttons
            with fluid font/padding so all five fit a phone without wrapping
            into a second, confusing row. */}
        <div style={{ display: "flex", gap: "clamp(0.25rem, 1.2vw, 0.5rem)", justifyContent: "center", flexWrap: "nowrap", marginBottom: "2.5rem" }}>
          {SCALE.map(s => (
            <button key={s.val} onClick={() => pick(s.val)} style={{
              flex: "1 1 0", minWidth: 0, maxWidth: 130,
              padding: "0.85rem clamp(0.15rem, 1.5vw, 1.1rem)", borderRadius: 10, cursor: "pointer",
              fontFamily: "'DM Sans', sans-serif", fontSize: "clamp(0.64rem, 2.7vw, 0.88rem)", fontWeight: 500,
              minHeight: 48, lineHeight: 1.3, textAlign: "center",
              transition: "all 0.15s",
              background: chosen === s.val ? "#9B5DE5" : "white",
              color: chosen === s.val ? "white" : "#3C3C43",
              border: chosen === s.val ? "2px solid #9B5DE5" : "1.5px solid #E5E2DC",
              WebkitTapHighlightColor: "transparent",
            }}>
              {s.label}
            </button>
          ))}
        </div>

        {/* Nav buttons */}
        <div style={{ display: "flex", gap: "0.75rem", justifyContent: "center" }}>
          {idx > 0 && (
            <button onClick={back} style={{
              background: "transparent", border: "1.5px solid #E5E2DC", color: "#999",
              padding: "0.9rem 1.5rem", borderRadius: 10, cursor: "pointer",
              fontFamily: "'DM Sans', sans-serif", fontSize: "0.9rem", minHeight: 48,
              WebkitTapHighlightColor: "transparent",
            }}>← Back</button>
          )}
          <button onClick={next} disabled={chosen === null} style={{
            background: chosen !== null ? "linear-gradient(135deg,#E8673A,#1B5FE8)" : "#E5E2DC",
            color: "white", border: "none", padding: "0.9rem 2rem", borderRadius: 10,
            cursor: chosen !== null ? "pointer" : "not-allowed",
            fontFamily: "'DM Sans', sans-serif", fontSize: "0.9rem", fontWeight: 600,
            minHeight: 48, WebkitTapHighlightColor: "transparent",
          }}>
            {idx + 1 < total ? "Next →" : "Complete Exercise →"}
          </button>
        </div>
      </div>
    </div>
  );
}




// -- PERSONALITY RESULTS --

// Conditionally wraps children in a WithSideNav or plain div
function MaybeNav({ noSideNav, navItems, currentStep, onGo, accent, children }) {
  if (noSideNav) return <div style={{ minWidth: 0, flex: 1 }}>{children}</div>;
  return <WithSideNav navItems={navItems} currentStep={currentStep} onGo={onGo} accent={accent}>{children}</WithSideNav>;
}

// ── ROLE TOKEN RESOLVER (module level) ───────────────────────────────────────
// Couple-type prose uses {EXP}/{GRD} (open axis) and {RCH}/{WDR} (engage axis)
// plus their _sub/_obj/_pos/_isC pronoun forms. Tokens only resolve when the
// two partners actually differ on that axis. Anything unresolved is stripped
// back to a generic phrase so a raw token never reaches the page.
function resolveRoleTokens(str, myS, partS, userName, partnerName, userPronouns = "", partnerPronouns = "") {
  if (!str) return str;
  let out = str;
  const a = computeIndividualType(myS), b = computeIndividualType(partS);
  const uOpen = a.openScore >= 3.0, pOpen = b.openScore >= 3.0;
  const uEngage = a.withdrawScore <= 3.0, pEngage = b.withdrawScore <= 3.0;
  const fill = (nameA, nameB, pronA, pronB, A, B) => {
    out = out.replace(new RegExp(`\\{${A}\\}`, "g"), nameA).replace(new RegExp(`\\{${B}\\}`, "g"), nameB);
    ["sub", "obj", "pos", "isC"].forEach(f => {
      out = out.replace(new RegExp(`\\{${A}_${f}\\}`, "g"), pronoun(pronA, f))
               .replace(new RegExp(`\\{${B}_${f}\\}`, "g"), pronoun(pronB, f));
    });
  };
  if (uOpen !== pOpen) {
    const expName = uOpen ? userName : partnerName, grdName = uOpen ? partnerName : userName;
    const expPron = uOpen ? userPronouns : partnerPronouns, grdPron = uOpen ? partnerPronouns : userPronouns;
    fill(expName, grdName, expPron, grdPron, "EXP", "GRD");
    out = out.replace(/\b(the )?(expressive|open) partner\b/gi, expName).replace(/\b(the )?(guarded|reserved) partner\b/gi, grdName);
  }
  if (uEngage !== pEngage) {
    const rchName = uEngage ? userName : partnerName, wdrName = uEngage ? partnerName : userName;
    const rchPron = uEngage ? userPronouns : partnerPronouns, wdrPron = uEngage ? partnerPronouns : userPronouns;
    fill(rchName, wdrName, rchPron, wdrPron, "RCH", "WDR");
    out = out.replace(/\b(the )?(reaching|engaging) partner\b/gi, rchName).replace(/\b(the )?(withdrawing|quieter) partner\b/gi, wdrName);
  }
  return out;
}



// How far each partner's Part 2 read of the other is from what that person
// actually said. Positive means they placed their partner further toward the B
// pole than the partner placed themselves.
//
// ADMIN ONLY. This is diagnostic, not customer copy: telling a couple they have
// each other wrong, without the care that framing needs, is the kind of thing
// that lands badly. It renders only behind ?misreads=1.
function readErrorsFor(myAnswers, partnerAnswers) {
  if (!myAnswers || !partnerAnswers) return null;
  const pvOf = (ans) => {
    const out = {};
    for (const [k, v] of Object.entries(ans || {})) if (k.startsWith('pv_')) out[k.slice(3)] = v;
    return out;
  };
  const myTruth = calcDimScores(myAnswers);
  const partTruth = calcDimScores(partnerAnswers);
  const myRead = calcDimScores(pvOf(myAnswers));        // how I see them
  const partRead = calcDimScores(pvOf(partnerAnswers)); // how they see me
  const rows = [];
  for (const dim of DIMS) {
    const iSeeThem = myRead[dim], theyAre = partTruth[dim];
    const theySeeMe = partRead[dim], iAm = myTruth[dim];
    if ([iSeeThem, theyAre, theySeeMe, iAm].some(v => v == null || isNaN(v))) continue;
    rows.push({
      dim,
      mineOnThem: Number((iSeeThem - theyAre).toFixed(2)),
      theirsOnMe: Number((theySeeMe - iAm).toFixed(2)),
    });
  }
  if (!rows.length) return null;
  const mean = rows.reduce((a, r) => a + (Math.abs(r.mineOnThem) + Math.abs(r.theirsOnMe)) / 2, 0) / rows.length;
  return { rows: rows.sort((a, b) => Math.max(Math.abs(b.mineOnThem), Math.abs(b.theirsOnMe)) - Math.max(Math.abs(a.mineOnThem), Math.abs(a.theirsOnMe))), mean: Number(mean.toFixed(2)) };
}

// Comms action items, one per dimension where the gap is worth naming.
// Extracted to module level so What Comes Next can list the same items the
// results-at-a-glance plan draws from, rather than a second set.
/**
 * How many communication protocols any screen shows.
 *
 * Results at a glance sliced 3 and What Comes Next sliced 4, from this same
 * list, so the two pages named a different number of things to work on and the
 * fourth appeared only on one of them. Both read this.
 *
 * If you change it, change it here. Do not slice a different number at a call
 * site: that is how the two disagreed in the first place.
 */
export const COMMS_PROTOCOL_LIMIT = 3;

/**
 * The "this week" protocols.
 *
 * ── WHY THIS IS FOUR LINES ────────────────────────────────────────────────
 * It used to be the whole list written out again: nine dimensions with their
 * titles and instructions, plus the three-item fallback for a couple with no
 * gaps, all duplicated from api/_lib/comms-plan.js. Two copies of one list,
 * maintained by hand, with nothing checking they agreed.
 *
 * They had already drifted. The listening protocol read "Match presence to
 * what's needed" here with a straight apostrophe and with a curly one on the
 * server, so the website and the app showed different characters for the same
 * sentence. One character this time. The package rules started the same way.
 *
 * check-protocols.mjs now fails the build if this stops being the only copy.
 */
function buildCommsProtocols(byDim, userName, partnerName) {
  return commsProtocols(byDim, userName, partnerName);
}

function PersonalityResults({ myAnswers, partnerAnswers, userName, partnerName, coupleType, userPronouns = "", partnerPronouns = "", noSideNav = false, externalStep, onExternalGo, onGoExpectations, onGoBack, onNavigateTool, hasWorkbook = false }) {
  const [step, setStep] = useState(externalStep ?? 0);
  const [showRaw, setShowRaw] = useState(false);
  useEffect(() => { if (externalStep !== undefined) setStep(externalStep); }, [externalStep]);

  const myS = calcDimScores(myAnswers);
  const partS = calcDimScores(partnerAnswers);
  // Type/placement/role prose use the partner-view blend; the dimension bars below stay self-reported.
  const myB = typingDimScores(myAnswers, partnerAnswers);
  const partB = typingDimScores(partnerAnswers, myAnswers);
  // Copy for this couple: the version stamped on their results row.
  const _content = useContent();
  const feedback = generatePersonalityFeedback(myS, partS, userName, partnerName, _content);

  // Sort by gap ascending -- most similar first (items 1 & 4, 6 & 7 use this order)
  const sortedFeedback = [...feedback].sort((a, b) => a.gap - b.gap);
  const avgGap = feedback.reduce((s, f) => s + f.gap, 0) / feedback.length;
  const pairing = overallPairingLabel(avgGap);
  const byDim = Object.fromEntries(feedback.map(f => [f.dim, f]));

  // Ordered dims follow sorted order for step navigation (item 1)
  // Domain order drives navigation — keeps dims in a consistent,
  // logical reading sequence matching the sidebar.
  // DIMENSION_DISPLAY_ORDER, from api/_lib/comm-domains.js: the three domains
  // flattened. Written out here and again below as UR_DOMAIN_ORDER, in a file
  // the app cannot read, which is why the app showed these ten rows in the
  // scoring order instead and nothing noticed.
  const orderedDims = DIMENSION_DISPLAY_ORDER.filter(d => feedback.some(f => f.dim === d));
  // Detailed results are 3 grouped domain pages, not one page per dimension.
  // domainGroups is the source of truth for both the pages and the sidebar.
  const domainGroups = COMM_DOMAINS;
  // Only domains that actually have answered dimensions become pages.
  const detailDomains = domainGroups
    .map(g => ({ ...g, dims: orderedDims.filter(d => g.dims.includes(d)) }))
    .filter(g => g.dims.length);
  const nDetail = detailDomains.length;
  // Step for the page a given dimension now lives on (overview tiles link here).
  const domainStepOf = dim => { const i = detailDomains.findIndex(g => g.dims.includes(dim)); return i >= 0 ? i + 1 : 1; };
  // Same-type couples (both partners the same individual type) collapse to a
  // single combined "Communication Profile" page instead of two near-identical
  // individual pages.

  const go = s => { setStep(s); if (onExternalGo) onExternalGo(s); const sc = document.querySelector("[data-results-scroll]"); if (sc) sc.scrollTop = 0; else window.scrollTo({ top: 0, behavior: "smooth" }); };

  // The protocols are collected on What Comes Next, which builds them where
  // it uses them. This const was computed here and read by nothing.

  /**
   * ── THE ACTION PLAN, FROM THE ONE PLACE THAT BUILDS IT ─────────────────
   * Ellie, twice: "The what comes next page still isn't matching the action
   * items on the comms overview page."
   *
   * The first fix pointed What Comes Next at commsActionPlan and stopped
   * there. This page went on building its own three tiles, under the name
   * glancePlan, with its own rule for which dimension leads a domain: widest
   * gap, ties broken toward the dimension weighted more heavily in the axis
   * scoring. The server breaks a tie by taking the first in the domain's own
   * order. Ties are ordinary on a one-to-five scale, and over 12,000 domain
   * tiles the two rules choose a different lead dimension 11.1% of the time,
   * which is different advice on the two pages for the same couple. The 89%
   * that agreed is why it read as fine.
   *
   * Three more differences came out with it, none of them drifted yet:
   * the labels were typed again here in sentence case against the shared
   * list's title case, the colour was read off the domain's first dimension
   * rather than off the domain, and the extra line on "when things get hard"
   * was still here after she asked for it gone everywhere.
   *
   * So there is one builder. The detail page's one instruction is this same
   * tile, which is what its own note already claimed it was.
   */
  const commsTiles = commsActionPlan({ feedback, copy: _content });
  const commsTileFor = (dom) => commsTiles.find((t) => t.domain === dom) || null;

  const scaleLabels = ["Strongly A","Lean A","Neutral","Lean B","Strongly B"];

  // -- SIDE NAV ITEMS --
  // Group ordered dims by domain for sidebar display
  const personalityNavItems = [
    { label: "Overview", step: 0 },
    { label: "Detailed results", step: "detail-section", isSection: true },
    ...detailDomains.map((domain, i) => ({ label: domain.label, step: i + 1, isChild: true, italic: true, color: domain.color })),
  ];

  // -- STEP 0: OVERVIEW --
  if (step === 0) return (
    <MaybeNav noSideNav={noSideNav} navItems={personalityNavItems} currentStep={step} onGo={go} accent="#E8673A">
      {/* Brighter than the old near-black navy: this is the page people land
          on, and it was the darkest slide in the results. */}
      <ResultsSlide bg={gradientCss("comm-overview")}>
      <link href={FONT_URL} rel="stylesheet" />
      <div style={{ color: "white" }}>

        {/* Header */}
        <div style={{ marginBottom: "1.25rem" }}>
          {/* block: comm-overview/couple-type-lead */}
          {/* No page eyebrow. Ellie: "I want no page eyebrows throughout the
              results experience." The row that held it had no other child, so
              it went too rather than leaving an empty flex row's margin. */}
          <div style={{ fontSize: "clamp(1.8rem,6vw,2.8rem)", fontWeight: 700, fontFamily: HFONT, lineHeight: 1.0, marginBottom: "0.6rem" }}>{SC_TITLES["comm-overview"]}</div>
          
        </div>

        {/* ── COMPARISON BARS GRAPHIC ── */}
        <div style={{ background: "rgba(255,255,255,0.12)", border: "1px solid rgba(255,255,255,0.22)", borderRadius: 14, padding: "1rem 1.1rem", marginBottom: "1rem", boxShadow: "0 8px 26px rgba(0,0,0,0.16)" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.7rem" }}>
            {/* block: comm-overview/where-you-each-land */}
            <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, fontWeight: 700 }}>{SC_COPY.commPlacements}</div>
            <div style={{ display: "flex", gap: "0.85rem" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "0.3rem" }}>
                <div style={{ width: 7, height: 7, borderRadius: "50%", background: "#E8673A" }} />
                <span style={{ fontSize: "0.6rem", color: "rgba(255,255,255,0.45)", fontFamily: BFONT }}>{userName}</span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: "0.3rem" }}>
                <div style={{ width: 7, height: 7, borderRadius: "50%", background: "#6C7FFF" }} />
                <span style={{ fontSize: "0.6rem", color: "rgba(255,255,255,0.45)", fontFamily: BFONT }}>{partnerName}</span>
              </div>
            </div>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: "0.55rem" }}>
            {orderedDims.map(dim => {
              const f = byDim[dim];
              if (!f) return null;
              const m = DIM_META[f.dim];
              const myScore = myS[f.dim] ?? 3;
              const partScore = partS[f.dim] ?? 3;
              // Score is 1–5; normalize to 10–90% for visual range
              const myPct = Math.round(10 + (myScore - 1) * 20);
              const partPct = Math.round(10 + (partScore - 1) * 20);
              // 10px dots only overlap when within ~3% horizontally. Wider gaps stay on the line.
              const close = Math.abs(myPct - partPct) < 3;
              const myIsLeft = myPct <= partPct;
              const myDy = close ? (myIsLeft ? -4 : 4) : 0;
              const partDy = close ? (myIsLeft ? 4 : -4) : 0;
              return (
                <div key={f.dim} onClick={() => go(domainStepOf(f.dim))}
                  style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: "0.65rem" }}>
                  <span style={{ fontSize: "0.65rem", color: "rgba(255,255,255,0.65)", fontFamily: BFONT, flexShrink: 0, width: "clamp(88px,30%,120px)", lineHeight: 1.25 }}>{m.label}</span>
                  <div style={{ flex: 1, position: "relative", height: 6, background: "rgba(255,255,255,0.08)", borderRadius: 999, overflow: "visible" }}>
                    <div style={{ position: "absolute", top: "50%", transform: `translateY(calc(-50% + ${myDy}px))`, left: `${myPct}%`, width: 10, height: 10, borderRadius: "50%", background: "#E8673A", border: "1.5px solid rgba(14,11,7,0.3)", marginLeft: -5, zIndex: 2 }} />
                    <div style={{ position: "absolute", top: "50%", transform: `translateY(calc(-50% + ${partDy}px))`, left: `${partPct}%`, width: 10, height: 10, borderRadius: "50%", background: "#6C7FFF", border: "1.5px solid rgba(14,11,7,0.3)", marginLeft: -5, zIndex: 1 }} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Results-at-a-glance action plan — one item per domain */}
        <div style={{ marginBottom: "1rem" }}>
          <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, fontWeight: 700, marginBottom: "0.6rem" }}>Your action plan</div>
          <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
            {/* block: comm-overview/action-tiles */}
            {commsTiles.map((item, i) => (
              <div key={i} style={{ background: "rgba(255,255,255,0.13)", border: `1px solid ${item.color}66`, borderLeft: `4px solid ${item.color}`, borderRadius: 12, padding: "0.9rem 1.1rem", boxShadow: "0 6px 20px rgba(0,0,0,0.14)" }}>
                <div style={{ fontSize: "0.58rem", letterSpacing: "0.14em", textTransform: "uppercase", color: "rgba(255,255,255,0.95)", fontFamily: BFONT, fontWeight: 700, marginBottom: "0.4rem" }}>{item.label}</div>
                {item.title && <div style={{ fontSize: "0.82rem", color: "rgba(255,255,255,0.9)", fontFamily: BFONT, fontWeight: 600, marginBottom: "0.35rem" }}>{item.title}</div>}
                <div style={{ fontSize: "0.75rem", color: "rgba(255,255,255,0.6)", fontFamily: BFONT, lineHeight: 1.6 }}>{item.body}</div>
              </div>
            ))}
          </div>
        </div>


      </div>
      <NavButtons onBack={() => (onGoBack || (() => {}))()} backDisabled={!onGoBack} nextLabel={"Begin: " + detailDomains[0]?.label + " →"} onNext={() => go(1)} />
      </ResultsSlide>
    </MaybeNav>
  );

  // -- STEPS 1-N: ONE DIMENSION PER SCREEN (sorted order) --
  // -- STEPS 1-3: ONE GROUPED DOMAIN PAGE PER SCREEN --
  // The detail pages are grouped by domain (internal processing / how you connect /
  // when things get hard) rather than one page per dimension. Each page carries
  // the domain prose, one orientation bar per dimension in that domain, and the
  // side-by-side response dropdown (same on every page, all dimensions).
  if (step >= 1 && step <= nDetail) {
    const grp = detailDomains[step - 1];
    const isLast = step === nDetail;
    const nextGrp = detailDomains[step];
    const gDark = DIM_META[grp.dims[0]].dark;

    return (
    <MaybeNav noSideNav={noSideNav} navItems={personalityNavItems} currentStep={step} onGo={go} accent="#E8673A">
      <ResultsSlide bg={"linear-gradient(145deg, " + gDark + "dd, " + gDark + "99, #22204a)"}>
        <link href={FONT_URL} rel="stylesheet" />
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", marginBottom: "0.75rem" }}>
          <div style={{ marginLeft: "auto", fontSize: "0.68rem", color: "rgba(255,255,255,0.3)", fontFamily: BFONT }}>{step} of {nDetail}</div>
        </div>
        <div style={{ fontSize: "clamp(1.5rem,5vw,2rem)", fontWeight: 700, color: "white", lineHeight: 1.1, marginBottom: "1rem", fontFamily: HFONT }}>{grp.label}</div>

        {/* Domain prose */}
        {/* block: comm-domain/intro */}
        <p style={{ fontSize: "0.88rem", color: "rgba(255,255,255,0.75)", lineHeight: 1.8, fontFamily: BFONT, fontWeight: 300, margin: "0 0 1.5rem" }}>{grp.prose}</p>

        {/* Orientation overview: one bar per dimension in this domain */}
        <div style={{ background: "rgba(255,255,255,0.10)", borderRadius: 14, padding: "1.25rem 1.5rem", border: "1px solid rgba(255,255,255,0.16)" }}>
          <div style={{ fontSize: "0.62rem", textTransform: "uppercase", letterSpacing: "0.12em", color: "rgba(255,255,255,0.9)", fontWeight: 700, marginBottom: "1.1rem", fontFamily: BFONT }}>Overall orientation</div>
          <div style={{ display: "flex", flexDirection: "column", gap: "1.1rem" }}>
            {/* block: comm-domain/dimensions */}
            {grp.dims.map(dim => {
              const m = DIM_META[dim];
              return (
                <div key={dim}>
                  <div style={{ fontSize: "0.78rem", fontWeight: 700, color: "white", fontFamily: BFONT, marginBottom: "0.15rem" }}>{m.label}</div>
                  {/* Poles sit either side of the bar rather than above it, so
                      each dimension costs one row instead of three. */}
                  <div style={{ display: "flex", alignItems: "center", gap: "0.6rem" }}>
                    <span style={{ fontSize: "0.68rem", fontWeight: 600, color: "rgba(255,255,255,0.8)", fontFamily: BFONT, flexShrink: 0, width: "clamp(58px,18%,92px)", textAlign: "right", lineHeight: 1.2 }}>{m.ends[0]}</span>
                    {/* Inset so a marker at either extreme clears the pole
                        label instead of printing on it. */}
                    <div style={{ flex: 1, minWidth: 0, padding: "0 13px" }}>
                      <DimTrackViz myScore={myS[dim]} theirScore={partS[dim]} color={m.color} userName={userName} partnerName={partnerName} />
                    </div>
                    <span style={{ fontSize: "0.68rem", fontWeight: 600, color: "rgba(255,255,255,0.8)", fontFamily: BFONT, flexShrink: 0, width: "clamp(58px,18%,92px)", lineHeight: 1.2 }}>{m.ends[1]}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* ── MISREADS (admin only, ?misreads=1) ──────────────────────────
            Diagnostic view of how far each partner's Part 2 read is from what
            the other actually said. Never shown to customers. */}
        {(() => {
          let on = false;
          try { on = new URLSearchParams(window.location.search).get('misreads') === '1'; } catch {}
          if (!on) return null;
          const re = readErrorsFor(myAnswers, partnerAnswers);
          if (!re) return null;
          const inDomain = re.rows.filter(r => grp.dims.includes(r.dim));
          if (!inDomain.length) return null;
          const fmt = v => (v > 0 ? '+' : '') + v.toFixed(2);
          const tone = v => Math.abs(v) >= 1 ? "#FF9E80" : Math.abs(v) >= 0.5 ? "#FFD27F" : "rgba(255,255,255,0.75)";
          return (
            <div style={{ marginTop: "1.5rem", background: "rgba(0,0,0,0.22)", border: "1px dashed rgba(255,255,255,0.35)", borderRadius: 14, padding: "1.1rem 1.35rem" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: "0.7rem" }}>
                <span style={{ fontSize: "0.6rem", textTransform: "uppercase", letterSpacing: "0.14em", color: "rgba(255,255,255,0.9)", fontWeight: 700, fontFamily: BFONT }}>Misreads · admin only</span>
                <span style={{ fontSize: "0.6rem", color: "rgba(255,255,255,0.6)", fontFamily: BFONT }}>mean error {re.mean.toFixed(2)}</span>
              </div>
              <div style={{ fontSize: "0.62rem", color: "rgba(255,255,255,0.55)", fontFamily: BFONT, marginBottom: "0.6rem", lineHeight: 1.5 }}>
                How far each read sits from what the other actually said. Positive means read further toward the right-hand pole than they placed themselves.
              </div>
              {inDomain.map(r => (
                <div key={r.dim} style={{ display: "flex", justifyContent: "space-between", gap: "1rem", padding: "0.3rem 0", borderTop: "1px solid rgba(255,255,255,0.12)" }}>
                  <span style={{ fontSize: "0.72rem", color: "rgba(255,255,255,0.85)", fontFamily: BFONT }}>{DIM_META[r.dim].label}</span>
                  <span style={{ fontSize: "0.72rem", fontFamily: BFONT, whiteSpace: "nowrap" }}>
                    <span style={{ color: tone(r.mineOnThem) }}>{userName} on {partnerName} {fmt(r.mineOnThem)}</span>
                    <span style={{ color: "rgba(255,255,255,0.3)" }}>  ·  </span>
                    <span style={{ color: tone(r.theirsOnMe) }}>{partnerName} on {userName} {fmt(r.theirsOnMe)}</span>
                  </span>
                </div>
              ))}
            </div>
          );
        })()}

        {/* block: comm-domain/action-tile */}
        {/* ── ONE THING TO TRY — guidance for this domain's widest gap ──
            The title was a ternary on whether advice existed. It could not
            reach the other branch: the guard below returns null when there is
            no advice, so this only ever read "One thing to try". */}
        {(() => {
          /* The same tile Results at a glance shows for this domain, which is
             what the note above has always said this is. It was a second
             computation of it, from the page's own copy of the rule. */
          const tile = commsTileFor(grp.id);
          const advice = tile?.body || null;
          if (!advice) return null;
          return (
            <div style={{ marginTop: "1.5rem", background: "rgba(255,255,255,0.10)", border: "1px solid rgba(255,255,255,0.2)", borderLeft: `4px solid ${tile.color}`, borderRadius: 14, padding: "1.25rem 1.5rem" }}>
              <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: "1rem", marginBottom: "0.6rem" }}>
                {/* The label belongs HERE, on the detail page, where this tile
                    is the page's one instruction. It is dropped only where the
                    same tile is pulled onto Results at a glance, which names
                    the domain above it and shows three of them at once. */}
                <div style={{ fontSize: "0.62rem", textTransform: "uppercase", letterSpacing: "0.12em", color: "rgba(255,255,255,0.9)", fontWeight: 700, fontFamily: BFONT }}>One thing to try</div>
              </div>
              <p style={{ fontSize: "0.86rem", color: "rgba(255,255,255,0.88)", fontFamily: BFONT, lineHeight: 1.7, margin: 0 }}>{advice}</p>
            </div>
          );
        })()}

        {/* block: comm-domain/side-by-side */}
        {/* Two-column arrows-to-bar side-by-side (all dims, exercise order) — dropdown */}
        <details style={{ marginTop: "1.5rem", background: "rgba(255,255,255,0.05)", borderRadius: 14, border: "1px solid rgba(255,255,255,0.14)" }}>
          <summary style={{ listStyle: "none", cursor: "pointer", padding: "1.1rem 1.5rem", fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: "rgba(255,255,255,0.85)", fontWeight: 700, fontFamily: BFONT, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <span>Side by side {grp.label.toLowerCase()} responses</span>
            <span style={{ fontSize: "0.9rem", opacity: 0.6 }}>▾</span>
          </summary>
          <div style={{ padding: "0.5rem 1.5rem 1.5rem" }}>
            <SideBySideResponses dims={grp.dims} myAnswers={myAnswers} partnerAnswers={partnerAnswers} userName={userName} partnerName={partnerName} />
          </div>
        </details>

        <NavButtons
          onBack={() => go(step - 1)}
          onNext={() => (isLast ? (onGoExpectations || (() => {})) : () => go(step + 1))()}
          nextLabel={isLast ? (onGoExpectations ? "Expectations →" : "Done") : (nextGrp.label + " →")}
          nextDisabled={isLast && !onGoExpectations}
        />
      </ResultsSlide>
    </MaybeNav>
    );
  }


  // ── NO SUMMARY PAGE ──────────────────────────────────────────────────────
  // A fourth Communication page lived here, reachable only by a step past the
  // last domain, which no nav item and no next button produces. Deleted with
  // its DIM_HEADLINES table, which was keyed to an older dimension set:
  // energy, decision, affection, planning, expressiveness, togetherness and
  // change, of which only energy and conflict still exist, so eight of the ten
  // live dimensions fell through to a generic line.
  //
  // A step out of range renders nothing rather than a stale page.
  return null;
}




// Unique origin context per gap -- avoids repeated phrases (item 12)
// Expectations pages share one background. The previous values read near-black:
// the category pages had no bg at all and fell through to the flat #0f0c29.
// Detail-page ground. Lifted from near-black navy: the glance page moved to a
// brighter treatment and these read as murky beside it. Still darker than the
// glance page, so the two are distinguishable.
// EXP_BG, the one violet every expectations page used to draw, is gone: each
// page is on its own category's colour now. The stops it named live on as the
// fallback in groundForCategory, for a category with no colour of its own.

function ExpectationsResults({ myAnswers, partnerAnswers, userName, partnerName, forcedSection, noSideNav = false, onGoWhatComesNext, onGoBack, onExternalGo, coupleTypeCode = null, coupleTypeName = null, coupleTypeColor = "#1B5FE8" }) {
  // ── Fixed 5 display categories ──────────────────────────────────────────────
  // ── Step system: 0=overview, "convo-0".."convo-4"=individual cats,
  //                "action-plan"=plan, "summary"=summary.
  // The old standalone Common Ground / Conversations pages are gone (7.3);
  // their content lives on each category page. Legacy links land on overview.
  const sectionToStep = (s) => {
    if (!s || s === "overview") return 0;
    if (s === "common-ground" || s === "conversations") return 0;
    if (s === "summary") return "summary";
    // "convo-N" comes in directly from UnifiedResults routing — pass through as-is
    if (typeof s === "string" && s.startsWith("convo-")) return s;
    // Category IDs like "household", "financial" — find their convo index
    const catIdx = FIXED_CATS.findIndex(c => c.id === s);
    if (catIdx >= 0) return `convo-${catIdx}`;
    return 0;
  };

  const [step, setStep] = useState(sectionToStep(forcedSection));
  useEffect(() => { setStep(sectionToStep(forcedSection)); }, [forcedSection]);
  const [showRaw, setShowRaw] = useState(false);

  const go = (s) => {
    setStep(s);
    if (onExternalGo) onExternalGo(s);
    const sc = document.querySelector("[data-results-scroll]");
    if (sc) sc.scrollTop = 0; else window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ── Build rows from responsibilities ─────────────────────────────────────────
  // Career answers are relative to whoever answered ("Primarily mine" /
  // "Primarily my partner's"). Normalize to an absolute person so the user's
  // and partner's answers are on the same reference. mine = the user's answer,
  // theirs = the partner's answer.
  const normRespVal = (v, isUser) => normRespValue(v, isUser, userName, partnerName);
  const rows = [];
  RESPONSIBILITY_CATEGORIES.forEach(cat => {
    cat.items.forEach(item => {
      const key = `${cat.id}__${item}`;
      const rawMine = myAnswers.responsibilities?.[key];
      const rawTheirs = partnerAnswers.responsibilities?.[mirrorRespKey(key)];
      if (!rawMine || !rawTheirs) return;
      const score = scoreRespClient(rawMine, rawTheirs, userName, partnerName);
      const mine = normRespVal(rawMine, true);
      const theirs = normRespVal(rawTheirs, false);
      // agrees() from api/_lib/expectations.js, not `mine === theirs`.
      //
      // Comparing the two display names happened to give the right answer for
      // most pairs and the wrong one wherever "Doesn't apply" appeared, and the
      // server had its own rule that dropped those rows instead. One couple,
      // two products, two different sets of results. There is one rule now and
      // this is a call to it.
      rows.push({ category: cat.label, catId: cat.id, item: substName(item, userName, partnerName), mine, theirs, aligned: agrees(rawMine, rawTheirs) === true, score });
    });
  });

  // Life questions — all grouped as "Life & Values"
  const lifeRows = LIFE_QUESTIONS.map(q => {
    const mine = myAnswers.life?.[q.id];
    const theirs = partnerAnswers.life?.[mirrorLifeId(q.id)];
    return {
      category: "Life & Values", catId: "life", item: substName(q.text, userName, partnerName),
      mine, theirs,
      aligned: mine === theirs,
      score: scoreLqClient(mine, theirs, q.options),
    };
  }).filter(r => r.mine && r.theirs);

  // ── Couple type context for expectations overview ────────────────────────────
  // The couple type is defined by communication scores and is passed in from the
  // parent (coupleTypeCode/Name/Color). Previously this recomputed the type from
  // ex2 expectations answers via calcDimScores, which produced a DIFFERENT type
  // than the rest of the results (e.g. "ignition" here vs "jumpstart" elsewhere).
  const EXP_COUPLE_CONTEXT = {
    WW: "Two Initiators both lean toward open expression. When expectations differ, you'll likely name it, the work is making sure you've actually heard each other before resolving.",
    XX: "The collaboration tend to move through disagreement efficiently. Watch that practical resolution doesn't skip the emotional weight of what's actually at stake.",
    YY: "Two Feelers both carry feeling deeply. When an expectation gap lands hard, give each other the space before the conversation. It'll go better for it.",
    ZZ: "Two Holders may let things sit. Build a deliberate practice of raising misaligned expectations before they calcify into resentment.",
    WX: "One of you will surface expectation gaps readily; the other processes first. The one who brings it up isn't necessarily the one who cares more.",
    WY: "Different conflict clocks apply here too. The one who names the expectation gap first isn't pushing. They're ready. The other will need a moment before the conversation is possible.",
    WZ: "The Initiator will name gaps; The Protector will need time to respond. That asymmetry is wiring, not avoidance, name that explicitly.",
    XY: "The Anchor wants to resolve quickly; The Feeler needs space to process. Neither is wrong. Build a return window into any expectation conversation.",
    XZ: "Both of you hold things close. Expectation gaps that go unnamed can accumulate quietly, schedule the conversation, don't wait for it to happen organically.",
    YZ: "Both withdraw under pressure. When an expectation surfaces, one of you will need to come back first, let that be the agreed pattern.",
  };
  const pairKey = coupleTypeCode ? coupleTypeCode.split("").sort().join("") : null;
  const coupleTypeExpContext = pairKey ? EXP_COUPLE_CONTEXT[pairKey] || null : null;


  const allRows = [...rows, ...lifeRows];
  const aligned = allRows.filter(r => r.aligned);
  const gaps = allRows.filter(r => !r.aligned);

  const resolveLabel = (val) => {
    if (!val) return val;
    if (val === "Partner A") return userName;
    if (val === "Partner B") return partnerName;
    return val;
  };

  // Stats per fixed category
  const catData = FIXED_CATS.map(fc => {
    const catRows = allRows.filter(r => r.catId === fc.id);
    const catGaps = catRows.filter(r => !r.aligned);
    const catAligned = catRows.filter(r => r.aligned);
    return { ...fc, rows: catRows, gaps: catGaps, aligned: catAligned, hasGaps: catGaps.length > 0, fullyAligned: catGaps.length === 0 && catRows.length > 0 };
  });

  // Fully aligned cats (no gaps at all)
  const fullyAlignedCats = catData.filter(c => c.fullyAligned);

  // Results at a glance: the three categories with the widest gaps, one card
  // each, leading with the first topic to talk about. The full list lives on
  // the Expectations Action Plan page.
  // Every category that has gaps, with all of its gap topics. Drives the full
  // checklist on the glance page (it used to be the top three categories with
  // one topic each, which hid most of the list).
  const checklistItems = FIXED_CATS
    .map(fc => ({ ...fc, gapItems: gaps.filter(r => r.catId === fc.id) }))
    .filter(c => c.gapItems.length > 0);

  // ── Nav items ─────────────────────────────────────────────────────────────────
  const expectationsNavItems = [
    { label: "Overview", step: 0 },
    { label: "Detailed results", step: "detail-section", isSection: true },
    ...FIXED_CATS.map((fc, i) => ({
      label: fc.label, step: `convo-${i}`, isChild: true, italic: true,
      onClick: () => go(`convo-${i}`),
    })),
  ];

  // navCurrentStep passed directly — SideNav matches by exact equality
  const navCurrentStep = step;

  // ── STEP 0: OVERVIEW ─────────────────────────────────────────────────────────
  if (step === 0) {
    return (
      <MaybeNav noSideNav={noSideNav} navItems={expectationsNavItems} currentStep={navCurrentStep} onGo={go} accent="#1B5FE8">
        {/* Brighter than the detail pages, which are on their category's own
            colour. This is the landing page for the section. */}
        <ResultsSlide bg={gradientCss("exp-overview")}>
          <link href={FONT_URL} rel="stylesheet" />
          <div style={{ color: "white" }}>
            {/* Header */}
            <div style={{ marginBottom: "1.25rem" }}>
              <div style={{ fontSize: "clamp(1.8rem,6vw,2.8rem)", fontWeight: 700, fontFamily: HFONT, lineHeight: 1.0, marginBottom: "0.6rem" }}>{SC_TITLES["exp-overview"]}</div>

            </div>

            {/* ── EXPECTATIONS ALIGNMENT SCALE ── */}
            <div style={{ background: "rgba(255,255,255,0.12)", border: "1px solid rgba(255,255,255,0.22)", borderRadius: 14, padding: "1rem 1.1rem", marginBottom: "1rem", boxShadow: "0 8px 26px rgba(0,0,0,0.16)" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "0.7rem" }}>
                {/* block: exp-overview/by-category */}
                <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, fontWeight: 700 }}>Alignment by category</div>
                <div style={{ fontSize: "0.6rem", color: "rgba(255,255,255,0.3)", fontFamily: BFONT }}>% aligned</div>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: "0.55rem" }}>
                {catData.filter(fc => fc.rows.length > 0).map(fc => {
                  // Similarity-based pct: mean of item scores in [0,1], rounded
                  // to %. The same methodology as the headline alignPct, and now
                  // as the workbook: this comment claimed all three agreed and
                  // the workbook was counting exact matches, which came out up
                  // to 71 points lower on the same answers. Rows the scorer
                  // cannot read drop out of the mean rather than skewing it.
                  const scored = fc.rows.filter(r => r.score != null);
                  const pct = scored.length
                    ? Math.round((scored.reduce((a, r) => a + r.score, 0) / scored.length) * 100)
                    : 0;
                  const isStrong = pct >= 75;
                  /* ── THE SAME RAMP THE APP DRAWS THESE BARS WITH ─────────
                     This was green above 75, orange above 40 and #F87171 below,
                     a red that appears nowhere else. The app draws the same
                     expectations bars green above 80, amber above 50 and orange
                     below, through a function whose own comment says it is
                     "the same three the expectations categories use on their own
                     bars, so a percentage means the same thing wherever it
                     appears". It was not the same three, and the two surfaces
                     coloured one number two ways.

                     `isStrong` keeps its own threshold because it is not about
                     colour: it decides the wording beside the bar. */
                  const barColor = alignedTone(pct);
                  return (
                    <div key={fc.id} onClick={() => go(`convo-${FIXED_CATS.findIndex(c => c.id === fc.id)}`)}
                      style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: "0.55rem" }}>
                      <span style={{ fontSize: "0.63rem", color: "rgba(255,255,255,0.65)", fontFamily: BFONT, flexShrink: 0, width: "clamp(96px,32%,130px)", lineHeight: 1.25 }}>{fc.label}</span>
                      <div style={{ flex: 1, position: "relative", height: 6, background: "rgba(255,255,255,0.08)", borderRadius: 999 }}>
                        <div style={{ position: "absolute", left: 0, top: 0, height: "100%", width: `${pct}%`, background: barColor, borderRadius: 999, transition: "width 0.3s" }} />
                      </div>
                      <span style={{ fontSize: "0.6rem", color: barColor, fontFamily: BFONT, fontWeight: 700, flexShrink: 0, minWidth: "32px", textAlign: "right" }}>{pct}%</span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* ── CONVERSATIONS TO HAVE — every gap topic, grouped by category ── */}
            {gaps.length > 0 ? (
              <div style={{ marginBottom: "1rem" }}>
                {/* block: exp-overview/conversations */}
                <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, fontWeight: 700, marginBottom: "0.5rem" }}>Conversations to have</div>
                <p style={{ fontSize: "0.75rem", color: "rgba(255,255,255,0.62)", fontFamily: BFONT, lineHeight: 1.55, margin: "0 0 0.75rem" }}>
                  {gaps.length} topic{gaps.length !== 1 ? "s" : ""} where your assumptions differ, across {checklistItems.length} area{checklistItems.length !== 1 ? "s" : ""}. Open an area to see its full list.
                </p>
                <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
                  {/* Collapsed by default so the page stays scannable. The
                      summary row carries the count, the word "topics", and a
                      chevron, so it reads as openable rather than as a link. */}
                  {checklistItems.map(fc => (
                    <details key={fc.id} style={{ background: "rgba(255,255,255,0.13)", borderRadius: 14, overflow: "hidden", border: "1px solid rgba(255,255,255,0.22)", borderLeft: `4px solid ${fc.color}`, boxShadow: "0 6px 20px rgba(0,0,0,0.14)" }}>
                      <summary style={{ listStyle: "none", cursor: "pointer", background: "rgba(255,255,255,0.09)", padding: "0.7rem 1rem", display: "flex", justifyContent: "space-between", alignItems: "center", gap: "0.75rem" }}>
                        <span style={{ fontSize: "0.68rem", fontWeight: 700, color: "rgba(255,255,255,0.95)", textTransform: "uppercase", letterSpacing: "0.1em", fontFamily: BFONT }}>{fc.label}</span>
                        <span style={{ display: "flex", alignItems: "center", gap: "0.5rem", flexShrink: 0 }}>
                          <span style={{ fontSize: "0.62rem", color: "rgba(255,255,255,0.75)", fontFamily: BFONT }}>{fc.gapItems.length} topic{fc.gapItems.length !== 1 ? "s" : ""}</span>
                          <span style={{ fontSize: "0.6rem", color: "rgba(255,255,255,0.6)", fontFamily: BFONT, letterSpacing: "0.06em" }}>Show</span>
                          <span style={{ fontSize: "0.8rem", color: "rgba(255,255,255,0.75)", lineHeight: 1 }}>▾</span>
                        </span>
                      </summary>
                      <div style={{ borderTop: "1px solid rgba(255,255,255,0.16)" }}>
                        {fc.gapItems.map((g, gi) => (
                          <div key={gi} style={{ display: "flex", alignItems: "flex-start", gap: "0.75rem", padding: "0.6rem 1rem", borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
                            <div style={{ width: 17, height: 17, borderRadius: 4, border: "1.5px solid rgba(255,255,255,0.55)", background: "rgba(255,255,255,0.12)", flexShrink: 0, marginTop: 1 }} />
                            <span style={{ fontSize: "0.8rem", color: "rgba(255,255,255,0.88)", fontFamily: BFONT, lineHeight: 1.45 }}>{g.item}</span>
                          </div>
                        ))}
                        <div onClick={() => go(`convo-${FIXED_CATS.findIndex(x => x.id === fc.id)}`)}
                          style={{ padding: "0.6rem 1rem", cursor: "pointer", fontSize: "0.7rem", fontWeight: 600, color: "rgba(255,255,255,0.8)", fontFamily: BFONT }}>
                          Open {fc.label} →
                        </div>
                      </div>
                    </details>
                  ))}
                </div>
              </div>
            ) : (
              <div style={{ background: "rgba(16,185,129,0.16)", border: "1px solid rgba(16,185,129,0.35)", borderRadius: 16, padding: "1.5rem", textAlign: "center", marginBottom: "1rem" }}>
                <div style={{ fontSize: "0.9rem", fontWeight: 700, color: "white", fontFamily: BFONT }}>Aligned across every area.</div>
                <div style={{ fontSize: "0.78rem", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, marginTop: "0.35rem" }}>Nothing to work through. Keep staying current with each other.</div>
              </div>
            )}

          </div>
          <NavButtons onBack={() => (onGoBack || (() => {}))()} backDisabled={!onGoBack} onNext={() => go("convo-0")} nextLabel={`${FIXED_CATS[0].label} →`} />
        </ResultsSlide>
      </MaybeNav>
    );
  }

  // ── STEP 1 / 2 (Common Ground, Conversations Worth Having) removed (7.3).
  // Both are now folded into the per-category pages: each one lists the
  // conversations to have and the responsibilities already agreed on. Any
  // stale link to those steps lands on the overview.
  if (step === 1 || step === 2) { setTimeout(() => go(0), 0); return null; }

  const convoMatch = typeof step === "string" && step.startsWith("convo-");
  if (convoMatch) {
    const catIdx = parseInt(step.split("-")[1]);
    const fc = FIXED_CATS[catIdx];
    // A bad index (NaN, -1, out of range) used to crash on fc.id below. Send
    // stray links back to the overview instead of the error boundary.
    if (!fc) { setTimeout(() => go(0), 0); return null; }
    const thisCatGaps = gaps.filter(r => r.catId === fc.id);
    const thisCatAligned = aligned.filter(r => r.catId === fc.id);
    const isLastCat = catIdx === FIXED_CATS.length - 1;

    const catNarration = CATEGORY_INTRO;

    return (
      <MaybeNav noSideNav={noSideNav} navItems={expectationsNavItems} currentStep={navCurrentStep} onGo={go} accent="#1B5FE8">
        {/* The category's own colour, from api/_lib/section-grounds.js, which
            the app reads through the results nav. `fc.bg` never existed on a
            category, so every one of the six drew EXP_BG and the colour each
            carries on its tile, its pill and its bar stopped at its own page. */}
        <ResultsSlide bg={`linear-gradient(145deg, ${groundForCategory(fc.color).join(", ")})`}>
          <link href={FONT_URL} rel="stylesheet" />

          {/* The exercise eyebrow was removed from here earlier and left an
              empty flex row behind, which still contributed its bottom margin.
              No page eyebrows anywhere in results. */}
          {/* Header */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: "0.5rem" }}>
            <div style={{ fontSize: "clamp(1.5rem,5vw,2rem)", fontFamily: HFONT, fontWeight: 700, letterSpacing: "-0.02em", color: "white", lineHeight: 1.1 }}>
              {fc.label}
            </div>
            <span style={{ fontSize: "0.68rem", color: "rgba(255,255,255,0.35)", fontFamily: BFONT, paddingBottom: "0.1rem" }}>{catIdx + 1} of {FIXED_CATS.length}</span>
          </div>

          {/* A dividing line, not a progress bar.
              Ellie asked for this on the app first and then here: the count
              beside the heading already says where you are, and a bar
              measuring how far through a set of conversations you have read
              turns reading your own results into a task with a completion
              percentage. The category's colour stays, because it is what ties
              this page to its tile on Results at a glance. */}
          {/* The rule under the title is gone, on both surfaces. Ellie: "can
              we remove the orange bar under the title and above 'a tip for you
              both' on all expectations detailed pages". */}

          {/* ── FOCAL POINT: Couple-type starter ── */}
          <div style={{ background: "rgba(255,255,255,0.07)", border: "1.5px solid rgba(255,255,255,0.13)", borderRadius: 14, padding: "1.1rem 1.3rem", marginBottom: "1.4rem" }}>
            {/* White, on both surfaces. It was the couple type's own colour,
                which on six different category grounds is six different
                amounts of legible. */}
            <div style={{ fontSize: "0.55rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "white", fontFamily: BFONT, fontWeight: 700, marginBottom: "0.55rem" }}>
              {coupleTypeName ? SC_COPY.expectationsTip(userName, partnerName) : "A tip for you both"}
            </div>
            <p style={{ fontSize: "0.88rem", color: "rgba(255,255,255,0.85)", fontFamily: BFONT, fontWeight: 400, lineHeight: 1.7, margin: 0 }}>
              {(coupleTypeName && EXP_CAT_STARTERS[fc.id]?.[pairKey])
                ? EXP_CAT_STARTERS[fc.id][pairKey]
                : catNarration[fc.id]}
            </p>
          </div>

          {thisCatGaps.length === 0 ? null : (() => {
            const childLabel = (val) => {
              if (!val) return "—";
              if (val === "N/A" || val === "Didn't apply") return "—";
              return val;
            };
            const hasAnyChildhood = thisCatGaps.some(g => {
              const ck = `${fc.id}__${g.item}`;
              return myAnswers?.childhood?.[ck] || partnerAnswers?.childhood?.[ck];
            });
            const gridCols = hasAnyChildhood ? "1.6fr 1fr 1fr 1fr 1fr" : "1.6fr 1fr 1fr";
            const nameSpan = hasAnyChildhood ? "span 2" : "span 1";
            return (
              <div style={{ background: "white", borderRadius: 14, overflow: "hidden", border: `1.5px solid ${fc.color}20` }}>
                {/* Section label */}
                <div style={{ padding: "0.65rem 1rem", borderBottom: `1px solid ${fc.color}18`, background: fc.color + "0c" }}>
                  <span style={{ fontSize: "0.62rem", fontWeight: 800, letterSpacing: "0.2em", textTransform: "uppercase", color: fc.color, fontFamily: BFONT }}>Conversations to have</span>
                </div>
                {/* ── THE THREE GRIDS SHARE ONE SET OF COLUMNS ──────────
                    Ellie: "Emotional labor, names in rows don't look centered
                    with Expects and Experienced column titles."

                    On every category, not only that one. This row carried a
                    rem of horizontal padding and the two rows under it carried
                    none, so the same `1.6fr 1fr 1fr 1fr 1fr` resolved to 92.5pt
                    columns here and 98.2pt below: measured, thirty-two points
                    of difference, which is exactly the padding. The names
                    drifted left of the columns they name, a little more with
                    each column, so the first looked right and the second was
                    visibly out.

                    The padding moves onto the cells, where it does not change
                    what a fraction of the row is worth. */}
                <div style={{ display: "grid", gridTemplateColumns: gridCols, gap: 0, paddingTop: "0.55rem" }}>
                  <div />
                  <div style={{ gridColumn: nameSpan, textAlign: "center", fontSize: "0.62rem", fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: fc.color, fontFamily: BFONT, paddingBottom: "0.4rem", borderBottom: `2.5px solid ${fc.color}40` }}>{userName}</div>
                  <div style={{ gridColumn: nameSpan, textAlign: "center", fontSize: "0.62rem", fontWeight: 700, letterSpacing: "0.12em", textTransform: "uppercase", color: "#777", fontFamily: BFONT, paddingBottom: "0.4rem", borderBottom: "2.5px solid rgba(0,0,0,0.12)" }}>{partnerName}</div>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: gridCols, gap: 0, borderBottom: `1px solid ${fc.color}15` }}>
                  <div style={{ padding: "0.25rem 1rem 0.4rem" }} />
                  <div style={{ background: fc.color + "0a", padding: "0.2rem 0 0.4rem", textAlign: "center", fontSize: "0.5rem", fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", color: fc.color, fontFamily: BFONT }}>Expects</div>
                  {hasAnyChildhood && <div style={{ background: fc.color + "06", padding: "0.2rem 0 0.4rem", textAlign: "center", fontSize: "0.5rem", fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", color: fc.color, fontFamily: BFONT, opacity: 0.6 }}>Experienced</div>}
                  <div style={{ background: "rgba(0,0,0,0.025)", borderLeft: "1px solid rgba(0,0,0,0.07)", padding: "0.2rem 0 0.4rem", textAlign: "center", fontSize: "0.5rem", fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", color: "#999", fontFamily: BFONT }}>Expects</div>
                  {hasAnyChildhood && <div style={{ background: "rgba(0,0,0,0.015)", padding: "0.2rem 0 0.4rem", textAlign: "center", fontSize: "0.5rem", fontWeight: 600, letterSpacing: "0.08em", textTransform: "uppercase", color: "#bbb", fontFamily: BFONT }}>Experienced</div>}
                </div>
                {/* Rows */}
                {/* block: exp-conversation/questions */}
                {thisCatGaps.map((g, gi) => {
                  const ck = `${fc.id}__${g.item}`;
                  const myChild = myAnswers?.childhood?.[ck];
                  const partChild = partnerAnswers?.childhood?.[ck];
                  // What "Both of us" turned out to mean, shown under the
                  // answer it refines. Asked every time and shown nowhere
                  // until now.
                  const myDetail = myAnswers?.bothDetail?.[ck] || null;
                  const partDetail = partnerAnswers?.bothDetail?.[ck] || null;
                  const isLast = gi === thisCatGaps.length - 1;
                  /* No horizontal padding on the row, for the reason above the
                     names grid: three grids share one column template and a
                     padding here makes this row's columns narrower than the
                     headers above it, so an answer sits left of the column that
                     names it. The inset moves onto the first cell, which is
                     where the header row already carries it.

                     A block comment above the `return`, not a JSX comment under
                     it: nothing may sit between `return (` and the root element,
                     which is the third time that has cost a build this week. */
                  return (
                    <div key={gi} style={{ display: "grid", gridTemplateColumns: gridCols, gap: 0, padding: "0.65rem 0", borderTop: `1px solid ${fc.color}10`, alignItems: "center", background: gi % 2 === 1 ? fc.color + "06" : "transparent" }}>
                      {/* Responsibility name */}
                      <div style={{ fontSize: "0.78rem", fontWeight: 500, color: "#2a2848", fontFamily: BFONT, lineHeight: 1.35, paddingLeft: "1rem", paddingRight: "0.75rem" }}>{g.item}</div>
                      {/* userName expects, and what Both turned out to mean */}
                      <div style={{ fontSize: "0.8rem", fontWeight: 700, color: fc.color, fontFamily: BFONT, lineHeight: 1.35, textAlign: "center", background: fc.color + "0d", borderRadius: 6, padding: "0.2rem 0.4rem", margin: "0 0.25rem" }}>
                        {respDisplay(resolveLabel(g.mine), myDetail) || "—"}
                      </div>
                      {/* userName experienced */}
                      {hasAnyChildhood && <div style={{ fontSize: "0.72rem", color: "#aaa", fontFamily: BFONT, fontStyle: "italic", lineHeight: 1.35, textAlign: "center" }}>{childLabel(myChild)}</div>}
                      {/* partnerName expects, and what Both turned out to mean */}
                      <div style={{ fontSize: "0.8rem", fontWeight: 700, color: "#555", fontFamily: BFONT, lineHeight: 1.35, textAlign: "center", background: "rgba(0,0,0,0.04)", borderRadius: 6, padding: "0.2rem 0.4rem", margin: "0 0.25rem", borderLeft: "1px solid rgba(0,0,0,0.07)" }}>
                        {respDisplay(resolveLabel(g.theirs), partDetail) || "—"}
                      </div>
                      {/* partnerName experienced */}
                      {hasAnyChildhood && <div style={{ fontSize: "0.72rem", color: "#aaa", fontFamily: BFONT, fontStyle: "italic", lineHeight: 1.35, textAlign: "center" }}>{childLabel(partChild)}</div>}
                    </div>
                  );
                })}
              </div>
            );
          })()}

          {/* ── Already aligned in this category (7.3) ── */}
          {thisCatAligned.length > 0 && (
            <div style={{ marginTop: thisCatGaps.length > 0 ? "1rem" : 0, background: ALIGNED_PANEL.fill, border: `1.5px solid ${ALIGNED_PANEL.border}`, borderRadius: 14, overflow: "hidden" }}>
              {/* Opaque, in its own deep green. It was the section green at 7
                  per cent over the page's ground, which on Career & Work's
                  orange page came out orange. */}
              <div style={{ padding: "0.65rem 1rem", borderBottom: `1px solid ${ALIGNED_PANEL.border}`, background: ALIGNED_PANEL.head, display: "flex", alignItems: "center", gap: "0.5rem" }}>
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke={ALIGNED_PANEL.accent} strokeWidth="3" strokeLinecap="round"><polyline points="20 6 9 17 4 12"/></svg>
                <span style={{ fontSize: "0.62rem", fontWeight: 800, letterSpacing: "0.2em", textTransform: "uppercase", color: ALIGNED_PANEL.accent, fontFamily: BFONT }}>Already aligned</span>
                <span style={{ fontSize: "0.62rem", color: ALIGNED_PANEL.text, opacity: 0.55, fontFamily: BFONT, marginLeft: "auto" }}>{thisCatAligned.length} item{thisCatAligned.length !== 1 ? "s" : ""}</span>
              </div>
              <div>
                {thisCatAligned.map((a, ai) => (
                  <div key={ai} style={{ display: "grid", gridTemplateColumns: "1.6fr 1fr", gap: 0, padding: "0.55rem 1rem", borderTop: ai === 0 ? "none" : `1px solid ${ALIGNED_PANEL.border}`, alignItems: "center" }}>
                    <div style={{ fontSize: "0.76rem", color: ALIGNED_PANEL.text, fontFamily: BFONT, lineHeight: 1.35, paddingRight: "0.75rem" }}>{a.item}</div>
                    <div style={{ fontSize: "0.76rem", fontWeight: 600, color: ALIGNED_PANEL.text, fontFamily: BFONT, textAlign: "center", background: "rgba(4,120,87,0.08)", borderRadius: 6, padding: "0.2rem 0.4rem" }}>{resolveLabel(a.mine) || "—"}</div>
                  </div>
                ))}
              </div>
              <div style={{ padding: "0.5rem 1rem", borderTop: `1px solid ${ALIGNED_PANEL.border}` }}>
                <span style={{ fontSize: "0.7rem", color: ALIGNED_PANEL.accent, fontFamily: BFONT, fontWeight: 300 }}>{thisCatGaps.length === 0 ? `Fully aligned here. You and ${partnerName} are on the same page across all ${thisCatAligned.length} item${thisCatAligned.length !== 1 ? "s" : ""}.` : ""}</span>
              </div>
            </div>
          )}

          <NavButtons
            onBack={() => catIdx > 0 ? go(`convo-${catIdx - 1}`) : go(0)}
            onNext={() => isLastCat ? (onGoWhatComesNext || (() => {}))() : go(`convo-${catIdx + 1}`)}
            nextLabel={isLastCat ? "Action Plan →" : `Next: ${FIXED_CATS[catIdx + 1].label} →`}
          />
        </ResultsSlide>
      </MaybeNav>
    );
  }

  // ── ACTION PLAN ──────────────────────────────────────────────────────────────

  return null;
}


const admiredNounLower = v => { const n = admiredNoun(v); return n ? n.toLowerCase() : n; };


// isSubstantive and quoted moved to api/_lib/reflection-insights.js with the
// code that uses them. Imported at the top of this file.


function AnniversaryExercise({ userName, partnerName, onComplete, onBack, partnerPronouns = "" }) {
  // Independent possessive for the partner ("theirs"/"hers"/"his"), used in the
  // completion copy ("When {partnerName} finishes ___").
  const _pPos = pronoun(partnerPronouns, "pos");
  const partnerPossAbs = _pPos === "their" ? "theirs" : _pPos === "her" ? "hers" : _pPos;
  // Mid-exercise persistence — same pattern as Ex01 and Ex02.
  const [answers, setAnswers] = useState(() => {
    try {
      const raw = localStorage.getItem('attune_ex3_progress');
      if (!raw) return {};
      const s = JSON.parse(raw);
      return s?.answers || {};
    } catch { return {}; }
  });
  const [step, setStep] = useState(() => {
    try {
      const raw = localStorage.getItem('attune_ex3_progress');
      if (!raw) return 0;
      const s = JSON.parse(raw);
      return typeof s?.step === 'number' ? s.step : 0;
    } catch { return 0; }
  });
  // 'intro' → 'questions'. Show intro only for fresh starts (no saved progress).
  // Also used to trigger the resume toast when the user comes back mid-exercise.
  const [resumedMidExercise] = useState(() => {
    try {
      const raw = localStorage.getItem('attune_ex3_progress');
      const s = raw ? JSON.parse(raw) : null;
      return !!(s?.answers && Object.keys(s.answers).length > 0);
    } catch { return false; }
  });
  const [phase, setPhase] = useState(() => resumedMidExercise ? 'questions' : 'intro');

  // Persist on every change
  useEffect(() => {
    const snapshot = { answers, step };
    try { localStorage.setItem('attune_ex3_progress', JSON.stringify(snapshot)); } catch {}
    if (phase === 'questions') {
      syncProgressCrossDevice(3, snapshot);
    }
  }, [answers, step, phase]);

  const total = ANNIVERSARY_QUESTIONS.length;
  const q = ANNIVERSARY_QUESTIONS[step];
  // Scale questions are answered when they have a numeric value; text questions need non-empty string
  const isAnswered = (q, answers) => {
    if (q.type === "scale") return answers[q.id] !== undefined;
    if (q.type === "pick") return !!answers[q.id];
    if (q.type === "rank") return Array.isArray(answers[q.id]) && answers[q.id].length === q.options.length;
    return !!answers[q.id]?.trim();
  };
  const allDone = ANNIVERSARY_QUESTIONS.every(q => isAnswered(q, answers));

  const handleNext = () => {
    if (step < total - 1) setStep(step + 1);
  };
  const handleBack = () => {
    if (step > 0) setStep(step - 1);
    else onBack();
  };

  // The opening page, from the module both surfaces read.
  const ex3Intro = exerciseIntro('ex3', { partner: partnerName });

  // ── Intro screen (Exercise 03) ────────────────────────────────────────
  // Mirrors the Expectations intro format: eyebrow, hook title, concrete
  // description, follow-up, duration, button. Shown once per fresh start;
  // resumed sessions skip straight to questions.
  if (phase === 'intro') {
    return (
      <div style={{ maxWidth: 560, margin: "0 auto", padding: "1.5rem 1rem 2rem", animation: "fadeIn 0.5s ease" }}>
        <link href={FONT_LINK} rel="stylesheet" />
        <style>{'@keyframes fadeIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}'}</style>
        {/* The cover, keeping this page's timing line. */}
        <CoverCard accent="#10b981" minHeight="auto">
          <p style={{ fontSize: "0.62rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#10b981", marginBottom: "1.25rem", fontFamily: font.body }}>Exercise 03 · Our Relationship Story</p>
          <p style={{ fontFamily: font.display, fontSize: "1.8rem", fontWeight: 700, color: C.ink, lineHeight: 1.15, marginBottom: "1.25rem", maxWidth: 420 }}>
            {ex3Intro.title}
          </p>
          {ex3Intro.body.map(para => (
            <p key={para.slice(0, 24)} style={{ fontSize: "0.92rem", color: C.muted, fontFamily: font.body, lineHeight: 1.7, marginBottom: "1rem", maxWidth: 420 }}>
              {para}
            </p>
          ))}
          <p style={{ fontSize: "0.72rem", color: C.muted, fontFamily: font.body, marginBottom: 0, letterSpacing: "0.05em" }}>
            ~10 minutes
          </p>
          <button onClick={() => setPhase('questions')}
            style={{ marginTop: "1.75rem", background: "linear-gradient(135deg, #10b981, #059669)", color: "white", border: "none", padding: "0.85rem 2.25rem", fontSize: "0.8rem", letterSpacing: "0.08em", textTransform: "uppercase", cursor: "pointer", fontFamily: font.body, borderRadius: 999, fontWeight: 700 }}>
            {ex3Intro.cta}
          </button>
        </CoverCard>
      </div>
    );
  }

  if (allDone && step >= total) {
    return (
      <div style={{ textAlign: "center", padding: "3.5rem 1.25rem 3rem", maxWidth: 520, margin: "0 auto", animation: "fadeIn 0.6s ease" }}>
        <style>{`@keyframes fadeIn{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}} @keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.04)}}`}</style>
        {/* Gradient ring with check — softer celebration, not a confetti blast */}
        <div style={{ position: "relative", width: 104, height: 104, margin: "0 auto 1.5rem" }}>
          <div style={{ position: "absolute", inset: 0, borderRadius: "50%", background: "conic-gradient(from 180deg, #10b981, #1B5FE8, #9B5DE5, #10b981)", padding: 3, animation: "pulse 2.2s ease-in-out infinite" }}>
            <div style={{ width: "100%", height: "100%", borderRadius: "50%", background: "white", display: "flex", alignItems: "center", justifyContent: "center" }}>
              <div style={{ width: 86, height: 86, borderRadius: "50%", background: "linear-gradient(135deg, #10b981, #059669)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "2.4rem", color: "white", fontWeight: 700 }}>✓</div>
            </div>
          </div>
        </div>
        <p style={{ fontFamily: font.display, fontSize: "2rem", fontWeight: 700, color: C.ink, marginBottom: "0.85rem", lineHeight: 1.1 }}>{exerciseComplete("ex3").title}</p>
        {/* From api/_lib/exercise-complete.js, the same module the app draws.
            Ellie: "I would rather them match the app's setup." */}
        {exerciseComplete("ex3").body.map((line) => (
          <p key={line.slice(0, 24)} style={{ fontSize: "0.95rem", color: C.muted, fontFamily: font.body, lineHeight: 1.7, maxWidth: 420, margin: "0 auto 2rem" }}>{line}</p>
        ))}
        <button onClick={() => { try { localStorage.removeItem('attune_ex3_progress'); } catch {} ; onComplete(answers); }} style={{ background: "linear-gradient(135deg, #10b981, #059669)", color: "white", border: "none", padding: "0.95rem 2.5rem", fontSize: "0.78rem", letterSpacing: "0.12em", textTransform: "uppercase", cursor: "pointer", fontFamily: font.body, borderRadius: 12, fontWeight: 700, boxShadow: "0 6px 20px rgba(16,185,129,0.28)" }}>{exerciseComplete("ex3").cta}</button>
      </div>
    );
  }

  const currentAnswered = isAnswered(q, answers);

  return (
    <div style={{ maxWidth: 560, margin: "0 auto" }}>
      <AnonymousStorageBanner />
      <ResumeToast show={resumedMidExercise} message="Picking up where you left off." />
      <div style={{ marginBottom: "2rem" }}>
        <button onClick={handleBack} style={{ background: "transparent", border: "none", color: C.muted, fontSize: "0.72rem", letterSpacing: "0.1em", textTransform: "uppercase", cursor: "pointer", fontFamily: font.body, padding: 0, marginBottom: "1.5rem", display: "block" }}>← Back</button>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "0.5rem" }}>
          <span style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#10b981", fontWeight: 700, fontFamily: font.body }}>Exercise 03 · Our Relationship Story</span>
        </div>
        <div style={{ background: C.stone + "40", borderRadius: 999, height: 4, marginBottom: "2rem" }}>
          <div style={{ background: "#1B5FE8", height: 4, borderRadius: 999, width: (((step) / total) * 100) + "%", transition: "width 0.3s" }} />
        </div>
        <span style={{ fontSize: "0.6rem", color: "#1B5FE8", fontWeight: 700, fontFamily: font.body, letterSpacing: "0.15em", textTransform: "uppercase" }}>{q.category}</span>
        <h2 style={{ fontFamily: font.display, fontSize: "1.35rem", fontWeight: 700, color: C.ink, margin: "0.5rem 0 1.5rem", lineHeight: 1.35 }}>{q.text}</h2>

        {q.type === "scale" ? (
          <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
            {q.scaleLabels.map((label, i) => {
              const selected = answers[q.id] === i;
              const color = q.scaleColors[i];
              return (
                <button key={i} onClick={() => setAnswers({ ...answers, [q.id]: i })}
                  style={{ display: "flex", alignItems: "center", gap: "0.85rem", background: selected ? color + "18" : "white", border: "1.5px solid " + (selected ? color : C.stone), borderRadius: 12, padding: "0.85rem 1.1rem", cursor: "pointer", textAlign: "left", transition: "all 0.15s" }}>
                  <div style={{ width: 20, height: 20, borderRadius: "50%", border: "2px solid " + (selected ? color : C.stone), background: selected ? color : "white", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    {selected && <div style={{ width: 8, height: 8, borderRadius: "50%", background: "white" }} />}
                  </div>
                  <span style={{ fontSize: "0.88rem", color: selected ? color : C.text, fontFamily: font.body, fontWeight: selected ? 600 : 400 }}>{label}</span>
                </button>
              );
            })}
          </div>
        ) : q.type === "pick" ? (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "0.55rem" }}>
            {q.options.map((opt, i) => {
              const selected = answers[q.id] === opt;
              return (
                <button key={i} onClick={() => setAnswers({ ...answers, [q.id]: opt })}
                  style={{ padding: "0.55rem 1.1rem", borderRadius: 999, border: "1.5px solid " + (selected ? "#1B5FE8" : C.stone), background: selected ? "#EEF2FF" : "white", color: selected ? "#1B5FE8" : C.text, fontFamily: font.body, fontSize: "0.85rem", fontWeight: selected ? 700 : 400, cursor: "pointer", transition: "all 0.15s" }}>
                  {opt}
                </button>
              );
            })}
          </div>
        ) : q.type === "rank" ? (() => {
          const ranked = answers[q.id] || [];
          const unranked = q.options.filter(o => !ranked.includes(o));
          const move = (item, dir) => {
            const arr = [...ranked];
            const idx = arr.indexOf(item);
            if (dir === "up" && idx > 0) { [arr[idx-1], arr[idx]] = [arr[idx], arr[idx-1]]; }
            if (dir === "down" && idx < arr.length-1) { [arr[idx], arr[idx+1]] = [arr[idx+1], arr[idx]]; }
            setAnswers({ ...answers, [q.id]: arr });
          };
          return (
            <div>
              <div style={{ fontSize: "0.65rem", color: C.muted, fontFamily: font.body, marginBottom: "0.75rem" }}>Tap an option to add it to your ranking, then use the arrows to reorder.</div>
              {ranked.length > 0 && (
                <div style={{ display: "flex", flexDirection: "column", gap: "0.4rem", marginBottom: "0.75rem" }}>
                  {ranked.map((item, i) => (
                    <div key={item} style={{ display: "flex", alignItems: "center", gap: "0.5rem", background: "#EEF2FF", border: "1.5px solid #1B5FE8", borderRadius: 10, padding: "0.6rem 0.85rem" }}>
                      <span style={{ fontSize: "0.7rem", fontWeight: 700, color: "#1B5FE8", fontFamily: font.body, width: 20, flexShrink: 0 }}>#{i+1}</span>
                      <span style={{ flex: 1, fontSize: "0.85rem", color: C.ink, fontFamily: font.body }}>{item}</span>
                      <button onClick={() => move(item,"up")} disabled={i===0} style={{ background: "none", border: "none", cursor: i===0?"default":"pointer", color: i===0?C.stone:"#1B5FE8", fontSize: "0.8rem", padding: "0 0.2rem" }}>▲</button>
                      <button onClick={() => move(item,"down")} disabled={i===ranked.length-1} style={{ background: "none", border: "none", cursor: i===ranked.length-1?"default":"pointer", color: i===ranked.length-1?C.stone:"#1B5FE8", fontSize: "0.8rem", padding: "0 0.2rem" }}>▼</button>
                      <button onClick={() => setAnswers({ ...answers, [q.id]: ranked.filter(r=>r!==item) })} style={{ background: "none", border: "none", cursor: "pointer", color: C.muted, fontSize: "0.75rem", padding: "0 0.2rem" }}>✕</button>
                    </div>
                  ))}
                </div>
              )}
              <div style={{ display: "flex", flexWrap: "wrap", gap: "0.45rem" }}>
                {unranked.map(opt => (
                  <button key={opt} onClick={() => setAnswers({ ...answers, [q.id]: [...ranked, opt] })}
                    style={{ padding: "0.45rem 0.9rem", borderRadius: 999, border: "1.5px solid " + C.stone, background: "white", color: C.muted, fontFamily: font.body, fontSize: "0.82rem", cursor: "pointer" }}>
                    + {opt}
                  </button>
                ))}
              </div>
            </div>
          );
        })() : (
          <textarea
            value={answers[q.id] || ""}
            onChange={e => setAnswers({ ...answers, [q.id]: e.target.value })}
            placeholder={q.placeholder}
            style={{ width: "100%", minHeight: 120, padding: "0.85rem 1rem", borderRadius: 12, border: "1.5px solid " + C.stone, fontFamily: font.body, fontSize: "0.88rem", color: C.text, background: "white", resize: "vertical", outline: "none", lineHeight: 1.6, boxSizing: "border-box" }}
          />
        )}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: "0.72rem", color: C.muted, fontFamily: font.body }}>{step + 1} of {total}</span>
        <div style={{ display: "flex", gap: "0.75rem" }}>
          {step > 0 && <button onClick={handleBack} style={{ background: "transparent", border: "1.5px solid " + C.stone, color: C.muted, padding: "0.6rem 1.1rem", fontSize: "0.72rem", cursor: "pointer", fontFamily: font.body, borderRadius: 8 }}>← Back</button>}
          {step < total - 1 ? (
            <button onClick={handleNext} disabled={!currentAnswered} style={{ background: currentAnswered ? "#1B5FE8" : C.stone, color: currentAnswered ? "white" : C.muted, border: "none", padding: "0.6rem 1.5rem", fontSize: "0.72rem", letterSpacing: "0.08em", textTransform: "uppercase", cursor: currentAnswered ? "pointer" : "default", fontFamily: font.body, borderRadius: 8, fontWeight: 600 }}>Continue →</button>
          ) : (
            <button onClick={() => { if (allDone) { try { localStorage.removeItem('attune_ex3_progress'); } catch {} ; onComplete(answers); } }} disabled={!currentAnswered} style={{ background: currentAnswered ? "linear-gradient(135deg, #1B5FE8, #3B3A8A)" : C.stone, color: currentAnswered ? "white" : C.muted, border: "none", padding: "0.6rem 1.75rem", fontSize: "0.72rem", letterSpacing: "0.08em", textTransform: "uppercase", cursor: currentAnswered ? "pointer" : "default", fontFamily: font.body, borderRadius: 8, fontWeight: 600 }}>Complete Reflection →</button>
          )}
        </div>
      </div>
    </div>
  );
}

// ======================================================
// MERGING LIVES CHECKLIST
// ======================================================
// Starting Out (newlywed) checklist.
// Items are objects: { text, description, links? }.
// State key uses item.text so existing checkmarks survive when only
// descriptions/links change. The `text` strings should stay stable.
//
// Section order matters: Name Change is first because it cascades into
// most other sections (IDs, bank accounts, insurance, etc.). Merging
// Finances is second since it involves decisions that shape later steps.


// Stylized line icons for the Merging lives checklist section headers, matching
// the site's lucide-style stroke set. Replaces the emoji glyphs.
function ChecklistIcon({ id, color = "#7A6753", size = 22 }) {
  const p = {
    namechange: <><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/></>,
    finances:   <><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></>,
    insurance:  <><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/></>,
    estate:     <><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="13" y2="17"/></>,
    taxes:      <><path d="M4 2v20l2-1 2 1 2-1 2 1 2-1 2 1 2-1 2 1V2l-2 1-2-1-2 1-2-1-2 1-2-1-2 1Z"/><path d="M16 8h-6a2 2 0 1 0 0 4h4a2 2 0 1 1 0 4H8"/><path d="M12 17.5v-11"/></>,
    home:       <><path d="M3 9.5 12 3l9 6.5"/><path d="M5 9v11a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V9"/><path d="M9 21v-6h6v6"/></>,
  };
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
      {p[id] || <circle cx="12" cy="12" r="9" />}
    </svg>
  );
}

function MergingLivesChecklist({ userName, partnerName, onBack, checklistState, setChecklistState }) {
  const totalItems = CHECKLIST_AREAS.reduce((s, a) => s + a.items.length, 0);
  const checkedCount = Object.values(checklistState).filter(v => v === true || v === 'na').length;
  const pct = Math.round((checkedCount / totalItems) * 100);

  // Which item's description is currently expanded. Single-open behavior
  // keeps the page compact; clicking an already-open item collapses it.
  const [expandedKey, setExpandedKey] = useState(null);

  const toggle = (key) => {
    const cur = checklistState[key];
    // Cycle: unchecked → done → N/A → unchecked
    const next = !cur ? true : cur === true ? 'na' : false;
    setChecklistState({ ...checklistState, [key]: next });
  };

  return (
    <div style={{ maxWidth: 620, margin: "0 auto" }}>
      <div style={{ marginBottom: "1.75rem" }}>
        <h1 style={{ fontFamily: font.display, fontSize: "1.8rem", fontWeight: 700, color: C.ink, lineHeight: 1.1, marginBottom: "0.6rem" }}>{CHECKLIST_COPY.title}</h1>
        <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: font.body, fontWeight: 300, lineHeight: 1.65, marginBottom: "1.25rem" }}>{CHECKLIST_COPY.intro}</p>
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
          <div style={{ flex: 1, background: C.stone + "60", borderRadius: 999, height: 6 }}>
            <div style={{ background: "linear-gradient(90deg, #E8673A, #1B5FE8)", height: 6, borderRadius: 999, width: pct + "%", transition: "width 0.3s" }} />
          </div>
          <span style={{ fontSize: "0.72rem", color: C.muted, fontFamily: font.body, flexShrink: 0 }}>{checkedCount}/{totalItems} {CHECKLIST_COPY.progress}</span>
        </div>
        {/* How the checkbox works — not obvious that a second tap marks N/A. */}
        <div style={{ display: "flex", alignItems: "flex-start", gap: "0.6rem", background: C.warm, border: "1px solid " + C.stone, borderRadius: 10, padding: "0.7rem 0.9rem", marginTop: "0.9rem" }}>
          <div style={{ width: 18, height: 18, borderRadius: 6, border: "2px solid " + C.clay, flexShrink: 0, marginTop: "0.05rem" }} />
          <p style={{ fontSize: "0.75rem", color: C.muted, fontFamily: font.body, lineHeight: 1.55, margin: 0 }}>
            {CHECKLIST_COPY.howItWorks}
          </p>
        </div>
      </div>
      {CHECKLIST_AREAS.map(area => {
        const areaChecked = area.items.filter(item => { const v = checklistState[area.id + "__" + item.text]; return v === true || v === 'na'; }).length;
        return (
          <div key={area.id} style={{ background: "white", border: "1.5px solid " + C.stone, borderRadius: 14, marginBottom: "0.75rem", overflow: "hidden" }}>
            <div style={{ padding: "1rem 1.25rem", borderBottom: "1px solid " + C.stone + "60", display: "flex", alignItems: "center", gap: "0.75rem", background: area.color + "08" }}>
              <ChecklistIcon id={area.id} color={area.color} />
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: font.display, fontSize: "0.95rem", fontWeight: 700, color: C.ink }}>{area.label}</div>
                <div style={{ fontSize: "0.65rem", color: C.muted, fontFamily: font.body }}>{areaChecked}/{area.items.length} complete</div>
              </div>
              {areaChecked === area.items.length && <span style={{ fontSize: "0.7rem", color: area.color, fontWeight: 700, fontFamily: font.body }}>✓ Done</span>}
            </div>
            <div style={{ padding: "0.75rem 1.25rem" }}>
              {area.items.map(item => {
                const key = area.id + "__" + item.text;
                const state = checklistState[key]; // false | true | 'na'
                const isDone = state === true;
                const isNA   = state === 'na';
                const isExpanded = expandedKey === key;
                const hasDetail = !!(item.description || (item.links && item.links.length));
                return (
                  <div key={item.text} style={{ borderBottom: "1px solid " + C.stone + "40" }}>
                    <div style={{ display: "flex", alignItems: "flex-start", gap: "0.75rem", padding: "0.5rem 0" }}>
                      <div onClick={() => toggle(key)} style={{ display: "flex", alignItems: "flex-start", gap: "0.75rem", flex: 1, cursor: "pointer", minWidth: 0 }}>
                        <div style={{ width: 18, height: 18, borderRadius: 5, border: "2px solid " + (isDone ? area.color : isNA ? C.muted : C.stone), background: isDone ? area.color : isNA ? C.stone + "80" : "white", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginTop: "0.05rem", transition: "all 0.15s" }}>
                          {isDone && <span style={{ color: "white", fontSize: "0.7rem", fontWeight: 700, lineHeight: 1 }}>✓</span>}
                          {isNA   && <span style={{ color: C.muted, fontSize: "0.6rem", fontWeight: 700, lineHeight: 1 }}>-</span>}
                        </div>
                        <span style={{ fontSize: "0.82rem", color: isDone || isNA ? C.muted : C.text, fontFamily: font.body, textDecoration: isDone ? "line-through" : "none", fontStyle: isNA ? "italic" : "normal", lineHeight: 1.45 }}>
                          {item.text}{isNA ? <span style={{ fontSize: "0.7rem", marginLeft: "0.5rem", color: C.muted }}>{CHECKLIST_COPY.notApplicable}</span> : null}
                        </span>
                      </div>
                      {hasDetail && (
                        <button
                          onClick={(e) => { e.stopPropagation(); setExpandedKey(isExpanded ? null : key); }}
                          aria-label={isExpanded ? "Hide details" : "Show details"}
                          aria-expanded={isExpanded}
                          style={{ background: "transparent", border: "none", color: C.muted, cursor: "pointer", padding: "0.15rem 0.35rem", fontSize: "0.72rem", fontFamily: font.body, flexShrink: 0, lineHeight: 1, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 6, transition: "color 0.15s, background 0.15s" }}
                          onMouseEnter={(e) => { e.currentTarget.style.color = area.color; e.currentTarget.style.background = area.color + "12"; }}
                          onMouseLeave={(e) => { e.currentTarget.style.color = C.muted; e.currentTarget.style.background = "transparent"; }}
                        >
                          <span style={{ display: "inline-flex", transition: "transform 0.2s ease", transform: isExpanded ? "rotate(180deg)" : "rotate(0)" }}>
                            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
                          </span>
                        </button>
                      )}
                    </div>
                    {hasDetail && isExpanded && (
                      <div style={{ padding: "0.1rem 0 0.85rem 2.4rem", animation: "fadein 0.2s ease" }}>
                        {item.description && (
                          <p style={{ fontSize: "0.76rem", color: C.muted, fontFamily: font.body, lineHeight: 1.6, margin: "0 0 0.55rem", fontWeight: 300 }}>
                            {item.description}
                          </p>
                        )}
                        {item.links && item.links.length > 0 && (
                          <div style={{ display: "flex", flexWrap: "wrap", gap: "0.4rem 0.75rem" }}>
                            {item.links.map(link => (
                              <a key={link.url} href={link.url} target={link.url.startsWith("http") ? "_blank" : undefined} rel={link.url.startsWith("http") ? "noopener noreferrer" : undefined}
                                style={{ fontSize: "0.72rem", color: area.color, fontFamily: font.body, textDecoration: "none", fontWeight: 500, borderBottom: "1px solid " + area.color + "40", paddingBottom: 1 }}
                                onMouseEnter={(e) => { e.currentTarget.style.borderBottomColor = area.color; }}
                                onMouseLeave={(e) => { e.currentTarget.style.borderBottomColor = area.color + "40"; }}
                              >{link.label} →</a>
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ──────────────────────────────────────────────────────────────────────────
// SHARED BUDGET TOOL (Premium add-on)
// ──────────────────────────────────────────────────────────────────────────
// Redesigned flow:
//   1. ORIENT   — each partner's post-tax monthly income + pooling model
//   2. ESSENTIALS — housing, transport, food, health, debt, regular savings
//   3. DISCRETIONARY — lifestyle, giving, personal spending (split per partner)
//   4. GOALS    — target + timeline, auto-calc monthly contribution, shown
//                 against remaining surplus
//   5. REVEAL   — pure facts, no commentary: what the budget does, what each
//                 partner said on ex2 finances questions, how money moves
//                 under the chosen pooling model
//
// Data shape persisted (localStorage + Supabase profiles.budget_data):
//   {
//     incomes: { [userName]: "5500", [partnerName]: "4000" },
//     pooling: 'combined' | 'proportional' | 'fifty_fifty' | 'separate',
//     expenses: { "housing__Rent / Mortgage": "1850", ... },
//     personal: { [userName]: "400", [partnerName]: "350" },
//     goals: [ { id, name, target, months } ],
//   }
// ──────────────────────────────────────────────────────────────────────────


function BudgetTool({ userName, partnerName, onBack, budgetState, setBudgetState,
                     ex2Answers, partnerEx2, accountId }) {
  const font = { display: HFONT, body: BFONT };

  // Seed from persisted state if present; otherwise sensible empty shape.
  const init = budgetState || {};
  const [incomes, setIncomes]       = useState(init.incomes       || { [userName]: "", [partnerName]: "" });
  const [pooling, setPooling]       = useState(init.pooling       || "proportional");
  const [expenses, setExpenses]     = useState(init.expenses      || {});
  const [personal, setPersonal]     = useState(init.personal      || { [userName]: "", [partnerName]: "" });
  const [goals, setGoals]           = useState(init.goals         || []);
  const [dirty, setDirty]           = useState(false);
  const [saveStatus, setSaveStatus] = useState("idle"); // 'idle' | 'saving' | 'saved'

  /**
   * Which fields the partner has open, polled while this screen is up.
   *
   * Ellie: "The budget should show your partner's icon or something in a text
   * box if they're currently editing that figure."
   *
   * A poll rather than a live channel, because the app deliberately carries no
   * realtime client and this has to work the same on both surfaces. Six seconds
   * against a server window of twelve, so a marker appears within one cycle of
   * the partner arriving and clears within one of them leaving. It stops when
   * the tab is hidden: nobody is watching a marker on a screen they cannot see.
   */
  const [partnerEditing, setPartnerEditing] = useState({});
  useEffect(() => {
    if (!accountId) return undefined;
    let stopped = false;
    const read = async () => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      try {
        const { supabase: sb, hasSupabase } = await import('./supabase.js');
        if (!hasSupabase()) return;
        const { data: { session } } = await sb.auth.getSession();
        if (!session?.access_token) return;
        const r = await fetch('/api/tool-data', { headers: { Authorization: `Bearer ${session.access_token}` } });
        if (!r.ok) return;
        const b = await r.json().catch(() => null);
        if (!stopped && b?.ok) setPartnerEditing(b.editing || {});
      } catch { /* a marker nobody sees is the cost of a failed poll */ }
    };
    read();
    const iv = setInterval(read, 6000);
    return () => { stopped = true; clearInterval(iv); };
  }, [accountId]);

  // Mark dirty whenever the user changes anything
  const markDirty = () => { if (!dirty) setDirty(true); if (saveStatus === 'saved') setSaveStatus('idle'); };
  const setIncome  = (who, v) => { setIncomes(x => ({ ...x, [who]: v })); markDirty(); };
  const setExpense = (k, v)   => { setExpenses(x => ({ ...x, [k]: v })); markDirty(); };
  const setPers    = (who, v) => { setPersonal(x => ({ ...x, [who]: v })); markDirty(); };
  const changePool = (id)     => { setPooling(id); markDirty(); };
  const addGoal    = ()       => { setGoals(g => [...g, { id: 'g_' + Date.now(), name: "", target: "", months: "" }]); markDirty(); };
  const editGoal   = (id, patch) => { setGoals(g => g.map(x => x.id === id ? { ...x, ...patch } : x)); markDirty(); };
  const delGoal    = (id)     => { setGoals(g => g.filter(x => x.id !== id)); markDirty(); };

  // Save: write to localStorage immediately, also upsert to Supabase if
  // logged in. Flow: idle → saving → saved (2s) → idle.
  const save = async () => {
    const snapshot = { incomes, pooling, expenses, personal, goals };
    setSaveStatus("saving");
    setBudgetState(snapshot);
    try { localStorage.setItem('attune_budget', JSON.stringify(snapshot)); } catch {}
    if (accountId) {
      await saveSharedTool('budget', snapshot);
    }
    setDirty(false);
    setSaveStatus("saved");
    setTimeout(() => setSaveStatus("idle"), 2000);
  };

  // Current reveal calc (always running — cheap + used for sticky summary)
  const rev = computeReveal({ incomes, pooling, expenses, personal, goals }, userName, partnerName);
  const hasIncome   = rev.totalIncome > 0;
  const hasExpenses = rev.sharedExpenses > 0 || rev.uPersonal > 0 || rev.pPersonal > 0 || rev.goalsMonthly > 0;
  const showReveal  = hasIncome && hasExpenses;

  /**
   * Number input, currency format, responsive to keyboard and mobile numeric.
   *
   * ── AND WHO ELSE IS IN IT ─────────────────────────────────────────────────
   * Ellie: "The budget should show your partner's icon or something in a text
   * box if they're currently editing that figure." `field` names the box, the
   * focus is reported, and a dot appears in any box the partner has open. The
   * field id has to mean the same thing on both surfaces or the marker lands on
   * the wrong box; check-shared-tools holds them to one list.
   */
  const numInput = (value, onChange, placeholder = "0", w = 130, field = null) => (
    <div style={{ display: "flex", alignItems: "center", gap: 4, background: "white", border: "1.5px solid " + (field && partnerEditing[field] ? C.accent : C.stone), borderRadius: 8, padding: "0.35rem 0.65rem", width: w, position: "relative" }}>
      <span style={{ color: C.muted, fontFamily: font.body, fontSize: "0.82rem" }}>$</span>
      <input
        type="text" inputMode="decimal" value={value || ""} onChange={e => onChange(e.target.value)}
        onFocus={field ? () => markEditing(field) : undefined}
        onBlur={field ? () => markEditing('') : undefined}
        placeholder={placeholder}
        style={{ border: "none", outline: "none", background: "transparent", fontFamily: font.body, fontSize: "0.88rem", color: C.ink, width: "100%", padding: 0 }}
      />
      {field && partnerEditing[field] ? (
        <span
          title={`${partnerName || 'Your partner'} is editing this`}
          aria-label={`${partnerName || 'Your partner'} is editing this`}
          style={{ position: "absolute", right: -7, top: -7, width: 16, height: 16, borderRadius: "50%", background: C.accent, color: "white", fontSize: "0.58rem", fontWeight: 700, fontFamily: font.body, display: "flex", alignItems: "center", justifyContent: "center", border: "2px solid white" }}>
          {(partnerName || 'P').trim().charAt(0).toUpperCase()}
        </span>
      ) : null}
    </div>
  );

  return (
    <div style={{ maxWidth: 720, margin: "0 auto", paddingBottom: "6rem" }}>
      {/* ── Title ───────────────────────────────────────────── */}
      <h1 style={{ fontFamily: font.display, fontSize: "1.9rem", fontWeight: 700, color: C.ink, lineHeight: 1.1, marginBottom: "0.5rem" }}>{BUDGET_COPY.title}</h1>
      <p style={{ fontSize: "0.92rem", color: C.muted, fontFamily: font.body, fontWeight: 300, lineHeight: 1.65, marginBottom: "0.4rem" }}>
        {BUDGET_COPY.intro}
      </p>
      <p style={{ fontSize: "0.78rem", color: C.muted, fontFamily: font.body, fontWeight: 300, lineHeight: 1.6, marginBottom: "1.5rem", fontStyle: "italic" }}>
        Both of you can access and edit this tool from your dashboard. Use <strong>{BUDGET_COPY.save}</strong> to sync across devices.
      </p>

      {/* ── Sticky summary bar ─────────────────────────────────────── */}
      <div style={{ position: "sticky", top: 0, zIndex: 10, background: "linear-gradient(135deg, #0f0c29, #1d1a4e)", borderRadius: 14, padding: "1rem 1.25rem", marginBottom: "1.5rem", color: "white", boxShadow: "0 6px 24px rgba(15,12,41,0.25)" }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "1rem" }}>
          {[
            /* The four labels come from BUDGET_COPY so the app can show the
               same three numbers under the same names. They were typed here
               and typed differently in the app, which is how the two tools came
               to disagree about which numbers a budget has. */
            { label: BUDGET_COPY.statIncome,  value: bFmt(rev.totalIncome),  color: BUDGET_STAT_COLORS.income },
            { label: rev.surplus >= 0 ? BUDGET_COPY.statLeft : BUDGET_COPY.statOver,
              value: (rev.surplus >= 0 ? "" : "-") + bFmt(rev.surplus),
              color: rev.surplus >= 0 ? BUDGET_STAT_COLORS.left : BUDGET_STAT_COLORS.over },
            { label: BUDGET_COPY.statSavings, value: rev.savingsRate.toFixed(1) + "%", color: BUDGET_STAT_COLORS.savings },
          ].map(({ label, value, color }) => (
            <div key={label}>
              <div style={{ fontSize: "0.56rem", color: "rgba(255,255,255,0.72)", letterSpacing: "0.15em", textTransform: "uppercase", fontFamily: font.body, marginBottom: "0.2rem" }}>{label}</div>
              <div style={{ fontFamily: font.display, fontSize: "1.3rem", fontWeight: 700, color }}>{value}</div>
            </div>
          ))}
        </div>
        {dirty && (
          <div style={{ marginTop: "0.6rem", fontSize: "0.68rem", color: "rgba(255,220,170,0.9)", fontFamily: font.body, letterSpacing: "0.05em" }}>
            ● Unsaved changes
          </div>
        )}
      </div>

      {/* ── Section: ORIENT ─────────────────────────────────────────── */}
      <section style={{ marginBottom: "2.25rem" }}>
        <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#1B5FE8", fontFamily: font.body, fontWeight: 700, marginBottom: "0.35rem" }}>Step 1</div>
        <h2 style={{ fontFamily: font.display, fontSize: "1.35rem", fontWeight: 700, color: C.ink, margin: "0 0 0.4rem" }}>{BUDGET_COPY.step1}</h2>
        <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: font.body, lineHeight: 1.6, marginBottom: "1.25rem" }}>
          {BUDGET_COPY.step1Intro}
        </p>

        {/* Incomes */}
        <div style={{ background: "white", border: "1.5px solid " + C.stone, borderRadius: 14, padding: "1.15rem 1.25rem", marginBottom: "1.25rem" }}>
          <div style={{ fontSize: "0.7rem", letterSpacing: "0.16em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: font.body, marginBottom: "0.9rem" }}>{BUDGET_COPY.incomeLabel}</div>
          {[userName, partnerName].map((name, i) => (
            <div key={name} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0.5rem 0", borderTop: i === 0 ? "none" : "1px solid " + C.stone + "40" }}>
              <span style={{ fontSize: "0.9rem", color: C.ink, fontFamily: font.body, fontWeight: 500 }}>{name}</span>
              {numInput(incomes[name], v => setIncome(name, v), "0", 140, `income:${name}`)}
            </div>
          ))}
        </div>

        {/* Pooling model */}
        <div style={{ fontSize: "0.7rem", letterSpacing: "0.16em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: font.body, marginBottom: "0.7rem" }}>{BUDGET_COPY.poolingLabel}</div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: "0.65rem" }}>
          {POOLING_MODELS.map(m => {
            const sel = pooling === m.id;
            return (
              <button key={m.id} onClick={() => changePool(m.id)}
                style={{ textAlign: "left", background: sel ? "#1B5FE808" : "white", border: "2px solid " + (sel ? "#1B5FE8" : C.stone), borderRadius: 12, padding: "0.85rem 1rem", cursor: "pointer", fontFamily: font.body, transition: "all 0.15s" }}>
                <div style={{ fontSize: "0.9rem", fontWeight: 700, color: sel ? "#1B5FE8" : C.ink, marginBottom: "0.3rem" }}>{m.label}</div>
                <div style={{ fontSize: "0.76rem", color: C.muted, lineHeight: 1.5 }}>{m.desc}</div>
              </button>
            );
          })}
        </div>
      </section>

      {/* ── Section: ESSENTIALS ─────────────────────────────────────── */}
      <section style={{ marginBottom: "2.25rem" }}>
        <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#10b981", fontFamily: font.body, fontWeight: 700, marginBottom: "0.35rem" }}>Step 2</div>
        <h2 style={{ fontFamily: font.display, fontSize: "1.35rem", fontWeight: 700, color: C.ink, margin: "0 0 0.4rem" }}>{BUDGET_COPY.essentials}</h2>
        <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: font.body, lineHeight: 1.6, marginBottom: "1.25rem" }}>
          {BUDGET_COPY.essentialsIntro}
        </p>
        {BUDGET_CATEGORIES.filter(c => c.group === "essentials").map(cat =>
          <BudgetCategoryBlock key={cat.id} cat={cat} expenses={expenses} setExpense={setExpense} numInput={numInput} font={font} />)}
      </section>

      {/* ── Section: DISCRETIONARY ──────────────────────────────────── */}
      <section style={{ marginBottom: "2.25rem" }}>
        <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#E8673A", fontFamily: font.body, fontWeight: 700, marginBottom: "0.35rem" }}>Step 3</div>
        <h2 style={{ fontFamily: font.display, fontSize: "1.35rem", fontWeight: 700, color: C.ink, margin: "0 0 0.4rem" }}>{BUDGET_COPY.discretionary}</h2>
        <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: font.body, lineHeight: 1.6, marginBottom: "1.25rem" }}>
          {BUDGET_COPY.discretionaryIntro}
        </p>
        {BUDGET_CATEGORIES.filter(c => c.group === "discretionary").map(cat =>
          <BudgetCategoryBlock key={cat.id} cat={cat} expenses={expenses} setExpense={setExpense} numInput={numInput} font={font} />)}

        {/* Personal spending — per partner */}
        <div style={{ background: "white", border: "1.5px solid " + C.stone, borderRadius: 14, padding: "0.85rem 1.15rem", marginTop: "0.6rem" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0.55rem 0 0.85rem", borderBottom: "1px solid " + C.stone + "60" }}>
            <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
              <BudgetIcon id="personal" color="#E8673A" />
              <span style={{ fontSize: "0.95rem", fontWeight: 700, color: C.ink, fontFamily: font.display }}>{BUDGET_COPY.personalLabel}</span>
            </div>
          </div>
          {[userName, partnerName].map(name => (
            <div key={name} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0.55rem 0", borderBottom: "1px solid " + C.stone + "30" }}>
              <span style={{ fontSize: "0.88rem", color: C.ink, fontFamily: font.body }}>{name}</span>
              {numInput(personal[name], v => setPers(name, v), "0", 130)}
            </div>
          ))}
        </div>
      </section>

      {/* ── Section: GOALS ──────────────────────────────────────────── */}
      <section style={{ marginBottom: "2.25rem" }}>
        <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#F59E0B", fontFamily: font.body, fontWeight: 700, marginBottom: "0.35rem" }}>Step 4</div>
        <h2 style={{ fontFamily: font.display, fontSize: "1.35rem", fontWeight: 700, color: C.ink, margin: "0 0 0.4rem" }}>{BUDGET_COPY.goals}</h2>
        <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: font.body, lineHeight: 1.6, marginBottom: "1.25rem" }}>
          {BUDGET_COPY.goalsIntro}
        </p>

        {goals.map(g => {
          const monthly = bNum(g.months) > 0 ? bNum(g.target) / bNum(g.months) : 0;
          return (
            <div key={g.id} style={{ background: "white", border: "1.5px solid " + C.stone, borderRadius: 12, padding: "0.9rem 1rem", marginBottom: "0.6rem", display: "grid", gridTemplateColumns: "1fr auto auto auto", gap: "0.55rem", alignItems: "center" }}>
              <input value={g.name} onChange={e => editGoal(g.id, { name: e.target.value })} placeholder="Goal name"
                style={{ border: "1.5px solid " + C.stone, borderRadius: 8, padding: "0.45rem 0.7rem", fontFamily: font.body, fontSize: "0.85rem", color: C.ink, minWidth: 0 }}/>
              <div style={{ display: "flex", alignItems: "center", gap: 4, background: "white", border: "1.5px solid " + C.stone, borderRadius: 8, padding: "0.35rem 0.65rem", width: 110 }}>
                <span style={{ color: C.muted, fontFamily: font.body, fontSize: "0.78rem" }}>$</span>
                <input type="text" inputMode="decimal" value={g.target} onChange={e => editGoal(g.id, { target: e.target.value })} placeholder="target"
                  style={{ border: "none", outline: "none", background: "transparent", fontFamily: font.body, fontSize: "0.85rem", color: C.ink, width: "100%", padding: 0 }}/>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 4, background: "white", border: "1.5px solid " + C.stone, borderRadius: 8, padding: "0.35rem 0.65rem", width: 90 }}>
                <input type="text" inputMode="numeric" value={g.months} onChange={e => editGoal(g.id, { months: e.target.value })} placeholder="months"
                  style={{ border: "none", outline: "none", background: "transparent", fontFamily: font.body, fontSize: "0.85rem", color: C.ink, width: "100%", padding: 0 }}/>
                <span style={{ color: C.muted, fontFamily: font.body, fontSize: "0.7rem" }}>mo</span>
              </div>
              <button onClick={() => delGoal(g.id)} aria-label="Remove goal"
                style={{ background: "transparent", border: "none", color: C.muted, cursor: "pointer", padding: "0.3rem 0.5rem", fontSize: "1.1rem", lineHeight: 1 }}>×</button>
              {monthly > 0 && (
                <div style={{ gridColumn: "1 / -1", fontSize: "0.75rem", color: C.muted, fontFamily: font.body, paddingTop: "0.3rem" }}>
                  Needs <strong style={{ color: C.ink }}>{bFmt(monthly)}/month</strong> · {bNum(g.months)} months to target
                </div>
              )}
            </div>
          );
        })}
        <button onClick={addGoal}
          style={{ background: C.warm, border: "1.5px dashed " + C.stone, color: C.ink, padding: "0.75rem 1.2rem", borderRadius: 10, cursor: "pointer", fontFamily: font.body, fontSize: "0.82rem", fontWeight: 500, width: "100%" }}>
          + Add a savings goal
        </button>
      </section>

      {/* ── Section: REVEAL ─────────────────────────────────────────── */}
      {showReveal && (
        <section style={{ marginBottom: "2.25rem" }}>
          <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#9B5DE5", fontFamily: font.body, fontWeight: 700, marginBottom: "0.35rem" }}>The picture</div>
          <h2 style={{ fontFamily: font.display, fontSize: "1.35rem", fontWeight: 700, color: C.ink, margin: "0 0 1.25rem" }}>What your budget shows</h2>

          <BudgetReveal rev={rev} userName={userName} partnerName={partnerName}
            ex2Answers={ex2Answers} partnerEx2={partnerEx2} font={font} />
        </section>
      )}

      {/* ── Save bar (sticky footer) ────────────────────────────────── */}
      <div style={{ position: "fixed", bottom: 0, left: 0, right: 0, background: "white", borderTop: "1.5px solid " + C.stone, padding: "0.85rem 1.25rem", display: "flex", alignItems: "center", justifyContent: "center", gap: "0.9rem", boxShadow: "0 -4px 18px rgba(0,0,0,0.06)", zIndex: 20 }}>
        <div style={{ fontSize: "0.78rem", color: C.muted, fontFamily: font.body }}>
          {saveStatus === 'saved'  ? "✓ Saved" :
           saveStatus === 'saving' ? "Saving…" :
           dirty                   ? "Unsaved changes" :
                                     "All changes saved"}
        </div>
        <button onClick={save} disabled={!dirty || saveStatus === 'saving'}
          style={{ background: (!dirty || saveStatus === 'saving') ? C.stone : "linear-gradient(135deg, #1B5FE8, #1447b8)",
                   color: (!dirty || saveStatus === 'saving') ? C.muted : "white", border: "none",
                   padding: "0.7rem 1.6rem", fontSize: "0.76rem", letterSpacing: "0.08em", textTransform: "uppercase",
                   cursor: (!dirty || saveStatus === 'saving') ? "default" : "pointer",
                   fontFamily: font.body, borderRadius: 9, fontWeight: 700 }}>
          Save changes
        </button>
      </div>
    </div>
  );
}

// ── Helper: one category block with its line items ────────────────────────
// Stylized line icons for the budget category headers, matching the site's
// lucide-style stroke set. Replaces the emoji glyphs so the tool reads
// consistent with the rest of Attune.
function BudgetIcon({ id, color = "#7A6753", size = 18 }) {
  const p = {
    housing:   <><path d="M3 9.5 12 3l9 6.5"/><path d="M5 9v11a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V9"/><path d="M9 21v-6h6v6"/></>,
    transport: <><path d="M19 17h2c.6 0 1-.4 1-1v-3c0-.9-.7-1.7-1.5-1.9C18.7 10.6 16 10 16 10s-1.3-1.4-2.2-2.3c-.5-.4-1.1-.7-1.8-.7H5c-.6 0-1.1.4-1.4.9l-1.4 2.9A3.7 3.7 0 0 0 2 12v4c0 .6.4 1 1 1h2"/><circle cx="7" cy="17" r="2"/><circle cx="17" cy="17" r="2"/></>,
    food:      <><path d="M3 2v7c0 1.1.9 2 2 2a2 2 0 0 0 2-2V2"/><path d="M7 2v20"/><path d="M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3Zm0 0v7"/></>,
    health:    <><path d="m10.5 20.5 10-10a4.95 4.95 0 1 0-7-7l-10 10a4.95 4.95 0 1 0 7 7Z"/><path d="m8.5 8.5 7 7"/></>,
    debt:      <><line x1="12" y1="20" x2="12" y2="10"/><line x1="18" y1="20" x2="18" y2="4"/><line x1="6" y1="20" x2="6" y2="16"/></>,
    savings:   <><line x1="12" y1="2" x2="12" y2="22"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></>,
    lifestyle: <><path d="m12 3-1.9 5.8a2 2 0 0 1-1.3 1.3L3 12l5.8 1.9a2 2 0 0 1 1.3 1.3L12 21l1.9-5.8a2 2 0 0 1 1.3-1.3L21 12l-5.8-1.9a2 2 0 0 1-1.3-1.3z"/><path d="M5 3v4"/><path d="M3 5h4"/></>,
    giving:    <><path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.29 1.49 4.04 3 5.5l7 7Z"/></>,
    personal:  <><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></>,
  };
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ verticalAlign: "middle", flexShrink: 0 }}>
      {p[id] || <circle cx="12" cy="12" r="9" />}
    </svg>
  );
}

function BudgetCategoryBlock({ cat, expenses, setExpense, numInput, font }) {
  const catTotal = cat.items.reduce((s, item) => s + bNum(expenses[cat.id + '__' + item]), 0);
  return (
    <div style={{ background: "white", border: "1.5px solid " + C.stone, borderRadius: 14, padding: "0.85rem 1.15rem", marginBottom: "0.6rem" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0.55rem 0 0.85rem", borderBottom: "1px solid " + C.stone + "60" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          <BudgetIcon id={cat.id} color={cat.group === "essentials" ? "#10b981" : "#E8673A"} />
          <span style={{ fontSize: "0.95rem", fontWeight: 700, color: C.ink, fontFamily: font.display }}>{cat.label}</span>
        </div>
        {catTotal > 0 && <span style={{ fontSize: "0.8rem", color: C.muted, fontFamily: font.body, fontWeight: 500 }}>{bFmt(catTotal)}</span>}
      </div>
      {cat.items.map(item => {
        const key = cat.id + '__' + item;
        return (
          <div key={item} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0.55rem 0", borderBottom: "1px solid " + C.stone + "30" }}>
            <span style={{ fontSize: "0.85rem", color: C.ink, fontFamily: font.body, flex: 1, marginRight: "0.75rem" }}>{item}</span>
            {numInput(expenses[key], v => setExpense(key, v), "0", 120)}
          </div>
        );
      })}
    </div>
  );
}

// ── Helper: the reveal. Pure facts, no commentary. ────────────────────────
function BudgetReveal({ rev, userName, partnerName, ex2Answers, partnerEx2, font }) {
  // Expectations echo — pulled from ex2 Life & Values. We surface three
  // questions only: lq_finances, lq_money_lean, lq_money_risk.
  const echoQs = [
    { id: 'lq_finances',   label: 'How you want to manage money' },
    { id: 'lq_money_lean', label: 'Saving vs spending' },
    { id: 'lq_money_risk', label: 'Financial risk' },
  ];
  const myLife = ex2Answers?.life || {};
  const parLife = partnerEx2?.life || {};

  const blockStyle = { background: "white", border: "1.5px solid " + C.stone, borderRadius: 14, padding: "1.15rem 1.35rem", marginBottom: "0.9rem" };
  const blockHeader = { fontSize: "0.65rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#9B5DE5", fontFamily: font.body, fontWeight: 700, marginBottom: "0.75rem" };

  return (
    <>
      {/* Block 1 — what the budget does */}
      <div style={blockStyle}>
        <div style={blockHeader}>What your budget does</div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: "1rem", marginBottom: rev.topCats.length ? "1rem" : 0 }}>
          <RevealStat label="Savings rate" value={rev.savingsRate.toFixed(1) + "%"} font={font}/>
          <RevealStat label={rev.surplus >= 0 ? "Unallocated each month" : "Over budget"} value={bFmt(rev.surplus)} font={font}/>
          <RevealStat label="Toward goals monthly" value={bFmt(rev.goalsMonthly)} font={font}/>
        </div>
        {rev.topCats.length > 0 && (
          <div style={{ paddingTop: "0.9rem", borderTop: "1px solid " + C.stone }}>
            <div style={{ fontSize: "0.72rem", color: C.muted, fontFamily: font.body, marginBottom: "0.5rem", fontWeight: 500 }}>
              Top categories as share of income
            </div>
            {rev.topCats.map(c => (
              <div key={c.label} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0.35rem 0" }}>
                <span style={{ fontSize: "0.85rem", color: C.ink, fontFamily: font.body }}>{c.label}</span>
                <span style={{ fontSize: "0.85rem", color: C.ink, fontFamily: font.body, fontWeight: 600 }}>{c.pct.toFixed(1)}% · {bFmt(c.amount)}</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Block 2 — what you each said */}
      {(ex2Answers?.life || partnerEx2?.life) && (
        <div style={blockStyle}>
          <div style={blockHeader}>What you each said</div>
          <div style={{ fontSize: "0.75rem", color: C.muted, fontFamily: font.body, marginBottom: "0.75rem", fontStyle: "italic" }}>
            From your Expectations Exercise answers.
          </div>
          {echoQs.map((q, i) => {
            const mine = myLife[q.id];
            const theirs = parLife[mirrorLifeId(q.id)];
            if (!mine && !theirs) return null;
            return (
              <div key={q.id} style={{ padding: "0.7rem 0", borderTop: i === 0 ? "none" : "1px solid " + C.stone + "60" }}>
                <div style={{ fontSize: "0.78rem", color: C.muted, fontFamily: font.body, marginBottom: "0.35rem" }}>{q.label}</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.75rem" }}>
                  <div>
                    <div style={{ fontSize: "0.72rem", color: C.muted, fontFamily: font.body, textTransform: "uppercase", letterSpacing: "0.1em", marginBottom: "0.15rem" }}>{userName}</div>
                    <div style={{ fontSize: "0.88rem", color: C.ink, fontFamily: font.body, fontWeight: 500 }}>{mine || "—"}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: "0.72rem", color: C.muted, fontFamily: font.body, textTransform: "uppercase", letterSpacing: "0.1em", marginBottom: "0.15rem" }}>{partnerName}</div>
                    <div style={{ fontSize: "0.88rem", color: C.ink, fontFamily: font.body, fontWeight: 500 }}>{theirs || "—"}</div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Block 3 — how the money moves */}
      <div style={blockStyle}>
        <div style={blockHeader}>How the money moves</div>
        {rev.pooling === 'separate' ? (
          <div style={{ fontSize: "0.88rem", color: C.ink, fontFamily: font.body, lineHeight: 1.6 }}>
            You chose <strong>fully separate</strong>. Each of you tracks your own contribution independently, no shared split is calculated.
          </div>
        ) : rev.pooling === 'combined' ? (
          <div style={{ fontSize: "0.88rem", color: C.ink, fontFamily: font.body, lineHeight: 1.6 }}>
            You chose <strong>fully combined</strong>. Combined pool of {bFmt(rev.totalIncome)}/month covers {bFmt(rev.sharedExpenses + rev.goalsMonthly)} in shared expenses and savings, leaving {bFmt(rev.surplus)} unallocated from the pool.
          </div>
        ) : (
          <div>
            <div style={{ fontSize: "0.75rem", color: C.muted, fontFamily: font.body, marginBottom: "0.75rem" }}>
              Under <strong>{POOLING_MODELS.find(m => m.id === rev.pooling)?.label}</strong>:
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.85rem" }}>
              {[
                { name: userName,    contribution: rev.uContribution, personal: rev.uPersonal, leftover: rev.uLeftover },
                { name: partnerName, contribution: rev.pContribution, personal: rev.pPersonal, leftover: rev.pLeftover },
              ].map(p => (
                <div key={p.name} style={{ border: "1px solid " + C.stone, borderRadius: 10, padding: "0.75rem 0.9rem" }}>
                  <div style={{ fontSize: "0.76rem", color: C.muted, fontFamily: font.body, textTransform: "uppercase", letterSpacing: "0.1em", marginBottom: "0.4rem" }}>{p.name}</div>
                  <div style={{ fontSize: "0.78rem", color: C.ink, fontFamily: font.body, lineHeight: 1.7 }}>
                    <div>Contribution to shared: <strong>{bFmt(p.contribution)}</strong></div>
                    <div>Personal spending: <strong>{bFmt(p.personal)}</strong></div>
                    <div style={{ paddingTop: "0.3rem", borderTop: "1px solid " + C.stone + "80", marginTop: "0.3rem" }}>
                      Leftover: <strong>{bFmt(p.leftover)}</strong>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Outro: this is a living tool, not a one-time exercise. Keep the
          copy declarative and un-congratulatory, the budget isn't finished,
          it's alive. */}
      <div style={{ marginTop: "2rem", background: "linear-gradient(135deg, rgba(217,83,124,.05), rgba(232,103,58,.05))", border: "1.5px solid rgba(217,83,124,.22)", borderRadius: 16, padding: "1.5rem 1.6rem", textAlign: "center" }}>
        <p style={{ fontSize: "0.62rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#D9537C", fontWeight: 700, fontFamily: font.body, marginBottom: "0.65rem" }}>Your shared budget</p>
        <p style={{ fontFamily: font.display, fontSize: "1.2rem", fontWeight: 700, color: C.ink, lineHeight: 1.3, marginBottom: "0.6rem" }}>
          Built together. Revisit as things change.
        </p>
        <p style={{ fontSize: "0.82rem", color: C.muted, fontFamily: font.body, lineHeight: 1.7, margin: 0, maxWidth: 420, marginLeft: "auto", marginRight: "auto" }}>
          Raises, new expenses, goals that shift. Come back whenever the numbers do. Use <strong>Save changes</strong> to sync updates across both of your devices.
        </p>
      </div>
    </>
  );
}

// Reveal stat tile — bold number with a small label above
function RevealStat({ label, value, font }) {
  return (
    <div>
      <div style={{ fontSize: "0.65rem", letterSpacing: "0.15em", textTransform: "uppercase", color: C.muted, fontFamily: font.body, fontWeight: 600, marginBottom: "0.25rem" }}>{label}</div>
      <div style={{ fontFamily: font.display, fontSize: "1.4rem", fontWeight: 700, color: C.ink }}>{value}</div>
    </div>
  );
}

