// reflectionActionTitle and deriveAnniversaryInsights moved to
// api/_lib/reflection-insights.js so the app can render the same plan.
// Imported at the top of this file.



// The Relationship Reflection action plan had a page of its own and Ellie
// removed it from both surfaces: the plan itself is on the at-a-glance page,
// where a reader meets it without a detour. ActionPlanList drew that page and
// outlived it, unused, for long enough to look like something still in service.
//
// ─────────────────────────────────────────────────────────────────────────────
// BETA SURVEY MODAL — 4-question in-app feedback, triggered from results sidebar
// ─────────────────────────────────────────────────────────────────────────────
const BETA_Qs = [
  {
    id: "useful",
    q: "How useful were your results?",
    type: "scale",
    labels: ["Not useful", "Somewhat", "Very useful"],
  },
  {
    id: "surprise",
    q: "Was there anything in your results that surprised you?",
    type: "choice",
    options: ["Yes, something I didn't expect", "A little, some things landed differently", "Not really. It confirmed what I knew"],
  },
  {
    id: "together",
    q: "Have you reviewed your results with your partner yet?",
    type: "choice",
    options: ["Yes, together", "Not yet, planning to", "No. We did it separately"],
  },
  {
    id: "improve",
    q: "What would have made Attune more useful?",
    type: "text",
    placeholder: "Anything at all, length, format, what was missing, what felt off",
  },
];

function BetaSurveyModal({ userName, coupleType, onClose }) {
  const [step, setStep] = React.useState(0);
  const [answers, setAnswers] = React.useState({});
  const [submitted, setSubmitted] = React.useState(false);
  const [submitting, setSubmitting] = React.useState(false);

  const q = BETA_Qs[step];
  const total = BETA_Qs.length;
  const ans = answers[q?.id];
  const canNext = q?.type === "text" ? true : !!ans;

  const next = () => {
    if (step < total - 1) setStep(s => s + 1);
    else handleSubmit();
  };

  const handleSubmit = async () => {
    setSubmitting(true);
    try {
      await fetch('/api/get-feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'beta_survey', userName, coupleType: coupleType?.name, answers }),
      });
    } catch {}
    setSubmitted(true);
    setSubmitting(false);
  };

  if (submitted) return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(14,11,7,0.6)", zIndex: 500, display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem" }} onClick={onClose}>
      <div onClick={e => e.stopPropagation()} style={{ background: C.cream, borderRadius: 22, padding: "2.25rem 2rem", width: "100%", maxWidth: 400, textAlign: "center", maxHeight: "88dvh", overflowY: "auto", WebkitOverflowScrolling: "touch", boxShadow: "0 24px 64px rgba(0,0,0,0.25)" }}>
        <div style={{ width: 52, height: 52, borderRadius: "50%", background: "linear-gradient(135deg, #10b981, #059669)", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 1.25rem", fontSize: "1.3rem" }}>✓</div>
        <div style={{ fontFamily: font.display, fontSize: "1.3rem", fontWeight: 700, color: C.ink, marginBottom: "0.6rem" }}>Thank you.</div>
        <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: font.body, lineHeight: 1.7, marginBottom: "1.5rem" }}>Your feedback goes directly to the people building Attune. It shapes what we change.</p>
        <button onClick={onClose} style={{ background: C.ink, color: "white", border: "none", borderRadius: 11, padding: "0.7rem 2rem", fontSize: "0.82rem", fontWeight: 700, cursor: "pointer", fontFamily: font.body }}>Done</button>
      </div>
    </div>
  );

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(14,11,7,0.6)", zIndex: 500, display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem" }} onClick={onClose}>
      <div onClick={e => e.stopPropagation()} style={{ background: C.cream, borderRadius: 22, padding: "2.25rem 2rem", width: "100%", maxWidth: 420, maxHeight: "88dvh", overflowY: "auto", WebkitOverflowScrolling: "touch", boxShadow: "0 24px 64px rgba(0,0,0,0.25)" }}>
        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.75rem" }}>
          <div>
            <div style={{ fontSize: "0.55rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#E8673A", fontFamily: font.body, fontWeight: 700, marginBottom: "0.2rem" }}>Beta feedback</div>
            <div style={{ fontSize: "0.7rem", color: C.muted, fontFamily: font.body }}>{step + 1} of {total}</div>
          </div>
          <button onClick={onClose} aria-label="Close" style={{ background: "transparent", border: "none", fontSize: "1.1rem", cursor: "pointer", color: C.muted }}>✕</button>
        </div>

        {/* Progress bar */}
        <div style={{ height: 3, background: C.stone, borderRadius: 2, marginBottom: "1.75rem", overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${((step + 1) / total) * 100}%`, background: "linear-gradient(90deg,#E8673A,#1B5FE8)", borderRadius: 2, transition: "width 0.3s ease" }} />
        </div>

        {/* Question */}
        <div style={{ fontFamily: font.display, fontSize: "1.1rem", fontWeight: 700, color: C.ink, lineHeight: 1.3, marginBottom: "1.5rem" }}>{q.q}</div>

        {/* Scale */}
        {q.type === "scale" && (
          <div style={{ display: "flex", gap: "0.5rem", marginBottom: "0.5rem" }}>
            {[1, 2, 3, 4, 5].map(v => (
              <button key={v} onClick={() => setAnswers(a => ({ ...a, [q.id]: v }))}
                style={{ flex: 1, aspectRatio: "1", borderRadius: 10, border: `1.5px solid ${ans === v ? "#E8673A" : C.stone}`, background: ans === v ? "#FFF0EB" : "white", color: ans === v ? "#E8673A" : C.muted, fontWeight: ans === v ? 700 : 400, fontSize: "0.85rem", cursor: "pointer", transition: "all 0.12s", fontFamily: font.body }}>
                {v}
              </button>
            ))}
          </div>
        )}
        {q.type === "scale" && (
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.62rem", color: C.muted, fontFamily: font.body, marginBottom: "1.5rem" }}>
            {q.labels.map((l, i) => <span key={i}>{l}</span>)}
          </div>
        )}

        {/* Choice */}
        {q.type === "choice" && (
          <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem", marginBottom: "1.5rem" }}>
            {q.options.map((o, i) => (
              <button key={i} onClick={() => setAnswers(a => ({ ...a, [q.id]: o }))}
                style={{ padding: "0.75rem 1rem", borderRadius: 11, border: `1.5px solid ${ans === o ? "#E8673A" : C.stone}`, background: ans === o ? "#FFF0EB" : "white", color: ans === o ? "#E8673A" : C.ink, fontWeight: ans === o ? 600 : 400, fontSize: "0.82rem", cursor: "pointer", textAlign: "left", fontFamily: font.body, transition: "all 0.12s" }}>
                {o}
              </button>
            ))}
          </div>
        )}

        {/* Text */}
        {q.type === "text" && (
          <textarea
            placeholder={q.placeholder}
            value={ans || ""}
            onChange={e => setAnswers(a => ({ ...a, [q.id]: e.target.value }))}
            rows={4}
            style={{ width: "100%", border: `1.5px solid ${C.stone}`, borderRadius: 11, padding: "0.75rem 1rem", fontSize: "0.85rem", fontFamily: font.body, color: C.ink, background: "white", outline: "none", resize: "none", marginBottom: "1.5rem", boxSizing: "border-box" }}
          />
        )}

        <button onClick={next} disabled={!canNext || submitting}
          style={{ width: "100%", background: canNext ? "linear-gradient(135deg, #E8673A, #1B5FE8)" : C.stone, color: canNext ? "white" : C.muted, border: "none", borderRadius: 11, padding: "0.85rem", fontSize: "0.82rem", fontWeight: 700, cursor: canNext ? "pointer" : "default", fontFamily: font.body, transition: "all 0.15s" }}>
          {submitting ? "Submitting…" : step < total - 1 ? "Next →" : "Submit feedback"}
        </button>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// RETAKE COMPARISON CARD
// Shows on the results page when the user has completed an exercise more than
// once (we have both current answers and a prior snapshot). Surfaces the
// delta between completions as:
//   (a) a banner summary — "X of Y questions shifted since {date}"
//   (b) an expandable side-by-side accordion with before → after per change
// Returns null when there's no prior snapshot or when answers are identical.
//
// Focused on Exercise 2 (expectations) because those answers are
// categorical strings with stable keys — well-suited to string-equality
// delta detection. A future version can extend this to Ex1 and Ex3.
// ─────────────────────────────────────────────────────────────────────────────
function RetakeComparisonCard({ currentEx2, priorEx2, priorAt, userName, partnerName }) {
  const [expanded, setExpanded] = useState(false);

  // Flatten both answer sets into {categorizedKey: answerString} dicts so we
  // can compare apples to apples. Skip keys that are objects (bothDetail,
  // childhoodBothDetail) — those are secondary fields, not primary answers.
  const flatten = (obj) => {
    if (!obj || typeof obj !== 'object') return {};
    const out = {};
    // Responsibilities: keyed by `category__item` like household__Cooking meals
    if (obj.responsibilities && typeof obj.responsibilities === 'object') {
      Object.entries(obj.responsibilities).forEach(([k, v]) => {
        if (typeof v === 'string' && v.length > 0) out[`resp:${k}`] = v;
      });
    }
    // Life: keyed by lq_* like lq_children, lq_location
    if (obj.life && typeof obj.life === 'object') {
      Object.entries(obj.life).forEach(([k, v]) => {
        if (typeof v === 'string' && v.length > 0) out[`life:${k}`] = v;
      });
    }
    // Childhood: structured similar to responsibilities
    if (obj.childhood && typeof obj.childhood === 'object') {
      Object.entries(obj.childhood).forEach(([k, v]) => {
        if (typeof v === 'string' && v.length > 0) out[`child:${k}`] = v;
      });
    }
    // childhoodStructure — scalar
    if (typeof obj.childhoodStructure === 'string' && obj.childhoodStructure) {
      out['child:_structure'] = obj.childhoodStructure;
    }
    return out;
  };

  const cur = flatten(currentEx2);
  const prior = flatten(priorEx2);
  const priorKeys = Object.keys(prior);
  // No snapshot at all, or snapshot was empty — don't render
  if (priorKeys.length === 0) return null;

  // Find changed answers (present in both, different value)
  const changes = [];
  const unchanged = [];
  priorKeys.forEach(k => {
    if (!cur[k]) return; // question dropped between takes, skip
    if (cur[k] === prior[k]) unchanged.push(k);
    else changes.push({ key: k, before: prior[k], after: cur[k] });
  });

  // Nothing to show if everything stayed identical (still surface that fact
  // but in a muted way — it's a meaningful result that the user is
  // consistent across time)
  const totalComparable = changes.length + unchanged.length;
  if (totalComparable === 0) return null;

  // Friendly label for a question key
  const labelFor = (key) => {
    const [scope, rest] = key.split(':', 2);
    if (scope === 'resp') {
      // Format: "household__Cooking meals" → "Cooking meals (household)"
      const [cat, item] = rest.split('__');
      return item ? `${item}` : rest;
    }
    if (scope === 'life') {
      // lq_children → Children, lq_conflict_when → Conflict timing
      const map = {
        lq_children: 'Children',
        lq_involve_user: `Involvement with ${userName || 'your'}'s family`,
        lq_involve_partner: `Involvement with ${partnerName || "partner's"}'s family`,
        lq_family_conf: 'Family conflict loyalty', lq_location: 'Where you live',
        lq_social: 'Social life', lq_routine: 'Routine vs spontaneity',
        lq_faith: 'Faith / spirituality', lq_values: 'Core values',
        lq_finances: 'Combining finances', lq_money_lean: 'Saving vs spending',
        lq_money_risk: 'Risk tolerance',
      };
      return map[rest] || rest;
    }
    if (scope === 'child') {
      if (rest === '_structure') return 'Childhood home structure';
      const [cat, item] = rest.split('__');
      return item ? `${item}` : rest;
    }
    return key;
  };

  // Category grouping for the expanded view
  const scopeLabel = (key) => {
    if (key.startsWith('resp:')) return 'Responsibilities';
    if (key.startsWith('life:')) return 'Life & values';
    if (key.startsWith('child:')) return 'Childhood context';
    return 'Other';
  };
  const changesByScope = {};
  changes.forEach(c => {
    const scope = scopeLabel(c.key);
    if (!changesByScope[scope]) changesByScope[scope] = [];
    changesByScope[scope].push(c);
  });

  // Format the prior-completion date
  const priorDateStr = priorAt ? new Date(priorAt).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) : 'your last completion';

  const pctChanged = Math.round((changes.length / totalComparable) * 100);
  const shiftLevel = pctChanged >= 30 ? 'significant' : pctChanged >= 10 ? 'notable' : 'minor';
  const shiftColor = pctChanged >= 30 ? '#E8673A' : pctChanged >= 10 ? '#A66534' : '#10b981';

  return (
    <div style={{
      background: 'linear-gradient(135deg, rgba(232,103,58,0.04), rgba(27,95,232,0.04))',
      border: '1.5px solid rgba(232,103,58,0.18)',
      borderRadius: 14,
      padding: '1.1rem 1.25rem',
      marginBottom: '1.5rem',
    }}>
      {/* Eyebrow + summary */}
      <div style={{
        fontSize: '0.58rem',
        letterSpacing: '0.22em',
        textTransform: 'uppercase',
        color: shiftColor,
        fontWeight: 700,
        fontFamily: BFONT,
        marginBottom: '0.55rem',
      }}>
        ✦ Since last time
      </div>
      <div style={{ fontFamily: HFONT, fontSize: '1.15rem', fontWeight: 700, color: '#0E0B07', lineHeight: 1.35, marginBottom: '0.35rem' }}>
        {changes.length === 0
          ? `${userName}, your answers are consistent across time.`
          : `${userName}, you shifted on ${changes.length} of ${totalComparable} questions.`}
      </div>
      <p style={{ fontSize: '0.82rem', color: '#7A6753', fontFamily: BFONT, lineHeight: 1.6, margin: '0 0 0.85rem' }}>
        {changes.length === 0
          ? `You completed this on ${priorDateStr} and your views have held steady.`
          : `You completed this on ${priorDateStr}. That's a ${shiftLevel} shift, ${pctChanged}% of your answers changed.`}
      </p>

      {changes.length > 0 && (
        <button onClick={() => setExpanded(!expanded)}
          style={{
            background: 'transparent',
            border: '1px solid rgba(232,103,58,0.35)',
            color: '#A66534',
            fontSize: '0.72rem',
            fontWeight: 600,
            padding: '0.5rem 0.9rem',
            borderRadius: 8,
            cursor: 'pointer',
            fontFamily: BFONT,
            letterSpacing: '0.06em',
          }}>
          {expanded ? '✕ Hide comparison' : 'View side-by-side →'}
        </button>
      )}

      {expanded && (
        <div style={{ marginTop: '1rem', borderTop: '1px solid rgba(232,103,58,0.15)', paddingTop: '1rem' }}>
          {Object.entries(changesByScope).map(([scope, list]) => (
            <div key={scope} style={{ marginBottom: '1.1rem' }}>
              <div style={{
                fontSize: '0.6rem',
                letterSpacing: '0.2em',
                textTransform: 'uppercase',
                color: '#7A6753',
                fontWeight: 700,
                fontFamily: BFONT,
                marginBottom: '0.55rem',
              }}>
                {scope} · {list.length} shift{list.length === 1 ? '' : 's'}
              </div>
              {list.map(c => (
                <div key={c.key} style={{
                  background: 'white',
                  border: '1px solid #E8DDD0',
                  borderRadius: 10,
                  padding: '0.7rem 0.85rem',
                  marginBottom: '0.45rem',
                }}>
                  <div style={{ fontSize: '0.78rem', fontWeight: 600, color: '#0E0B07', fontFamily: BFONT, marginBottom: '0.45rem' }}>
                    {labelFor(c.key)}
                  </div>
                  <div style={{ display: 'flex', gap: '0.55rem', alignItems: 'stretch', flexWrap: 'wrap' }}>
                    <div style={{ flex: '1 1 140px', background: '#FBF8F3', border: '1px solid #E8DDD0', borderRadius: 7, padding: '0.45rem 0.6rem' }}>
                      <div style={{ fontSize: '0.58rem', letterSpacing: '0.16em', textTransform: 'uppercase', color: '#7A6753', fontWeight: 700, fontFamily: BFONT, marginBottom: '0.2rem' }}>Before</div>
                      <div style={{ fontSize: '0.76rem', color: '#5C4A38', fontFamily: BFONT, lineHeight: 1.45 }}>{c.before}</div>
                    </div>
                    <div style={{ flex: '0 0 auto', display: 'flex', alignItems: 'center', fontSize: '0.9rem', color: '#A66534' }}>→</div>
                    <div style={{ flex: '1 1 140px', background: 'linear-gradient(135deg, rgba(232,103,58,0.06), rgba(27,95,232,0.06))', border: '1px solid rgba(232,103,58,0.25)', borderRadius: 7, padding: '0.45rem 0.6rem' }}>
                      <div style={{ fontSize: '0.58rem', letterSpacing: '0.16em', textTransform: 'uppercase', color: '#A66534', fontWeight: 700, fontFamily: BFONT, marginBottom: '0.2rem' }}>Now</div>
                      <div style={{ fontSize: '0.76rem', color: '#0E0B07', fontFamily: BFONT, lineHeight: 1.45 }}>{c.after}</div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ))}
          <p style={{ fontSize: '0.7rem', color: '#7A6753', fontFamily: BFONT, lineHeight: 1.6, margin: '0.5rem 0 0', fontStyle: 'italic' }}>
            Shifts between retakes are normal and often meaningful. They're worth a conversation.
          </p>
        </div>
      )}
    </div>
  );
}

// ── Post-results survey (all couples). Mirrors the beta survey's key metrics
// in a shorter form so beta + general responses land on the same admin charts.
const POST_Qs = [
  { id: "rating",      q: "How would you rate your Attune experience?", type: "stars" },
  { id: "convo",       q: "Did it lead to a real conversation with your partner?", type: "choice", options: ["Yes", "Not yet"] },
  { id: "nps",         q: "How likely are you to recommend Attune to a friend?", type: "nps" },
  { id: "expectation", q: "How did it compare to what you expected?", type: "scale", labels: ["Fell short", "About right", "Exceeded"] },
  { id: "testimonial", q: "Anything you'd like to share about your experience?", sub: "Optional. We may feature your words as a testimonial on our site.", type: "text", optional: true, placeholder: "What stood out, what it opened up…" },
  { id: "improve",     q: "Anything you'd change?", type: "text", optional: true, placeholder: "Optional" },
];

function PostResultsSurvey({ respondentId = null, userName, coupleType, onClose, onDone }) {
  const [step, setStep] = React.useState(0);
  const [answers, setAnswers] = React.useState({});
  const [submitted, setSubmitted] = React.useState(false);
  const [submitting, setSubmitting] = React.useState(false);
  const q = POST_Qs[step];
  const total = POST_Qs.length;
  const ans = answers[q?.id];
  const canNext = q?.optional ? true : (q?.type === "text" ? true : (ans !== undefined && ans !== null && ans !== ""));

  const send = async (completed) => {
    try {
      await fetch('/api/submit-beta-survey', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ surveyType: 'post_results', respondentId, userName, coupleType: coupleType?.name || null, answers, completed }),
      });
    } catch {}
  };
  const finish = async () => { setSubmitting(true); await send(true); setSubmitted(true); setSubmitting(false); };
  const next = () => { if (step < total - 1) setStep(s => s + 1); else finish(); };
  // Incomplete capture: if they close with anything answered but not submitted,
  // still persist what we have.
  const close = () => { if (!submitted && Object.keys(answers).length > 0) { send(false); } onClose && onClose(); };

  if (submitted) return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(14,11,7,0.6)", zIndex: 500, display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem" }} onClick={() => { onDone && onDone(); }}>
      <div onClick={e => e.stopPropagation()} style={{ background: C.cream, borderRadius: 22, padding: "2.25rem 2rem", width: "100%", maxWidth: 400, textAlign: "center", maxHeight: "88dvh", overflowY: "auto", WebkitOverflowScrolling: "touch", boxShadow: "0 24px 64px rgba(0,0,0,0.25)" }}>
        <div style={{ width: 52, height: 52, borderRadius: "50%", background: "linear-gradient(135deg, #10b981, #059669)", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 1.25rem", fontSize: "1.3rem", color: "white" }}>✓</div>
        <div style={{ fontFamily: font.display, fontSize: "1.3rem", fontWeight: 700, color: C.ink, marginBottom: "0.6rem" }}>Thank you{userName ? `, ${userName}` : ""}.</div>
        <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: font.body, lineHeight: 1.7, marginBottom: "1.5rem" }}>This helps us understand Attune's impact and shape what comes next.</p>
        <button onClick={() => { onDone && onDone(); }} style={{ background: C.ink, color: "white", border: "none", borderRadius: 11, padding: "0.7rem 2rem", fontSize: "0.82rem", fontWeight: 700, cursor: "pointer", fontFamily: font.body }}>Done</button>
      </div>
    </div>
  );

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(14,11,7,0.6)", zIndex: 500, display: "flex", alignItems: "center", justifyContent: "center", padding: "1rem" }} onClick={close}>
      <div onClick={e => e.stopPropagation()} style={{ background: C.cream, borderRadius: 22, padding: "2.25rem 2rem", width: "100%", maxWidth: 440, maxHeight: "88dvh", overflowY: "auto", WebkitOverflowScrolling: "touch", boxShadow: "0 24px 64px rgba(0,0,0,0.25)" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem" }}>
          <div>
            <div style={{ fontSize: "0.55rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#E8673A", fontFamily: font.body, fontWeight: 700, marginBottom: "0.2rem" }}>Your experience</div>
            <div style={{ fontSize: "0.7rem", color: C.muted, fontFamily: font.body }}>{step + 1} of {total}</div>
          </div>
          <button onClick={close} aria-label="Close" style={{ background: "transparent", border: "none", fontSize: "1.1rem", cursor: "pointer", color: C.muted }}>✕</button>
        </div>
        <div style={{ height: 3, background: C.stone, borderRadius: 2, marginBottom: "1.6rem", overflow: "hidden" }}>
          <div style={{ height: "100%", width: `${((step + 1) / total) * 100}%`, background: "linear-gradient(90deg,#E8673A,#1B5FE8)", borderRadius: 2, transition: "width 0.3s ease" }} />
        </div>
        <div style={{ fontFamily: font.display, fontSize: "1.1rem", fontWeight: 700, color: C.ink, lineHeight: 1.3, marginBottom: q.sub ? "0.4rem" : "1.4rem" }}>{q.q}</div>
        {q.sub && <div style={{ fontSize: "0.72rem", color: C.muted, fontFamily: font.body, marginBottom: "1.2rem", lineHeight: 1.5 }}>{q.sub}</div>}

        {q.type === "stars" && (
          <div style={{ display: "flex", gap: "0.4rem", justifyContent: "center", marginBottom: "1.6rem" }}>
            {[1,2,3,4,5].map(v => (
              <button key={v} onClick={() => setAnswers(a => ({ ...a, [q.id]: v }))} aria-label={`${v} star`}
                style={{ background: "transparent", border: "none", cursor: "pointer", fontSize: "2rem", lineHeight: 1, color: (ans >= v) ? "#E8673A" : "#D9CFC2", transition: "color .1s" }}>{ans >= v ? "★" : "☆"}</button>
            ))}
          </div>
        )}
        {q.type === "nps" && (
          <div style={{ marginBottom: "1.6rem" }}>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(11,1fr)", gap: "0.25rem" }}>
              {Array.from({ length: 11 }, (_, v) => (
                <button key={v} onClick={() => setAnswers(a => ({ ...a, [q.id]: v }))}
                  style={{ aspectRatio: "1", borderRadius: 8, border: `1.5px solid ${ans === v ? "#E8673A" : C.stone}`, background: ans === v ? "#FFF0EB" : "white", color: ans === v ? "#E8673A" : C.muted, fontWeight: ans === v ? 700 : 400, fontSize: "0.72rem", cursor: "pointer", fontFamily: font.body }}>{v}</button>
              ))}
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.6rem", color: C.muted, fontFamily: font.body, marginTop: "0.4rem" }}><span>Not likely</span><span>Very likely</span></div>
          </div>
        )}
        {q.type === "scale" && (<>
          <div style={{ display: "flex", gap: "0.5rem", marginBottom: "0.5rem" }}>
            {[1,2,3,4,5].map(v => (
              <button key={v} onClick={() => setAnswers(a => ({ ...a, [q.id]: v }))}
                style={{ flex: 1, aspectRatio: "1", borderRadius: 10, border: `1.5px solid ${ans === v ? "#E8673A" : C.stone}`, background: ans === v ? "#FFF0EB" : "white", color: ans === v ? "#E8673A" : C.muted, fontWeight: ans === v ? 700 : 400, fontSize: "0.85rem", cursor: "pointer", fontFamily: font.body }}>{v}</button>
            ))}
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.62rem", color: C.muted, fontFamily: font.body, marginBottom: "1.5rem" }}>{q.labels.map((l,i)=><span key={i}>{l}</span>)}</div>
        </>)}
        {q.type === "choice" && (
          <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem", marginBottom: "1.5rem" }}>
            {q.options.map((o,i) => (
              <button key={i} onClick={() => setAnswers(a => ({ ...a, [q.id]: o }))}
                style={{ padding: "0.75rem 1rem", borderRadius: 11, border: `1.5px solid ${ans === o ? "#E8673A" : C.stone}`, background: ans === o ? "#FFF0EB" : "white", color: ans === o ? "#E8673A" : C.ink, fontWeight: ans === o ? 600 : 400, fontSize: "0.82rem", cursor: "pointer", textAlign: "left", fontFamily: font.body }}>{o}</button>
            ))}
          </div>
        )}
        {q.type === "text" && (
          <textarea placeholder={q.placeholder} value={ans || ""} onChange={e => setAnswers(a => ({ ...a, [q.id]: e.target.value }))}
            style={{ width: "100%", minHeight: 90, borderRadius: 11, border: `1.5px solid ${C.stone}`, padding: "0.75rem", fontSize: "0.82rem", fontFamily: font.body, color: C.ink, resize: "vertical", marginBottom: "1.5rem", boxSizing: "border-box" }} />
        )}

        <div style={{ display: "flex", gap: "0.6rem", alignItems: "center" }}>
          {step > 0 && <button onClick={() => setStep(s => s - 1)} style={{ background: "transparent", border: `1.5px solid ${C.stone}`, borderRadius: 11, padding: "0.7rem 1.1rem", fontSize: "0.8rem", fontWeight: 600, cursor: "pointer", color: C.muted, fontFamily: font.body }}>Back</button>}
          <button onClick={next} disabled={!canNext || submitting}
            style={{ flex: 1, background: (canNext && !submitting) ? C.ink : C.stone, color: "white", border: "none", borderRadius: 11, padding: "0.75rem", fontSize: "0.82rem", fontWeight: 700, cursor: (canNext && !submitting) ? "pointer" : "default", fontFamily: font.body }}>
            {submitting ? "Sending…" : (step < total - 1 ? "Next" : "Submit")}
          </button>
        </div>
        <div style={{ fontSize: "0.6rem", color: C.muted, fontStyle: "italic", fontFamily: font.body, textAlign: "center", marginTop: "1rem", lineHeight: 1.5 }}>Responses are used in aggregate to assess the impact of the Attune experience.</div>
      </div>
    </div>
  );
}

// Wraps the results tree so every component inside renders from the copy
// version stamped on this couple's results row. contentVersion is null for
// demo mode and for couples stamped before pinning existed, which resolves to
// current.
function UnifiedResultsRoot(props) {
  return (
    <ContentContext.Provider value={props.contentVersion ?? null}>
      <UnifiedResults {...props} />
    </ContentContext.Provider>
  );
}

/**
 * "How was your experience?", at the end of the results.
 *
 * ── WHY IT IS BACK ────────────────────────────────────────────────────────
 * It was a component here once, already disconnected from anything that
 * rendered it, and d54d7c2 deleted it as unreferenced. Nothing has asked for
 * feedback since. /api/send-feedback, /api/get-feedback and two tiles on the
 * admin kept reporting on it, all showing nothing.
 *
 * Every sentence and every question comes from api/_lib/feedback-copy.js,
 * which the app's screen reads too, so the two surfaces cannot ask different
 * questions. The wording is Ellie's, recovered from the deleted component
 * rather than rewritten.
 *
 * ── WHERE IT SITS ─────────────────────────────────────────────────────────
 * The end of What Comes Next, which is the last page of the whole results
 * experience. Asking before somebody has read their results is asking about
 * something they have not seen.
 */
function ExperienceFeedback({ userName }) {
  const [phase, setPhase] = useState("idle");   // idle | form | thanks
  const [rating, setRating] = useState(null);
  const [answers, setAnswers] = useState({});
  const [sending, setSending] = useState(false);

  const scaleQuestions = FEEDBACK_QUESTIONS.filter(q => q.type === "scale");
  const allScaleAnswered = scaleQuestions.every(q => answers[q.id] != null);

  function submit() {
    setSending(true);
    fetch('/api/send-feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        source: 'app_experience',
        rating,
        questionAnswers: answers,
        stage: answers.q_stage || null,
        howHeard: answers.q_source || null,
        message: answers.q_open || null,
      }),
    }).catch(() => {});   // non-blocking: a thank you is owed either way
    setTimeout(() => { setPhase("thanks"); setSending(false); }, 400);
  }

  if (phase === "thanks") {
    return (
      <div style={{ marginTop: "2.5rem", background: "linear-gradient(135deg,#0e2a18,#154428)", borderRadius: 18, padding: "2rem", textAlign: "center" }}>
        <div style={{ fontFamily: HFONT, fontSize: "1.05rem", fontWeight: 700, color: "white", marginBottom: "0.4rem" }}>
          {FEEDBACK_COPY.thanksTitle}{userName ? `, ${userName}` : ""}.
        </div>
        <p style={{ fontSize: "0.78rem", color: "rgba(255,255,255,.55)", lineHeight: 1.65, margin: 0 }}>{FEEDBACK_COPY.thanks}</p>
      </div>
    );
  }

  if (phase === "idle") {
    return (
      <div style={{ marginTop: "2.5rem", background: "linear-gradient(135deg,#0f0c29,#1d1a4e)", borderRadius: 18, padding: "2rem", textAlign: "center", position: "relative", overflow: "hidden" }}>
        <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 3, background: "linear-gradient(90deg,#E8673A,#1B5FE8)" }} />
        <div style={{ fontFamily: HFONT, fontSize: "1.1rem", fontWeight: 700, color: "white", marginBottom: "0.4rem" }}>{FEEDBACK_COPY.title}</div>
        <p style={{ fontSize: "0.78rem", color: "rgba(255,255,255,.75)", lineHeight: 1.65, maxWidth: 400, margin: "0 auto 1.25rem" }}>{FEEDBACK_COPY.invitation}</p>
        <div style={{ display: "flex", gap: "0.75rem", justifyContent: "center", flexWrap: "wrap", marginBottom: "1rem" }}>
          {FEEDBACK_RATINGS.map((label, i) => (
            <button key={label} onClick={() => { setRating(i); setPhase("form"); }}
              style={{ background: "rgba(255,255,255,.08)", border: "1.5px solid rgba(255,255,255,.15)", borderRadius: 10, padding: "0.55rem 1rem", fontSize: "0.8rem", color: "rgba(255,255,255,.75)", cursor: "pointer", fontFamily: BFONT, fontWeight: 500 }}>
              {label}
            </button>
          ))}
        </div>
        <button onClick={() => setPhase("form")}
          style={{ fontSize: "0.7rem", color: "rgba(255,255,255,.4)", background: "transparent", border: "none", cursor: "pointer", fontFamily: BFONT, textDecoration: "underline" }}>
          {FEEDBACK_COPY.skip}
        </button>
      </div>
    );
  }

  const chip = (id, value, label) => {
    const on = answers[id] === value;
    return (
      <button key={String(value)} onClick={() => setAnswers(a => ({ ...a, [id]: on ? undefined : value }))}
        style={{ background: on ? "#1B5FE8" : "white", color: on ? "white" : C.muted, border: `1.5px solid ${on ? "#1B5FE8" : C.stone}`, borderRadius: 999, padding: "0.4rem 0.85rem", fontSize: "0.75rem", fontFamily: BFONT, cursor: "pointer" }}>
        {label}
      </button>
    );
  };

  return (
    <div style={{ marginTop: "2.5rem", background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 18, padding: "1.75rem" }}>
      <div style={{ fontFamily: HFONT, fontSize: "1.05rem", fontWeight: 700, color: C.ink }}>{FEEDBACK_COPY.cta}</div>
      <p style={{ fontSize: "0.72rem", color: C.muted, fontFamily: BFONT, margin: "0.3rem 0 1.25rem" }}>{FEEDBACK_COPY.reassurance}</p>

      <div style={{ fontSize: "0.62rem", letterSpacing: ".16em", textTransform: "uppercase", color: C.muted, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.75rem" }}>{FEEDBACK_COPY.scaleHeading}</div>

      {FEEDBACK_QUESTIONS.map(q => (
        <div key={q.id} style={{ marginBottom: "1.1rem" }}>
          <div style={{ fontSize: "0.82rem", color: C.ink, fontFamily: BFONT, marginBottom: "0.45rem" }}>{q.label}</div>
          {q.type === "scale" && (
            <div style={{ display: "flex", gap: "0.4rem", flexWrap: "wrap" }}>
              {FEEDBACK_SCALE.map((label, i) => chip(q.id, i + 1, label))}
            </div>
          )}
          {q.type === "choice" && (
            <div style={{ display: "flex", gap: "0.4rem", flexWrap: "wrap" }}>
              {(q.options || []).map(opt => chip(q.id, opt, opt))}
            </div>
          )}
          {q.type === "text" && (
            <textarea value={answers[q.id] || ""} onChange={e => setAnswers(a => ({ ...a, [q.id]: e.target.value }))}
              rows={3}
              style={{ width: "100%", padding: "0.6rem 0.75rem", border: `1.5px solid ${C.stone}`, borderRadius: 10, fontSize: "0.82rem", fontFamily: BFONT, color: C.ink, resize: "vertical" }} />
          )}
        </div>
      ))}

      <button onClick={submit} disabled={!allScaleAnswered || sending}
        style={{ marginTop: "0.5rem", background: allScaleAnswered && !sending ? "linear-gradient(135deg,#E8673A,#1B5FE8)" : C.stone, color: allScaleAnswered && !sending ? "white" : C.muted, border: "none", borderRadius: 10, padding: "0.7rem 1.5rem", fontSize: "0.8rem", fontWeight: 700, fontFamily: BFONT, cursor: allScaleAnswered && !sending ? "pointer" : "default" }}>
        {sending ? FEEDBACK_COPY.submitting : FEEDBACK_COPY.submit}
      </button>

      <p style={{ fontSize: "0.7rem", color: C.muted, fontFamily: BFONT, marginTop: "0.9rem", marginBottom: 0 }}>{FEEDBACK_COPY.privacy}</p>
    </div>
  );
}

function UnifiedResults({ ex1Answers, partnerEx1, ex2Answers, partnerEx2, ex3Answers, partnerEx3, ex2AnswersPrior = null, ex2PriorAt = null, hasAnniversary, userName, partnerName, initialSection, onSectionChange = null, isMobile = false, portrait = null, hasChecklist = false, hasBudget = false, hasWorkbook = false, hasIntimacy = false, intimacyAnswers = null, partnerIntimacy = null, hasConflict = false, conflictAnswers = null, conflictResults = null, intimacyVariant = 'premarital', onNavigateTool = null, userPronouns = "", partnerPronouns = "", isBetaTester = false }) {

  // Compute all the data we need up front
  const myS = typingDimScores(ex1Answers, partnerEx1);
  const partS = typingDimScores(partnerEx1, ex1Answers);
  // Self-report scores for the dimension GAP feedback (bars/gaps stay self; only type & placement blend).
  const mySelf = calcDimScores(ex1Answers);
  const partSelf = calcDimScores(partnerEx1);
  // Same-type couples get a single combined "Communication Profile" page; the
  // comms sub-nav label reflects that.
  // Copy for this couple: the version stamped on their results row.
  const _content = useContent();
  const personalityFeedback = generatePersonalityFeedback(mySelf, partSelf, userName, partnerName, _content);
  const sortedFeedback = [...personalityFeedback].sort((a, b) => a.gap - b.gap);
  // Domain order — matches PersonalityResults navigation
  // The same one list. This was the second hand-written copy.
  const orderedDims = DIMENSION_DISPLAY_ORDER.filter(d => personalityFeedback.some(f => f.dim === d));
  // Comms detailed results are three grouped domain pages, not one per dimension.
  // COMM_DOMAINS. This was a full copy of it, ids, labels, colours and all,
  // under a comment saying it "must stay in step with detailDomains inside
  // PersonalityResults". It cannot drift now because there is nothing to drift
  // from: both read the one module the app reads too.
  const UR_DOMAINS = COMM_DOMAINS
    .filter(g => orderedDims.some(d => g.dims.includes(d)));
  const nUR = UR_DOMAINS.length;
  const byDim = Object.fromEntries(personalityFeedback.map(f => [f.dim, f]));
  const avgGap = personalityFeedback.reduce((s, f) => s + f.gap, 0) / personalityFeedback.length;
  const pairing = overallPairingLabel(avgGap);

  // Expectations data
  const allRows = RESPONSIBILITY_CATEGORIES.flatMap(cat =>
    cat.items.map(item => {
      const key = `${cat.id}__${item}`;
      const rawMine = ex2Answers?.responsibilities?.[key];
      const rawTheirs = rawMine ? partnerEx2?.responsibilities?.[mirrorRespKey(key)] : null;
      const mine = rawMine ? normRespValue(rawMine, true, userName, partnerName) : rawMine;
      const theirs = rawTheirs ? normRespValue(rawTheirs, false, userName, partnerName) : rawTheirs;
      const bothAnswered = mine && theirs;
      const aligned = mine === theirs;
      const score = bothAnswered ? scoreRespClient(rawMine, rawTheirs, userName, partnerName) : null;
      return { item: substName(item, userName, partnerName), category: cat.label, catId: cat.id, mine, theirs, aligned, bothAnswered, score };
    })
  );
  const expCatSummary = RESPONSIBILITY_CATEGORIES.map(cat => {
    const rows = allRows.filter(r => r.catId === cat.id && r.bothAnswered && r.score != null);
    const pct = rows.length
      ? Math.round((rows.reduce((a, r) => a + r.score, 0) / rows.length) * 100)
      : null;
    return { ...cat, pct };
  });

  const alignedCount = allRows.filter(r => r.aligned && r.bothAnswered).length;
  // Headline expectations alignment: similarity-based overall (mean of 6
  // domain pcts). Matches the workbook Snapshot overall row.
  const alignPct = computeOverallExpectationsPctClient(ex2Answers, partnerEx2, userName, partnerName);
  const coupleType = deriveCoupleTypeFromExercise(
    myS, partS, alignPct
  );
  const [typeShared, setTypeShared] = useState(false);
  const shareCardRef = useRef(null);
  const [shareBusy, setShareBusy] = useState(false);
  const [showSurvey, setShowSurvey] = useState(false);
  const [stayEmail, setStayEmail] = useState('');
  const [stayDone, setStayDone] = useState(() => { try { return !!localStorage.getItem('attune_stay_subscribed'); } catch { return false; } });
  const [stayLoading, setStayLoading] = useState(false);
  const handleStaySubmit = async () => {
    if (!stayEmail.trim() || !stayEmail.includes('@')) return;
    setStayLoading(true);
    try {
      // account isn't a prop of UnifiedResults — read from localStorage
      // (matches the same lookup pattern used elsewhere in this component).
      const _acct = (() => { try { return JSON.parse(localStorage.getItem('attune_account') || 'null'); } catch { return null; } })();
      // beta_survey email retired (email #10 removed).
      localStorage.setItem('attune_stay_subscribed', '1');
    } catch {}
    setStayDone(true);
    setStayLoading(false);
  };

  // Section/page system: "summary" | "comm-overview" | "comm-{dim}" | "exp-overview" | "exp-{catId}" | "exp-life" | "reflection"
  // The results section is part of the URL, so a page can be linked to,
  // shared, bookmarked, and opened directly by a notification. A query param
  // rather than a path segment: no server rewrite rules needed, and the static
  // routes (/checkout, /start) are unaffected.
  const SECTION_PARAM = "s";
  const sectionFromUrl = () => {
    try { return new URLSearchParams(window.location.search).get(SECTION_PARAM) || null; } catch { return null; }
  };
  const writeSectionToUrl = (sec, { replace = false } = {}) => {
    try {
      const url = new URL(window.location.href);
      if (sec) url.searchParams.set(SECTION_PARAM, sec); else url.searchParams.delete(SECTION_PARAM);
      const method = replace ? "replaceState" : "pushState";
      window.history[method]({ ...(window.history.state || {}), attuneSection: sec }, "", url.toString());
    } catch {}
  };

  const mapSection = (s) => {
    if (s === "personality") return "comm-overview";
    if (s === "expectations") return "exp-overview";
    if (s === "anniversary") return "reflection";
    // Migrate saved section ids that were removed/renamed, so returning users
    // whose stored state points at an old page don't land on a blank section.
    if (s === "couple-map") return "couple-type";
    if (s === "summary" || s === "full-summary") return "couple-type";
    if (!s) return "highlights";
    // A section this couple does not own (a core package on reflection-plan
    // from a stale stored state or a shared link) used to render an empty
    // column. Sections are validated against availableSections below.
    return s;
  };
  const getInitialSection = () => mapSection(sectionFromUrl() || initialSection);
  // Sections this couple can actually reach. hasAnniversary and
  // intimacyBothDone are declared further down the component body, so this has
  // to stay a function: calling it during the initial render would hit the
  // temporal dead zone. It is only ever called from effects and from go(),
  // both of which run after the body has finished executing.
  // Which sections this couple can reach, from api/_lib/results-sections.js.
  //
  // This list used to be written out here, and the app wrote out a different
  // one with six entries and its own labels. Two products, same name. It stays
  // a function for the same reason as before: hasAnniversary and
  // intimacyBothDone are declared below, so calling it during the initial
  // render would hit the temporal dead zone.
  const availableSections = () => availableResultsSections({
    hasReflection: hasAnniversary,
    intimacyReady: intimacyBothDone,
    conflictListed,
  });
  const safeSection = (s) => {
    const m = mapSection(s);
    return availableSections().includes(m) ? m : "highlights";
  };
  const [section, setSection] = useState(getInitialSection());

  /**
   * How long each results section is read for.
   *
   * The view timer above files the whole results experience under one key,
   * 'app:results', which answers "how long do results take" and not "which
   * page do people stay on". Ellie asked the Engagement page for the second.
   *
   * Same sender, so the consent rule in public/_track.js covers this too.
   */
  useEffect(() => {
    if (typeof window === 'undefined' || !window.__attuneTrack || !section) return;
    const started = Date.now();
    const opened = section;
    return () => {
      const ms = Date.now() - started;
      if (ms >= 1000) window.__attuneTrack('page_time', 'app:results:' + opened, ms);
    };
  }, [section]);
  const [commExpanded, setCommExpanded] = useState(section.startsWith("comm"));
  const [expExpanded, setExpExpanded] = useState(section.startsWith("exp"));
  const [reflExpanded, setReflExpanded] = useState(section.startsWith("reflection"));
  const [intimExpanded, setIntimExpanded] = useState(section.startsWith("intimacy"));
  const [conflictExpanded, setConflictExpanded] = useState(section.startsWith("conflict"));
  // section is internal state seeded once from initialSection. The mobile
  // sub-nav lives outside this component and can only set the parent's
  // activeResult, so without this every mobile tab was a no-op. Deliberately
  // keyed on initialSection alone: adding section to the deps would fight
  // with go().
  // Correct an unreachable stored section after mount (a core package landing
  // on reflection-plan from a stale saved state or a shared link).
  useEffect(() => {
    setSection(cur => {
      if (availableSections().includes(cur)) return cur;
      // Report up too, so the persisted state stops pointing at a page this
      // couple cannot reach and a refresh does not repeat the correction.
      if (onSectionChange) onSectionChange("highlights");
      return "highlights";
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!initialSection) return;
    const mapped = safeSection(initialSection);
    setSection(cur => {
      if (mapped === cur) return cur;
      setCommExpanded(mapped.startsWith("comm"));
      setExpExpanded(mapped.startsWith("exp"));
      setReflExpanded(mapped.startsWith("reflection"));
      setIntimExpanded(mapped.startsWith("intimacy"));
      setConflictExpanded(mapped.startsWith("conflict"));
      return mapped;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialSection]);
  // Intimacy results: only present when the couple owns the add-on AND both
  // partners have finished. summarizeIntimacy is imported at module top.
  const intimacyBothDone = hasIntimacy && !!(intimacyAnswers) && !!(partnerIntimacy?.answers);
  const intimacySummary = intimacyBothDone ? summarizeIntimacy(intimacyAnswers, partnerIntimacy.answers) : null;

  // Conflict results appear as soon as THIS person has finished, unlike every
  // other exercise: their patterns are their own and do not need the partner.
  // The shared sections fill in later, so this section can be half-populated,
  // which no other results section can be.
  // Gated on both partners, like every other exercise. The patterns section is
  // still private to each viewer once open; gating controls WHEN results
  // appear, not who can see what inside them.
  /**
   * Conflict results come from /api/conflict-results, not from this device.
   *
   * They were computed here, from `conflictAnswers` and a `partnerConflict`
   * prop that was always null: the partner's raw conflict record is withheld
   * by /api/partner-sync on purpose, because the pattern half is private and
   * the product says so in writing on the page. So conflictBothDone was always
   * false and every conflict page on this site said "Not open yet", for every
   * couple, however long ago they had both finished.
   *
   * That is also the answer to "conflict works on the app and not the web":
   * the app has always read this endpoint. It pairs the two records on the
   * server, where both legitimately are, and applies the partner allowlist on
   * the way out.
   *
   * `you` is the reader's own full summary and `partner` is the allowlisted
   * view of theirs, which is everything these pages draw.
   */
  const conflictSelf = conflictResults?.ready ? conflictResults.you : null;
  const conflictTheirs = conflictResults?.ready ? conflictResults.partner : null;
  const conflictBothDone = !!(conflictSelf && conflictTheirs);
  /**
   * Your own summary, available as soon as YOU have finished.
   *
   * This was gated on both partners, which made Your Patterns wait for a
   * partner it does not use: it is the private page, built from the reader's
   * answers alone. The three shared pages are gated where they are rendered.
   */
  const conflictMine = conflictSelf;
  // Nav presence only requires owning it, so the section is listed and greyed
  // rather than missing, which is how the other exercises behave.
  const conflictListed = !!hasConflict;
  /**
   * The pairing, which was conflictPair(mine, theirs) over two raw records.
   *
   * It cannot be that any more and should never have been: it needed the
   * partner's raw answers. `partner` on the endpoint's payload is the
   * allowlisted view of their summary, which is the same `b` shape these pages
   * read: overall, repairRanking, openings, strength, reflection, appreciation.
   */
  const conflictPairing = conflictBothDone ? { a: conflictSelf, b: conflictTheirs } : null;

  // ── ANONYMOUS TYPE TRACKING ─────────────────────────────────────────────────
  // Fires once per results session. No PII — only type IDs and 4-letter style codes.
  const _typeFired = useRef(false);
  useEffect(() => {
    if (_typeFired.current) return;
    /* Nothing to report until the couple has a type. */
    if (!coupleType?.id) return;
    _typeFired.current = true;
    const codeA = getStyleCode(myS);
    const codeB = getStyleCode(partS);
    /* The same banding the couple reads on their results page. It used to be
       its own, at 1.0, 1.8 and 2.5, so the chart Ellie reads disagreed with
       what the customer was told about one couple in five. */
    const gapTier = pairingTier(avgGap);
    const hasEx2 = !!(ex2Answers && partnerEx2 && Object.keys(ex2Answers).length > 0 && Object.keys(partnerEx2).length > 0);
    fetch("/api/track-type", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        /* No fallback. "complementary" is not a couple type any more and was
           being sent for every couple the engine could not place, so the one
           bucket with anything in it was a legacy name standing for an absence.
           A couple with no type is not counted, which is the honest answer. */
        coupleTypeId: coupleType.id,
        codeA, codeB, gapTier, hasEx2,
      }),
    }).catch(() => {}); // non-blocking, non-critical

    // ── Save full computed session to localStorage for admin workbook generation ──
    // Serializes the real scores, couple type, and expectations gaps from this session.
    // Admin reads attune_live_session to generate a real personalized workbook.
    try {
      const account = (() => { try { return JSON.parse(localStorage.getItem('attune_account') || 'null'); } catch { return null; } })();
      // Build the full payload structure once. Phase 5a: session now stores
      // the rich payload so admin/auto-fulfill paths can pass everything
      // straight through to the workbook endpoint without rebuilding it.
      const sessionPayload = buildWorkbookPayload(
        userName || account?.name || 'Partner A',
        partnerName || account?.partnerName || 'Partner B',
        ex1Answers, partnerEx1,
        ex2Answers, partnerEx2,
        coupleType
      );
      const session = {
        savedAt:      Date.now(),
        userName:     sessionPayload.userName,
        partnerName:  sessionPayload.partnerName,
        pkg:          account?.pkg || 'core',
        scores:       sessionPayload.scores,
        partnerScores: sessionPayload.partnerScores,
        coupleType:   coupleType ? {
          id:          coupleType.id,
          name:        coupleType?.name,
          tagline:     coupleType?.tagline,
          description: coupleType?.description,
          nuance:      coupleType?.nuance,
          color:       coupleType?.color,
        } : null,
        // The workbook's reference card opens with "Phrase for the two of you".
        // It reads phrase_that_lands, which payloadToCouple takes from
        // phraseThatLands (or coupleType.tips[0].phraseTry). This session object
        // strips tips and never carried the phrase, so the card rendered blank.
        // Resolve the name and role tokens here — the builder only substitutes
        // {U}/{P}, so an unresolved {EXP}/{GRD} would print raw.
        phraseThatLands: (() => {
          const raw = coupleType?.tips?.[0]?.phraseTry;
          if (!raw) return null;
          const named = raw
            .replace(/\{U\}/g, userName || 'Partner A')
            .replace(/\{P\}/g, partnerName || 'Partner B');
          try { return resolveRoleTokens(named, myS, partS, userName, partnerName); }
          catch { return named; }
        })(),
        // Phase 5a fields
        responsibilities: sessionPayload.responsibilities,
        lifeQuestions:    sessionPayload.lifeQuestions,
        // Legacy field, kept for backward compatibility
        expGaps:          sessionPayload.expGaps,
      };
      localStorage.setItem('attune_live_session', JSON.stringify(session));
    } catch (_) {}

    // ── Fire the 30-day workbook flash promo (once results are ready) ────────
    // Couples who did NOT already buy the workbook get a single-use, 30%-off
    // code emailed to both partners. The endpoint is idempotent and binds the
    // code to the couple, so firing from either partner/device is safe.
    (async () => {
      try {
        if (localStorage.getItem('attune_wb_promo_fired')) return;
        const _ord = (() => { try { return JSON.parse(localStorage.getItem('attune_order') || 'null'); } catch { return null; } })();
        if (_ord?.addonWorkbook) return; // already owns the workbook
        const _acct = (() => { try { return JSON.parse(localStorage.getItem('attune_account') || 'null'); } catch { return null; } })();
        if (!_acct?.email) return;
        const bothEx1 = !!(ex1Answers && partnerEx1 && Object.keys(ex1Answers).length && Object.keys(partnerEx1).length);
        const bothEx2 = !!(ex2Answers && partnerEx2 && Object.keys(ex2Answers).length && Object.keys(partnerEx2).length);
        if (!bothEx1 || !bothEx2) return;
        try { localStorage.setItem('attune_wb_promo_fired', '1'); } catch {}
        const { supabase: _sbp } = await import('./supabase.js');
        const { data: { session: _sp } } = await _sbp.auth.getSession();
        await fetch('/api/generate-workbook-promo', {
          method: 'POST', headers: { 'Content-Type': 'application/json', ...(_sp?.access_token ? { Authorization: `Bearer ${_sp.access_token}` } : {}) },
          body: JSON.stringify({
            accountEmail: _acct.email,
            partnerEmail: _acct.partnerEmail || '',
            toName:       _acct.name || '',
            partnerName:  _acct.partnerName || '',
          }),
        });
      } catch (e) { console.warn('[Attune] workbook promo trigger failed:', e); }
    })();

    // ── Auto-fulfil workbook if pre-ordered ─────────────────────────────────
    // If the couple ordered a digital workbook before completing exercises,
    // generate it now and mark it ready. If they ordered print, flag for fulfillment.
    // Gates: order exists, workbook addon purchased, not already generated,
    // and BOTH partners have completed ex1 and ex2 (partial data would
    // produce a workbook with empty sections, which we never want to ship).
    (async () => {
      try {
        const orderRaw = localStorage.getItem('attune_order');
        if (!orderRaw) return;
        const ord = JSON.parse(orderRaw);
        // 10.6 — ownership is not the same as the add-on flag. Premium (and comp
        // premium) accounts include the workbook while addonWorkbook stays ''.
        // Guarding on addonWorkbook alone meant generation never fired for them
        // and the dashboard sat on "Generating now" forever.
        const _ownsWorkbook = !!ord?.addonWorkbook || (ord?.pkgKey || ord?.pkg) === 'premium';
        if (!_ownsWorkbook) return;
        if (localStorage.getItem('attune_workbook_ready') === 'true') return; // already done
        // A URL means the file exists. Whether its signature has expired is a
        // different question, and not this one: it decides whether to generate,
        // not whether to hand anyone a link.
        if (ord?.workbookUrl) return; // generated on another device

        // Require both partners to have completed both exercises. Without
        // this, the workbook would generate from one partner's data alone.
        const bothEx1Done = !!(ex1Answers && partnerEx1
          && Object.keys(ex1Answers).length > 0
          && Object.keys(partnerEx1).length > 0);
        const bothEx2Done = !!(ex2Answers && partnerEx2
          && Object.keys(ex2Answers).length > 0
          && Object.keys(partnerEx2).length > 0);
        if (!bothEx1Done || !bothEx2Done) {
          ord.workbookStatus = 'pending_exercises';
          localStorage.setItem('attune_order', JSON.stringify(ord));
          return;
        }

        if (ord.addonWorkbook === 'print') {
          // Flag print order for fulfillment. Two paths:
          //  1. localStorage (legacy admin-on-same-device view)
          //  2. Supabase orders.workbook_status (server-side, visible to
          //     any admin/fulfillment vendor regardless of device)
          ord.workbookStatus = 'print_queued';
          localStorage.setItem('attune_order', JSON.stringify(ord));
          localStorage.setItem('attune_workbook_print_queued', JSON.stringify({
            queuedAt: Date.now(),
            orderNum: ord.orderNum,
            buyerName: ord.buyerName,
            buyerEmail: ord.buyerEmail,
          }));
          // Server-side: update the order row so admin dashboards on
          // other devices and any external fulfillment tooling can see
          // this order is ready to ship. Best-effort; if Supabase is
          // unavailable, the localStorage flag still drives the local
          // admin view.
          try {
            const { supabase: sb, hasSupabase } = await import('./supabase.js');
            if (hasSupabase() && ord.orderNum) {
              await sb.from('orders').update({
                workbook_status: 'print_queued',
              }).eq('order_num', ord.orderNum);
            }
          } catch (_) {}
          return;
        }

        // Digital — auto-generate AND persist to Supabase Storage.
        // Calls /api/store-workbook-pdf (which calls the external Render
        // Playwright service to produce the Volume 01 PDF, then uploads
        // it to storage and returns a 7-day signed URL). The order row is
        // updated server-side with workbook_url + workbook_status='ready'
        // + workbook_format='pdf'.
        ord.workbookStatus = 'generating';
        localStorage.setItem('attune_order', JSON.stringify(ord));

        // Build full payload using shared helper. Phase 5a: payload now
        // includes responsibilities + lifeQuestions for the new renderer
        // alongside the legacy expGaps shape for backward compatibility.
        const payload = buildWorkbookPayload(
          userName, partnerName,
          ex1Answers, partnerEx1,
          ex2Answers, partnerEx2,
          coupleType
        );
        // Add orderId so store-workbook-pdf can update the row.
        if (ord.orderNum) payload.orderId = ord.orderNum;

        // Pull the user's access token so the API can verify they own a
        // workbook addon. Without this header, the endpoint returns 401.
        const _wbAuth = await (async () => {
          try {
            const { supabase: sb, hasSupabase } = await import('./supabase.js');
            if (!hasSupabase()) return null;
            const { data: { session } } = await sb.auth.getSession();
            return session?.access_token || null;
          } catch { return null; }
        })();
        const resp = await fetch('/api/store-workbook-pdf', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(_wbAuth ? { Authorization: `Bearer ${_wbAuth}` } : {}),
          },
          body: JSON.stringify(payload),
        });

        if (!resp.ok) {
          // Don't fail silently. A swallowed 403/500 here is what left the
          // dashboard sitting on "Generating now" with nothing to debug (10.6).
          let _body = '';
          try { _body = await resp.text(); } catch {}
          console.warn('[Attune] workbook generation failed:', resp.status, _body.slice(0, 200));
          ord.workbookStatus = 'failed';
          try { localStorage.setItem('attune_order', JSON.stringify(ord)); } catch {}
        }
        if (resp.ok) {
          // store-workbook-pdf returns { ok, url, filename } — persist
          // the signed URL in the order so the dashboard download can
          // pull it directly without re-generating.
          try {
            const data = await resp.json();
            localStorage.setItem('attune_workbook_ready', 'true');
            ord.workbookStatus = 'ready';
            if (data?.url) ord.workbookUrl = data.url;
            if (data?.filename) ord.workbookFilename = data.filename;
            localStorage.setItem('attune_order', JSON.stringify(ord));
            // Notify buyer by email
            if (ord.buyerEmail) {
              // account isn't a prop here — read from localStorage so the
              // server-side dedup can match the right user.
              const _acct = (() => { try { return JSON.parse(localStorage.getItem('attune_account') || 'null'); } catch { return null; } })();
              // workbook_ready email retired — folded into the results-ready email (emails #4 + #7 combined).
            }
          } catch {}
        }
      } catch (e) {
        console.warn('[Attune] workbook auto-generation threw:', e);
      }
    })();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // 10.2 — the left nav holds exactly where you scrolled it. Clicking a page
  // does not move it, and neither does the page changing under it. The position
  // lives at module scope (_navScrollTop) so it also survives the nav being
  // unmounted and remounted between views, which a ref would not.
  //
  // The active item is only scrolled into view on FIRST mount (so a deep link or
  // a fresh entry into results shows you where you are). After that the nav is
  // yours: it stays put.
  const sidebarRef = useRef(null);
  const navFirstMount = useRef(true);
  // True while we are writing scrollTop ourselves, so the resulting scroll
  // event does not overwrite the very position we are restoring.
  const navRestoring = useRef(false);
  // Tracked via the onScroll prop rather than addEventListener: changing pages
  // can hand us a brand new sidebar node, and a listener bound once on mount
  // would be left attached to the old one, silently losing the position.
  const onNavScroll = (e) => { if (!navRestoring.current) _navScrollTop = e.currentTarget.scrollTop; };
  useLayoutEffect(() => {
    const el = sidebarRef.current;
    if (!el) return;
    if (navFirstMount.current) {
      navFirstMount.current = false;
      const active = el.querySelector('[data-nav-active="true"]');
      if (active) {
        const itemTop = active.offsetTop;
        const itemBottom = itemTop + active.offsetHeight;
        if (itemTop < el.scrollTop + 8 || itemBottom > el.scrollTop + el.clientHeight - 8) {
          active.scrollIntoView({ block: "nearest" });
          _navScrollTop = el.scrollTop;
          return;
        }
      }
    }
    // Restore, and never fight the user's position afterwards. The second pass
    // runs after paint because on the first pass the new page's nav items may
    // not have their final height yet, which would clamp scrollTop to 0.
    const apply = () => {
      if (!sidebarRef.current) return;
      navRestoring.current = true;
      if (sidebarRef.current.scrollTop !== _navScrollTop) sidebarRef.current.scrollTop = _navScrollTop;
    };
    apply();
    const raf = requestAnimationFrame(() => { apply(); navRestoring.current = false; });
    return () => { cancelAnimationFrame(raf); navRestoring.current = false; };
  });

  const go = (sec) => {
    if (sec !== section) writeSectionToUrl(sec);
    setSection(sec);
    // Tell the parent where we are. Without this the parent's activeResult
    // stayed at whatever it was seeded with, so the persisted results state
    // was stale and a refresh dropped the user back on the wrong page.
    if (onSectionChange) onSectionChange(sec);
    // Accordion: expand the section being entered, collapse every other one.
    setCommExpanded(sec.startsWith("comm"));
    setExpExpanded(sec.startsWith("exp"));
    setReflExpanded(sec.startsWith("reflection"));
    setIntimExpanded(sec.startsWith("intimacy"));
    setConflictExpanded(sec.startsWith("conflict"));
    const sc = document.querySelector("[data-results-scroll]");
    if (sc) sc.scrollTop = 0; else window.scrollTo({ top: 0 });
  };

  // Browser Back moves one section back within results (11.1). The root results
  // entry is tagged with the current section; each go() pushes a section entry.
  // On Back we restore that section; the app-level results popstate is taught to
  // stay put while a section entry is present, so only Back from the root exits.
  useEffect(() => {
    // Stamp the current section onto the entry the user arrived on, so Back
    // has something to return to and the URL matches what is on screen.
    writeSectionToUrl(section, { replace: true });
    const onPop = (e) => {
      // Prefer the URL: it is authoritative and survives entries pushed before
      // this ran. History state is the fallback for older entries.
      const sec = sectionFromUrl() || (e && e.state && e.state.attuneSection);
      if (sec) {
        const mapped = safeSection(sec);
        setSection(mapped);
        if (onSectionChange) onSectionChange(mapped);
      }
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  // Sidebar items
  /**
   * ── THE NAME OF A SECTION COMES FROM THE NAV ────────────────────────────
   * The sidebar used to write its own labels, and two of them had drifted from
   * the names the app shows: "Communication" against "Communication Styles",
   * and "Physical Intimacy" against "Physical Intimacy Expectations", which is
   * the exercise's own name and the one Ellie asked for by name on What Comes
   * Next. Someone reading the website and then the phone met two names for one
   * screen.
   *
   * Only the label is taken. The icon, the short label, the colour and the two
   * synthetic "Detailed results" rows are this sidebar's own presentation and
   * have no counterpart in the nav, so they stay here.
   */
  const navLabels = (() => {
    const out = {};
    for (const g of resultsNav({
      hasReflection: hasAnniversary,
      intimacyReady: intimacyBothDone,
      conflictListed,
    })) {
      out[g.id] = g.label;
      for (const c of (g.children || [])) out[c.id] = c.label;
    }
    return out;
  })();
  const navLabel = (id, fallback) => navLabels[id] || fallback;

  /**
   * ── AND THE COLOUR, FOR THE SAME REASON ─────────────────────────────────
   * Communication was purple here and orange in the app; Relationship
   * Reflection was blue here and green there. Both times the app agreed with
   * the page's own ground and with SectionColor in the theme, and this sidebar
   * was the odd one out: the dot beside a section's name was a colour that
   * section is nowhere else in the product.
   *
   * A section's rows take their section's colour unless they carry one of their
   * own, which the communication domains and the expectations categories do and
   * which is deliberate: those pages are tinted per domain.
   */
  const navColors = (() => {
    const out = {};
    for (const g of resultsNav({
      hasReflection: hasAnniversary,
      intimacyReady: intimacyBothDone,
      conflictListed,
    })) {
      if (g.color) out[g.id] = g.color;
      for (const c of (g.children || [])) out[c.id] = c.color || g.color;
    }
    return out;
  })();
  const navColor = (id, fallback) => navColors[id] || fallback;

  const sidebarSections = [
    { id: "highlights", label: navLabel("highlights", "Highlights"), icon: "✦", color: coupleType?.color || "#E8673A" },
    { id: "couple-type", label: navLabel("couple-type", "Couple Type"), shortLabel: "Type & Map", icon: "◈", color: coupleType?.color || "#E8673A" },
    {
      id: "comm", label: navLabel("comm", "Communication"), shortLabel: "Comms", icon: "◉", color: navColor("comm", "#E8673A"),
      children: [
        { id: "comm-overview", label: navLabel("comm-overview", "Overview") },
        { id: "comm-detail-header", label: navLabel("comm-detail-header", "Detailed results"), isDomainHeader: true, color: navColor("comm", "#E8673A") },
        ...UR_DOMAINS.map(g => ({ id: `comm-${g.id}`, label: g.label, isDeepChild: true, italic: true, color: g.color })),
      ]
    },
    {
      id: "exp", label: navLabel("exp", "Expectations"), icon: "◉", color: navColor("exp", "#1B5FE8"),
      children: [
        { id: "exp-overview", label: navLabel("exp-overview", "Overview") },
        { id: "exp-detail-header", label: navLabel("exp-detail-header", "Detailed results"), isDomainHeader: true, color: navColor("exp", "#1B5FE8") },
        /* Each category has a colour of its own, which its page is tinted with
           and which check-category-colors holds both surfaces to. This row drew
           all six in one green, so the sidebar was the only place in the product
           where Household and Financial looked like the same thing. */
        ...FIXED_CATS.map((fc) => ({ id: fc.section, label: fc.label, isDeepChild: true, italic: true, color: fc.color })),
      ]
    },
    ...(hasAnniversary ? [{
      id: "reflection", label: navLabel("reflection", "Relationship Reflection"), shortLabel: "Refl.", icon: "◉", color: navColor("reflection", "#10B981"),
      children: [
        { id: "reflection-overview", label: navLabel("reflection-overview", "Overview") },
        { id: "reflection-detail-header", label: navLabel("reflection-detail-header", "Detailed results"), isDomainHeader: true, color: navColor("reflection", "#10B981") },
        { id: "reflection-ratings", label: navLabel("reflection-ratings", "How You Each Rated"), isDeepChild: true, italic: true, color: navColor("reflection", "#10B981") },
        { id: "reflection-story", label: navLabel("reflection-story", "Side by Side"), isDeepChild: true, italic: true, color: navColor("reflection", "#10B981") },
      ]
    }] : []),
    ...(intimacyBothDone ? [{
      id: "intimacy", label: navLabel("intimacy", "Physical Intimacy"), shortLabel: "Intimacy", icon: "◉", color: navColor("intimacy", "#B5546E"),
      children: [
        { id: "intimacy-overview", label: navLabel("intimacy-overview", "Overview") },
        { id: "intimacy-detail-header", label: navLabel("intimacy-detail-header", "Detailed results"), isDomainHeader: true, color: navColor("intimacy", "#B5546E") },
        ...INTIMACY_DOMAINS.map(d => ({ id: `intimacy-${d.id}`, label: d.label, isDeepChild: true, italic: true, color: "#B5546E" })),
      ]
    }] : []),
    ...(conflictListed ? [{
      id: "conflict", label: navLabel("conflict", "Conflict Patterns"), shortLabel: "Conflict", icon: "\u25C9", color: navColor("conflict", "#1B5FE8"),
      locked: !conflictBothDone,
      children: [
        { id: "conflict-overview", label: navLabel("conflict-overview", "Overview") },
        { id: "conflict-detail-header", label: navLabel("conflict-detail-header", "Detailed results"), isDomainHeader: true, color: navColor("conflict", "#1B5FE8") },
        { id: "conflict-snapshot", label: navLabel("conflict-snapshot", "Your Conflict Snapshot"), isDeepChild: true, italic: true, color: navColor("conflict", "#1B5FE8") },
        { id: "conflict-patterns", label: navLabel("conflict-patterns", "Your Patterns"), isDeepChild: true, italic: true, color: navColor("conflict", "#1B5FE8") },
        { id: "conflict-wrote", label: navLabel("conflict-wrote", "What You Each Wrote"), isDeepChild: true, italic: true, color: navColor("conflict", "#1B5FE8") },
      ]
    }] : []),
    { id: "what-comes-next", label: navLabel("what-comes-next", "What Comes Next"), shortLabel: "What's Next", icon: "→", color: navColor("what-comes-next", "#E8673A") },
  ];

  // Sidebar render
  const Sidebar = () => (
    <div style={{ width: 200, flexShrink: 0, paddingRight: "1.5rem", display: "flex", flexDirection: "column", gap: "0.15rem" }}>
      {sidebarSections.map(sec => {
        const isActive = section === sec.id || (sec.children && section.startsWith(sec.id + "-"));
        const isExpanded = sec.id === "comm" ? commExpanded : sec.id === "exp" ? expExpanded : sec.id === "reflection" ? reflExpanded : sec.id === "intimacy" ? intimExpanded : sec.id === "conflict" ? conflictExpanded : false;
        const color = sec.color || "#7A6753";
        return (
          <div key={sec.id}>
            <button onClick={() => {
              if (sec.children) {
                /* Opening a chapter lands on its cover, which is the app's
                   behaviour: its nav row goes to the group's first child and the
                   first child is the cover. Before covers existed here this went
                   straight to the overview, so the five cover pages were
                   reachable only by a bookmark and nobody ever saw one. */
                const first = COVER_SECTIONS.includes(`${sec.id}-cover`) ? `${sec.id}-cover` : `${sec.id}-overview`;
                if (sec.id === "comm") { setCommExpanded(e => !e); if (!commExpanded) go(first); }
                else if (sec.id === "exp") { setExpExpanded(e => !e); if (!expExpanded) go(first); }
                else if (sec.id === "reflection") { setReflExpanded(e => !e); if (!reflExpanded) go(first); }
                else if (sec.id === "intimacy") { setIntimExpanded(e => !e); if (!intimExpanded) go(first); }
                else if (sec.id === "conflict") { setConflictExpanded(e => !e); if (!conflictExpanded) go(first); }
              } else { go(sec.id); }
            }} data-nav-active={section === sec.id ? "true" : undefined} style={{ width: "100%", background: (section === sec.id) ? color + "15" : "transparent", border: "none", borderRadius: 8, padding: "0.5rem 0.65rem", display: "flex", alignItems: "center", justifyContent: "space-between", cursor: "pointer", fontFamily: BFONT, transition: "background .15s" }}>
              <span style={{ fontSize: "0.75rem", fontWeight: isActive ? 700 : 500, color: isActive ? color : "#7A6753" }}>{sec.icon && <span style={{ marginRight: "0.4rem", fontSize: "0.65rem", opacity: 0.7 }}>{sec.icon}</span>}{sec.label}</span>
              {sec.children && <span style={{ fontSize: "0.95rem", lineHeight: 1, color: "#7A6753", opacity: 0.85 }}>{isExpanded ? "▾" : "▸"}</span>}
            </button>
            {sec.children && isExpanded && (
              <div style={{ paddingLeft: "0.75rem", display: "flex", flexDirection: "column", gap: "0.08rem", marginBottom: "0.25rem" }}>
                {sec.children.map(child => {
                  if (child.isDomainHeader) {
                    // Domain group header — not clickable, just a label with domain color
                    return (
                      <div key={child.id} style={{ padding: "0.35rem 0.6rem 0.1rem", marginTop: 0 }}>
                        <span style={{ fontSize: "0.55rem", letterSpacing: "0.14em", textTransform: "uppercase", fontWeight: 700, color: child.color || color, fontFamily: BFONT }}>{child.label}</span>
                      </div>
                    );
                  }
                  const childColor = child.color || color;
                  return (
                    <button key={child.id} data-nav-active={section === child.id ? "true" : undefined} onClick={() => go(child.id)} style={{ background: section === child.id ? childColor + "12" : "transparent", border: "none", borderLeft: section === child.id ? `2px solid ${childColor}` : "2px solid transparent", borderRadius: "0 6px 6px 0", padding: child.isDeepChild ? "0.25rem 0.6rem 0.25rem 1.25rem" : "0.35rem 0.6rem", textAlign: "left", cursor: "pointer", fontFamily: BFONT, transition: "all .12s" }}>
                      <span style={{ fontSize: child.isDeepChild ? "0.65rem" : "0.7rem", fontStyle: child.italic ? "italic" : "normal", fontWeight: section === child.id ? 700 : 400, color: section === child.id ? childColor : child.isDeepChild ? "#AAA098" : "#7A6753" }}>{child.label}</span>
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );

  // Mobile top tab bar (compact, no children)
  const MobileTabBar = () => (
    <div style={{ display: "flex", gap: "0.4rem", overflowX: "auto", paddingBottom: "0.5rem", marginBottom: "1.25rem", borderBottom: `1px solid ${C.stone}` }}>
      {/* Built from the same sidebarSections the sidebar is built from.
          Ellie: "Physical intimacy results section is still missing from my web
          view, it's not listed in the pill shaped nav buttons up top."

          It was a hand-written list of five beside a sidebar of eight, so it
          had no Conflict Patterns at all and its Intimacy entry was guarded by
          a second reading of the same condition. Two lists, one of them shorter,
          which is how a whole section can be missing on a phone and present on
          a laptop. */}
      {sidebarSections
        .filter(sec => sec.id !== "highlights")
        .map(sec => ({
          id: sec.children ? sec.children[0].id : sec.id,
          label: sec.shortLabel || sec.label,
          color: sec.color,
        }))
        .map(t => (
        <button key={t.id} onClick={() => go(t.id)} style={{ background: section.startsWith(t.id.replace("-overview","")) ? t.color + "15" : "transparent", border: `1.5px solid ${section.startsWith(t.id.replace("-overview","")) ? t.color : C.stone}`, borderRadius: 999, padding: "0.3rem 0.75rem", fontSize: "0.7rem", fontWeight: 600, color: section.startsWith(t.id.replace("-overview","")) ? t.color : C.muted, cursor: "pointer", fontFamily: BFONT, whiteSpace: "nowrap", flexShrink: 0 }}>
          {t.label}
        </button>
      ))}
    </div>
  );

  // Prev/Next navigation
  /**
   * ── THE PAGE ORDER IS THE NAV'S, NOT A COPY OF IT ───────────────────────
   * Ellie: "clicking the arrows takes me to the storycard highlights."
   *
   * This was a hand-typed list beside a shared one, which CLAUDE.md says is
   * always the shorter list, and it was: the five cover pages were not in it.
   * So on any cover `curIdx` was -1, the right arrow read `curIdx < length - 1`
   * as true, and `allPages[0]` is Highlights. Every cover's arrow went there.
   *
   * navPageIds is the nav flattened in order, which is what this wanted to be.
   * The old list also restated UR_DOMAINS and FIXED_CATS, so a category moving
   * would have walked the arrows out of step with the sidebar silently.
   */
  const allPages = navPageIds({
    hasReflection: hasAnniversary,
    intimacyReady: intimacyBothDone,
    conflictListed,
  });
  const curIdx = allPages.indexOf(section);
  /**
   * ── THE ARROWS FLOAT, AS THEY DO IN THE APP ────────────────────────────
   * Ellie: "Same as we did for the app, all results pages on the site should
   * have a grey arrow that's visible in the bottom right no matter where you
   * are on the page, so the nav is very clear. Remove the labeled buttons in
   * the bottom corners."
   *
   * The labelled pair sat at the foot of the content, so on a long page the way
   * forward was only visible once you had scrolled to the end of what you were
   * reading. Fixed to the viewport, they are where the app puts them and they
   * are there the whole time.
   *
   * The app's geometry, so the two surfaces are the same control: a 46 point
   * circle, a chevron, a hairline and a soft drop, because a pale circle on a
   * white page needs an edge from somewhere.
   *
   * The destination is still named, in the accessible label and the tooltip,
   * which is where a name belongs once the control is a glyph.
   */
  const ARROW = 46;
  /**
   * ── THE ARROWS SIT INSIDE THE CONTENT, NOT INSIDE THE WINDOW ────────────
   * Ellie: "The previous/next arrows should be left- and right-aligned
   * (respectively) with the margins of each results page content (they should
   * be the same exact position from page to page but should not be outside of
   * the margins like they currently are, the back arrow is below the left nav
   * currently)."
   *
   * They were `left: 1.5rem` and `right: 1.5rem` against the viewport, so on a
   * wide window the back arrow sat under the sidebar and neither lined up with
   * anything on the page.
   *
   * And: "The previous/next arrows should not be able to be on top of the
   * footer, the lowest they can go should be the bottom of the page content."
   * Fixed to the window, they floated over the dark footer once you reached the
   * end. So the bottom is whichever is higher, their resting place or the end
   * of the content.
   *
   * Measured rather than guessed, because the column's width is the window's
   * less a sidebar that is there on a laptop and not on a phone, and because a
   * number tuned on one window is wrong on every other. Before the first
   * measurement they fall back to the corner they used to take, which is the
   * old behaviour rather than no arrows.
   */
  const contentRef = useRef(null);
  const [arrowBox, setArrowBox] = useState(null);
  useEffect(() => {
    const el = contentRef.current;
    if (!el) return undefined;
    const report = () => {
      const r = el.getBoundingClientRect();
      /* 60 is the footer strip the results view pins to the bottom of the
         window, and 16 is the gap every other corner on this page uses. */
      const rest = 76;
      const atContentEnd = Math.round(window.innerHeight - r.bottom + 16);
      const next = {
        left: Math.round(r.left),
        right: Math.round(window.innerWidth - r.right),
        bottom: Math.max(rest, atContentEnd),
      };
      setArrowBox((cur) => (cur
        && Math.abs(cur.left - next.left) < 2
        && Math.abs(cur.right - next.right) < 2
        && Math.abs(cur.bottom - next.bottom) < 2 ? cur : next));
    };
    report();
    window.addEventListener("scroll", report, true);
    window.addEventListener("resize", report);
    const ro = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(report);
    if (ro) ro.observe(el);
    return () => {
      window.removeEventListener("scroll", report, true);
      window.removeEventListener("resize", report);
      if (ro) ro.disconnect();
    };
  });

  const arrowStyle = (side) => ({
    position: "fixed",
    bottom: arrowBox ? arrowBox.bottom : 76,
    [side]: arrowBox ? arrowBox[side] : "1.5rem",
    width: ARROW, height: ARROW, borderRadius: ARROW / 2,
    display: "flex", alignItems: "center", justifyContent: "center",
    background: "rgba(255,253,249,0.92)", backdropFilter: "blur(10px)",
    border: "1px solid rgba(14,11,7,0.10)",
    boxShadow: "0 3px 10px rgba(14,11,7,0.16)",
    color: C.ink, fontSize: "1.1rem", lineHeight: 1,
    cursor: "pointer", zIndex: 60,
  });
  const PrevNext = () => (
    <>
      {/* A section the nav does not list has no place in the sequence, so it
          gets no arrows. Before this, -1 drew a Next that went to Highlights. */}
      {curIdx > 0 ? (
        <button
          onClick={() => go(allPages[curIdx - 1])}
          aria-label={`Back to ${getPageLabel(allPages[curIdx - 1])}`}
          title={getPageLabel(allPages[curIdx - 1])}
          style={arrowStyle("left")}>
          {"\u2039"}
        </button>
      ) : null}
      {curIdx >= 0 && curIdx < allPages.length - 1 ? (
        <button
          onClick={() => go(allPages[curIdx + 1])}
          aria-label={`On to ${getPageLabel(allPages[curIdx + 1])}`}
          title={getPageLabel(allPages[curIdx + 1])}
          style={arrowStyle("right")}>
          {"\u203A"}
        </button>
      ) : null}
    </>
  );

  /**
   * ── THE NAME OF A PAGE IS THE NAV'S NAME FOR IT ─────────────────────────
   * This was twenty lines of hand-typed labels beside the nav's own, and it
   * failed the way a hand-typed list always fails here: it had no branch for a
   * cover, so once the arrows reached the covers they announced "Back to
   * comm-cover". The raw id, to a reader, on the live site.
   *
   * It had already failed once before in the same way, which is written into
   * the lines it replaced: "Without these the Prev/Next buttons fell back to
   * the raw section id and read conflict-patterns instead of Your Patterns."
   * Fixing that by adding four more lines left the next gap exactly as open.
   *
   * resultsNav names every page, and it is what the sidebar and the app both
   * draw from. Four of those names are just "Overview", which is right under a
   * group heading and ambiguous on its own, so a name that more than one page
   * shares takes its group's name in front of it.
   */
  const pageLabels = (() => {
    const groups = resultsNav({
      hasReflection: hasAnniversary,
      intimacyReady: intimacyBothDone,
      conflictListed,
    });
    const seen = new Map();
    for (const g of groups) {
      for (const c of (g.children || [g])) {
        seen.set(c.label, (seen.get(c.label) || 0) + 1);
      }
    }
    const out = {};
    for (const g of groups) {
      for (const c of (g.children || [g])) {
        out[c.id] = seen.get(c.label) > 1 && g.label && g.label !== c.label
          ? `${g.label} ${c.label}`
          : c.label;
      }
    }
    return out;
  })();

  function getPageLabel(id) {
    return pageLabels[id] || id;
  }

  // Layout wrapper
  const Layout = ({ children, accent }) => (
    <div>
      {/* Mobile tabs */}
      <div style={{ display: "none" }} className="mobile-tabs"><MobileTabBar /></div>
      <style>{`@media(max-width:680px){.mobile-tabs{display:block!important}.desktop-sidebar{display:none!important}}`}</style>
      <div style={{ display: "flex", gap: "0", alignItems: "flex-start" }}>
        {/* Sidebar: sticky + its own scroll context so wheel events stay in the nav */}
        <div className="desktop-sidebar" ref={sidebarRef} onScroll={onNavScroll} style={{
          position: "sticky",
          top: 0,
          paddingTop: "1.25rem",
          maxHeight: "calc(100vh - 116px)",
          overflowY: "auto",
          overflowX: "hidden",
          scrollbarWidth: "thin",
          scrollbarColor: "rgba(193,127,71,0.35) transparent",
          /* Fade mask at top/bottom so it's visually obvious the nav scrolls
             rather than looking like it's cut off. */
          WebkitMaskImage: "linear-gradient(to bottom, transparent 0, #000 12px, #000 calc(100% - 16px), transparent 100%)",
          maskImage: "linear-gradient(to bottom, transparent 0, #000 12px, #000 calc(100% - 16px), transparent 100%)",
        }}>
          <Sidebar />
          {/* Extra bottom padding so last nav item doesn't sit flush at the edge */}
          <div style={{ height: "2rem" }} />
        </div>
        {/* ── THE EDGES PAGE, AS THE STORYCARDS DO ─────────────────────
            Ellie: "Clicking the left or right edge of the results pages should
            move you forward or backward, in both the app and the site, just
            like the storycard highlights do."

            The storycards' own rule, which is hers from when she asked for it
            there: "if I tap the left hand side of the page I want it to go back
            a page." A sixth of the width on each side here rather than a third,
            because a results page is a column of text somebody is reading and
            the middle has to stay theirs.

            Anything that is itself a control still wins: a click on a button,
            a link or a marked sentence stops before it reaches this handler,
            which is why it sits on the column and not on a layer over it. And a
            click that finished a text selection pages nothing, or marking a
            sentence would cost you the page you marked. */}
        <div
          ref={contentRef}
          onClick={(e) => {
            if (!allPages.length || curIdx < 0) return;
            const sel = typeof window !== "undefined" && window.getSelection
              ? String(window.getSelection() || "") : "";
            if (sel.trim()) return;
            if (e.target.closest("button, a, input, textarea, select, [role=button]")) return;
            const box = e.currentTarget.getBoundingClientRect();
            const edge = box.width / 6;
            const x = e.clientX - box.left;
            if (x < edge) { if (curIdx > 0) go(allPages[curIdx - 1]); return; }
            if (x > box.width - edge && curIdx < allPages.length - 1) go(allPages[curIdx + 1]);
          }}
          style={{ flex: 1, minWidth: 0, padding: "0 1.5rem" }}>
          {children}
          {/* ── EVERY PAGE, WITHOUT ASKING ───────────────────────────────
              Ellie: "Not seeing these on cover pages, overview pages, or any
              detailed pages."

              She was right on twelve of the eighteen. Each page used to opt out
              of the shared pair and four of them then drew their own lower
              down, which is this file's recurring failure in miniature: one
              rule kept in several places with nothing checking that they agree.
              The pair is fixed to the viewport now, so where it sits in the
              markup decides nothing, and there is no reason for a page to have
              an opinion about it. check-results-arrows holds that. */}
          <PrevNext />
        </div>
      </div>
    </div>
  );

  /*
   * ── PAGE: A CHAPTER COVER ───────────────────────────────────────────────
   * Ellie: "Mirror cover pages for exercises and results on both web and app."
   *
   * The app has had these since 87f0e273 and the website never did, so
   * `comm-cover` fell through to the comms prefix and drew the overview again,
   * character for character, while `reflection-cover` and `intimacy-cover`
   * matched no branch at all and drew an empty column. Nobody had landed on one
   * because this sidebar did not offer them; the app's nav comes from the
   * server, which does.
   *
   * The app's page, in this file's materials: a gradient rule around a cream
   * card, the chapter's mark, its name, and one control. The title comes from
   * RESULTS_SECTION_LABELS and the word on the button from the server's
   * PAGE_COPY (SC_COPY here), both of which the app reads too, so neither surface is choosing
   * its own wording. Everything else here is layout.
   */
  if (section.endsWith("-cover")) {
    const group = sidebarSections.find((x) => x.id === section.replace("-cover", ""));
    const accent = group?.color || coupleType?.color || "#E8673A";
    return (
      <Layout accent={accent}>
        {/* block: cover/frame */}
        <div style={{ padding: "1.5rem 0.5rem" }}>
          <div style={{ borderRadius: 26, padding: 1.5, background: "linear-gradient(135deg, #E8673A, #9B5DE5, #1B5FE8)" }}>
            <div style={{
              borderRadius: 25, background: C.cream, minHeight: "min(72vh, 620px)",
              display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
              padding: "3rem 2rem", textAlign: "center",
            }}>
              {/* The glow is many faint rings rather than one translucent disc,
                  because a single circle is the thing she asked to get rid of:
                  "can we make the glow more subtle, like a tint that disperses
                  gently? Right now it looks like a circle." */}
              <div style={{
                width: 132, height: 132, borderRadius: "50%", display: "flex",
                alignItems: "center", justifyContent: "center", marginBottom: "2rem",
                /* Ellie: "now the glow is too faint". It was 13% of the accent at
                   the centre, which on cream is close to nothing. 31% now, still
                   falling to nothing well inside the box so it disperses rather
                   than becoming the disc she asked me to take out. */
                background: `radial-gradient(circle, ${accent}50 0%, ${accent}30 38%, ${accent}14 58%, transparent 76%)`,
              }}>
                {/* ── THE SECTION'S ICON, NOT A DOT ────────────────────────
                    Ellie: "Insights cover pages on the web use a dot with a
                    glow behind it rather than the icon like the app."

                    `group.icon` has never existed on these rows, so this fell
                    to the `◉` every time: a default that looked deliberate.
                    The five icons are the ones already drawn for the insights
                    menu, which are the website's version of the app's SF
                    Symbols, at the size the app's cover uses. */}
                {NAV_ICONS[section.replace("-cover", "")]
                  ? NAV_ICONS[section.replace("-cover", "")](accent, 78)
                  : <span style={{ fontSize: "3.2rem", color: accent, lineHeight: 1 }}>{"\u25C9"}</span>}
              </div>
              {/* block: cover/title */}
              <h1 style={{ fontFamily: font.display, fontSize: "clamp(1.7rem, 4vw, 2.4rem)", fontWeight: 700, color: C.ink, lineHeight: 1.15, margin: 0, maxWidth: 460 }}>
                {RESULTS_SECTION_LABELS[section] || group?.label || ""}
              </h1>
              {/* block: cover/start */}
              <button
                onClick={() => go(section.replace("-cover", "-overview"))}
                style={{
                  marginTop: "2.25rem", background: accent, color: "white", border: "none",
                  borderRadius: 999, padding: "0.85rem 2.25rem", fontSize: "0.8rem",
                  fontWeight: 700, letterSpacing: "0.08em", textTransform: "uppercase",
                  fontFamily: font.body, cursor: "pointer",
                }}>
                {SC_COPY.coverStart}
              </button>
            </div>
          </div>
        </div>
      </Layout>
    );
  }

  // ── PAGE: HIGHLIGHTS ─────────────────────────────────────────────────────────
  if (section === "highlights") {
    return (
      <Layout accent={coupleType?.color || "#E8673A"}>
        {/* block: highlights/storycards */}
        <div style={{ maxWidth: 620 }}>
          {/* Retake comparison — renders only when the user has a prior
              Ex2 snapshot. Shows delta summary + expandable side-by-side. */}
          <RetakeComparisonCard
            currentEx2={ex2Answers}
            priorEx2={ex2AnswersPrior}
            priorAt={ex2PriorAt}
            userName={userName}
            partnerName={partnerName}
          />
          <div style={{ marginBottom: "1.5rem" }}>
            <div style={{ fontFamily: HFONT, fontSize: "1.6rem", fontWeight: 700, color: C.ink, marginBottom: "0.25rem" }}>Your highlights</div>
            <p style={{ fontSize: "0.82rem", color: C.muted, fontFamily: BFONT, margin: 0 }}>Swipe through each card. Download any to share or save.</p>
          </div>
          <ResultsHighlights
            ex1Answers={ex1Answers} partnerEx1={partnerEx1}
            ex2Answers={ex2Answers} partnerEx2={partnerEx2}
            ex3Answers={ex3Answers} partnerEx3={partnerEx3}
            userName={userName} partnerName={partnerName}
            userPronouns={userPronouns} partnerPronouns={partnerPronouns}
            portrait={portrait}
            intimacyAnswers={intimacyBothDone ? intimacyAnswers : null}
            partnerIntimacy={intimacyBothDone ? partnerIntimacy : null}
            intimacyVariant={intimacyVariant}
            onDone={() => go("couple-type")}
            inline={true}
          />
        </div>
      </Layout>
    );
  }

  // ── PAGE: COUPLE TYPE ────────────────────────────────────────────────────────
  if (section === "couple-type") {
    const ct = coupleType;
    if (!ct) return <Layout accent="#E8673A"><p style={{fontFamily:BFONT,color:C.muted}}>Complete all exercises to see your couple type.</p></Layout>;
    // Resolve "the expressive/guarded partner" role labels to real names when
    // the two partners actually differ on the Open/Guarded axis. Open-leaning
    // (openScore >= 3) reads as expressive; below that, guarded. If both sit on
    // the same side the role label is ambiguous, so we leave it generic.
    const _ctTypeA = computeIndividualType(myS);
    const _ctTypeB = computeIndividualType(partS);
    const _uOpen = _ctTypeA.openScore >= 3.0;
    const _pOpen = _ctTypeB.openScore >= 3.0;
    const _uEngage = _ctTypeA.withdrawScore <= 3.0;
    const _pEngage = _ctTypeB.withdrawScore <= 3.0;
    // Open/Guarded axis names
    let _expressiveName = null, _guardedName = null;
    let _expressivePron = null, _guardedPron = null;
    if (_uOpen !== _pOpen) {
      _expressiveName = _uOpen ? userName : partnerName;
      _guardedName = _uOpen ? partnerName : userName;
      _expressivePron = _uOpen ? userPronouns : partnerPronouns;
      _guardedPron = _uOpen ? partnerPronouns : userPronouns;
    }
    // Engage/Withdraw axis names
    let _reachingName = null, _withdrawingName = null;
    let _reachingPron = null, _withdrawingPron = null;
    if (_uEngage !== _pEngage) {
      _reachingName = _uEngage ? userName : partnerName;
      _withdrawingName = _uEngage ? partnerName : userName;
      _reachingPron = _uEngage ? userPronouns : partnerPronouns;
      _withdrawingPron = _uEngage ? partnerPronouns : userPronouns;
    }
    const _applyRoles = (str) => {
      let s = str;
      // Role-name and role-pronoun tokens. These let prose say things like
      // "{EXP} is the expressive one and {EXP_sub} tends to..." and get the
      // correct partner's name AND matching pronoun, instead of a generic
      // "they". Tokens only fill when the two partners actually differ on that
      // axis; otherwise they're stripped so a fallback clause can carry.
      if (_expressiveName && _guardedName) {
        s = s.replace(/\{EXP\}/g, _expressiveName).replace(/\{GRD\}/g, _guardedName)
             .replace(/\{EXP_sub\}/g, pronoun(_expressivePron, "sub")).replace(/\{EXP_obj\}/g, pronoun(_expressivePron, "obj")).replace(/\{EXP_pos\}/g, pronoun(_expressivePron, "pos")).replace(/\{EXP_isC\}/g, pronoun(_expressivePron, "isC"))
             .replace(/\{GRD_sub\}/g, pronoun(_guardedPron, "sub")).replace(/\{GRD_obj\}/g, pronoun(_guardedPron, "obj")).replace(/\{GRD_pos\}/g, pronoun(_guardedPron, "pos")).replace(/\{GRD_isC\}/g, pronoun(_guardedPron, "isC"));
      }
      if (_reachingName && _withdrawingName) {
        s = s.replace(/\{RCH\}/g, _reachingName).replace(/\{WDR\}/g, _withdrawingName)
             .replace(/\{RCH_sub\}/g, pronoun(_reachingPron, "sub")).replace(/\{RCH_obj\}/g, pronoun(_reachingPron, "obj")).replace(/\{RCH_pos\}/g, pronoun(_reachingPron, "pos")).replace(/\{RCH_isC\}/g, pronoun(_reachingPron, "isC"))
             .replace(/\{WDR_sub\}/g, pronoun(_withdrawingPron, "sub")).replace(/\{WDR_obj\}/g, pronoun(_withdrawingPron, "obj")).replace(/\{WDR_pos\}/g, pronoun(_withdrawingPron, "pos")).replace(/\{WDR_isC\}/g, pronoun(_withdrawingPron, "isC"));
      }
      // Capitalize the replacement when the role label starts a sentence/title
      // (e.g. "Guarded partner: ..." -> "Preston: ..."). Names are already
      // capitalized, so a single case-insensitive replace works for both.
      // Swap a role label for the partner's name: "The guarded partner tends
      // to..." becomes "Preston tends to...". Names are already capitalized, so
      // one case-insensitive replace covers sentence starts too.
      //
      // An INDEFINITE article means the phrase is generic, describing the
      // archetype rather than this person, and must be left alone. Without this
      // check, "shares more than a truly guarded partner would" rendered as
      // "more than a truly Preston would". Definite article or none means this
      // person, and still swaps.
      const roleSwap = (str, phrase, name) =>
        str.replace(
          new RegExp('\\b(a |an |the )?(?:truly |genuinely |really )?' + phrase + '\\b', 'gi'),
          (match, article) => (article && /^(a|an) $/i.test(article) ? match : name),
        );
      if (_expressiveName && _guardedName) {
        s = roleSwap(s, 'expressive partner', _expressiveName);
        s = roleSwap(s, 'guarded partner',    _guardedName);
        s = roleSwap(s, 'open partner',       _expressiveName);
        s = roleSwap(s, 'reserved partner',   _guardedName);
      }
      if (_reachingName && _withdrawingName) {
        s = roleSwap(s, 'reaching partner',    _reachingName);
        s = roleSwap(s, 'engaging partner',    _reachingName);
        s = roleSwap(s, 'withdrawing partner', _withdrawingName);
        s = roleSwap(s, 'quieter partner',     _withdrawingName);
      }
      return s;
    };
    const interp = (str) => _applyRoles(str
      .replace(/\{U\}/g, userName).replace(/\{P\}/g, partnerName)
      .replace(/\{U_sub\}/g, pronoun(userPronouns, "sub")).replace(/\{U_obj\}/g, pronoun(userPronouns, "obj")).replace(/\{U_pos\}/g, pronoun(userPronouns, "pos")).replace(/\{U_isC\}/g, pronoun(userPronouns, "isC"))
      .replace(/\{P_sub\}/g, pronoun(partnerPronouns, "sub")).replace(/\{P_obj\}/g, pronoun(partnerPronouns, "obj")).replace(/\{P_pos\}/g, pronoun(partnerPronouns, "pos")).replace(/\{P_isC\}/g, pronoun(partnerPronouns, "isC")));
    // Axis-aware near-line prose. Count how many partners sit within 0.6 of each
    // axis line (0/1/2). For each item, an Engage-near or Open-near override can
    // replace the default: both-near text when the count is 2, one-near text when
    // it is 1, default when 0. Unlisted items fall through to the default, so
    // nothing blanks. interp is applied here, so consumers render the strings
    // directly. Source: NEAR_AXIS_PROSE (reviewed with Ellie + Carolina).
    const _nearEngageCount =
      (Math.abs(_ctTypeA.withdrawScore - 3) < 0.6 ? 1 : 0) +
      (Math.abs(_ctTypeB.withdrawScore - 3) < 0.6 ? 1 : 0);
    const _nearOpenCount =
      (Math.abs(_ctTypeA.openScore - 3) < 0.6 ? 1 : 0) +
      (Math.abs(_ctTypeB.openScore - 3) < 0.6 ? 1 : 0);
    const _nearProse = NEAR_AXIS_PROSE[ct.id] || {};
    const _pickNear = (map, i, count) => {
      if (!map || count < 1) return undefined;
      const v = map[i];
      if (v == null) return undefined;
      if (typeof v === "string") return v;
      return count >= 2 ? (v.both != null ? v.both : v.one) : (v.one != null ? v.one : v.both);
    };
    const _proseSet = (base, engMap, openMap) => {
      const out = (base || []).slice();
      for (let i = 0; i < out.length; i++) {
        const e = _pickNear(engMap, i, _nearEngageCount);
        if (e !== undefined) out[i] = e;
        const o = _pickNear(openMap, i, _nearOpenCount);
        if (o !== undefined) out[i] = o; // open override wins on a rare same-index collision
      }
      return out.map(x => interp(x));
    };
    // The share card sits mounted off-screen at storycard dimensions, so this
    // just screenshots it with the same html2canvas path the highlights reel uses.
    const handleShare = () => {
      if (shareBusy || !shareCardRef.current) return;
      setShareBusy(true);
      const file = `attune-couple-type-${userName.toLowerCase()}-${partnerName.toLowerCase()}.png`;
      try { downloadCard(shareCardRef.current, file); } catch { toast("Download not available. Take a screenshot instead."); }
      setTypeShared(true);
      setTimeout(() => { setTypeShared(false); setShareBusy(false); }, 2800);
    };
    // ── Couple-map derivation (merged in from the former Couple Map page) ──
    const newType = deriveNewCoupleType(myS, partS);
    const itA = INDIVIDUAL_TYPES[newType.typeInfoA.typeCode];
    const itB = INDIVIDUAL_TYPES[newType.typeInfoB.typeCode];
    return (
      <Layout accent={ct.color}>
        <div style={{ maxWidth: 660 }}>

          {/* 1. HEADER */}
          {/* block: couple-type/lead */}
          <div style={{ marginBottom: "1.25rem" }}>
            <div style={{ fontFamily: HFONT, fontSize: "clamp(1.7rem,4vw,2.3rem)", fontWeight: 700, color: C.ink, lineHeight: 1.08, letterSpacing: "-0.02em" }}>
              {SC_COPY.coupleTypeTitle(userName, partnerName)}
            </div>
          </div>

          <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: C.muted, fontFamily: BFONT, fontWeight: 700, marginBottom: "1rem" }}>
            Your couple map
          </div>
          {/* 3. COUPLE MAP TILE */}
          {/* ── THE MAP (with axis descriptions inside the same tile) ── */}
          <div style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 20, padding: isMobile ? "1.25rem" : "1.75rem", marginBottom: "1.5rem" }}>
            <div style={{ display: "flex", justifyContent: "center", marginBottom: "1.5rem" }}>
              <div style={{ width: "100%", maxWidth: isMobile ? 340 : 420 }}>
                {/* block: couple-type/map */}
                <CoupleMapSVG myS={myS} partS={partS} userName={userName} partnerName={partnerName} size={isMobile ? 320 : 400} />
              </div>
            </div>
            <div style={{ height: 1, background: C.stone, opacity: 0.6, margin: "0 0 1.25rem" }} />
            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: "1.1rem" }}>
              {/* block: couple-type/axes */}
              {AXES.map(ax => (
                <div key={ax.label} style={{ borderLeft: `3px solid ${ax.color}`, paddingLeft: "0.9rem" }}>
                  <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: ax.color, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.5rem" }}>{ax.label}</div>
                  {/* One sentence per axis. The pole lines that used to sit
                      here, with the up and down arrows, were cut from both
                      surfaces: the label names both ends already. */}
                  <p style={{ fontSize: "0.82rem", color: C.ink, fontFamily: BFONT, lineHeight: 1.65, margin: 0 }}>{ax.desc}</p>
                </div>
              ))}
            </div>
          </div>

          <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: C.muted, fontFamily: BFONT, fontWeight: 700, marginTop: "1.75rem", marginBottom: "1rem" }}>
            Your individual types
          </div>
          {/* block: couple-type/individual-types */}
          {/* 4. INDIVIDUAL TILES */}
          {/* ── INDIVIDUAL TYPES (merged: identity + placement blurb + bars) ── */}
          {(() => {
            const blurbFor = (name, pron, info) => individualBlurb(name, pron, info.engageCoord, info.openCoord);
            return (
            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(0,1fr) minmax(0,1fr)", gap: isMobile ? "1rem" : "1rem", marginBottom: "1.5rem" }}>
              {[
                { name: userName, it: itA, info: newType.typeInfoA, pron: userPronouns },
                { name: partnerName, it: itB, info: newType.typeInfoB, pron: partnerPronouns },
              ].map(({ name, it, info, pron }) => (
                <div key={name} style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 16, padding: isMobile ? "1.1rem" : "1.4rem", borderTop: `4px solid ${it.color}` }}>
                  <div style={{ fontSize: "0.58rem", letterSpacing: "0.2em", textTransform: "uppercase", color: it.color, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.35rem" }}>{name}</div>
                  <div style={{ fontFamily: HFONT, fontSize: isMobile ? "1.05rem" : "1.2rem", fontWeight: 700, color: C.ink, marginBottom: "0.6rem" }}>{it.name}</div>
                  <p style={{ fontSize: "0.82rem", color: C.muted, fontFamily: BFONT, lineHeight: 1.7, margin: "0 0 1.1rem" }}>{blurbFor(name, pron, info)}</p>
                  <div style={{ display: "flex", flexDirection: "column", gap: "0.55rem" }}>
                    {axisRows(name, { engage: info.engageCoord, open: info.openCoord }).map(({ label, value, score }) => (
                      <div key={label}>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.2rem" }}>
                          <span style={{ fontSize: "0.6rem", color: C.muted, fontFamily: BFONT, fontWeight: 600 }}>{label}</span>
                          <span style={{ fontSize: "0.6rem", color: it.color, fontFamily: BFONT, fontWeight: 600 }}>{value}</span>
                        </div>
                        <div style={{ height: 4, background: C.stone, borderRadius: 2, overflow: "hidden" }}>
                          <div style={{ height: "100%", width: `${Math.round(score * 100)}%`, background: it.color, borderRadius: 2 }} />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
            );
          })()}

          <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: C.muted, fontFamily: BFONT, fontWeight: 700, marginTop: "1.75rem", marginBottom: "1rem" }}>
            Your couple type
          </div>
          {/* 6. CELEBRATORY TYPE REVEAL */}
          <div style={{ borderRadius: 20, overflow: "hidden", margin: "1.75rem 0 1.25rem", position: "relative" }}>
            <div style={{ background: `linear-gradient(145deg, ${ct.color}ee, ${ct.color}99)`, padding: "2.25rem 2.25rem 2rem", position: "relative", overflow: "hidden" }}>
              <div style={{ position: "absolute", bottom: -20, right: -10, fontFamily: HFONT, fontSize: "6rem", fontWeight: 700, color: "rgba(255,255,255,0.08)", lineHeight: 1, pointerEvents: "none", userSelect: "none", letterSpacing: "-0.04em", whiteSpace: "nowrap" }}>
                {ct.name.replace("The ", "")}
              </div>
              {/* block: couple-type/name */}
              <div style={{ fontFamily: HFONT, fontSize: "clamp(2.4rem, 6vw, 3.6rem)", fontWeight: 700, color: "white", lineHeight: 0.95, marginBottom: "0.85rem", letterSpacing: "-0.03em" }}>
                {ct.name}
              </div>
              <p style={{ fontSize: "1rem", color: "rgba(255,255,255,0.9)", fontFamily: BFONT, fontWeight: 500, lineHeight: 1.45, margin: 0, maxWidth: 440 }}>
                {ct.tagline}
              </p>
            </div>
          </div>

          {/* 7. The "what this looks like in your relationship" tile was
              removed from both surfaces at Ellie's ask, 22 September. */}

          {/* 8. SIDE-BY-SIDE: WHAT COMES NATURALLY | WHAT'S WORTH BEING AWARE OF */}
          <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: "1rem", marginBottom: "1.25rem" }}>
            {ct.strengths?.length > 0 && (
              <div style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 18, padding: "1.5rem" }}>
                {/* block: couple-type/strengths */}
                <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#10b981", fontFamily: BFONT, fontWeight: 700, marginBottom: "1rem" }}>What comes naturally</div>
                <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
                  {ct.strengths.slice(0,2).map((sx, i) => (
                    <div key={i} style={{ display: "flex", gap: "0.7rem", alignItems: "flex-start" }}>
                      <div style={{ width: 20, height: 20, borderRadius: "50%", background: "rgba(16,185,129,0.12)", border: "1.5px solid rgba(16,185,129,0.3)", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", marginTop: 2 }}>
                        <span style={{ fontSize: "0.6rem", color: "#10b981", fontWeight: 700 }}>✓</span>
                      </div>
                      <p style={{ fontSize: "0.84rem", color: C.ink, fontFamily: BFONT, lineHeight: 1.65, margin: 0 }}>{interp(sx)}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {ct.stickingPoints?.length > 0 && (
              <div style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 18, padding: "1.5rem" }}>
                {/* block: couple-type/sticking-points */}
                <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#E8673A", fontFamily: BFONT, fontWeight: 700, marginBottom: "1rem" }}>What's worth being aware of</div>
                <div style={{ display: "flex", flexDirection: "column", gap: "0.75rem" }}>
                  {_proseSet(ct.stickingPoints, _nearProse.stickingPointsNearEngage, _nearProse.stickingPointsNearOpen).slice(0,2).map((sx, i) => (
                    <div key={i} style={{ display: "flex", gap: "0.7rem", alignItems: "flex-start" }}>
                      <div style={{ width: 20, height: 20, borderRadius: "50%", background: "rgba(232,103,58,0.1)", border: "1.5px solid rgba(232,103,58,0.28)", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", marginTop: 2 }}>
                        <span style={{ fontSize: "0.65rem", color: "#E8673A", fontWeight: 700 }}>!</span>
                      </div>
                      <p style={{ fontSize: "0.84rem", color: C.ink, fontFamily: BFONT, lineHeight: 1.65, margin: 0 }}>{interp(sx)}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* 9. PHRASES TO TRY ───────────────────────────────────────────
              Ellie: "Remove the larger, white tiles and keep only the interior
              tiles with the phrase to try. Delete the bold label entirely, and
              only use the shaded tiles. From those tiles, remove the 'phrase to
              try' eyebrow since that's what the section is titled. There should
              just be 3, colored tiles with a phrase in each." */}
          <div style={{ marginBottom: "1.25rem" }}>
            <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: C.muted, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.75rem" }}>
              Phrases to try
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
              {ct.tips?.filter(t => t.phraseTry).map((tip, i) => {
                const tipColor = [ct.color, "#1B5FE8", "#10b981"][i % 3];
                return (
                  <div key={i} style={{ background: `${tipColor}14`, border: `1px solid ${tipColor}3d`, borderRadius: 12, padding: "0.9rem 1.1rem" }}>
                    {/* block: couple-type/tips */}
                    <span style={{ fontSize: "0.85rem", color: C.ink, fontFamily: BFONT, fontStyle: "italic", lineHeight: 1.6 }}>"{interp(tip.phraseTry)}"</span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* SHARE */}
          {/* Off-screen at full storycard size so the downloaded PNG is crisp
              regardless of viewport. Never visible to the user. */}
          <div aria-hidden="true" style={{ position: "fixed", left: -9999, top: 0, width: CARD_W, height: CARD_H, pointerEvents: "none" }}>
            <div ref={shareCardRef}>
              <CoupleTypeShareCard ct={ct} userName={userName} partnerName={partnerName} tagline={interp(ct.tagline)} />
            </div>
          </div>
          <div style={{ display: "flex", gap: "0.75rem", alignItems: "center", flexWrap: "wrap" }}>
            <button onClick={handleShare}
              disabled={shareBusy}
              style={{ background: typeShared ? "#10b981" : C.ink, color: "white", border: "none", borderRadius: 10, padding: "0.65rem 1.5rem", fontSize: "0.75rem", fontWeight: 700, cursor: shareBusy ? "wait" : "pointer", fontFamily: BFONT, letterSpacing: "0.04em", transition: "background 0.2s", opacity: shareBusy ? 0.7 : 1 }}>
              {typeShared ? "Image downloaded ✓" : shareBusy ? "Creating image…" : "Download your share image ↓"}
            </button>
            <p style={{ fontSize: "0.72rem", color: C.muted, fontFamily: BFONT, margin: 0 }}>Post it to your stories or send it to a friend.</p>
          </div>

        </div>
      </Layout>
    );
  }

  // ── COMM PAGES: delegate to PersonalityResults with step override ───────────
  if (section.startsWith("comm")) {
    const dimStep = (() => {
      if (section === "comm-overview") return 0;
      // comm-profiles and comm-plan were removed. Any stored or bookmarked
      // link to them lands on the overview rather than a blank page.
      if (section === "comm-profiles" || section === "comm-plan") return 0;
      const key = section.replace("comm-", "");
      // Domain page id, or a legacy comm-<dim> link resolving to its domain page.
      let i = UR_DOMAINS.findIndex(g => g.id === key);
      if (i < 0) i = UR_DOMAINS.findIndex(g => g.dims.includes(key));
      return i >= 0 ? i + 1 : 0;
    })();
    return (
      <Layout accent="#E8673A">
        <PersonalityResultsPage
          myAnswers={ex1Answers} partnerAnswers={partnerEx1}
          userName={userName} partnerName={partnerName}
          coupleType={coupleType}
          userPronouns={userPronouns} partnerPronouns={partnerPronouns}
          forcedStep={dimStep} orderedDims={orderedDims}
          onGoExpectations={() => go("exp-overview")}
          // The forward path arrives here from Couple Type, so Back returns
          // there rather than dead-ending on the first page of the section.
          onGoBack={() => go("couple-type")}
          onNavigateTool={onNavigateTool}
          hasWorkbook={hasWorkbook}
          onStepChange={s => {
            if (s === 0) go("comm-overview");
            else if (s >= 1 && s <= nUR) go(`comm-${UR_DOMAINS[s-1].id}`);
          }}
        />
      </Layout>
    );
  }

  // ── EXP PAGES: delegate to ExpectationsResults with section override ────────
  if (section.startsWith("exp")) {
    const expSection = section === "exp-overview" ? "overview"
      : section === "exp-action-plan" ? "overview"
      // The step is the page's place in the flow; the section id is the
      // category's own. They were the same number until Life & Values moved to
      // the front, and reading one as the other put every page one off.
      : section.startsWith("exp-convo-") ? `convo-${Math.max(0, FIXED_CATS.findIndex(fc => fc.section === section))}`
      : "overview";
    return (
      <Layout accent="#1B5FE8">
        <ExpectationsResultsPage
          myAnswers={ex2Answers} partnerAnswers={partnerEx2}
          coupleTypeCode={(() => { try { const t = deriveNewCoupleType(myS, partS); return (t?.typeInfoA?.typeCode || "") + (t?.typeInfoB?.typeCode || ""); } catch { return null; } })()}
          coupleTypeName={(() => { try { return deriveNewCoupleType(myS, partS)?.name || null; } catch { return null; } })()}
          coupleTypeColor={(() => { try { return deriveNewCoupleType(myS, partS)?.color || "#1B5FE8"; } catch { return "#1B5FE8"; } })()}
          userName={userName} partnerName={partnerName}
          forcedSection={expSection}
          onGoWhatComesNext={() => go(hasAnniversary ? "reflection-overview" : intimacyBothDone ? "intimacy-overview" : "what-comes-next")}
          // Back out of the section rather than dead-ending: the forward path
          // arrives here from the last comms detail page.
          onGoBack={() => go(UR_DOMAINS.length ? `comm-${UR_DOMAINS[UR_DOMAINS.length - 1].id}` : "comm-overview")}
          onExternalGo={s => {
            if (s === 0) go("exp-overview");
            // `convo-N` is a step inside ExpectationsResults, which counts in
            // the order the pages are read. The route it becomes is the
            // category's own section id, which does not.
            else if (typeof s === "string" && s.startsWith("convo-")) {
              const fc = FIXED_CATS[parseInt(s.split("-")[1])];
              if (fc) go(fc.section);
            }
          }}
        />
      </Layout>
    );
  }

  // ── REFLECTION ────────────────────────────────────────────────────────────────
  if (section.startsWith("reflection") && hasAnniversary) {
    const mine = ex3Answers || SARAH_ANNIVERSARY_DEMO;
    const theirs = partnerEx3 || JAMES_ANNIVERSARY_DEMO;
    const insights = deriveAnniversaryInsights(mine, theirs, userName, partnerName, coupleType);
    const scaleQs = ANNIVERSARY_QUESTIONS.filter(q => q.type === "scale");
    const textQs = [
      { id: "a1", label: "A moment that defined us", category: "Milestones" },
      { id: "a2", label: "Something that made us stronger", category: "Milestones" },
      { id: "a6", label: "What I want to work on", category: "Looking Forward" },
      { id: "a7", label: "Something I wish we'd handled differently", category: "Looking Forward" },
      { id: "a5", label: "Where I see us in 5 years", category: "Looking Forward" },
      { id: "a3", label: "What I'm most grateful for", category: "What Matters" },
      { id: "a4", label: "What I want more of together", category: "What Matters" },
    ];
    const actionItems = insights.filter(i => i.type === "explore").map(i => i.title);

    // ── REFLECTION OVERVIEW ───────────────────────────────────────────────────
    if (section === "reflection-overview" || section === "reflection") {
      const explores = insights.filter(i => i.type === "explore").length;
      // The heading and the line under it. Both were written here, where the
      // app cannot read them, so the app opened this page with the section's
      // name and no line at all. One builder now, in api/_lib.
      const ov = reflectionOverview({ mine, theirs, you: userName, them: partnerName });
      const myAdmire = mine.a8;
      const theirAdmire = theirs.a8;
      return (
        <Layout accent="#1B5FE8">
          {/* Brighter than the detail pages, which keep the darker ground.
              Matches the comms and expectations glance pages. */}
          <ResultsSlide bg={gradientCss("reflection-overview")}>
            <link href={FONT_URL} rel="stylesheet" />
            <div style={{ color: "white" }}>
              {/* Header — matches the comms + expectations overviews */}
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "0.6rem", marginBottom: "0.5rem" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "0.6rem" }}>
                </div>
              </div>
              {/* Ellie: the title "should read Relationship Reflection" and
                  the line under it goes. Both surfaces read the title from
                  PAGE_TITLES, so neither can drift. */}
              <div style={{ fontSize: "clamp(1.8rem,6vw,2.8rem)", fontWeight: 700, fontFamily: HFONT, lineHeight: 1.05, marginBottom: "1rem" }}>{SC_TITLES["reflection-overview"]}</div>

              {/* How you feel right now — scale questions (8.2) */}
              <div style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: 14, padding: "1.1rem 1.25rem", marginBottom: "1rem" }}>
                {/* block: reflection-overview/ratings */}
                <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.35)", fontFamily: BFONT, fontWeight: 700, marginBottom: "1rem" }}>{ov.ratingsLabel}</div>
                {scaleQs.filter(q => q.id !== "a0").map(q => {
                  const myVal = mine[q.id] ?? 2;
                  const theirVal = theirs[q.id] ?? 2;
                  const endLow = q.scaleLabels[0];
                  const endHigh = q.scaleLabels[q.scaleLabels.length - 1];
                  // The shorter name, from the questions file. Typed here, it
                  // was three strings the app could not read, so the app
                  // printed the whole question where this printed two words.
                  const short = GLANCE_TEXT[q.id] || q.text.split("?")[0];
                  return (
                    <div key={q.id} style={{ marginBottom: "0.9rem" }}>
                      <div style={{ fontSize: "0.7rem", color: "rgba(255,255,255,0.7)", fontWeight: 500, fontFamily: BFONT, marginBottom: "0.4rem" }}>{short}</div>
                      <div style={{ display: "flex", alignItems: "center", gap: "0.55rem" }}>
                        <span style={{ fontSize: "0.55rem", color: "rgba(255,255,255,0.32)", fontFamily: BFONT, width: 62, flexShrink: 0, textAlign: "right", lineHeight: 1.25 }}>{endLow}</span>
                        <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 4 }}>
                          {[[userName, myVal, "#E8673A"], [partnerName, theirVal, "#5B6DF8"]].map(([name, val, color]) => (
                            <div key={name} style={{ display: "flex", gap: 3 }}>
                              {q.scaleLabels.map((_, i) => (
                                <div key={i} style={{ flex: 1, height: 7, borderRadius: 2, background: i <= val ? color : "rgba(255,255,255,0.1)" }} />
                              ))}
                            </div>
                          ))}
                        </div>
                        <span style={{ fontSize: "0.55rem", color: "rgba(255,255,255,0.32)", fontFamily: BFONT, width: 62, flexShrink: 0, lineHeight: 1.25 }}>{endHigh}</span>
                      </div>
                    </div>
                  );
                })}
                <div style={{ display: "flex", justifyContent: "center", gap: "1.1rem", paddingTop: "0.25rem" }}>
                  {[[userName, "#E8673A"], [partnerName, "#5B6DF8"]].map(([name, color]) => (
                    <div key={name} style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}>
                      <div style={{ width: 8, height: 8, borderRadius: "50%", background: color, flexShrink: 0 }} />
                      <span style={{ fontSize: "0.65rem", color: "rgba(255,255,255,0.5)", fontFamily: BFONT }}>{name}</span>
                    </div>
                  ))}
                </div>
              </div>


              {/* ── ACTION PLAN ──────────────────────────────────────────────
                  Ellie: "App rel relf results at a glance page lists the action
                  plan as the things you each said you're going to work on. The
                  site uses a different, less helpful list. Make the site also
                  use the self-answer for the action plan on this page."

                  The old list was derived insights, which are the product's
                  reading of the answers. What each person actually wrote when
                  asked what they want to work on is better: it is theirs, and
                  it is the thing they will recognise. */}
              {(() => {
                // The answers themselves, which this page already has: mine
                // and theirs are the two people's raw reflection answers, and
                // a6 is "one thing I want to work on in how I show up for you".
                const yourWords = String(mine?.a6 || '').trim();
                const theirWords = String(theirs?.a6 || '').trim();
                if (!yourWords && !theirWords) return null;
                const commitment = { you: yourWords, them: theirWords };
                return (
                  <div style={{ marginBottom: "1rem" }}>
                    {/* block: reflection-overview/action-plan */}
                    <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, fontWeight: 700, marginBottom: "0.6rem" }}>{ov.planLabel}</div>
                    <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                      {[{ name: userName, words: commitment.you, color: SC_PEOPLE.you },
                        { name: partnerName, words: commitment.them, color: SC_PEOPLE.them }].map((p, i) => (
                        <div key={i} style={{ background: "rgba(255,255,255,0.13)", border: "1px solid rgba(255,255,255,0.22)", borderLeft: `4px solid ${p.color}`, borderRadius: 12, padding: "0.8rem 1rem" }}>
                          <div style={{ fontSize: "0.85rem", fontWeight: 700, color: "white", fontFamily: BFONT, lineHeight: 1.4 }}>{p.name}</div>
                          {/* Ellie: "Your action plan on overview... for the rel
                              relf. section should have each person's content in
                              italics and quotation marks, so that it's clear
                              that that's what the person wrote." The app draws
                              the same two tiles the same way.

                              The marks are added here rather than stored with
                              the answer: what someone typed is what they typed,
                              and baking punctuation into the value would put a
                              quotation mark in their journal and the workbook. */}
                          <div style={{ fontSize: "0.78rem", color: "rgba(255,255,255,0.72)", fontFamily: BFONT, fontStyle: "italic", lineHeight: 1.55, marginTop: "0.25rem" }}>{"\u201C" + (p.words || "") + "\u201D"}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })()}

            </div>
          </ResultsSlide>
        </Layout>
      );
    }

    // ── REFLECTION INSIGHTS ───────────────────────────────────────────────────
    // ── HOW YOU EACH RATED ────────────────────────────────────────────────────
    // Everything with a fixed answer: the scales, the admiration pick, the
    // priority ranking. Shown as comparisons rather than described in prose.
    // Free-text answers live on Side by Side, in the couple's own words.
    if (section === "reflection-ratings" || section === "reflection-insights") {
      const overallQ = ANNIVERSARY_QUESTIONS.find(q => q.id === "a0");
      const _reflSameInit = (userName?.[0] || "").toUpperCase() === (partnerName?.[0] || "").toUpperCase();
      const ratedScales = scaleQs.filter(q => mine[q.id] != null && theirs[q.id] != null);
      const pct = v => (v / 4) * 100;

      /**
       * One rating, both people on it.
       *
       * Ellie: "I want the sliding bars on how you each rated page to look
       * like they do on comms detailed pages with the poles on the sides of
       * the bars." So the two ends sit either side of the track rather than
       * above its corners, which is how every communication row is drawn and
       * how the app draws this one now.
       *
       * Each person's answer stays under their own mark, which is what the app
       * was asked to copy from here.
       */
      const ScaleRow = ({ q }) => {
        const mv = mine[q.id], tv = theirs[q.id];
        const gap = Math.abs(mv - tv);
        const tone = gap === 0 ? "#10b981" : gap === 1 ? "#1B5FE8" : "#E8673A";
        // The poles sit on the bar's centre line. The row's middle column is
        // the bar plus the answer labels under it, so centring the row put
        // them level with the middle of that whole stack rather than with the
        // bar. They take the bar row's height instead, which is the same fix
        // the app needed. Ellie: "pole labels ... should be middle aligned
        // with the bar itself."
        // Wrapping, and level with the bar. Ellie: "wrap pole titles so that
        // text isn't cut off." These are phrases rather than words, and a
        // fixed 6px line box cut every one of them to nothing.
        const pole = { fontSize: "0.66rem", color: C.muted, fontFamily: BFONT, flexShrink: 0, width: "clamp(64px,20%,104px)", lineHeight: 1.25, marginTop: -3 };
        return (
          <div>
            <div style={{ fontFamily: HFONT, fontSize: "0.86rem", fontWeight: 700, color: C.ink, marginBottom: "0.7rem" }}>{q.text}</div>
            <div style={{ display: "flex", alignItems: "flex-start", gap: "0.6rem" }}>
              <span style={{ ...pole, justifyContent: "flex-end", textAlign: "right" }}>{q.scaleLabels[0]}</span>
              <div style={{ flex: 1, minWidth: 0, padding: "0 11px" }}>
                <div style={{ position: "relative", height: 6, background: C.stone, borderRadius: 999 }}>
                  {gap > 0 && (
                    <div style={{ position: "absolute", top: 0, bottom: 0, left: `${Math.min(pct(mv), pct(tv))}%`, width: `${Math.abs(pct(mv) - pct(tv))}%`, background: tone, opacity: 0.22, borderRadius: 999 }} />
                  )}
                  {[[mv, userName, "#E8673A", 2, -TM_STAGGER], [tv, partnerName, "#1B5FE8", 1, TM_STAGGER]].map(([v, name, col, z, dy]) => (
                    <div key={name} style={{ position: "absolute", top: "50%", left: `${pct(v)}%`, transform: `translate(-50%, calc(-50% + ${gap === 0 ? dy : 0}px))`, width: 18, height: 18, borderRadius: "50%", background: col, border: "2.5px solid white", boxShadow: "0 1px 4px rgba(0,0,0,0.18)", zIndex: z, display: "flex", alignItems: "center", justifyContent: "center", ...scType("mark") }}>{_reflSameInit ? "" : name[0]}</div>
                  ))}
                </div>
                <div style={{ position: "relative", height: 20, marginTop: gap === 0 ? 10 : 6 }}>
                  {gap === 0 ? (
                    // Same score: one label under the shared mark, so the two
                    // names cannot print on top of each other.
                    <span style={{ position: "absolute", left: `${pct(mv)}%`, transform: "translateX(-50%)", fontSize: "0.66rem", fontWeight: 700, fontFamily: BFONT, whiteSpace: "nowrap", textAlign: "center" }}>
                      {_reflSameInit && (<><span style={{ color: "#E8673A" }}>{userName}</span><span style={{ color: C.muted }}> &amp; </span><span style={{ color: "#1B5FE8" }}>{partnerName}</span><span style={{ color: C.muted }}> · </span></>)}
                      <span style={{ color: C.text, fontWeight: 600 }}>{q.scaleLabels[mv]}</span>
                    </span>
                  ) : [[mv, userName, "#E8673A"], [tv, partnerName, "#1B5FE8"]].map(([v, name, col], idx) => {
                    const isLeft = pct(v) < pct(idx === 0 ? tv : mv);
                    return (
                      <span key={name} style={{ position: "absolute", left: `${pct(v)}%`, transform: isLeft ? "translateX(-100%)" : "translateX(0)", paddingRight: isLeft ? 5 : 0, paddingLeft: isLeft ? 0 : 5, fontSize: "0.66rem", fontWeight: 700, color: col, fontFamily: BFONT, whiteSpace: "nowrap" }}>
                        {_reflSameInit ? (name + " · " + q.scaleLabels[v]) : q.scaleLabels[v]}
                      </span>
                    );
                  })}
                </div>
              </div>
              <span style={pole}>{q.scaleLabels[q.scaleLabels.length - 1]}</span>
            </div>
          </div>
        );
      };

      /**
       * A tile of ratings under one heading.
       *
       * Ellie: "I want one tile for overall and one tile for how things feel
       * right now, and the how things feel right now tile should have 3
       * questions in it." It was a card per question, so the rating about the
       * relationship as a whole sat in the same frame as the three about parts
       * of it.
       */
      const RatedTile = ({ label, rows }) => (
        <div style={{ marginBottom: "1.5rem" }}>
          <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#1B5FE8", fontWeight: 700, fontFamily: BFONT, marginBottom: "0.6rem" }}>{label}</div>
          <div style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 14, padding: "1.1rem 1.25rem" }}>
            {rows.map((q, i) => (
              <div key={q.id} style={{ paddingTop: i === 0 ? 0 : "1.1rem", marginTop: i === 0 ? 0 : "1.1rem", borderTop: i === 0 ? "none" : `1px solid ${C.stone}` }}>
                <ScaleRow q={q} />
              </div>
            ))}
          </div>
        </div>
      );

      return (
        <Layout accent="#1B5FE8">
          <div style={{ maxWidth: 660 }}>
            {/* No page dot and no eyebrow. Ellie: "make sure these are gone from every results page across web and app." The two reflection detail pages were the last two carrying them. */}
            <h2 style={{ fontFamily: HFONT, fontSize: "clamp(1.6rem,3vw,2.2rem)", fontWeight: 700, color: C.ink, lineHeight: 1.1, marginBottom: "0.5rem" }}>{REFLECTION_PAGES.ratings.title}</h2>
            {/* The line under this heading is gone, on both surfaces. */}

            {overallQ && mine.a0 != null && theirs.a0 != null && (
              <RatedTile label="Overall" rows={[overallQ]} />
            )}

            {/* block: reflection-ratings/scales */}
            {ratedScales.filter(q => q.id !== "a0").length > 0 && (
              <RatedTile label="How things feel right now" rows={ratedScales.filter(q => q.id !== "a0")} />
            )}

            {/* Admiration pick */}
            {mine.a8 && theirs.a8 && (
              <div style={{ marginBottom: "1.5rem" }}>
                {/* block: reflection-overview/admired */}
                <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#1B5FE8", fontWeight: 700, fontFamily: BFONT, marginBottom: "0.6rem" }}>What you each admire</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.75rem" }}>
                  {[[userName, partnerName, mine.a8, "#E8673A"], [partnerName, userName, theirs.a8, "#1B5FE8"]].map(([from, about, val, col]) => (
                    <div key={from} style={{ background: "white", border: `1.5px solid ${col}30`, borderRadius: 14, padding: "1.1rem 1.25rem", borderTop: `3px solid ${col}` }}>
                      <div style={{ fontSize: "0.58rem", letterSpacing: "0.14em", textTransform: "uppercase", color: col, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.5rem" }}>{from} admires</div>
                      <div style={{ fontFamily: HFONT, fontSize: "1.35rem", fontWeight: 700, color: C.ink, lineHeight: 1.1 }}>{admiredNoun(val)}</div>
                      <div style={{ fontSize: "0.7rem", color: C.muted, fontFamily: BFONT, marginTop: "0.3rem" }}>in {about}</div>
                    </div>
                  ))}
                </div>
                {mine.a8 === theirs.a8 && (
                  <div style={{ marginTop: "0.6rem", background: "#EDFAF5", border: "1px solid #10b98130", borderRadius: 10, padding: "0.6rem 0.9rem", fontSize: "0.76rem", color: "#047857", fontFamily: BFONT, fontWeight: 600 }}>
                    You picked the same quality, without conferring.
                  </div>
                )}
              </div>
            )}

            {/* Priority ranking — curved gradient lines connect the same item on each list */}
            {Array.isArray(mine.a_priority) && Array.isArray(theirs.a_priority) && mine.a_priority.length > 0 && theirs.a_priority.length > 0 && (() => {
              const ROW = 42, HEAD = 24;
              const n = mine.a_priority.length;
              const H = n * ROW;
              return (
              <div style={{ marginBottom: "1.5rem" }}>
                <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#1B5FE8", fontWeight: 700, fontFamily: BFONT, marginBottom: "0.6rem" }}>{REFLECTION_PAGES.priorities.title}</div>
                <div style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 14, overflow: "hidden" }}>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 92px 1fr", padding: "0.95rem 1.15rem 1.1rem" }}>
                    {/* Left: user's ranking, aligned toward the connectors */}
                    <div>
                      <div style={{ height: HEAD, display: "flex", alignItems: "center", justifyContent: "flex-end", fontSize: "0.56rem", letterSpacing: "0.14em", textTransform: "uppercase", color: "#E8673A", fontWeight: 700, fontFamily: BFONT }}>{userName}</div>
                      {mine.a_priority.map((item, ri) => (
                        <div key={item} style={{ height: ROW, display: "flex", alignItems: "center", gap: "0.4rem", justifyContent: "flex-end", textAlign: "right" }}>
                          <span style={{ fontSize: "0.78rem", color: C.ink, fontFamily: BFONT, whiteSpace: "nowrap" }}>{item}</span>
                          <span style={{ fontSize: "0.6rem", fontWeight: 700, color: "#E8673A", opacity: 0.6, fontFamily: BFONT, flexShrink: 0 }}>#{ri + 1}</span>
                        </div>
                      ))}
                    </div>
                    {/* Middle: curved, gradient-coloured connectors */}
                    <div>
                      <div style={{ height: HEAD }} />
                      <svg width="100%" height={H} viewBox={`0 0 100 ${H}`} preserveAspectRatio="none" style={{ display: "block", overflow: "visible" }}>
                        <defs>
                          {mine.a_priority.map((item, ri) => {
                            const rj = theirs.a_priority.indexOf(item);
                            if (rj < 0) return null;
                            return (
                              <linearGradient key={item} id={`plg-${ri}`} x1="0" y1="0" x2="1" y2="0">
                                <stop offset="0%" stopColor="#E8673A" />
                                <stop offset="100%" stopColor="#1B5FE8" />
                              </linearGradient>
                            );
                          })}
                        </defs>
                        {mine.a_priority.map((item, ri) => {
                          const rj = theirs.a_priority.indexOf(item);
                          if (rj < 0) return null;
                          const y1 = ri * ROW + ROW / 2, y2 = rj * ROW + ROW / 2;
                          const gap = Math.abs(ri - rj);
                          return (
                            <path key={item} d={`M 8 ${y1} C 46 ${y1}, 54 ${y2}, 92 ${y2}`} fill="none"
                              stroke={`url(#plg-${ri})`} strokeWidth={gap === 0 ? 3 : 2}
                              strokeOpacity={gap === 0 ? 0.95 : 0.5} strokeLinecap="round"
                              vectorEffect="non-scaling-stroke" />
                          );
                        })}
                      </svg>
                    </div>
                    {/* Right: partner's ranking, aligned toward the connectors */}
                    <div>
                      <div style={{ height: HEAD, display: "flex", alignItems: "center", fontSize: "0.56rem", letterSpacing: "0.14em", textTransform: "uppercase", color: "#1B5FE8", fontWeight: 700, fontFamily: BFONT }}>{partnerName}</div>
                      {theirs.a_priority.map((item, ri) => (
                        <div key={item} style={{ height: ROW, display: "flex", alignItems: "center", gap: "0.4rem" }}>
                          <span style={{ fontSize: "0.6rem", fontWeight: 700, color: "#1B5FE8", opacity: 0.6, fontFamily: BFONT, flexShrink: 0 }}>#{ri + 1}</span>
                          <span style={{ fontSize: "0.78rem", color: C.ink, fontFamily: BFONT, whiteSpace: "nowrap" }}>{item}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div style={{ padding: "0.6rem 1.15rem", borderTop: `1px solid ${C.stone}40`, background: "#FAFAF8" }}>
                    <span style={{ fontSize: "0.7rem", color: C.muted, fontFamily: BFONT, fontWeight: 300 }}>
                      {REFLECTION_PAGES.priorities.note}
                    </span>
                  </div>
                </div>
              </div>
              );
            })()}
          </div>
        </Layout>
      );
    }

    // ── REFLECTION STORY (SIDE BY SIDE) ──────────────────────────────────────
    if (section === "reflection-story") {
      // The previous synthesis note guessed a theme from keywords and could
      // claim "you both pointed to..." on two answers that matched nothing at
      // all. Two answers side by side do not need a verdict. They need a
      // question, so each pair carries a fixed prompt tied to that question.
      const PROMPTS = REFLECTION_PROMPTS;

      return (
        <Layout accent="#1B5FE8">
          <div style={{ maxWidth: 660 }}>
            {/* No page dot and no eyebrow. Ellie: "make sure these are gone from every results page across web and app." The two reflection detail pages were the last two carrying them. */}
            <h2 style={{ fontFamily: HFONT, fontSize: "clamp(1.6rem,3vw,2.2rem)", fontWeight: 700, color: C.ink, lineHeight: 1.1, marginBottom: "0.5rem" }}>{REFLECTION_PAGES.story.title}</h2>
            <p style={{ fontSize: "0.82rem", color: C.muted, fontFamily: BFONT, fontWeight: 300, marginBottom: "1.5rem", lineHeight: 1.65 }}>{REFLECTION_PAGES.story.sub}</p>
            {/* block: reflection-story/groups */}
          {STORY_CATEGORIES.map(cat => {
              const catQs = textQs.filter(q => q.category === cat);
              return (
                <div key={cat} style={{ marginBottom: "1.75rem" }}>
                  <div style={{ fontSize: "0.6rem", letterSpacing: "0.2em", textTransform: "uppercase", color: "#1B5FE8", fontWeight: 700, fontFamily: BFONT, marginBottom: "0.6rem" }}>{cat}</div>
                  {/* block: reflection-story/pairs */}
                  {catQs.map(q => {
                    const prompt = PROMPTS[q.id];
                    const answered = mine[q.id] && theirs[q.id];
                    return (
                      <div key={q.id} style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 14, marginBottom: "0.75rem", overflow: "hidden" }}>
                        <div style={{ padding: "0.7rem 1.1rem", borderBottom: `1px solid ${C.stone}50`, background: "#FAFAF8" }}>
                          <span style={{ fontFamily: HFONT, fontSize: "0.82rem", fontWeight: 700, color: C.ink }}>{q.label}</span>
                        </div>
                        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr" }}>
                          {[[userName, mine[q.id], "#E8673A"], [partnerName, theirs[q.id], "#1B5FE8"]].map(([name, ans, col], i) => (
                            <div key={name} style={{ padding: "0.9rem 1.1rem", borderRight: i === 0 ? `1px solid ${C.stone}40` : "none" }}>
                              <div style={{ fontSize: "0.58rem", letterSpacing: "0.14em", textTransform: "uppercase", color: col, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.45rem" }}>{name}</div>
                              <p style={{ fontSize: "0.79rem", color: C.text, fontFamily: BFONT, fontWeight: 300, lineHeight: 1.72, margin: 0, fontStyle: "italic" }}>"{ans || "–"}"</p>
                            </div>
                          ))}
                        </div>
                        {prompt && answered && (
                          <div style={{ padding: "0.7rem 1.1rem", background: "#FBF8F3", borderTop: `1px solid ${C.stone}30`, display: "flex", alignItems: "flex-start", gap: "0.55rem" }}>
                            <span style={{ fontSize: "0.55rem", letterSpacing: "0.14em", textTransform: "uppercase", color: "#E8673A", fontWeight: 700, fontFamily: BFONT, whiteSpace: "nowrap", marginTop: "0.15rem" }}>{TALK_ABOUT_IT}</span>
                            <span style={{ fontSize: "0.77rem", color: C.text, fontFamily: BFONT, fontWeight: 300, lineHeight: 1.6 }}>{prompt}</span>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              );
            })}

          </div>
        </Layout>
      );
    }

    // ── REFLECTION ACTION PLAN ────────────────────────────────────────────────
    // The reflection action plan had a page of its own. Ellie: "App and site
    // both show a detailed page for rel relf called action plan. Remove that
    // page from both web and app." The plan itself is on the at-a-glance page,
    // where a reader meets it without a detour.

    return null;
  }

  // ── PAGE: PHYSICAL INTIMACY (add-on results section) ──────────────────────────
  if (section.startsWith("intimacy") && intimacyBothDone) {
    const ROSE = "#B5546E";
    const ROSE_DARK = "#4a1c30";
    const stateColor = { aligned: "#10b981", discuss: "#E8673A", different: "#B5546E", unspoken: "#7A6753", incomplete: "#7A6753" };
    const stateLabel = { aligned: "Aligned", discuss: "Worth discussing", different: "Different expectations", unspoken: "Left unspoken", incomplete: "Incomplete" };
    const sub = (s) => (s || "").replace(/\{U\}/g, userName).replace(/\{P\}/g, partnerName);
    const dims = intimacySummary.dimSummary;
    const positions = intimacyDimensionPositions(intimacyAnswers, partnerIntimacy.answers);
    const skips = intimacyDimensionSkips(intimacyAnswers, partnerIntimacy.answers);
    // One-sided skip: exactly one partner skipped the whole dimension. Returns
    // the skipper's name, or null. (Both-skipped is handled by the 'unspoken' state.)
    const oneSidedSkip = (dimId) => {
      const sk = skips[dimId] || {};
      if (sk.mineSkipped && !sk.theirsSkipped) return userName;
      if (sk.theirsSkipped && !sk.mineSkipped) return partnerName;
      return null;
    };
    const proseFor = (dimId, state) => sub(INTIMACY_RESULTS_PROSE[dimId]?.[state] || INTIMACY_RESULTS_PROSE[dimId]?.discuss || "");
    const alignedCount = dims.filter(d => d.state === "aligned").length;
    const exploreCount = dims.filter(d => d.state === "discuss" || d.state === "different").length;
    const dimIds = INTIMACY_DIMENSIONS.map(d => d.id);

    // ── OVERVIEW ──
    if (section === "intimacy-overview" || section === "intimacy") {
      return (
        <Layout accent={ROSE}>
          {/* Brighter than the detail pages, which keep the darker ground. */}
          <ResultsSlide bg={gradientCss("intimacy-overview")}>
            <link href={FONT_URL} rel="stylesheet" />
            <div style={{ color: "white" }}>
              {/* Header — same shape as the comms + expectations overviews */}
              {/* Ellie: the hero "should have the hero read physical intimacy
                  expectations", and the line under it about how things are now
                  is gone. It led with the two names, which does not say what
                  the page is. The title is shared, so neither surface drifts. */}
              <div style={{ fontSize: "clamp(1.8rem,6vw,2.8rem)", fontWeight: 700, fontFamily: HFONT, lineHeight: 1.05, marginBottom: "1rem" }}>{SC_TITLES["intimacy-overview"]}</div>
              
              {/* The placement bars: label left, bar right, key top-right (9.1). The
                  label is shared copy now, from api/_lib/results-sections.js. */}
              <div style={{ background: "rgba(255,255,255,0.12)", border: "1px solid rgba(255,255,255,0.22)", borderRadius: 14, padding: "1rem 1.1rem", marginBottom: "1rem", boxShadow: "0 8px 26px rgba(0,0,0,0.16)" }}>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "0.7rem", gap: "1rem", flexWrap: "wrap" }}>
                  {/* block: intimacy-overview/where-you-each-land */}
                  <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.3)", fontFamily: BFONT, fontWeight: 700 }}>{SC_COPY.commPlacements}</div>
                </div>
                {/* ── ONE BAR PER ASPECT, AS A PERCENTAGE ──────────────────
                    Ellie: "can we make the bars % aligned rather than the
                    placement dots?" Six two-person charts stacked is six
                    things to read, and the question this page answers is how
                    close the two of you are on each aspect, which is one
                    number. The legend and the pole labels go with the dots:
                    a percentage needs neither.

                    An aspect one of them skipped has no percentage and says
                    so, because unanswered is not nought per cent aligned. */}
                <div style={{ display: "flex", flexDirection: "column", gap: "0.55rem" }}>
                  {INTIMACY_DIMENSIONS.map(d => {
                    const found = (intimacySummary?.dimSummary || []).find(x => x.id === d.id);
                    const pct = found?.avgGap == null ? null : Math.round((1 - found.avgGap) * 100);
                    /* The third copy of this ramp was here. It lives in
                       the app's lib now, which the app reads as well, so a
                       percentage cannot mean one thing on a phone and another
                       on a laptop. */
                    const tone = pct == null ? "rgba(255,255,255,0.4)" : alignedTone(pct);
                    return (
                      <div key={d.id} onClick={() => go(`intimacy-${d.id}`)}
                        style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: "0.65rem" }}>
                        <span style={{ fontSize: "0.65rem", color: "rgba(255,255,255,0.65)", fontFamily: BFONT, flexShrink: 0, width: "clamp(88px,30%,120px)", lineHeight: 1.25 }}>{d.label}</span>
                        <div style={{ flex: 1, height: 6, background: "rgba(255,255,255,0.12)", borderRadius: 999, overflow: "hidden" }}>
                          {pct != null && <div style={{ width: `${pct}%`, height: "100%", background: tone, borderRadius: 999 }} />}
                        </div>
                        <span style={{ fontSize: "0.65rem", fontWeight: 700, color: tone, fontFamily: BFONT, width: 40, textAlign: "right", flexShrink: 0 }}>
                          {pct == null ? "\u2014" : `${pct}%`}
                        </span>
                      </div>
                    );
                  })}
                </div>
              </div>


              {/* ── ACTION PLAN — the aspects worth talking about ── */}
              {(() => {
                // Three, furthest apart first, from the one function both
                // surfaces read. This filtered its own copy of the dimensions
                // and took four while the app took three from a differently
                // filtered list, so the same couple saw four items here and
                // six on a phone. Ellie asked for three, and for them to be
                // the same three.
                const items = intimacyActionPlan(intimacySummary?.dimSummary || []);
                /* No plan, and the reason is worth saying: agreeing is not the
                   same as having said it out loud. This line used to be on
                   Conversations Worth Having, which is gone.

                   WHEN it may be said is intimacyAllAlignedNote's decision, not
                   this page's. An empty action plan is not the same thing as
                   agreeing: a couple who skipped every question have an empty
                   plan too, and this page told them they line up across the
                   board. The app reads the same answer out of the results
                   payload, so fixing it there fixed one of the two surfaces and
                   left this one saying it. */
                const allAligned = intimacyAllAlignedNote(intimacySummary?.dimSummary || []);
                if (!items.length) {
                  if (!allAligned) return null;
                  return (
                    <div style={{ marginBottom: "1rem", background: "rgba(255,255,255,0.13)", border: "1px solid rgba(255,255,255,0.22)", borderLeft: `4px solid ${ROSE}`, borderRadius: 12, padding: "0.9rem 1.1rem" }}>
                      <p style={{ fontSize: "0.82rem", color: "rgba(255,255,255,0.85)", fontFamily: BFONT, lineHeight: 1.6, margin: 0 }}>{allAligned}</p>
                    </div>
                  );
                }
                return (
                  <div style={{ marginBottom: "1rem" }}>
                    {/* block: intimacy-overview/action-plan */}
                    <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, fontWeight: 700, marginBottom: "0.6rem" }}>Your action plan</div>
                    <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                      {items.map((d, i) => {
                        const meta = INTIMACY_DIMENSIONS.find(x => x.id === d.id);
                        const prompt = (INTIMACY_RESULTS_PROSE[d.id]?.prompt || "").replace(/\{U\}/g, userName).replace(/\{P\}/g, partnerName);
                        return (
                          <div key={i} onClick={() => go(`intimacy-${d.id}`)}
                            style={{ background: "rgba(255,255,255,0.13)", border: "1px solid rgba(255,255,255,0.22)", borderLeft: `4px solid ${ROSE}`, borderRadius: 12, padding: "0.9rem 1.1rem", boxShadow: "0 6px 20px rgba(0,0,0,0.14)", cursor: "pointer" }}>
                            <div style={{ fontSize: "0.85rem", fontWeight: 700, color: "white", fontFamily: BFONT, lineHeight: 1.4 }}>Talk about {(meta?.label || d.id).toLowerCase()}</div>
                            {prompt && <div style={{ fontSize: "0.78rem", color: "rgba(255,255,255,0.72)", fontFamily: BFONT, lineHeight: 1.55, marginTop: "0.3rem" }}>{prompt}</div>}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })()}

            </div>
          </ResultsSlide>
        </Layout>
      );
    }

    /* ── ONE PAGE PER DOMAIN, THREE ASPECTS ON EACH ───────────────────────
       Ellie: "Regroup physical intimacy pages just like we did for comms. 2
       pages: How it happens - Frequency, Initiating, Adventurousness. What
       makes it work - Comfort & Safety, Communication, What It Is For."

       The page is still built by the renderer below, which draws one aspect.
       It is called once per aspect in the domain rather than once for the
       page, so the three stack: same bars, same prompts, same dropdown, no
       second renderer to keep in step with this one.

       INTIMACY_DOMAINS is the grouping and the tie-break order, shared with
       the app and with the scoring. */
    const domainMatch = INTIMACY_DOMAINS.find(dm => section === `intimacy-${dm.id}`);
    if (domainMatch) {
      return (
        <Layout>
          <ResultsSlide>
            <IntimacyDomainPage
              domain={domainMatch}
              dims={dims}
              positions={positions}
              myAnswers={intimacyAnswers}
              partnerAnswers={partnerIntimacy?.answers}
              userName={userName}
              partnerName={partnerName}
              variant={intimacyVariant}
              onGo={go}
            />
          </ResultsSlide>
        </Layout>
      );
    }

    // ── PER-DIMENSION PAGE (retired ids only; see RETIRED_SECTIONS) ──
    const dimMatch = dimIds.find(id => section === `intimacy-${id}`);
    if (dimMatch) {
      const d = INTIMACY_DIMENSIONS.find(x => x.id === dimMatch);
      const ds = dims.find(x => x.id === dimMatch);
      const st = ds?.state || "incomplete";
      const pos = positions[dimMatch] || {};
      const myPct = pos.mine == null ? null : Math.round(8 + pos.mine * 84);
      const partPct = pos.theirs == null ? null : Math.round(8 + pos.theirs * 84);
      const idx = dimIds.indexOf(dimMatch);
      const nextId = idx < dimIds.length - 1 ? `intimacy-${dimIds[idx + 1]}` : "what-comes-next";
      const prevId = idx > 0 ? `intimacy-${dimIds[idx - 1]}` : "intimacy-overview";
      const skipper = oneSidedSkip(dimMatch);
      const osk = INTIMACY_RESULTS_PROSE[dimMatch]?.oneSkipped;
      // Per-dimension gradient, so each page has its own tone the way the comms
      // dimension pages do (they key off DIM_META.dark).
      // The tints live in api/_lib/intimacy-results.js so the app can paint
      // the same six pages from the same numbers.
      return (
        <Layout accent={ROSE}>
          <ResultsSlide bg={`linear-gradient(145deg, ${groundForDimension(dimMatch).join(", ")})`}>
            <link href={FONT_URL} rel="stylesheet" />
            <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", marginBottom: "0.75rem" }}>
              <div style={{ marginLeft: "auto", fontSize: "0.68rem", color: "rgba(255,255,255,0.3)", fontFamily: BFONT }}>{idx + 1} of {dimIds.length}</div>
            </div>
            <div style={{ fontSize: "clamp(1.5rem,5vw,2rem)", fontWeight: 700, color: "white", lineHeight: 1.1, marginBottom: "0.4rem", fontFamily: HFONT }}>{d.label}</div>
            <p style={{ fontSize: "0.85rem", color: "rgba(255,255,255,0.6)", fontFamily: BFONT, fontWeight: 300, lineHeight: 1.6, marginBottom: "1.25rem" }}>{sub(INTIMACY_RESULTS_PROSE[dimMatch]?.intro)}</p>

            {/* block: intimacy-dimension/state */}
            {/* Track */}
            <div style={{ background: "rgba(255,255,255,0.1)", borderRadius: 14, padding: "1.25rem 1.5rem", marginBottom: "1rem", border: "1px solid rgba(255,255,255,0.16)" }}>
              <div style={{ fontSize: "0.62rem", textTransform: "uppercase", letterSpacing: "0.12em", color: "rgba(255,255,255,0.9)", fontWeight: 700, marginBottom: "0.9rem", fontFamily: BFONT }}>Overall</div>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.1rem" }}>
                <span style={{ fontSize: "0.7rem", fontWeight: 600, color: "rgba(255,255,255,0.85)", fontFamily: BFONT }}>{d.poles?.[0]}</span>
                <span style={{ fontSize: "0.7rem", fontWeight: 600, color: "rgba(255,255,255,0.85)", fontFamily: BFONT }}>{d.poles?.[1]}</span>
              </div>
              <PctTrackViz myPct={myPct} partPct={partPct} userName={userName} partnerName={partnerName} />
            </div>

            {/* block: intimacy-dimension/prompt */}
            {/* Talk about it / one-partner-skipped (the skip variant stays intact) */}
            {skipper && osk ? (
              <div style={{ background: "rgba(255,255,255,0.08)", borderRadius: 14, padding: "1.25rem 1.5rem", border: "1px solid rgba(255,255,255,0.18)" }}>
                <p style={{ fontSize: "0.9rem", color: "rgba(255,255,255,0.8)", lineHeight: 1.75, margin: "0 0 1rem", fontFamily: BFONT, fontWeight: 300 }}>{osk.lead.replace(/\{SKIPPER\}/g, skipper)}</p>
                <div style={{ fontSize: "0.62rem", textTransform: "uppercase", letterSpacing: "0.12em", color: "#E08DA6", fontWeight: 700, marginBottom: "0.5rem", fontFamily: BFONT }}>{TALK_ABOUT_IT}</div>
                <p style={{ fontSize: "0.9rem", color: "white", lineHeight: 1.75, margin: 0, fontFamily: BFONT, fontWeight: 400 }}>{sub(osk.question)}</p>
              </div>
            ) : (
              <div style={{ background: "rgba(255,255,255,0.08)", borderRadius: 14, padding: "1.25rem 1.5rem", border: "1px solid rgba(255,255,255,0.18)" }}>
                <div style={{ fontSize: "0.62rem", textTransform: "uppercase", letterSpacing: "0.12em", color: "#E08DA6", fontWeight: 700, marginBottom: "0.5rem", fontFamily: BFONT }}>{TALK_ABOUT_IT}</div>
                <p style={{ fontSize: "0.9rem", color: "white", lineHeight: 1.75, margin: 0, fontFamily: BFONT, fontWeight: 400 }}>{sub(INTIMACY_RESULTS_PROSE[dimMatch]?.prompt)}</p>
              </div>
            )}

            {/* block: intimacy-dimension/questions */}
            {/* Behind a disclosure, the same as every Communication domain
                page. It used to open expanded, which put the most explicit
                content in the product on screen the moment the page loaded,
                with no step in between. Ellie asked for the dropdown.

                Same markup as the comms one deliberately, so the two read as
                the same control rather than two things that both happen to
                open. */}
            <details style={{ marginTop: "1.5rem", background: "rgba(255,255,255,0.05)", borderRadius: 14, border: "1px solid rgba(255,255,255,0.14)" }}>
              <summary style={{ listStyle: "none", cursor: "pointer", padding: "1.1rem 1.5rem", fontSize: "0.72rem", textTransform: "uppercase", letterSpacing: "0.1em", color: "rgba(255,255,255,0.85)", fontWeight: 700, fontFamily: BFONT, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <span>Side by side {(INTIMACY_DIMENSIONS[idx]?.label || "").toLowerCase()} responses</span>
                <span style={{ fontSize: "0.9rem", opacity: 0.6 }}>▾</span>
              </summary>
              <div style={{ padding: "0.5rem 1.5rem 1.5rem" }}>
                <IntimacyResponseBreakdown dim={dimMatch} myAnswers={intimacyAnswers} partnerAnswers={partnerIntimacy?.answers} userName={userName} partnerName={partnerName} variant={intimacyVariant} />
              </div>
            </details>

            <NavButtons
              onBack={() => go(prevId)}
              onNext={() => go(nextId)}
              nextLabel={(idx < dimIds.length - 1 ? INTIMACY_DIMENSIONS[idx + 1].label : "Conversations Worth Having") + " →"}
            />
          </ResultsSlide>
        </Layout>
      );
    }

    // ── ACTION PLAN ──
    // Conversations Worth Having had a page of its own here. Ellie asked for
    // it to go from both surfaces: its list is the at-a-glance page's action
    // plan, which a reader meets without a detour, and each of the six
    // dimension pages already carries its own question.

    return null;
  }

  // ── PAGE: WHAT COMES NEXT ─────────────────────────────────────────────────────
  // ── HOW YOU FIGHT ─────────────────────────────────────────────────────────
  // Half of this section is private and half is shared, which no other results
  // section is. Your own patterns render the moment you finish; everything
  // needing your partner waits for them.
  if (conflictListed && section.startsWith("conflict-")) {
    // Listed once owned, so the contents link always resolves. Until both
    // partners have finished this exercise the section renders a waiting
    // state rather than nothing, which is what made the link look stale.
    /**
     * Three states, not two.
     *
     * Loading is its own state now. The payload arrives over the network, and
     * treating "not here yet" as "not finished" told someone who had answered
     * everything that they had not, for as long as the request took.
     *
     * Your Patterns opens as soon as YOU have finished, which is what the
     * comment above this block has always said and what the app has always
     * done. The website gated all four pages on both partners, so the one page
     * that is private to you and needs nobody else waited for your partner.
     */
    const conflictLoading = conflictResults == null;
    const conflictYoursReady = !!conflictSelf;
    const needsBoth = section !== 'conflict-patterns';

    if (conflictLoading || !conflictYoursReady || (needsBoth && !conflictBothDone)) {
      const title = conflictLoading ? 'Loading' : 'Not open yet';
      const body = conflictLoading
        ? 'One moment.'
        : !conflictYoursReady
          ? WAITING.LOCKED_BY_YOU
          : WAITING.LOCKED_BY_THEM;
      return (
        <Layout accent="#1B5FE8">
          <div style={{ maxWidth: 560 }}>
            <div style={{ fontSize: "0.62rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "#1B5FE8", fontWeight: 700, fontFamily: BFONT, marginBottom: "0.6rem" }}>Conflict patterns</div>
            <div style={{ fontSize: "clamp(1.4rem,3.5vw,1.85rem)", fontWeight: 700, fontFamily: HFONT, color: C.ink, marginBottom: "0.75rem" }}>{title}</div>
            <p style={{ fontSize: "0.9rem", color: C.muted, fontFamily: BFONT, lineHeight: 1.7, marginBottom: "1.5rem" }}>
              {body}
            </p>
            {/* setView is not in scope here, so this navigates by URL rather
                than referencing a prop this component does not receive. */}
            <button onClick={() => { try { window.location.href = '/app?view=conflict'; } catch {} }}
              style={{ background: "#1B5FE8", color: "white", border: "none", borderRadius: 12, padding: "0.8rem 1.5rem", fontSize: "0.86rem", fontWeight: 700, fontFamily: BFONT, cursor: "pointer", display: (!conflictLoading && !conflictYoursReady) ? "inline-block" : "none" }}>
              Take the exercise
            </button>
          </div>
        </Layout>
      );
    }
    const BLUE = "#1B5FE8";
    const cc = CONFLICT_RESULTS_COPY;
    const interp = (t) => interpConflict(t, { partner: partnerName, a: userName, b: partnerName });

    const Badge = ({ shared }) => (
      <span style={{ fontSize: "0.6rem", fontWeight: 700, fontFamily: BFONT, borderRadius: 99,
        padding: "0.25rem 0.6rem", letterSpacing: "0.04em",
        background: shared ? "#E7F3EC" : "#FBE9F1", color: shared ? "#2E7D5B" : "#B5546E" }}>
        {shared ? cc.sharedBadge : cc.privateBadge}
      </span>
    );

    const Chip = ({ children }) => (
      <span style={{ display: "inline-block", background: "#EEF3FF", border: `1px solid ${BLUE}33`,
        color: BLUE, borderRadius: 99, padding: "0.35rem 0.75rem", fontSize: "0.76rem",
        fontFamily: BFONT, fontWeight: 600, marginRight: "0.4rem", marginBottom: "0.4rem" }}>{children}</span>
    );

    const chipsFor = (ans) => ['c1', 'c2', 'c_topic']
      .map(id => OPENING_CHIPS[id]?.[ans?.[id]])
      .filter(Boolean);

    // The four bars. Colour tracks the band rather than the pattern, so the
    // page reads at a glance without needing to know which is which.
    const PatternRow = ({ p }) => {
      const copy = PATTERN_COPY[p.key];
      const v = p.value ?? 0;
      const pct = (v / 3) * 100;
      const tone = BAND_COLORS[v] || BAND_COLORS[0];
      // Never gets no advice at all. Rarely gets an awareness note. Sometimes
      // and Often get the action. Attaching an instruction to an absent
      // pattern would read as a warning about something that is not happening.
      const advice = v >= 2 ? PATTERN_ACTIONS[p.key] : v === 1 ? PATTERN_NOTES[p.key] : null;
      const adviceLabel = v >= 2 ? 'One thing to try' : 'One thing to keep in mind';
      return (
        <div key={p.key} style={{ padding: "1rem 0", borderTop: `1px solid ${C.stone}` }}>
          <div style={{ fontSize: "0.92rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.15rem" }}>{copy.label}</div>
          <div style={{ fontSize: "0.74rem", color: C.muted, fontFamily: BFONT, marginBottom: "0.5rem" }}>{copy.definition}</div>
          {/* Frequency sits directly above the right edge of the bar, in the
              bar's own colour, so the reading and the measure are one unit. */}
          <div style={{ textAlign: "right", fontSize: "0.68rem", fontWeight: 700, color: tone, fontFamily: BFONT, marginBottom: "0.25rem" }}>
            {FREQUENCY_LABELS[v]}
          </div>
          <div style={{ height: 5, background: C.stone, borderRadius: 99 }}>
            <div style={{ height: "100%", width: `${Math.max(pct, 3)}%`, background: tone, borderRadius: 99 }} />
          </div>
          {advice && (
            <div style={{ marginTop: "0.8rem", background: "#F4F7FF", borderRadius: 8, padding: "0.75rem 0.95rem" }}>
              {/* Physical Intimacy's plan is a detail page, so the label stays.
                  Which of the two it reads depends on the frequency band, and
                  that difference is the point of having it. */}
              <div style={{ fontSize: "0.6rem", letterSpacing: "0.12em", textTransform: "uppercase", color: BLUE, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.35rem" }}>{adviceLabel}</div>
              {v >= 2 && (
                <div style={{ fontSize: "0.84rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.25rem" }}>{advice.title}</div>
              )}
              <p style={{ fontSize: "0.82rem", color: C.ink, fontFamily: BFONT, lineHeight: 1.6, margin: 0 }}>{interp(advice.body)}</p>
            </div>
          )}
        </div>
      );
    };

    const Head = ({ title, shared }) => (
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
        <div style={{ fontSize: "clamp(1.4rem,3.5vw,1.85rem)", fontWeight: 700, fontFamily: HFONT, color: C.ink }}>{title}</div>
        <Badge shared={shared} />
      </div>
    );

    const Card = ({ children }) => (
      <div style={{ background: "white", border: `1.5px solid ${C.stone}`, borderRadius: 16, padding: "1.4rem 1.6rem" }}>{children}</div>
    );

    // ── Snapshot: how each of you opens a disagreement. Shared, and the one
    //    part of this exercise where both answers are equally valid. ──
    if (section === "conflict-snapshot") {
      // Three columns: the question on the left, then each person's answer.
      // With the label above the pair, the eye had to travel down and back up
      // to connect a question to its answers.
      const COLS = isMobile ? "1fr" : "minmax(0,1.3fr) minmax(0,1fr) minmax(0,1fr)";
      return (
        <Layout accent={BLUE}>
          <div style={{ maxWidth: 760 }}>
            {/* block: conflict-snapshot/head */}
            <div style={{ fontSize: "clamp(1.4rem,3.5vw,1.85rem)", fontWeight: 700, fontFamily: HFONT, color: C.ink, marginBottom: "1rem" }}>{cc.snapshotTitle}</div>
            {/* block: conflict-snapshot/openings */}
            <div style={{ fontSize: "0.62rem", letterSpacing: "0.16em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.6rem" }}>Conflict</div>
            <Card>
              <div style={{ display: "grid", gridTemplateColumns: COLS, gap: "0.5rem 1.25rem", marginBottom: "0.5rem" }}>
                <div />
                <div style={{ fontSize: "0.62rem", letterSpacing: "0.14em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: BFONT }}>{userName}</div>
                <div style={{ fontSize: "0.62rem", letterSpacing: "0.14em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: BFONT }}>{partnerName}</div>
              </div>
              {SNAPSHOT_ROWS.map((row, i) => (
                <div key={row.id} style={{ display: "grid", gridTemplateColumns: COLS, gap: "0.4rem 1.25rem", alignItems: "center",
                  paddingTop: "0.9rem", marginTop: i ? "0.9rem" : 0, borderTop: `1px solid ${C.stone}` }}>
                  <div style={{ fontSize: "0.8rem", color: C.muted, fontFamily: BFONT, lineHeight: 1.45 }}>{row.label}</div>
                  {/* Both sides off the summaries, by the field the row
                      carries. These read raw answers by question id, which
                      only ever worked for the reader's own half. */}
                  <div><Chip>{OPENING_CHIPS[row.id]?.[conflictMine?.openings?.[row.field]] || "\u2014"}</Chip></div>
                  <div><Chip>{OPENING_CHIPS[row.id]?.[conflictTheirs?.openings?.[row.field]] || "\u2014"}</Chip></div>
                </div>
              ))}
            </Card>

            {/* What helps you reset, absorbed from its own page. It is short,
                it is about the same shared material, and a page of two lists
                did not earn a nav entry of its own. */}
            <div style={{ marginTop: "1.75rem" }}>
              {/* block: conflict-snapshot/repair */}
              <div style={{ fontSize: "0.62rem", letterSpacing: "0.16em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.6rem" }}>Repair</div>
              <Card>
                <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: "1.75rem" }}>
                  {[[partnerName, userName, conflictMine.repairRanking],
                    [userName, partnerName, conflictPairing.b.repairRanking]].map(([actor, wants, ranking]) => (
                    <div key={wants}>
                      <div style={{ fontSize: "0.62rem", letterSpacing: "0.14em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.7rem", lineHeight: 1.4 }}>
                        What {wants} wants from {actor}, in order
                      </div>
                      {(ranking || []).slice(0, 3).map((r, i) => (
                        <div key={r} style={{ display: "flex", gap: "0.6rem", alignItems: "flex-start", marginBottom: "0.55rem" }}>
                          <span style={{ color: BLUE, fontWeight: 700, fontSize: "0.85rem", fontFamily: BFONT }}>{i + 1}</span>
                          <span style={{ fontSize: "0.86rem", color: C.ink, fontFamily: BFONT, lineHeight: 1.5 }}>{r}</span>
                        </div>
                      ))}
                    </div>
                  ))}
                </div>

                {/* ── WHAT YOU EACH DO ────────────────────────────────────
                    c8, which neither surface has ever shown. It is in the
                    partner allowlist, so both of you agreed to share it by
                    answering it, and it has sat in the payload unread. The
                    rankings above are what each of you wants done; this is
                    what each of you actually does, which is the other half of
                    the same question and belongs beside it.

                    The question's own text is the label. A heading here would
                    be customer copy, which is Ellie's. */}
                {(conflictMine.strength || conflictTheirs?.strength) && (
                  <div style={{ marginTop: "1.5rem", paddingTop: "1.25rem", borderTop: `1px solid ${C.stone}` }}>
                    <div style={{ fontSize: "0.78rem", color: C.muted, fontFamily: BFONT, lineHeight: 1.5, marginBottom: "0.8rem" }}>
                      {RESET_QUESTION}
                    </div>
                    <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: "0.9rem" }}>
                      {[[userName, conflictMine.strength], [partnerName, conflictTheirs?.strength]].map(([nm, v]) => (
                        <div key={nm}>
                          <div style={{ fontSize: "0.62rem", letterSpacing: "0.14em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.35rem" }}>{nm}</div>
                          <Chip>{v || "\u2014"}</Chip>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </Card>
            </div>
          </div>
        </Layout>
      );
    }

    // ── Patterns: private, always. Never rendered for the partner. ──
    if (section === "conflict-patterns") {
      return (
        <Layout accent={BLUE}>
          <div style={{ maxWidth: 660 }}>
            {/* block: conflict-patterns/head */}
            <div style={{ fontSize: "clamp(1.4rem,3.5vw,1.85rem)", fontWeight: 700, fontFamily: HFONT, color: C.ink, marginBottom: "0.5rem" }}>{cc.patternsTitle}</div>
            {/* block: conflict-patterns/privacy */}
            <div style={{ fontSize: "0.8rem", fontWeight: 600, color: "#B5546E", fontFamily: BFONT, lineHeight: 1.5, marginBottom: "0.9rem" }}>
              * {cc.patternsPrivacy}
            </div>
            <Card>
              <p style={{ fontSize: "0.86rem", color: C.muted, fontFamily: BFONT, lineHeight: 1.65, marginTop: 0, marginBottom: "0.6rem" }}>{cc.patternsIntro}</p>
              {/* block: conflict-patterns/rows */}
              {conflictMine.ranked.map(p => <PatternRow key={p.key} p={p} />)}
              {conflictMine.flaggedCount === 0 && (
                <p style={{ fontSize: "0.86rem", color: C.ink, fontFamily: BFONT, lineHeight: 1.7, marginTop: "1.1rem", marginBottom: 0, fontWeight: 600 }}>
                  {interp(cc.allClear)}
                </p>
              )}
            </Card>
          </div>
        </Layout>
      );
    }

    // ── What you each wrote ──────────────────────────────────────────────
    // Grouped by question with the two answers side by side, so the pair can
    // be read against each other. A vertical list of four quotes made the
    // reader hold one answer in their head while scrolling to its counterpart.
    if (section === "conflict-wrote") {
      // WROTE_ROWS, not a copy of them. These two headings were typed here and
      // the app had its own shorter pair, so the same two answers sat under
      // different headings on the two products.
      const QUESTIONS = WROTE_ROWS;
      const quoteCard = (name, text) => (
        <div style={{ background: "#FDF6EC", border: "1px solid #EBD9BE", borderRadius: 12, padding: "1rem 1.2rem" }}>
          <div style={{ fontSize: "0.6rem", letterSpacing: "0.14em", textTransform: "uppercase", color: "#9A6B2F", fontWeight: 700, fontFamily: BFONT, marginBottom: "0.5rem" }}>{name}</div>
          <p style={{ fontSize: "0.88rem", color: C.ink, fontFamily: BFONT, fontStyle: text ? "italic" : "normal", lineHeight: 1.7, margin: 0 }}>
            {text ? `"${text}"` : "No answer given."}
          </p>
        </div>
      );
      return (
        <Layout accent={BLUE}>
          <div style={{ maxWidth: 720 }}>
            {/* block: conflict-wrote/head */}
            <Head title={cc.wroteTitle} shared={true} />
            {/* block: conflict-wrote/rows */}
            {QUESTIONS.map((q, i) => (
              <div key={q.key} style={{ marginBottom: i < QUESTIONS.length - 1 ? "2rem" : 0 }}>
                <div style={{ fontSize: "0.62rem", letterSpacing: "0.14em", textTransform: "uppercase", color: C.muted, fontWeight: 700, fontFamily: BFONT, marginBottom: "0.7rem" }}>{q.label}</div>
                <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: "0.9rem" }}>
                  {quoteCard(userName, conflictMine[q.key])}
                  {quoteCard(partnerName, conflictPairing.b[q.key])}
                </div>
              </div>
            ))}
          </div>
        </Layout>
      );
    }

    // ── Results at a glance ──────────────────────────────────────────────
    // Coloured ground, matching the reflection glance page. Q1 is the
    // high-level read: each partner's own sense of how conflict goes, which is
    // the only shared, non-private number this exercise produces.
    const flagged = conflictMine.ranked.filter(p => (p.value ?? 0) >= 2);
    // The c0 question's own options, not a second copy of them. Typed out
    // here, this was five strings the app could not read, which is why its
    // Conflict at a glance had no chart: there was nothing to label the bars.
    const C0_LABELS = (CONFLICT_QUESTIONS.find(q => q.id === 'c0')?.options || []).map(o => o.label);
    const myC0 = conflictMine.overall ?? 2;
    const theirC0 = conflictPairing?.b?.overall ?? 2;
    const c0Aligned = Math.abs(myC0 - theirC0) <= 1;

    return (
      <Layout accent={BLUE}>
        <ResultsSlide bg={gradientCss("conflict-overview")}>
          <link href={FONT_URL} rel="stylesheet" />
          <div style={{ color: "white" }}>
            <div style={{ fontSize: "clamp(1.8rem,6vw,2.8rem)", fontWeight: 700, fontFamily: HFONT, lineHeight: 1.05, marginBottom: "0.6rem" }}>{SC_TITLES["conflict-overview"]}</div>
            {/* Q1, the one shared number this exercise produces. Everything
                else on the risk side is private to each reader. */}
            {/* block: conflict-overview/overall */}
            <div style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: 14, padding: "1.1rem 1.25rem", marginBottom: "1.25rem" }}>
              {/* Ellie: this page "needs some color in the content, can the
                  bars be colored and can the section labels be colored?" Both
                  labels were white at a third opacity. */}
              <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: CONFLICT_GLANCE_LABEL, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.8rem" }}>How you each describe conflict resolution in your relationship</div>
              {[[userName, myC0], [partnerName, theirC0]].map(([nm, v]) => (
                <div key={nm} style={{ marginBottom: "0.7rem" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: "0.3rem" }}>
                    <span style={{ fontSize: "0.78rem", color: "white", fontFamily: BFONT, fontWeight: 600 }}>{nm}</span>
                    <span style={{ fontSize: "0.76rem", color: "rgba(255,255,255,0.8)", fontFamily: BFONT }}>{C0_LABELS[v]}</span>
                  </div>
                  <div style={{ height: 6, background: "rgba(255,255,255,0.14)", borderRadius: 99 }}>
                    <div style={{ height: "100%", width: `${((v + 1) / 5) * 100}%`, background: conflictOverallColor(v), borderRadius: 99 }} />
                  </div>
                </div>
              ))}
            </div>

            {/* block: conflict-overview/action-plan */}
            {/* The heading, and the note that this list is nobody else's.
                Level with the heading and out at the right margin, which is
                where an aside belongs: it qualifies the heading without
                interrupting it. This page is read together and the plan on it
                is built from patterns only the reader can see. */}
            <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: "1rem", marginBottom: "0.7rem" }}>
              <div style={{ fontSize: "0.55rem", letterSpacing: "0.18em", textTransform: "uppercase", color: CONFLICT_GLANCE_LABEL, fontFamily: BFONT, fontWeight: 700 }}>Your action plan</div>
              <div style={{ fontSize: "0.7rem", fontWeight: 600, color: "#FF8A7A", fontFamily: BFONT, flexShrink: 0 }}>{CONFLICT_RESULTS_COPY.glancePrivate}</div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: "0.7rem" }}>
              {flagged.length > 0 ? flagged.map(p => (
                <div key={p.key} style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.14)", borderRadius: 14, padding: "1rem 1.2rem" }}>
                  {/* No eyebrow. On Results at a glance the cards ARE the
                      actions, three of them in a row under a heading that
                      already says so, and a label over each one repeated the
                      heading three times. It stays on the Patterns detail
                      page, where a card sits alone under its own bar. */}
                  <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "baseline", marginBottom: "0.35rem", gap: "0.75rem" }}>
                    <span style={{ fontSize: "0.62rem", color: "rgba(255,255,255,0.55)", fontFamily: BFONT, flexShrink: 0 }}>{PATTERN_COPY[p.key].label}</span>
                  </div>
                  <div style={{ fontSize: "0.88rem", fontWeight: 700, color: "white", fontFamily: BFONT, marginBottom: "0.25rem" }}>{PATTERN_ACTIONS[p.key]?.title}</div>
                  <p style={{ fontSize: "0.82rem", color: "rgba(255,255,255,0.85)", fontFamily: BFONT, lineHeight: 1.65, margin: 0 }}>{interp(PATTERN_ACTIONS[p.key]?.body)}</p>
                </div>
              )) : (
                <div style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.14)", borderRadius: 14, padding: "1rem 1.2rem" }}>
                  <div style={{ fontSize: "0.88rem", fontWeight: 700, color: "white", fontFamily: BFONT, marginBottom: "0.25rem" }}>{NO_ACTION_NEEDED.title}</div>
                  <p style={{ fontSize: "0.82rem", color: "rgba(255,255,255,0.85)", fontFamily: BFONT, lineHeight: 1.65, margin: 0 }}>{interp(NO_ACTION_NEEDED.body)}</p>
                </div>
              )}
            </div>
          </div>
        </ResultsSlide>
      </Layout>
    );


  }

  if (section === "what-comes-next") {
    const NavActionLink = ({ onClick, bg, border, icon, title, sub, accentColor }) => {
      const iconSvgs = {
        "💬": <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/><line x1="8" y1="9" x2="16" y2="9"/><line x1="8" y1="13" x2="13" y2="13"/></svg>,
        "comm": <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/><line x1="8" y1="9" x2="16" y2="9"/><line x1="8" y1="13" x2="13" y2="13"/></svg>,
        "📋": <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round"><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><line x1="9" y1="12" x2="15" y2="12"/><line x1="9" y1="16" x2="13" y2="16"/></svg>,
        "💚": <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>,
        "✅": <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round"><polyline points="20 6 9 17 4 12"/></svg>,
        "💰": <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>,
        "🧠": <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={accentColor} strokeWidth="2" strokeLinecap="round"><path d="M9.5 2A2.5 2.5 0 0 1 12 4.5v15a2.5 2.5 0 0 1-4.96-.46 2.5 2.5 0 0 1-1.04-4.69A2.5 2.5 0 0 1 5 12a2.5 2.5 0 0 1 2-2.45V4.5A2.5 2.5 0 0 1 9.5 2z"/><path d="M14.5 2A2.5 2.5 0 0 0 12 4.5v15a2.5 2.5 0 0 0 4.96-.46 2.5 2.5 0 0 0 1.04-4.69A2.5 2.5 0 0 0 19 12a2.5 2.5 0 0 0-2-2.45V4.5A2.5 2.5 0 0 0 14.5 2z"/></svg>,
      };
      return (
      <button onClick={onClick}
        style={{ display: "flex", alignItems: "center", gap: "1rem", background: bg, border, borderRadius: 14, padding: "1rem 1.25rem", cursor: "pointer", textAlign: "left", width: "100%" }}>
        <div style={{ width: 36, height: 36, borderRadius: 10, background: accentColor + "22", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          {iconSvgs[icon] || <div style={{ width: 10, height: 10, borderRadius: "50%", background: accentColor }} />}
        </div>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: "0.85rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.1rem" }}>{title}</div>
          <div style={{ fontSize: "0.72rem", color: C.muted, fontFamily: BFONT }}>{sub}</div>
        </div>
        <span style={{ color: accentColor, fontSize: "1rem", flexShrink: 0 }}>→</span>
      </button>
      );
    };
    return (
      <Layout accent="#E8673A">
        <div style={{ maxWidth: 560, margin: "0 auto" }}>
          <h2 style={{ fontFamily: HFONT, fontSize: "clamp(1.8rem,3vw,2.4rem)", fontWeight: 700, color: C.ink, lineHeight: 1.1, letterSpacing: "-0.02em", marginBottom: "1.5rem" }}>What comes next</h2>

          {/* ── ACTION ITEMS — one dropdown per exercise the couple has ── */}
          {(() => {
            /**
             * ── ONE PAGE, BUILT ONCE ──────────────────────────────────────
             * This used to assemble its own six groups from its own
             * client-side results, beside api/_lib/what-comes-next.js doing
             * the same job for the app. Two implementations of one page, and
             * they had drifted in six ways that Ellie found by reading them
             * side by side: different wording on the expectations rows, a
             * different name for Physical Intimacy, a different rule choosing
             * the conflict items, conflict nested inside the intimacy branch,
             * the reflection rows written two ways, and the comms rows titled
             * with advice rather than with the page they came from.
             *
             * So it calls the same function the app is served. What stays here
             * is the adapter: this surface computes its results in the browser
             * and has to shape them into what that function takes.
             */
            const wcn = whatComesNext({
              coupleTypeId: coupleType?.id || null,
              commsPlan: {
                tiles: commsActionPlan({
                  feedback: personalityFeedback,
                  copy: _content,
                }),
                protocols: buildCommsProtocols(byDim, userName, partnerName),
              },
              expectations: (() => {
                const counts = {};
                allRows.filter(r => r.bothAnswered && !r.aligned)
                  .forEach(r => { counts[r.category] = (counts[r.category] || 0) + 1; });
                return {
                  categories: FIXED_CATS.map(c => ({
                    label: c.label,
                    section: c.section,
                    differences: counts[c.label] || 0,
                  })),
                };
              })(),
              intimacy: (intimacyBothDone && intimacySummary)
                ? { actionPlan: intimacyActionPlan(intimacySummary.dimSummary || []) }
                : null,
              reflection: (hasAnniversary && ex3Answers && partnerEx3)
                ? { written: [{ key: "a6", you: ex3Answers.a6 || "", them: partnerEx3.a6 || "" }] }
                : null,
              conflictReady: !!conflictMine,
              conflictAnswers,
              names: { you: userName, them: partnerName },
              /* Who holds which role, so a tip names the person rather than the
                 archetype. The same pair the server builds from its stored
                 axes; here they are the two typed profiles this page already
                 has. */
              sides: {
                you: { name: userName, pronouns: userPronouns, axes: { open: myS?.openScore, withdraw: myS?.withdrawScore } },
                them: { name: partnerName, pronouns: partnerPronouns, axes: { open: partS?.openScore, withdraw: partS?.withdrawScore } },
              },
            });
            /* The renderer below has always spoken of tip and phrase. The
               payload says title and say, which is what the app reads, so the
               names are mapped here rather than changed on the payload and
               broken for the app. */
            const groups = (wcn.groups || []).map(g => ({
              id: g.id,
              label: g.label,
              color: g.color || "#E8673A",
              section: g.section,
              items: (g.items || []).map(it => ({
                tip: it.title,
                quote: it.quote || null,
                phrase: it.say || it.body || "",
                section: it.section || null,
              })),
            }));

            if (!groups.length) return null;
            return (
              <div style={{ marginBottom: "1.75rem" }}>
                <p style={{ fontSize: "0.8rem", color: C.muted, fontFamily: BFONT, fontWeight: 300, lineHeight: 1.6, margin: "0 0 0.85rem" }}>
                  Each part of your results ends in something to do. They are gathered here, grouped by where they came from. Open one to see its items and the words to start with.
                </p>
                <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                  {/* block: what-comes-next/groups */}
                  {/* ── ONE OPEN AT A TIME ────────────────────────────────
                      Ellie: "on both app and site, clicking on a new section in
                      'what comes next' should close the other dropdown."

                      `name` on a <details> is what the browser already has for
                      this: elements sharing a name behave as one accordion. No
                      state, no handler, and it keeps working if someone opens
                      one with a keyboard. */}
                  {groups.map(g => (
                    <details key={g.id} name="what-comes-next" style={{ background: "white", border: `1.5px solid ${C.stone}`, borderLeft: `4px solid ${g.color}`, borderRadius: 14, overflow: "hidden" }}>
                      <summary style={{ listStyle: "none", cursor: "pointer", padding: "0.85rem 1.1rem", display: "flex", alignItems: "center", justifyContent: "space-between", gap: "0.75rem" }}>
                        <span style={{ fontSize: "0.82rem", fontWeight: 700, color: C.ink, fontFamily: BFONT }}>{g.label}</span>
                        <span style={{ display: "flex", alignItems: "center", gap: "0.5rem", flexShrink: 0 }}>
                          <span style={{ fontSize: "0.68rem", color: C.muted, fontFamily: BFONT }}>{g.items.length} item{g.items.length !== 1 ? "s" : ""}</span>
                          <span style={{ fontSize: "0.62rem", color: g.color, fontFamily: BFONT, fontWeight: 700 }}>Show</span>
                          <span style={{ fontSize: "0.8rem", color: g.color, lineHeight: 1 }}>▾</span>
                        </span>
                      </summary>
                      <div style={{ borderTop: `1px solid ${C.stone}` }}>
                        {/* ── A ROW WITH ITS OWN PAGE CARRIES ITS OWN ARROW ──
                            Ellie: "each row should have a little arrow on the
                            right side of the row to open that page directly."
                            The app draws the same arrow from the same field. */}
                        {g.items.map((it, i) => (
                          <div key={i} style={{ display: "flex", alignItems: "center", gap: "0.6rem", padding: "0.85rem 1.1rem", borderBottom: i < g.items.length - 1 ? `1px solid ${C.stone}` : "none" }}>
                            <div style={{ flex: 1, minWidth: 0 }}>
                              <div style={{ fontSize: "0.82rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: 0, lineHeight: 1.4 }}>
                                {it.tip}
                                {/* Their own words, in the same sentence as the
                                    name, set apart so it reads as a quotation.
                                    The app draws these two rows the same way. */}
                                {it.quote ? (
                                  <span style={{ fontWeight: 400, fontStyle: "italic" }}>{` \u201C${it.quote}\u201D`}</span>
                                ) : null}
                              </div>
                              {/* ── THE TRY LINE IS GONE ──────────────────
                                  Ellie, having asked for it twice and then read
                                  it on the page: "Remove the try lines, sorry."

                                  A row is its heading and the arrow to the page
                                  it came from. That page is where the advice
                                  lives and always was; this line was the
                                  summary repeating it, and for the comms rows
                                  it was the only place in the app some of those
                                  sentences appeared at all, which is the thing
                                  this page is not supposed to do.

                                  `say` stays on the payload: check-plans-agree
                                  compares it to prove a row came from its own
                                  section's plan rather than a second list, and
                                  the moment it is not sent nothing can tell
                                  those two apart again. */}
                            </div>
                            {it.section ? (
                              <button
                                onClick={() => go(it.section)}
                                aria-label={`Open ${it.tip}`}
                                title={it.tip}
                                style={{ background: "transparent", border: "none", cursor: "pointer", color: g.color, fontSize: "1.1rem", lineHeight: 1, padding: "0.2rem 0.3rem", flexShrink: 0 }}>
                                {"\u203A"}
                              </button>
                            ) : null}
                          </div>
                        ))}
                      </div>
                    </details>
                  ))}
                </div>

                {/* Download — one plain-text file with every item above. */}
                <button onClick={() => {
                  const out = ["ATTUNE ACTION PLAN", "=".repeat(40), `${userName} & ${partnerName}`, ""];
                  groups.forEach(g => {
                    out.push(g.label.toUpperCase());
                    g.items.forEach(it => { out.push("- " + it.tip); if (it.phrase) out.push('  Try: "' + it.phrase + '"'); });
                    out.push("");
                  });
                  const blob = new Blob([out.join("\n")], { type: "text/plain" });
                  const el = document.createElement("a");
                  el.href = URL.createObjectURL(blob);
                  el.download = "Attune_Action_Plan.txt";
                  el.click();
                }} style={{ display: "inline-flex", alignItems: "center", gap: "0.45rem", background: "white", border: `1.5px solid ${C.stone}`, color: C.ink, borderRadius: 10, padding: "0.6rem 1.1rem", fontSize: "0.75rem", fontWeight: 600, fontFamily: BFONT, cursor: "pointer", marginTop: "0.85rem" }}>
                  ↓ Download action plan
                </button>
              </div>
            );
          })()}

          {/* ── KEEP GROWING (workbook tile + in-practice list) ── */}
          <div style={{ fontSize: "0.62rem", letterSpacing: "0.22em", textTransform: "uppercase", color: C.clay, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.85rem" }}>Keep growing</div>

          {/* ── WORKBOOK CTA ── */}
          {/* Gated on hasWorkbook (i.e. user purchased the workbook addon).
              The workbook is a paid product. Without this gate, every user
              with results sees the download button and can fetch the
              workbook from /api/generate-workbook for free, which bypasses
              the paywall entirely. */}
          {hasWorkbook && (() => {
            // Build the payload from this couple's actual data
            /**
             * The workbook, which is a PDF.
             *
             * Ellie: "I want customers to be able to download the pdf. Remove the word
             * file." This was 115 lines that tried a stored link, then a .docx from
             * /api/generate-workbook, then html2pdf in a hidden iframe, then the .docx
             * again, under a button reading "Download (.docx)". None of those is the
             * workbook: the workbook is what the PDF service renders, and the dashboard
             * has always asked for that one. Two download paths producing two different
             * documents is the failure this codebase is organised against.
             *
             * src/workbook-download.js is the one path now, and both callers use it.
             */
            const buildAndDownload = async () => {
              const payload = buildWorkbookPayload(
                userName, partnerName,
                ex1Answers, partnerEx1,
                ex2Answers, partnerEx2,
                coupleType
              );
              const stored = (() => {
                try { return JSON.parse(localStorage.getItem('attune_order') || 'null')?.workbookUrl || null; }
                catch { return null; }
              })();
              const got = await getWorkbookUrl({
                storedUrl: stored,
                body: payload,
                /* Only when there is actually something to wait for. Her words, from the
                   module that already says this on both surfaces. */
                onBuilding: () => toast(WORKBOOK_COPY.generating),
              });
              if (got.error) { toast(got.error); return; }
              saveWorkbook(got.url, userName, partnerName);
            };

            return (
              // 10.1 — owned workbook reads as one of the "keep growing" tools,
              // not as a navy add-on pitch.
              <div style={{ background: C.warm, border: `1.5px solid ${C.stone}`, borderRadius: 16, padding: "1.25rem 1.4rem", marginBottom: "1.25rem", transition: "all 0.15s" }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = C.clay; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = C.stone; }}>
                <div style={{ display: "flex", alignItems: "center", gap: "1rem", marginBottom: "0.85rem" }}>
                  <div style={{ width: 34, height: 34, borderRadius: 10, background: "rgba(155,93,229,0.12)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#9B5DE5" strokeWidth="1.8" strokeLinecap="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: "0.8rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.1rem" }}>Your personalized workbook</div>
                    <div style={{ fontSize: "0.68rem", color: C.muted, fontFamily: BFONT }}>Exercises, prompts, and a discussion guide built from your answers</div>
                  </div>
                </div>
                <div style={{ display: "flex", gap: "0.65rem", flexWrap: "wrap", alignItems: "center" }}>
                  <button onClick={buildAndDownload}
                    style={{ display: "inline-flex", alignItems: "center", gap: "0.5rem", background: "#9B5DE5", color: "white", borderRadius: 10, padding: "0.6rem 1.25rem", border: "none", cursor: "pointer", fontSize: "0.78rem", fontWeight: 700, fontFamily: BFONT }}>
                    ↓ Download workbook
                  </button>
                  <a href="/offerings#pkg-workbook" onClick={(e) => { if (onNavigateTool) { e.preventDefault(); onNavigateTool("workbook-upsell"); } }} style={{ display: "inline-flex", alignItems: "center", gap: "0.5rem", background: "white", border: `1.5px solid ${C.stone}`, color: C.ink, borderRadius: 10, padding: "0.6rem 1.15rem", textDecoration: "none", fontSize: "0.78rem", fontWeight: 600, fontFamily: BFONT }}>
                    Order a bound copy →
                  </a>
                  {/* Ellie: "Remove the word file." It said "Opens in Word, Google
                      Docs, or Pages", which was true of the document this button
                      used to fetch and is not true of a workbook. */}
                  <span style={{ fontSize: "0.66rem", color: C.muted, fontFamily: BFONT }}>A PDF, built from your answers</span>
                </div>
              </div>
            );
          })()}

          {/* ── KEEP GROWING: in-practice list (workbook covered by CTA above) ── */}
          <div style={{ marginTop: "0.5rem", marginBottom: "0.5rem" }}>
            <div style={{ display: "flex", flexDirection: "column", gap: "0.5rem" }}>


              {/* Relationship Reflection */}
              {/* Relationship Reflection — only shown as an add-on prompt when not owned (10.2) */}
              {!hasAnniversary && (
                <a href="/offerings" style={{ display: "flex", alignItems: "center", gap: "1rem", background: C.warm, border: `1.5px solid ${C.stone}`, borderRadius: 14, padding: "0.85rem 1.1rem", textDecoration: "none", transition: "all 0.15s" }}
                  onClick={(e) => { e.preventDefault(); onNavigateTool && onNavigateTool('reflection-upsell'); }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = "#10b981"; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = C.stone; }}>
                  <div style={{ width: 34, height: 34, borderRadius: 10, background: "rgba(16,185,129,0.08)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#10b981" strokeWidth="1.8" strokeLinecap="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: "0.8rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.1rem" }}>Relationship Reflection <span style={{ fontSize: "0.62rem", fontWeight: 600, color: "#10b981", background: "rgba(16,185,129,0.1)", borderRadius: 999, padding: "0.1rem 0.5rem", marginLeft: "0.35rem" }}>Add-on</span></div>
                    <div style={{ fontSize: "0.68rem", color: C.muted, fontFamily: BFONT }}>A third exercise about the moments that shaped you</div>
                  </div>
                  <div style={{ color: "#10b981", fontSize: "1.3rem", fontWeight: 700, lineHeight: 1 }}>+</div>
                </a>
              )}
              {/* Physical Intimacy Expectations — add-on prompt when not owned (10.2) */}
              {!hasIntimacy && (
                <a href="/offerings" style={{ display: "flex", alignItems: "center", gap: "1rem", background: C.warm, border: `1.5px solid ${C.stone}`, borderRadius: 14, padding: "0.85rem 1.1rem", textDecoration: "none", transition: "all 0.15s" }}
                  onClick={(e) => { e.preventDefault(); onNavigateTool && onNavigateTool('intimacy-upsell'); }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = "#B5546E"; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = C.stone; }}>
                  <div style={{ width: 34, height: 34, borderRadius: 10, background: "rgba(181,84,110,0.08)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <svg width="15" height="16" viewBox="0 0 24 26" fill="none" stroke="#B5546E" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M7 11 V8 a5 5 0 0 1 10 0 V11"/><rect x="4" y="11" width="16" height="12" rx="3"/></svg>
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: "0.8rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.1rem" }}>Physical Intimacy Expectations <span style={{ fontSize: "0.62rem", fontWeight: 600, color: "#B5546E", background: "rgba(181,84,110,0.1)", borderRadius: 999, padding: "0.1rem 0.5rem", marginLeft: "0.35rem" }}>Add-on</span></div>
                    <div style={{ fontSize: "0.68rem", color: C.muted, fontFamily: BFONT }}>Answered independently, compared side by side</div>
                  </div>
                  <div style={{ color: "#B5546E", fontSize: "1.3rem", fontWeight: 700, lineHeight: 1 }}>+</div>
                </a>
              )}

              {/* Merging Lives Checklist */}
              {/* Keep growing lists what they do NOT have. The owned branch
                  used to render here too, so a reader who already had the tool
                  saw it under a heading that frames everything below it as
                  something to grow into. Owned tools live on the dashboard. */}
              {!hasChecklist && (
                <a href="/offerings" style={{ display: "flex", alignItems: "center", gap: "1rem", background: C.warm, border: `1.5px solid ${C.stone}`, borderRadius: 14, padding: "0.85rem 1.1rem", textDecoration: "none", transition: "all 0.15s" }}
                  onClick={(e) => { e.preventDefault(); onNavigateTool && onNavigateTool('checklist-upsell'); }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = C.clay; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = C.stone; }}>
                  <div style={{ width: 34, height: 34, borderRadius: 10, background: "rgba(193,127,71,0.08)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={C.clay} strokeWidth="1.8" strokeLinecap="round"><polyline points="20 6 9 17 4 12"/></svg>
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: "0.8rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.1rem" }}>Newlywed Checklist <span style={{ fontSize: "0.62rem", fontWeight: 600, color: C.clay, background: "rgba(193,127,71,0.1)", borderRadius: 999, padding: "0.1rem 0.5rem", marginLeft: "0.35rem" }}>Add-on</span></div>
                    <div style={{ fontSize: "0.68rem", color: C.muted, fontFamily: BFONT }}>A practical guide to starting your life together</div>
                  </div>
                  <div style={{ color: C.muted, fontSize: "0.9rem" }}>→</div>
                </a>
              )}

              {/* Shared Budgeting */}
              {/* Keep growing lists what they do NOT have. The owned branch
                  used to render here too, so a reader who already had the tool
                  saw it under a heading that frames everything below it as
                  something to grow into. Owned tools live on the dashboard. */}
              {!hasBudget && (
                <a href="/offerings" style={{ display: "flex", alignItems: "center", gap: "1rem", background: C.warm, border: `1.5px solid ${C.stone}`, borderRadius: 14, padding: "0.85rem 1.1rem", textDecoration: "none", transition: "all 0.15s" }}
                  onClick={(e) => { e.preventDefault(); onNavigateTool && onNavigateTool('budget-upsell'); }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = "#1B5FE8"; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = C.stone; }}>
                  <div style={{ width: 34, height: 34, borderRadius: 10, background: "rgba(27,95,232,0.08)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#1B5FE8" strokeWidth="1.8" strokeLinecap="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: "0.8rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.1rem" }}>Shared Budgeting Activity <span style={{ fontSize: "0.62rem", fontWeight: 600, color: "#1B5FE8", background: "rgba(27,95,232,0.1)", borderRadius: 999, padding: "0.1rem 0.5rem", marginLeft: "0.35rem" }}>Add-on</span></div>
                    <div style={{ fontSize: "0.68rem", color: C.muted, fontFamily: BFONT }}>Build a shared financial picture from your expectations</div>
                  </div>
                  <div style={{ color: C.muted, fontSize: "0.9rem" }}>→</div>
                </a>
              )}

              {/* In Practice resource library */}
              <a href="/practice?from=app" style={{ display: "flex", alignItems: "center", gap: "1rem", background: C.warm, border: `1.5px solid ${C.stone}`, borderRadius: 14, padding: "0.85rem 1.1rem", textDecoration: "none", transition: "all 0.15s" }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = C.clay; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = C.stone; }}>
                <div style={{ width: 34, height: 34, borderRadius: 10, background: "rgba(193,127,71,0.1)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={C.clay} strokeWidth="1.8" strokeLinecap="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/></svg>
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: "0.8rem", fontWeight: 700, color: C.ink, fontFamily: BFONT, marginBottom: "0.1rem" }}>Resource Library</div>
                  <div style={{ fontSize: "0.68rem", color: C.muted, fontFamily: BFONT }}>Guides on communication, conflict, and growing together</div>
                </div>
                <div style={{ color: C.muted, fontSize: "0.9rem" }}>→</div>
              </a>

            </div>
          </div>




          {/* ── CONTINUE LIVING ATTUNED ── */}
          <div style={{ fontSize: "0.62rem", letterSpacing: "0.22em", textTransform: "uppercase", color: C.clay, fontFamily: BFONT, fontWeight: 700, marginTop: "2rem", marginBottom: "0.85rem" }}>Continue living attuned</div>
          <div style={{ background: C.warm, border: `1.5px solid ${C.stone}`, borderRadius: 16, padding: "1.4rem 1.6rem", marginBottom: "1.5rem" }}>
            <div style={{ fontSize: "0.62rem", letterSpacing: "0.2em", textTransform: "uppercase", color: C.clay, fontFamily: BFONT, fontWeight: 700, marginBottom: "0.6rem" }}>Stay connected to your results</div>
            {stayDone ? (
              <div style={{ display: "flex", alignItems: "center", gap: "0.65rem" }}>
                <div style={{ width: 28, height: 28, borderRadius: "50%", background: "#ECFDF5", border: "1.5px solid rgba(16,185,129,0.3)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: "0.75rem" }}>✓</div>
                <p style={{ fontSize: "0.82rem", color: C.muted, fontFamily: BFONT, margin: 0, lineHeight: 1.55 }}>Done. We'll check in at 6 months with an option to retake and compare.</p>
              </div>
            ) : (
              <>
                <p style={{ fontSize: "0.85rem", color: C.muted, fontFamily: BFONT, fontWeight: 300, lineHeight: 1.72, marginBottom: "1rem" }}>
                  We'll check in at 6 months with an option to retake and compare. Results shift more than most couples expect.
                </p>
                <div style={{ display: "flex", gap: "0.65rem", alignItems: "center", flexWrap: "wrap" }}>
                  <input type="email" placeholder="your@email.com" value={stayEmail} onChange={e => setStayEmail(e.target.value)}
                    style={{ flex: 1, minWidth: 180, border: `1.5px solid ${C.stone}`, borderRadius: 10, padding: "0.6rem 0.9rem", fontSize: "0.82rem", fontFamily: BFONT, outline: "none", background: "white", color: C.ink }} />
                  <button disabled={stayLoading} onClick={handleStaySubmit}
                    style={{ background: C.ink, color: "white", border: "none", borderRadius: 10, padding: "0.6rem 1.2rem", fontSize: "0.78rem", fontWeight: 700, cursor: "pointer", fontFamily: BFONT, whiteSpace: "nowrap", opacity: stayLoading ? 0.6 : 1 }}>
                    {stayLoading ? "…" : "Stay in touch"}
                  </button>
                </div>
              </>
            )}
          </div>


          <div style={{ display: "flex", justifyContent: "flex-end", marginTop: "2.5rem", paddingTop: "1.5rem", borderTop: `1px solid ${C.stone}` }}>
            <button onClick={() => onNavigateTool && onNavigateTool("home")} style={{ background: "#2d2250", border: "none", borderRadius: 10, padding: "0.7rem 1.5rem", fontSize: "0.78rem", color: "white", cursor: "pointer", fontFamily: BFONT, fontWeight: 700, letterSpacing: ".02em" }}>
              Back to dashboard →
            </button>
          </div>
          {showSurvey && <BetaSurveyModal userName={userName} coupleType={coupleType} onClose={() => setShowSurvey(false)} />}

          {/* The end of the whole experience is where to ask how it went. */}
          <ExperienceFeedback userName={userName} />

          {/* Back out of the last page. Everything before this has a Back;
              without one here the final page of the whole experience could
              only be left through the sidebar. */}
          {curIdx > 0 && (
            <div style={{ marginTop: "2.5rem", paddingTop: "1.5rem", borderTop: `1px solid ${C.stone}` }}>
              <button onClick={() => go(allPages[curIdx - 1])}
                style={{ background: "transparent", border: `1.5px solid ${C.stone}`, borderRadius: 10, padding: "0.6rem 1.2rem", fontSize: "0.8rem", fontWeight: 600, color: C.ink, fontFamily: BFONT, cursor: "pointer" }}>
                ← {getPageLabel(allPages[curIdx - 1])}
              </button>
            </div>
          )}
        </div>
      </Layout>
    );
  }

  return null;
}

// Thin wrappers so PersonalityResults/ExpectationsResults can be driven externally
function PersonalityResultsPage({ myAnswers, partnerAnswers, userName, partnerName, coupleType, userPronouns = "", partnerPronouns = "", forcedStep, orderedDims: extDims, onStepChange, onGoExpectations, onGoBack, onNavigateTool, hasWorkbook = false }) {
  const go = s => { if (onStepChange) onStepChange(s); };
  return <PersonalityResults myAnswers={myAnswers} partnerAnswers={partnerAnswers} userName={userName} partnerName={partnerName} coupleType={coupleType} userPronouns={userPronouns} partnerPronouns={partnerPronouns} externalStep={forcedStep ?? 0} onExternalGo={go} noSideNav={true} onGoExpectations={onGoExpectations} onGoBack={onGoBack} onNavigateTool={onNavigateTool} hasWorkbook={hasWorkbook} />;
}
function ExpectationsResultsPage({ myAnswers, partnerAnswers, userName, partnerName, forcedSection, onGoWhatComesNext, onGoBack, onExternalGo, coupleTypeCode = null, coupleTypeName = null, coupleTypeColor = "#1B5FE8" }) {
  return <ExpectationsResults myAnswers={myAnswers} partnerAnswers={partnerAnswers} userName={userName} partnerName={partnerName} forcedSection={forcedSection} noSideNav={true} onGoWhatComesNext={onGoWhatComesNext} onGoBack={onGoBack} onExternalGo={onExternalGo} coupleTypeCode={coupleTypeCode} coupleTypeName={coupleTypeName} coupleTypeColor={coupleTypeColor} />;
}
// ─────────────────────────────────────────────────────────────────────────────


// ─────────────────────────────────────────────────────────────────────────────
// RESULTS HIGHLIGHTS - swipe-through before full results
// ─────────────────────────────────────────────────────────────────────────────

const CARD_W = 390;
const CARD_H = 720;

function downloadCard(cardRef, filename) {
  // Load html2canvas dynamically from CDN
  if (window._h2c) {
    window._h2c(cardRef, { scale: 2, useCORS: true, logging: false, width: CARD_W, height: CARD_H })
      .then(canvas => {
        const link = document.createElement("a");
        link.download = filename;
        link.href = canvas.toDataURL("image/png");
        link.click();
      }).catch(() => toast("Screenshot not available in this browser. Try long-pressing the card to save."));
    return;
  }
  const script = document.createElement("script");
  script.src = "https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js";
  script.onload = () => {
    window._h2c = window.html2canvas;
    downloadCard(cardRef, filename);
  };
  script.onerror = () => toast("Download not available. Take a screenshot instead.");
  document.head.appendChild(script);
}

// Shareable couple-type card, storycard dimensions, built for stories.
function CoupleTypeShareCard({ ct, userName, partnerName, tagline }) {
  const color = ct?.color || "#E8673A";
  return (
    // Solid base under the gradient: the mid stop is translucent, and without an
    // opaque layer beneath it the exported PNG washes out.
    <div style={{ width: CARD_W, height: CARD_H, background: "#120d2e", position: "relative", overflow: "hidden", display: "flex", flexDirection: "column", boxSizing: "border-box", containerType: "inline-size" }}>
      <div style={{ position: "absolute", inset: 0, background: `linear-gradient(160deg, #120d2e 0%, ${color}55 45%, #120d2e 100%)`, pointerEvents: "none" }} />
      <div style={{ height: 5, background: `linear-gradient(90deg, #E8673A, ${color}, #1B5FE8)`, flexShrink: 0, position: "relative" }} />
      {/* Oversized ghost word, same treatment as the type reveal tile */}
      <div style={{ position: "absolute", bottom: 78, right: -18, fontFamily: HFONT, fontSize: "5.5rem", fontWeight: 700, color: "rgba(255,255,255,0.07)", lineHeight: 1, letterSpacing: "-0.04em", whiteSpace: "nowrap", pointerEvents: "none" }}>
        {(ct?.name || "").replace("The ", "")}
      </div>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", padding: "2.5rem 2.25rem", position: "relative" }}>
        <div style={{ fontSize: "0.55rem", letterSpacing: "0.28em", textTransform: "uppercase", color: "rgba(255,255,255,0.6)", fontFamily: BFONT, fontWeight: 700, marginBottom: "0.6rem" }}>
          {userName} &amp; {partnerName}
        </div>
        <div style={{ fontSize: "0.6rem", letterSpacing: "0.22em", textTransform: "uppercase", color: "rgba(255,255,255,0.45)", fontFamily: BFONT, fontWeight: 700, marginBottom: "1.1rem" }}>
          Our couple type
        </div>
        <div style={{ fontFamily: HFONT, fontSize: "2.9rem", fontWeight: 700, color: "white", lineHeight: 0.98, letterSpacing: "-0.03em", marginBottom: "1.1rem" }}>
          {ct?.name}
        </div>
        <div style={{ width: 52, height: 3, background: color, borderRadius: 2, marginBottom: "1.1rem" }} />
        <p style={{ fontSize: "1rem", color: "rgba(255,255,255,0.88)", fontFamily: BFONT, fontWeight: 400, lineHeight: 1.5, margin: 0 }}>
          {tagline}
        </p>
      </div>
      <div style={{ flexShrink: 0, padding: "0 2.25rem 2rem", position: "relative" }}>
        <div style={{ height: 1, background: "rgba(255,255,255,0.15)", marginBottom: "1rem" }} />
        <div style={{ fontSize: "0.72rem", color: "rgba(255,255,255,0.75)", fontFamily: BFONT, fontWeight: 600, letterSpacing: "0.04em" }}>
          Find yours at attune-relationships.com
        </div>
      </div>
    </div>
  );
}

// Individual card wrapper with download affordance
function WrappedCard({ children, bg, onDownload, cardIndex, cardRef, inline, portraitCorner, isMobile = false }) {
  return (
    <div style={{ position: "relative", userSelect: "none", width: inline ? "100%" : isMobile ? "min(390px, calc(100vw - 1rem))" : CARD_W }}>
      <div ref={cardRef}
        style={{ width: inline ? "100%" : isMobile ? "min(390px, calc(100vw - 1rem))" : CARD_W, height: inline ? "min(72vw, 560px)" : isMobile ? "min(660px, calc(100vh - 130px))" : `min(${CARD_H}px, calc(100vh - 150px))`, background: bg || "#2d2250", borderRadius: 20, overflow: "hidden", position: "relative", flexShrink: 0, display: "flex", flexDirection: "column",
          /* The card is the container its text is sized against. Ellie's call:
             a storycard should look the same on a laptop, on a phone and in the
             downloaded image, and the app has always sized against the card
             because it has no window to measure. cqw in the shared scale reads
             this. */
          containerType: "inline-size" }}>
        {/* Attune watermark */}
        <div style={{ position: "absolute", bottom: 16, left: 20, display: "flex", alignItems: "center", gap: 6, opacity: 0.45 }}>
          <AttuneMark width={22} />
          <span style={{ ...scType("wordmark") }}>Attune</span>
        </div>
        {/* Portrait corner bubble */}
        {portraitCorner && (
          <div style={{ position: "absolute", bottom: 14, right: 14, width: 38, height: 38, borderRadius: "50%", overflow: "hidden", boxShadow: "0 2px 10px rgba(0,0,0,0.4)", background: "#1C1430" }}>
            {mkCouple(portraitCorner.p1, portraitCorner.p2, true, `wc-${cardIndex}`)}
          </div>
        )}
        {children}
      </div>
      {/* Download button below card */}
      <button onClick={onDownload}
        style={{ position: "absolute", bottom: -44, right: 0, background: "transparent", border: "1px solid rgba(255,255,255,0.2)", color: "rgba(255,255,255,0.78)", borderRadius: 8, padding: "0.35rem 0.75rem", fontSize: "0.62rem", letterSpacing: "0.1em", textTransform: "uppercase", cursor: "pointer", fontFamily: BFONT, transition: "all 0.15s" }}
        onMouseEnter={e => { e.currentTarget.style.borderColor = "rgba(255,255,255,0.78)"; e.currentTarget.style.color = "white"; }}
        onMouseLeave={e => { e.currentTarget.style.borderColor = "rgba(255,255,255,0.78)"; e.currentTarget.style.color = "rgba(255,255,255,0.78)"; }}>
        ↓ Download
      </button>
    </div>
  );
}

function ResultsHighlights({ ex1Answers, partnerEx1, ex2Answers, partnerEx2, ex3Answers, partnerEx3, userName, partnerName, userPronouns = "", partnerPronouns = "", portrait, onDone, onExit = null, inline = false, intimacyAnswers = null, partnerIntimacy = null, intimacyVariant = "premarital" }) {
  const [cardIdx, setCardIdx] = useState(0);
  const cardRef = useRef(null);
  const isMobile = useMobile(640);

  const myS = calcDimScores(ex1Answers);
  const partS = calcDimScores(partnerEx1);
  // Share-card couple type uses the blend; the gap feedback below stays self.
  const myB = typingDimScores(ex1Answers, partnerEx1);
  const partB = typingDimScores(partnerEx1, ex1Answers);
  // Copy for this couple: the version stamped on their results row.
  const _content = useContent();
  const feedback = generatePersonalityFeedback(myS, partS, userName, partnerName, _content);
  const sortedFeedback = [...feedback].sort((a, b) => a.gap - b.gap);
  const topStrength = sortedFeedback[0];
  const topGap = [...feedback].sort((a, b) => b.gap - a.gap)[0];
  const avgGap = feedback.reduce((s, f) => s + f.gap, 0) / feedback.length;
  const pairing = overallPairingLabel(avgGap);

  // Intimacy highlight: only when the couple owns the add-on and both finished.
  const intimacyShow = !!(intimacyAnswers && partnerIntimacy?.answers);
  const intimacySum = intimacyShow ? summarizeIntimacy(intimacyAnswers, partnerIntimacy.answers) : null;
  const intimacyTopAligned = intimacySum ? [...intimacySum.dimSummary].filter(d => d.state === "aligned").sort((a, b) => (a.avgGap ?? 1) - (b.avgGap ?? 1))[0] : null;
  const intimacyTopGap = intimacySum ? [...intimacySum.dimSummary].filter(d => d.avgGap != null).sort((a, b) => (b.avgGap ?? 0) - (a.avgGap ?? 0))[0] : null;
  const intimacyHighlight = intimacyTopAligned || intimacyTopGap;

  const allRows = RESPONSIBILITY_CATEGORIES.flatMap(cat =>
    cat.items.map(item => {
      const key = cat.id + "__" + item;
      const rawMine = ex2Answers?.responsibilities?.[key];
      const rawTheirs = partnerEx2?.responsibilities?.[mirrorRespKey(key)];
      if (!rawMine || !rawTheirs) return null;
      const mine = normRespValue(rawMine, true, userName, partnerName);
      const theirs = normRespValue(rawTheirs, false, userName, partnerName);
      return { item: substName(item, userName, partnerName), category: cat.label, mine, theirs, aligned: mine === theirs };
    }).filter(Boolean)
  );
  const lifeRows = LIFE_QUESTIONS.map(q => ({
    item: substName(q.text, userName, partnerName), category: q.category,
    mine: ex2Answers?.life?.[q.id], theirs: partnerEx2?.life?.[mirrorLifeId(q.id)],
    aligned: ex2Answers?.life?.[q.id] === partnerEx2?.life?.[mirrorLifeId(q.id)],
  })).filter(r => r.mine && r.theirs);
  const allExpRows = [...allRows, ...lifeRows];
  const alignedCount = allExpRows.filter(r => r.aligned).length;
  // Headline expectations alignment: similarity-based overall (mean of 6
  // domain pcts). Matches the workbook Snapshot overall row.
  const alignPct = computeOverallExpectationsPctClient(ex2Answers, partnerEx2, userName, partnerName);

  const coupleType = deriveCoupleTypeFromExercise(
    myB, partB, alignPct
  );

  const myStress = myS.stress || 3;
  const theirStress = partS.stress || 3;
  const mySeeks = myStress > 3.5;
  const theySeeks = theirStress > 3.5;
  const myWithdraws = myStress < 2.5;
  const theyWithdraws = theirStress < 2.5;
  const stressMismatch = (mySeeks && theyWithdraws) || (myWithdraws && theySeeks);

  const topConvo = sortedFeedback.filter(f => f.gap > 1.5).slice(0, 1)[0];
  const convoPrompt = topConvo ? {
    energy: "When one of us needs time alone and the other wants to connect, how do we handle that?",
    expression: "Is there something you've been sitting with that you haven't found the right moment to bring up?",
    needs: "What's something you need from me that you usually don't ask for directly?",
    bids: "What's something small I do that makes you feel noticed?",
    conflict: "After a disagreement, what does 'okay again' actually feel like for you?",
    repair: "What do you need from me in the hours after a hard conversation?",
    listening: "When you bring something to me, do you want me to listen, or do you want me to respond and ask questions?",
    love: "What's something I do that makes you feel genuinely loved?",
    feedback: "Is there something I do that bothers you that you haven't found the right way to bring up?",
  }[topConvo.dim] : "What do you each need that you haven't fully said out loud yet?";

  const strengthMeta = DIM_META[topStrength?.dim];
  const gapMeta = DIM_META[topGap?.dim];

  // ── Storycard highlight helpers ──────────────────────────────────────────
  const uPos = pronoun(userPronouns, "pos");
  const pPos = pronoun(partnerPronouns, "pos");
  // From api/_lib/comm-alignment.js, which the app's cards read too. This was
  // the same arithmetic written here by hand, with one difference that
  // mattered: `f.gap ?? 0` counted a dimension with no gap as perfectly
  // aligned, so an unanswered dimension quietly raised the figure.
  const commAlignPct = commAlignmentPct(feedback.map(f => f.gap));
  const lifeAlignPct = lifeRows.length ? Math.round(lifeRows.filter(r => r.aligned).length / lifeRows.length * 100) : 0;
  const respAlignPct = allRows.length ? Math.round(allRows.filter(r => r.aligned).length / allRows.length * 100) : 0;
  const intimacyAlignPct = (intimacySum && intimacySum.dimSummary && intimacySum.dimSummary.length)
    ? Math.round(intimacySum.dimSummary.filter(d => d.state === "aligned").length / intimacySum.dimSummary.length * 100) : null;
  // A five-dimension spread for the comms peek (most aligned -> most divergent).
  const commPeekDims = (() => { const n = sortedFeedback.length; if (n <= 5) return sortedFeedback; return [0, Math.round(n*0.25), Math.round(n*0.5), Math.round(n*0.72), n-1].map(i => sortedFeedback[i]); })();
  const Donut = ({ pct, color, label }) => {
    const r = 40, CC = 2 * Math.PI * r, dash = Math.max(0, Math.min(100, pct)) / 100 * CC;
    return (
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "0.7rem" }}>
        <div style={{ position: "relative", width: 100, height: 100 }}>
          <svg width="100" height="100" viewBox="0 0 100 100">
            <circle cx="50" cy="50" r={r} fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth="10" />
            <circle cx="50" cy="50" r={r} fill="none" stroke={color} strokeWidth="10" strokeLinecap="round" strokeDasharray={`${dash} ${CC}`} transform="rotate(-90 50 50)" />
          </svg>
          <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", paddingBottom: "5px", fontSize: "1.4rem", fontWeight: 700, color: "white", fontFamily: HFONT }}>{pct}%</div>
        </div>
        <div style={{ fontSize: "0.66rem", color: "rgba(255,255,255,0.62)", fontFamily: BFONT, textAlign: "center", lineHeight: 1.3, maxWidth: 120, letterSpacing: "0.03em" }}>{label}</div>
      </div>
    );
  };

  // Shared watermark style
  const watermark = (
    <div style={{ ...scType("siteLabel"), position: "absolute", bottom: 16, right: 18 }}>
      {/* block: highlights/watermark */}
      {SC_SITE}
    </div>
  );
  const watermarkDark = (
    <div style={{ ...scType("siteLabel"), color: "rgba(14,11,7,0.3)", position: "absolute", bottom: 16, right: 18 }}>
      {SC_SITE}
    </div>
  );

  const TOTAL_CARDS = 7 + ((ex3Answers && partnerEx3) ? 1 : 0) + (intimacyHighlight ? 1 : 0);
  const isLast = cardIdx === TOTAL_CARDS - 1;
  const handleDl = () => {
    if (cardRef.current) downloadCard(cardRef.current, "attune-" + userName.toLowerCase() + "-" + partnerName.toLowerCase() + "-" + (cardIdx + 1) + ".png");
  };
  const advance = () => { if (!isLast) setCardIdx(n => n + 1); else onDone(); };

  // Reflection data (if available)
  const hasReflData = !!(ex3Answers && partnerEx3);
  const reflOverallQ = ANNIVERSARY_QUESTIONS.find(q => q.id === "a0");
  const reflMyOverall = ex3Answers?.a0 ?? 3;
  const reflTheirOverall = partnerEx3?.a0 ?? 3;
  const reflAvgOverall = (reflMyOverall + reflTheirOverall) / 2;
  const reflOverallLabel = reflOverallQ ? reflOverallQ.scaleLabels[Math.round(reflAvgOverall)] : "really good";
  const reflOverallAligned = Math.abs(reflMyOverall - reflTheirOverall) <= 1;
  const reflMyAdmire = ex3Answers?.a8;
  const reflTheirAdmire = partnerEx3?.a8;
  const reflMyPriority = Array.isArray(ex3Answers?.a_priority) ? ex3Answers.a_priority[0] : null;
  const reflTheirPriority = Array.isArray(partnerEx3?.a_priority) ? partnerEx3.a_priority[0] : null;

  // Card dimensions — portrait ratio ideal for stories (9:16)
  const CARD_ASPECT = inline ? "min(72vw, 500px)" : CARD_H + "px";

  // ── Shared entrance animation ──────────────────────────────────────────────
  const cardAnim = `
    @keyframes cardReveal { from { opacity:0; transform:translateY(18px) scale(0.97); } to { opacity:1; transform:translateY(0) scale(1); } }
    @keyframes fadeUp { from { opacity:0; transform:translateY(12px); } to { opacity:1; transform:translateY(0); } }
    @keyframes popIn { from { opacity:0; transform:scale(0.88); } to { opacity:1; transform:scale(1); } }
    @keyframes slideRight { from { opacity:0; transform:translateX(-16px); } to { opacity:1; transform:translateX(0); } }
    @keyframes numCount { from { opacity:0; transform:scale(0.7); } to { opacity:1; transform:scale(1); } }
  `;

  // ── Shared dimension slider (aligned + diverge cards) ─────────────────────
  // Dots carry each partner's first initial. The name key underneath only
  // appears when both first initials match (the letters resolve it otherwise),
  // and it is ordered to match the chart: whoever sits further left is listed
  // first. Dots only shift vertically when they actually overlap.
  const sameInitial = (userName?.[0] || "").toUpperCase() === (partnerName?.[0] || "").toUpperCase();
  const DimSlider = ({ dim, meta }) => {
    // The scale's top and the two overlap numbers all come from
    // api/_lib/track-marks.js, so this card places a mark the way every other
    // chart in the product does and the way the app's copy of this card does.
    // It was 5, 6 and 10 written here, against the app's own three numbers.
    const myPct = Math.round(((myS[dim] || 3) / TM_CARD_MAX) * 100);
    const theirPct = Math.round(((partS[dim] || 3) / TM_CARD_MAX) * 100);
    const overlap = Math.abs(myPct - theirPct) < TM_CLOSE;
    const myIsLeft = myPct <= theirPct;
    const myDy = overlap ? (myIsLeft ? -TM_STAGGER : TM_STAGGER) : 0;
    const theirDy = overlap ? (myIsLeft ? TM_STAGGER : -TM_STAGGER) : 0;
    const legend = myIsLeft
      ? [{ name: userName, color: SC_PEOPLE.you }, { name: partnerName, color: SC_PEOPLE.them }]
      : [{ name: partnerName, color: SC_PEOPLE.them }, { name: userName, color: SC_PEOPLE.you }];
    return (
      <div style={{ marginBottom: "1.5rem", animation: "fadeUp 0.4s 0.24s both" }}>
        {/* Poles either side of the bar and centred on it, matching the
            orientation tiles. They were above the bar and at 45% opacity,
            which made them hard to read on the card's ground. */}
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          <span style={{ fontSize: "0.68rem", color: "rgba(255,255,255,0.78)", fontFamily: BFONT, lineHeight: 1.3, flexShrink: 0, width: "clamp(56px,19%,96px)", textAlign: "right" }}>{meta?.ends?.[0]}</span>
          <div style={{ flex: 1, minWidth: 0, padding: "0 11px" }}>
        <div style={{ height: 6, background: "rgba(255,255,255,0.12)", borderRadius: 3, position: "relative", overflow: "visible" }}>
          <div title={userName} style={{ position: "absolute", top: "50%", left: myPct + "%", transform: `translate(-50%, calc(-50% + ${myDy}px))`, width: 22, height: 22, borderRadius: "50%", background: "#E8673A", border: "2.5px solid white", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "0.5rem", color: "white", fontWeight: 700, fontFamily: BFONT, zIndex: 2 }}>{sameInitial ? "" : userName[0]}</div>
          <div title={partnerName} style={{ position: "absolute", top: "50%", left: theirPct + "%", transform: `translate(-50%, calc(-50% + ${theirDy}px))`, width: 22, height: 22, borderRadius: "50%", background: "#1B5FE8", border: "2.5px solid white", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "0.5rem", color: "white", fontWeight: 700, fontFamily: BFONT, zIndex: 2 }}>{sameInitial ? "" : partnerName[0]}</div>
        </div>
          </div>
          <span style={{ fontSize: "0.68rem", color: "rgba(255,255,255,0.78)", fontFamily: BFONT, lineHeight: 1.3, flexShrink: 0, width: "clamp(56px,19%,96px)" }}>{meta?.ends?.[1]}</span>
        </div>
        {sameInitial && (
          <div style={{ display: "flex", justifyContent: "center", gap: "1rem", marginTop: "1rem" }}>
            {legend.map(k => (
              <div key={k.name} style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}>
                <div style={{ width: 8, height: 8, borderRadius: "50%", background: k.color, flexShrink: 0 }} />
                <span style={{ fontSize: "0.62rem", color: "rgba(255,255,255,0.55)", fontFamily: BFONT, maxWidth: 110, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{k.name}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  const cards = [
    // ── 1. OPENER ──────────────────────────────────────────────────────────────
    <WrappedCard key={0} bg="linear-gradient(145deg, #0e0b1e 0%, #1a1040 50%, #0e0b1e 100%)" onDownload={handleDl} cardIndex={0} cardRef={cardRef} inline={inline} isMobile={isMobile}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden" }}>
        {watermark}
        {/* block: highlights/stripe */}
        <div style={{ height: 5, background: `linear-gradient(90deg, ${SC_STRIPE.join(", ")})`, flexShrink: 0 }} />
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "2.5rem 2.5rem 2rem", textAlign: "center", animation: "cardReveal 0.5s cubic-bezier(0.22,1,0.36,1) both" }}>
          {portrait && (
            <div style={{ width: 80, height: 80, borderRadius: "50%", overflow: "hidden", marginBottom: "1.5rem", border: "2px solid rgba(255,255,255,0.15)", boxShadow: "0 8px 32px rgba(0,0,0,0.4)", animation: "popIn 0.5s 0.1s cubic-bezier(0.34,1.56,0.64,1) both" }}>
              {mkCouple(portrait.p1, portrait.p2, true, "card0")}
            </div>
          )}
          <div style={{ ...scType("eyebrow"), marginBottom: "1.25rem", animation: "fadeUp 0.4s 0.15s both" }}>Your results</div>
          <div style={{ ...scType("names"), marginBottom: "1.5rem", animation: "fadeUp 0.5s 0.2s cubic-bezier(0.22,1,0.36,1) both" }}>
            {userName}<br/><span style={{ ...scType("amp") }}>&amp;</span><br/>{partnerName}
          </div>
          <div style={{ width: 40, height: 2, background: "linear-gradient(90deg, #E8673A, #1B5FE8)", borderRadius: 2, marginBottom: "1.5rem", animation: "popIn 0.4s 0.35s both" }} />
          <p style={{ ...scType("body"), maxWidth: 300, margin: 0, whiteSpace: "pre-line", animation: "fadeUp 0.4s 0.4s both" }}>
            {OPENER_BODY}
          </p>
        </div>
        <div style={{ ...scType("footer"), textAlign: "center", padding: "0 0 1.75rem", animation: "fadeUp 0.4s 0.55s both" }}>Tap to begin</div>
      </div>
    </WrappedCard>,

    // ── 2. COUPLE TYPE + MAP — "Your unique relationship environment" ─────────
    <WrappedCard key={1} bg={`linear-gradient(145deg, ${coupleType?.color || "#E8673A"}cc 0%, ${coupleType?.color || "#E8673A"}66 55%, #14102e 100%)`} onDownload={handleDl} cardIndex={1} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden" }}>
        {watermark}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "1.5rem 1.75rem 3.5rem", textAlign: "center" }}>
          <div style={{ ...scType("titleSm"), marginBottom: "0.7rem", maxWidth: 320, animation: "fadeUp 0.5s 0.1s both" }}>Your unique relationship environment</div>
          <div style={{ animation: "popIn 0.5s 0.25s cubic-bezier(0.34,1.56,0.64,1) both", marginBottom: "0.6rem", width: Math.round(SC_REF_WIDTH * SC_MAP_PCT) + 26, maxWidth: "92%" }}>
            {/* One size for both surfaces, from api/_lib/storycard-style.js.
                It was 184 here and 168 in the app. */}
            <CoupleMapSVG myS={myB} partS={partB} userName={userName} partnerName={partnerName} size={Math.round(SC_REF_WIDTH * SC_MAP_PCT)} hideCaption axisLabelColor="rgba(255,255,255,0.62)" />
          </div>
          <div style={{ ...scType("lead"), marginBottom: "0.55rem", animation: "fadeUp 0.4s 0.4s both" }}>Your couple type: <span style={{ fontWeight: 700, color: "white" }}>{coupleType?.name || "The orbit"}</span></div>
          <p style={{ ...scType("bodySm"), maxWidth: 258, margin: 0, animation: "fadeUp 0.4s 0.5s both" }}>Explore your full results to learn what this looks like for the two of you.</p>
        </div>
      </div>
    </WrappedCard>,

    // ── 3. HOW YOU COMMUNICATE — overview sliders, plainly introduced ─────────
    <WrappedCard key={2} bg="linear-gradient(145deg, #0a1226 0%, #16233f 55%, #0a1226 100%)" onDownload={handleDl} cardIndex={2} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden" }}>
        {watermark}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", padding: "2.5rem 2.25rem 2rem" }}>
          <div style={{ ...scType("title"), marginBottom: "1.7rem", animation: "fadeUp 0.5s 0.08s both" }}>How you each show up in the relationship</div>
          {commPeekDims.filter(Boolean).map(f => <DimSlider key={f.dim} dim={f.dim} meta={DIM_META[f.dim]} />)}
        </div>
      </div>
    </WrappedCard>,

    // ── 4. IN TUNE / DIVERGE — two call-outs + a comms alignment % ────────────
    <WrappedCard key={3} bg="linear-gradient(145deg, #07130f 0%, #0e2a1d 50%, #07130f 100%)" onDownload={handleDl} cardIndex={3} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden" }}>
        {watermark}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", padding: "3rem 2.25rem 2.5rem" }}>
          <div style={{ textAlign: "center", marginBottom: "2.25rem" }}>
            <div style={{ ...scType("leadLg"), marginBottom: "0.45rem", animation: "fadeUp 0.4s 0.05s both" }}>{userName} and {partnerName}'s communication styles are</div>
            <div style={{ ...scType("stat"), animation: "numCount 0.6s 0.12s cubic-bezier(0.34,1.56,0.64,1) both" }}>{commAlignPct}%</div>
            <div style={{ ...scType("statLabel"), marginTop: "0.25rem", animation: "fadeUp 0.4s 0.22s both" }}>aligned</div>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: "0.9rem", marginBottom: "1.75rem" }}>
            <div style={{ background: SC_CALLOUT.tune.tint, border: `1px solid ${SC_CALLOUT.tune.border}`, borderRadius: 12, padding: "0.9rem 1.1rem", animation: "slideRight 0.4s 0.25s both" }}>
              <div style={{ ...scType("calloutLabel"), color: SC_CALLOUT.tune.color, marginBottom: "0.3rem" }}>Where you're most in tune</div>
              <div style={{ ...scType("calloutValue") }}>{strengthMeta?.label || "Emotional Expression"}</div>
            </div>
            <div style={{ background: SC_CALLOUT.diverge.tint, border: `1px solid ${SC_CALLOUT.diverge.border}`, borderRadius: 12, padding: "0.9rem 1.1rem", animation: "slideRight 0.4s 0.34s both" }}>
              <div style={{ ...scType("calloutLabel"), color: SC_CALLOUT.diverge.color, marginBottom: "0.3rem" }}>Where you diverge most</div>
              <div style={{ ...scType("calloutValue") }}>{gapMeta?.label || "Conflict Style"}</div>
            </div>
          </div>
          <p style={{ ...scType("bodySm", { alpha: 0.5 }), margin: 0, animation: "fadeUp 0.4s 0.42s both" }}>Explore your results to see what each of these means, with guidance built for the two of you.</p>
        </div>
      </div>
    </WrappedCard>,

    // ── 5. EXPECTATIONS — overall % + life-values and responsibilities donuts ─
    <WrappedCard key={4} bg="linear-gradient(145deg, #060d1a 0%, #0d2545 50%, #060d1a 100%)" onDownload={handleDl} cardIndex={4} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden", alignItems: "center", justifyContent: "center", padding: "2.75rem 2.25rem 2.75rem", textAlign: "center" }}>
        {watermark}
        <div style={{ ...scType("eyebrowMd"), marginBottom: "0.9rem", animation: "fadeUp 0.4s 0.05s both" }}>Expectations</div>
        <div style={{ ...scType("statBig"), color: scStatColor(alignPct), marginBottom: "0.3rem", animation: "numCount 0.6s 0.1s cubic-bezier(0.34,1.56,0.64,1) both" }}>{alignPct}%</div>
        <div style={{ ...scType("statLabelSm"), marginBottom: "2.25rem", animation: "fadeUp 0.4s 0.25s both" }}>aligned overall</div>
        <div style={{ display: "flex", gap: "2.5rem", justifyContent: "center", animation: "fadeUp 0.4s 0.35s both" }}>
          <Donut pct={lifeAlignPct} color={SC_RING.life} label="Life & values" />
          <Donut pct={respAlignPct} color={SC_RING.responsibilities} label="Responsibilities" />
        </div>
      </div>
    </WrappedCard>,

    // ── 6. RELATIONSHIP REFLECTION (conditional) ──────────────────────────────
    ...(hasReflData ? [

    <WrappedCard key={5} bg="linear-gradient(145deg, #0f0c29 0%, #241a5e 50%, #0f0c29 100%)" onDownload={handleDl} cardIndex={5} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden", justifyContent: "center", padding: "2.75rem 2.25rem 2.75rem" }}>
        {watermark}
        <div style={{ ...scType("titleMd"), marginBottom: "1.75rem", animation: "fadeUp 0.5s 0.1s both" }}>What you admire in each other</div>
        <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
          {[[userName, uPos, reflTheirAdmire, "#E8673A", "0.24s"], [partnerName, pPos, reflMyAdmire, "#5B6DF8", "0.34s"]].map(([nm, pos, admire, col, delay]) => (
            <div key={nm} style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.12)", borderRadius: 16, padding: "1.25rem 1.35rem", animation: "fadeUp 0.5s " + delay + " both" }}>
              <div style={{ ...scType("caption"), marginBottom: "0.4rem" }}>{nm} is most admired for {pos}</div>
              <div style={{ ...scType("titleMd", { lh: 1.1 }), color: col }}>{admiredNounLower(admire)}</div>
            </div>
          ))}
        </div>
      </div>
    </WrappedCard>
    
    ] : []),

    // ── INTIMACY HIGHLIGHT — one card when the add-on is owned + both done ──────
    ...(intimacyHighlight ? [

    <WrappedCard key="intimacy-card" bg="linear-gradient(145deg, #2a0f1a 0%, #4a1c30 50%, #2a0f1a 100%)" onDownload={handleDl} cardIndex={99} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden", alignItems: "center", justifyContent: "center", padding: "2.75rem 2.5rem", textAlign: "center" }}>
        {watermark}
        <svg width="58" height="70" viewBox="0 0 58 70" style={{ marginBottom: "1.75rem", animation: "popIn 0.5s 0.1s cubic-bezier(0.34,1.56,0.64,1) both" }}>
          <path d="M15 29 V19 a14 14 0 0 1 28 0 V29" fill="none" stroke="#E08DA6" strokeWidth="5" strokeLinecap="round" />
          <rect x="7" y="29" width="44" height="35" rx="9" fill="#E08DA6" />
          <circle cx="29" cy="44" r="5.5" fill="#2a0f1a" />
          <rect x="26.5" y="46" width="5" height="11" rx="2.5" fill="#2a0f1a" />
        </svg>
        <div style={{ ...scType("eyebrowTint"), color: "rgba(224,141,166,0.85)", marginBottom: "0.9rem", animation: "fadeUp 0.4s 0.15s both" }}>Physical Intimacy</div>
        {intimacyAlignPct != null && (<div style={{ ...scType("statMid"), color: "#E08DA6", marginBottom: "0.7rem", animation: "numCount 0.6s 0.2s cubic-bezier(0.34,1.56,0.64,1) both" }}>{intimacyAlignPct}%</div>)}
        <div style={{ ...scType("statLabelSm"), marginBottom: "1.5rem", animation: "fadeUp 0.4s 0.3s both" }}>aligned</div>
        <p style={{ ...scType("bodyMd", { alpha: 0.58 }), maxWidth: 280, margin: 0, animation: "fadeUp 0.4s 0.38s both" }}>Explore what you each expect out of this part of your relationship.</p>
      </div>
    </WrappedCard>
    
    ] : []),

    // ── 8. ONE CONVERSATION — tailored-guidance framing ──────────────────────
    <WrappedCard key={hasReflData ? 6 : 5} bg="linear-gradient(145deg, #120d2e 0%, #2a1a5e 50%, #120d2e 100%)" onDownload={handleDl} cardIndex={hasReflData ? 6 : 5} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div onClick={advance} style={{ flex: 1, display: "flex", flexDirection: "column", cursor: "pointer", position: "relative", overflow: "hidden", justifyContent: "center", alignItems: "center", padding: "2.5rem 2.25rem", textAlign: "center" }}>
        {watermark}
        <p style={{ ...scType("bodyMd"), maxWidth: 300, margin: "0 auto 1.75rem", animation: "fadeUp 0.4s 0.05s both" }}>As you explore your results, you'll learn more about your unique dynamic and unlock guidance tailored to the two of you.</p>
        <div style={{ ...scType("listLabel"), marginBottom: "1rem", animation: "fadeUp 0.4s 0.12s both" }}>One conversation worth having for {userName} &amp; {partnerName}</div>
        <div style={{ background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.22)", borderRadius: 20, padding: "1.75rem 1.6rem", maxWidth: 320, width: "100%", boxSizing: "border-box", margin: "0 auto", animation: "popIn 0.55s 0.2s cubic-bezier(0.34,1.56,0.64,1) both", boxShadow: "0 8px 40px rgba(0,0,0,0.3)" }}>
          <p style={{ ...scType("quote"), fontStyle: "italic", margin: 0 }}>{convoPrompt}</p>
        </div>
      </div>
    </WrappedCard>,

    // ── 9. SENDOFF — celebratory entry into the full results ──────────────────
    <WrappedCard key={hasReflData ? 7 : 6} bg="linear-gradient(145deg, #0e0b1e 0%, #1a1040 50%, #0e0b1e 100%)" onDownload={handleDl} cardIndex={hasReflData ? 7 : 6} cardRef={cardRef} inline={inline} isMobile={isMobile} portraitCorner={portrait}>
      <style>{cardAnim}</style>
      <div style={{ flex: 1, display: "flex", flexDirection: "column", position: "relative", overflow: "hidden" }}>
        {watermark}
        <div style={{ height: 5, background: `linear-gradient(90deg, ${SC_STRIPE.join(", ")})`, flexShrink: 0 }} />
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "2.5rem 2.5rem", textAlign: "center", animation: "cardReveal 0.5s cubic-bezier(0.22,1,0.36,1) both" }}>
          <div style={{ width: 44, height: 2, background: "linear-gradient(90deg, #E8673A, #1B5FE8)", borderRadius: 2, marginBottom: "1.75rem", animation: "popIn 0.4s 0.1s both" }} />
          <div style={{ ...scType("titleLg"), marginBottom: "1rem", maxWidth: 320, animation: "fadeUp 0.5s 0.15s both" }}>We hope you continue to grow together throughout your Attune experience.</div>
          <p style={{ ...scType("bodyLg"), maxWidth: 280, margin: "0 0 2.25rem", animation: "fadeUp 0.4s 0.25s both" }}>Your full results are ready whenever you are.</p>
          <button onClick={onDone} style={{ ...scType("cta"), background: "linear-gradient(135deg, #E8673A, #1B5FE8)", border: "none", borderRadius: 14, padding: "1rem 2.25rem", cursor: "pointer", marginBottom: "0.85rem", width: "100%", maxWidth: 300, animation: "popIn 0.5s 0.32s cubic-bezier(0.34,1.56,0.64,1) both" }}>Explore your full results →</button>
          <button onClick={handleDl} style={{ ...scType("ctaAlt"), background: "rgba(255,255,255,0.07)", border: "1px solid rgba(255,255,255,0.15)", borderRadius: 14, padding: "0.85rem 2.25rem", cursor: "pointer", width: "100%", maxWidth: 300, animation: "popIn 0.5s 0.4s cubic-bezier(0.34,1.56,0.64,1) both" }}>Download this preview ↓</button>
        </div>
      </div>
    </WrappedCard>,
  ];
  const content = (
    <>
      <link href={FONT_URL} rel="stylesheet" />
      {!inline && <div style={{ height: 52, background: "rgba(20,16,40,0.97)", borderBottom: "1px solid rgba(255,255,255,0.07)", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 1.5rem", flexShrink: 0 }}>
        <button onClick={() => { if (typeof setView === 'function') setView('home'); else window.history.back(); }} style={{ background: "transparent", border: "none", color: "rgba(255,255,255,0.45)", fontSize: "0.7rem", letterSpacing: "0.08em", cursor: "pointer", fontFamily: BFONT, padding: 0, display: "flex", alignItems: "center", gap: "0.35rem" }}><span style={{ fontSize: "0.8rem" }}>←</span> Dashboard</button>
        <button onClick={onDone} style={{ background: "transparent", border: "none", color: "rgba(255,255,255,0.72)", fontSize: "0.68rem", letterSpacing: "0.1em", textTransform: "uppercase", cursor: "pointer", fontFamily: BFONT }}>
          View full results →
        </button>
      </div>}

      {/* block: highlights/progress */}
      {inline && <div style={{ display: "flex", gap: 5, marginBottom: "1.25rem" }}>
        {Array.from({ length: TOTAL_CARDS }).map((_, i) => (
          <div key={i} onClick={() => setCardIdx(i)} style={{ height: 4, width: i === cardIdx ? 28 : 18, borderRadius: 2, background: i === cardIdx ? (coupleType?.color || "#E8673A") : i < cardIdx ? "rgba(0,0,0,0.25)" : "#E8DDD0", cursor: "pointer", transition: "all 0.2s" }} />
        ))}
      </div>}

      {/* ── WHICH SIDE WAS TAPPED ────────────────────────────────────────
          Ellie: "Just like we have on the app, tapping the side of the results
          cards should go forward or backward to the next or previous page."

          The app's rule, from when she asked for it there: "On storycards, if I
          tap the left hand side of the page I want it to go back a page." A
          third of the width is the back half, which is the same fraction the
          app uses, because it has to be clearly a side rather than a sliver and
          it has to leave the middle to the card, where the buttons on the first
          and last card are.

          The last card does not advance. Tapping into nothing is how someone
          decides a thing is broken, and the end of the sequence has its own
          button. Neither does the first card go back.

          Anything inside the card that is itself a control still wins: a click
          on a button stops before it reaches here, which is why the handler is
          on the frame rather than on a layer over it. */}
      <div
        onClick={(e) => {
          /* A click that began as a selection is someone reading, not paging.
             Marking a sentence on a storycard and then losing the card is the
             kind of thing nobody reports and everybody notices. */
          const sel = typeof window !== "undefined" && window.getSelection
            ? String(window.getSelection() || "") : "";
          if (sel.trim()) return;
          const box = e.currentTarget.getBoundingClientRect();
          if (e.clientX - box.left < box.width / 3) {
            if (cardIdx > 0) setCardIdx((n) => n - 1);
            return;
          }
          if (!isLast) setCardIdx((n) => n + 1);
        }}
        style={{ flex: inline ? undefined : 1, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: inline ? "0 0 3rem" : isMobile ? "0.5rem 0 4rem" : "1rem 0.5rem 5rem", overflowY: inline ? undefined : "auto", WebkitOverflowScrolling: "touch", overscrollBehavior: "contain", cursor: "pointer" }}>
        {cards[cardIdx]}
      </div>

      {!inline && !isMobile && (<>
        {cardIdx > 0 && <button onClick={() => setCardIdx(n => n - 1)} aria-label="Previous"
          style={{ position: "absolute", top: "50%", left: "1.75rem", transform: "translateY(-50%)", width: 50, height: 50, borderRadius: "50%", background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.18)", color: "white", fontSize: "1.4rem", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 210, backdropFilter: "blur(8px)" }}>‹</button>}
        {!isLast && <button onClick={advance} aria-label="Next"
          style={{ position: "absolute", top: "50%", right: "1.75rem", transform: "translateY(-50%)", width: 50, height: 50, borderRadius: "50%", background: "rgba(255,255,255,0.1)", border: "1px solid rgba(255,255,255,0.18)", color: "white", fontSize: "1.4rem", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 210, backdropFilter: "blur(8px)" }}>›</button>}
      </>)}

      <div style={{ position: inline ? "static" : "absolute", bottom: inline ? undefined : 0, left: inline ? undefined : 0, right: inline ? undefined : 0, padding: inline ? "0" : "0 1.5rem 1.25rem", display: "flex", alignItems: "center", justifyContent: "space-between", gap: "1rem", marginTop: inline ? "1rem" : 0 }}>
        
        {/* block: highlights/controls */}
        {/* ── ONE SET OF ARROWS ────────────────────────────────────────
            Ellie: "Storycard highlights have two sets of nav arrows - remove
            the ones that are stationary below the card."

            Highlights is a results page, so the layout draws the floating pair
            that every results page has, and the storycards drew their own pair
            under the card as well. Two sets, doing two different things, which
            is worse than two sets doing one.

            The stationary pair is gone. Paging a card is the left or right edge
            of the card itself, which is how every story reel works and what she
            asked for here, and the dots below jump straight to one. The
            floating pair keeps its own job: the next results page. */}
        <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: inline ? 0 : 6 }}>
          {inline
            ? <span style={{ fontSize: "0.62rem", color: C.muted, fontFamily: BFONT, letterSpacing: "0.1em" }}>{cardIdx + 1} / {TOTAL_CARDS}</span>
            : Array.from({ length: TOTAL_CARDS }).map((_, i) => (
                <div key={i} onClick={() => setCardIdx(i)}
                  style={{ height: i === cardIdx ? 8 : 6, width: i === cardIdx ? 24 : 6, borderRadius: 99, background: i === cardIdx ? "white" : i < cardIdx ? "rgba(255,255,255,0.55)" : "rgba(255,255,255,0.18)", cursor: "pointer", transition: "all 0.2s", flexShrink: 0 }} />
              ))
          }
        </div>
      </div>
    </>
  );

  if (inline) return <div style={{ display: "flex", flexDirection: "column" }}>{content}</div>;
  return (
    <div style={{ position: "fixed", top: 0, left: 0, right: 0, bottom: 0, background: "#120f22", display: "flex", flexDirection: "column", zIndex: 200, overflow: "hidden", paddingBottom: "env(safe-area-inset-bottom)", alignItems: isMobile ? "center" : undefined }}>
      {/* Subtle side gradient panels on desktop */}
      <div style={{ position: "absolute", inset: 0, background: "radial-gradient(ellipse at 15% 50%, rgba(232,103,58,0.06) 0%, transparent 60%), radial-gradient(ellipse at 85% 50%, rgba(27,95,232,0.06) 0%, transparent 60%)", pointerEvents: "none" }} />
      {/* Exit to dashboard — without this the only way out of the storycards
          is to tap through every card, which left users stuck when they
          entered from the dashboard "see results" tile. */}
      {onExit && (
        <button onClick={(e) => { e.stopPropagation(); onExit(); }}
          style={{ position: "absolute", top: "max(1rem, env(safe-area-inset-top))", left: "1rem", zIndex: 210, background: "rgba(255,255,255,0.12)", border: "1px solid rgba(255,255,255,0.22)", color: "rgba(255,255,255,0.85)", borderRadius: 9, padding: "0.45rem 0.85rem", fontSize: "0.68rem", letterSpacing: "0.08em", textTransform: "uppercase", fontWeight: 600, cursor: "pointer", fontFamily: "'DM Sans', sans-serif", backdropFilter: "blur(8px)" }}>
          ← Dashboard
        </button>
      )}
      {content}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// AUTH MODAL — Sign up / Log in
// ─────────────────────────────────────────────────────────────────────────────
function AuthModal({ mode, onClose, onSuccess }) {
  const isMobile = useMobile(560);
  const [tab, setTab] = useState(mode || "signup");
  // Pre-fill names from URL params (passed from checkout on purchase)
  const _authParams = new URLSearchParams(window.location.search);
  const _p1 = _authParams.get('p1') || '';
  const _p2 = _authParams.get('p2') || '';
  const _partnerAEmail = (_authParams.get('pae') || '').toLowerCase(); // for uniqueness check on Partner B signup
  const [form, setForm] = useState({ name: _p1, pronouns: "", partnerName: _p2, partnerPronouns: "", partnerEmail: "", email: ((mode || "signup") === "login" ? (() => { try { return (JSON.parse(localStorage.getItem('attune_account') || 'null') || {}).email || ''; } catch { return ''; } })() : ""), password: "", emailOptIn: true, ageRange: "", gender: "", relationshipStatus: "", relationshipLength: "", children: "", signupSource: "" });
  const _authIsGift = _authParams.get('gift') === '1';
  const [welcomeAck, setWelcomeAck] = useState(false); // gift/QR celebratory landing acknowledged
  const [err, setErr] = useState("");
  const [capsOn, setCapsOn] = useState(false); // Caps Lock warning for password fields
  const [loading, setLoading] = useState(false);
  const [resetSent, setResetSent] = useState(false);
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [lockedUntil, setLockedUntil] = useState(null);
  const [shake, setShake] = useState(false);
  const upd = (k, v) => setForm(f => ({ ...f, [k]: v }));

  // ── Google and Apple ────────────────────────────────────────────────────────
  //
  // The setup email link is where most people make their account, and until now
  // the only way to make one was to invent another password. Both providers, not
  // one: Apple requires Sign in with Apple wherever a third-party login is
  // offered, and shipping Google alone is what gets an app rejected.
  //
  // The round trip leaves the site, so the order number from the setup email has
  // to survive it. It rides in the redirect URL, which is why redirectTo is the
  // current URL rather than a fixed path.
  //
  // Identity first, then the profile. Coming back from a provider, we know who
  // someone is and nothing else, so the same form still runs: names, pronouns,
  // partner, demographics. The email and password fields are the only part that
  // goes away, because the provider has already answered that question.
  const _oauthProvider = _authParams.get('oauth') || '';
  const [oauthIdentity, setOauthIdentity] = useState(null); // { user, session, provider }
  const [oauthBusy, setOauthBusy] = useState('');

  const startOAuth = async (provider) => {
    setErr('');
    setOauthBusy(provider);
    try {
      const { supabase: sb, hasSupabase } = await import('./supabase.js');
      if (!hasSupabase()) {
        setOauthBusy('');
        return setErr('Sign-in is unavailable right now. Please try again in a moment.');
      }
      const back = new URL(window.location.href);
      back.searchParams.set(tab === 'login' ? 'signin' : 'signup', '1');
      back.searchParams.set('oauth', provider);
      const { error } = await sb.auth.signInWithOAuth({
        provider,
        options: { redirectTo: back.toString() },
      });
      // No error means the browser is already navigating away.
      if (error) {
        setOauthBusy('');
        setErr(`${provider === 'apple' ? 'Apple' : 'Google'} sign-in is not available right now. Use an email and password below.`);
      }
    } catch (e) {
      console.warn('[oauth] start failed:', e);
      setOauthBusy('');
      setErr('That did not open. Use an email and password below.');
    }
  };

  // Coming back from the provider.
  React.useEffect(() => {
    if (!_oauthProvider) return;
    let cancelled = false;
    (async () => {
      setLoading(true);
      try {
        const { supabase: sb, hasSupabase } = await import('./supabase.js');
        if (!hasSupabase()) return;
        const { data } = await sb.auth.getSession();
        const session = data?.session || null;
        if (cancelled) return;
        if (!session?.user) {
          setErr('That sign-in did not complete. Try again, or use an email and password below.');
          return;
        }
        // A profile with a name means this is someone who already has an
        // account, whichever tab they pressed the button on. Send them through
        // the returning-person path rather than asking them to set up again.
        const { data: prof } = await sb.from('profiles').select('name').eq('id', session.user.id).maybeSingle();
        if (cancelled) return;
        if (prof?.name) {
          await completeLogin(sb, session.user);
          return;
        }
        // No profile, and nothing that says a new account is expected here.
        //
        // Setup arrives with an order number; an invited partner arrives with
        // an invite code. Without either, this is someone pressing Google or
        // Apple on the sign-in page for an identity Attune has never seen, and
        // the honest answer is to say so. Making them a blank account instead
        // is worse than refusing: they would land on an empty dashboard with
        // nothing they paid for, and now hold two accounts.
        const expectsNewAccount = !!(_authParams.get('orderNum') || _authParams.get('invite'));
        if (!expectsNewAccount) {
          await sb.auth.signOut().catch(() => {});
          setTab('login');
          setErr(
            `There is no Attune account for that ${_oauthProvider === 'apple' ? 'Apple' : 'Google'} sign-in. ` +
            'If you bought with a different email, sign in with that email and password below.');
          return;
        }
        setOauthIdentity({ user: session.user, session, provider: _oauthProvider });
        setTab('signup');
        // Providers hand back a display name. Prefilling the first name saves a
        // step; it stays editable because a Google account name is often not
        // what someone wants their partner to read.
        const meta = session.user.user_metadata || {};
        const guessed = String(meta.given_name || meta.name || meta.full_name || '').trim().split(/\s+/)[0] || '';
        setForm(f => ({ ...f, name: f.name || guessed, email: session.user.email || f.email }));
      } catch (e) {
        console.warn('[oauth] return failed:', e);
        if (!cancelled) setErr('Something went wrong finishing that sign-in. Use an email and password below.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
    // completeLogin is stable for the life of this modal and depending on it
    // would re-run the exchange on every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [_oauthProvider]);

  // Finish an account whose identity came from a provider. Same tail as a
  // password signup, so nothing can be done for one and skipped for the other.
  const handleOAuthFinish = async () => {
    if (!oauthIdentity) return;
    if (!form.name.trim()) return setErr('Add your first name above to continue.');
    setLoading(true);
    setErr('');
    try {
      await completeSignup(oauthIdentity.user, oauthIdentity.session, (oauthIdentity.user.email || '').toLowerCase());
    } catch (e) {
      console.warn('[oauth] finish failed:', e);
      setErr('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Trigger shake + clear after animation (0.45s)
  const triggerShake = () => {
    setShake(false);
    // Force reflow so animation restarts if triggered twice in a row
    requestAnimationFrame(() => { setShake(true); setTimeout(() => setShake(false), 500); });
  };

  const genInvite = () => Math.random().toString(36).slice(2, 10).toUpperCase();

  // Race a promise against a timeout. Without this, a stalled auth or fetch
  // call leaves the signup button locked in loading state and the user
  // sees nothing. Throws if the timeout wins.
  const withTimeout = (promise, ms, label) => Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error(`Timed out: ${label}`)), ms)),
  ]);

  /**
   * Everything after the identity exists.
   *
   * Split out of handleSignup because there are now two ways to arrive here
   * with an authenticated user: a password signup, and coming back from Google
   * or Apple. Both then need exactly the same things done — the profile row,
   * the local account, the order claim, the partner invite, the QR claim — and
   * the surest way to make one of those paths quietly skip a step is to write
   * it out twice.
   *
   * `signedInEmail` is passed rather than read off the form because with Apple
   * the form has no email in it: Apple supplies the address, and it may be a
   * relay one.
   */
  const completeSignup = async (user, session, signedInEmail) => {
    // Write profile fields that aren't in auth metadata.
    // Uses /api/create-profile (service role) instead of a direct
    // supabase write because when "Confirm email" is ON in Supabase,
    // auth.signUp() returns a user but no session — and the RLS
    // policy on profiles requires auth.uid() = id for inserts.
    // Without a session that check fails silently.
    const inviteCode = genInvite();
    try {
      await withTimeout(
        fetch('/api/create-profile', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            userId:              user.id,
            name:                form.name.trim(),
            pronouns:            form.pronouns.trim() || "",
            partnerName:         form.partnerName.trim() || "",
            partnerPronouns:     form.partnerPronouns.trim() || "",
            partnerEmail:        form.partnerEmail.trim().toLowerCase() || "",
            emailOptIn:          form.emailOptIn,
            inviteCode,
            pkg:                 new URLSearchParams(window.location.search).get("pkg") || "core",
            ageRange:            form.ageRange || null,
            gender:              form.gender || null,
            relationshipStatus:  form.relationshipStatus || null,
            relationshipLength:  form.relationshipLength || null,
            children:            form.children || null,
            signupSource:        form.signupSource || null,
          }),
        }),
        15000,
        'create-profile'
      );
    } catch (e) {
      // Profile creation is recoverable — login flow re-syncs missing
      // profile data. Better to let the user proceed than block them.
      console.warn('[signup] create-profile failed (will retry on next login):', e);
    }

    const account = {
      id: user.id,
      email: signedInEmail,
      name: form.name.trim(),
      pronouns: form.pronouns.trim() || "",
      partnerName: form.partnerName.trim() || "",
      partnerPronouns: form.partnerPronouns.trim() || "",
      partnerEmail: form.partnerEmail.trim().toLowerCase() || "",
      emailOptIn: form.emailOptIn,
      inviteCode,
      partnerJoined: false,
      pkg: new URLSearchParams(window.location.search).get("pkg") || "core",
      createdAt: Date.now(),
    };
    // Preserve the order summary checkout.html just wrote. The wipe below
    // removes attune_order, and the DB-based rebuild only runs on a later
    // fresh sign-in — without this, package add-ons are invisible until the
    // user signs out and back in.
    let _checkoutOrderSnapshot = null;
    try {
      if (_authParams.get('orderNum')) _checkoutOrderSnapshot = localStorage.getItem('attune_order');
    } catch {}
    // Clear stale data from any prior user/demo on this browser. Single
    // source of truth at module top; see USER_LOCALSTORAGE_KEYS.
    clearAllUserLocalStorage();
    try { localStorage.setItem("attune_account", JSON.stringify(account)); } catch {}
    if (_checkoutOrderSnapshot) {
      try { localStorage.setItem('attune_order', _checkoutOrderSnapshot); } catch {}
    }

    // Link the order created at checkout (via stripe-webhook with no user_id)
    // to this newly-created auth user. orderNum was passed in the URL by
    // checkout.html on success. Without this link, the user's orders are
    // only findable by buyer_email — fragile if email is changed later.
    // Multi-item orders are written as ORDER_NUM-1, ORDER_NUM-2, etc. by
    // the stripe webhook, so we also match the prefix to catch all rows.
    //
    // This used to be fire-and-forget, with a comment saying linkage "falls
    // back to buyer_email match on later sign-in if this fails". That
    // fallback only works while everyone signs in with the address they
    // bought with. Sign in with Apple can hand back a private relay address,
    // which never matches, so a dropped link leaves a paying customer with an
    // account and no entitlements. It is now awaited, on the server, where it
    // also records the purchase email on the profile so the account stays
    // findable whatever address the person logs in with.
    const _checkoutOrderNum = _authParams.get('orderNum');
    if (_checkoutOrderNum) {
      await claimOrder(_checkoutOrderNum, session?.access_token);
    }

    // Send partner invite email if partner email was provided.
    // Uses retry helper so a single transient failure doesn't permanently
    // lose the invite (Issue 4.7).
    if (form.partnerEmail.trim()) {
      const inviteUrl = `${window.location.origin}/app?invite=${encodeURIComponent(inviteCode)}&from=${encodeURIComponent(form.name.trim())}&pae=${encodeURIComponent(signedInEmail)}${form.partnerEmail?.trim() ? `&iie=${encodeURIComponent(form.partnerEmail.trim().toLowerCase())}` : ''}`;
      sendEmailWithRetry({
        type: 'partner_invite',
        fromName: form.name.trim(),
        toEmail: form.partnerEmail.trim(),
        toName: form.partnerName.trim() || 'Your partner',
        inviteUrl,
      });
    }

    // Welcome email is now fired on first dashboard view (Issue 2.6),
    // not at signup. This prevents the user from receiving two emails
    // back-to-back (Supabase confirm + Attune welcome) before they've
    // even confirmed.

    // If the user arrived via a QR-code scan, claim the order so the token
    // can't be reused. Uses retry helper (Issue 2.7) — without retry, a
    // transient network failure here means the QR token stays unclaimed
    // and anyone with the physical card could re-claim it.

    onSuccess(account);
  };

  const handleSignup = async () => {
    if (!form.name.trim()) return setErr("Add your first name above to continue.");
    if (!form.email.trim() || !form.email.includes("@")) return setErr("Enter a valid email above to continue.");
    if (!form.password || form.password.length < 6) return setErr("Choose a password with at least 6 characters above.");
    setLoading(true);
    setErr("");

    try {

    // ── Supabase auth ────────────────────────────────────────────────────────
    // Email uniqueness check — Partner B cannot use same email as Partner A
    if (_partnerAEmail && form.email.trim().toLowerCase() === _partnerAEmail) {
      return setErr("This email is already linked to the other partner's account. Each partner needs their own email address.");
    }

    const { supabase: sb, hasSupabase } = await import('./supabase.js');
    if (hasSupabase()) {
      let authData, authErr;
      try {
        const result = await withTimeout(
          sb.auth.signUp({
            email: form.email.trim().toLowerCase(),
            password: form.password,
            options: {
              data: { name: form.name.trim() },
              // Where Supabase redirects after the user clicks the email
              // confirmation link. Must match a URL in Supabase Dashboard →
              // Authentication → URL Configuration → Redirect URLs allow list.
              emailRedirectTo: `${window.location.origin}/app`,
            },
          }),
          20000,
          'auth.signUp'
        );
        authData = result.data;
        authErr = result.error;
      } catch (e) {
        console.warn('[signup] auth.signUp timed out or threw:', e);
        return setErr("That took too long and didn't go through. Wait a moment and try again.");
      }
      const ALREADY_MSG = "Looks like that email is already registered for an Attune account. Enter your password to sign in, or tap Forgot password below to reset it.";
      if (authErr) {
        const m = (authErr.message || '').toLowerCase();
        if (m.includes('already registered') || m.includes('already exists') || m.includes('already been registered') || authErr.code === 'user_already_exists') {
          setTab('login');
          return setErr(ALREADY_MSG);
        }
        return setErr(authErr.message);
      }
      // With "Confirm email" on, Supabase returns an obfuscated user with an
      // empty identities array (and no error) when the email already exists.
      // Treat that as already-registered too.
      if (authData?.user && Array.isArray(authData.user.identities) && authData.user.identities.length === 0) {
        setTab('login');
        return setErr(ALREADY_MSG);
      }
      if (!authData?.user?.id) return setErr("Sign-up didn't complete. Please try again.");

      await completeSignup(authData.user, authData.session, form.email.trim().toLowerCase());
      return;
    }

    // ── localStorage fallback (no Supabase configured) ───────────────────────
    const account = {
      email: form.email.trim().toLowerCase(),
      name: form.name.trim(),
      pronouns: form.pronouns.trim() || "",
      partnerName: form.partnerName.trim() || "",
      partnerPronouns: form.partnerPronouns.trim() || "",
      partnerEmail: form.partnerEmail.trim().toLowerCase() || "",
      emailOptIn: form.emailOptIn,
      inviteCode: genInvite(),
      partnerJoined: false,
      pkg: new URLSearchParams(window.location.search).get("pkg") || "core",
      createdAt: Date.now(),
    };
    try { localStorage.setItem("attune_account", JSON.stringify(account)); } catch {}

    // Send partner invite email if partner email provided
    if (form.partnerEmail.trim() && account.inviteCode) {
      const inviteUrl = `${window.location.origin}/app?invite=${encodeURIComponent(account.inviteCode)}&from=${encodeURIComponent(form.name.trim())}&pae=${encodeURIComponent(form.email.trim().toLowerCase())}${form.partnerEmail?.trim() ? `&iie=${encodeURIComponent(form.partnerEmail.trim().toLowerCase())}` : ''}`;
      sendEmailWithRetry({ type: 'partner_invite', fromName: form.name.trim(), toEmail: form.partnerEmail.trim(), toName: form.partnerName.trim() || 'Your partner', inviteUrl });
    }

    // Claim the QR token if we arrived from a physical card scan (Issue 2.7)

    onSuccess(account);

    } catch (e) {
      // Catch-all: any unexpected throw should surface to the user, not
      // silently leave the button stuck. The inner network calls already
      // catch their own errors; this is the safety net for everything else.
      console.warn('[signup] unexpected error:', e);
      setErr('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  /**
   * Everything after a returning person is authenticated.
   *
   * Split out for the same reason as completeSignup: pressing Google on the
   * sign-in tab has to do all of this, and this is a hundred lines of
   * hydration — prior answers, mid-exercise progress, budget, checklist,
   * notes, the workbook, the partner session — where every single line exists
   * because leaving it out broke something. A second copy would rot.
   *
   * `sb` is passed in so the caller owns the import.
   */
  const completeLogin = async (sb, user) => {
    // ── THE ERROR MATTERS HERE ──────────────────────────────────────────────
    // This discarded it. A read that fails, a mobile cold start with no
    // network yet, a transient auth or RLS hiccup, leaves `profile` undefined,
    // and the restore block below then reads "the server has no answers" and
    // deletes the local copy of every exercise. The dashboard says the
    // exercise was never done and results lock, until some later load happens
    // to succeed and puts them back.
    //
    // The server's copy is never at risk: answers are only written on
    // completion and never written as null. But a couple watching their
    // results disappear has no way to know that.
    //
    // `read` is what the rest of this function checks before clearing
    // anything: absence is only absence when the server actually answered.
    const { data: profile, error: profileErr } =
      await sb.from('profiles').select('*').eq('id', user.id).single();
    const read = { ok: !profileErr };
    if (profileErr) {
      console.warn('[Attune] profile read failed on sign-in; keeping local answers:', profileErr.message);
    }

    const account = {
      id: user.id,
      email: user.email,
      name: profile?.name || "",
      pronouns: profile?.pronouns || "",
      partnerName: profile?.partner_name || "",
      partnerPronouns: profile?.partner_pronouns || "",
      partnerEmail: profile?.partner_email || "",
      // email_opt_in defaults to true when missing entirely (new account
      // hydration). The previous `|| false` pattern masked an actual
      // user preference of false vs null/missing. Issue 2.3.
      emailOptIn: typeof profile?.email_opt_in === 'boolean' ? profile.email_opt_in : true,
      betaSurveyAt: profile?.beta_survey_at || null,
      inviteCode: profile?.invite_code || "",
      partnerJoined: profile?.partner_joined || false,
      joinedViaInvite: profile?.joined_via_invite || false,
      relationshipStatus: profile?.relationship_status || null,
      // Buyer's status drives the Ex2 variant for both partners. For the
      // buyer (Partner A, not joined via invite) it's their own status; for
      // the invitee it's resolved from the partner-sync fetch below.
      buyerRelationshipStatus: profile?.joined_via_invite ? null : (profile?.relationship_status || null),
      pkg: profile?.pkg || "core",
      createdAt: profile?.created_at ? new Date(profile.created_at).getTime() : Date.now(),
    };
    try { localStorage.setItem("attune_account", JSON.stringify(account)); } catch {}

    // Restore exercise answers from Supabase (cross-device support)
    // Restore exercise answers from Supabase (cross-device support). When the
    // server has no answers for an exercise (e.g. after an admin reset), clear
    // any stale local copy so a previously-completed exercise doesn't linger on
    // the device and keep showing as done.
    try {
      // Every exercise, derived rather than listed: this block covered the
      // first three only, so an admin reset of a newer exercise left the
      // local copy in place and it kept reading as complete.
      if (profile?.ex1_answers) localStorage.setItem('attune_ex1', JSON.stringify(profile.ex1_answers));
      else if (read.ok) localStorage.removeItem('attune_ex1');
      if (profile?.intimacy_data) localStorage.setItem('attune_intimacy', JSON.stringify(profile.intimacy_data));
      else if (read.ok) localStorage.removeItem('attune_intimacy');
      if (profile?.conflict_data) localStorage.setItem('attune_conflict', JSON.stringify(profile.conflict_data));
      else if (read.ok) localStorage.removeItem('attune_conflict');
    } catch {}
    try {
      if (profile?.ex2_answers) localStorage.setItem('attune_ex2', JSON.stringify(profile.ex2_answers));
      else if (read.ok) localStorage.removeItem('attune_ex2');
    } catch {}
    try {
      if (profile?.ex3_answers) localStorage.setItem('attune_ex3', JSON.stringify(profile.ex3_answers));
      else if (read.ok) localStorage.removeItem('attune_ex3');
    } catch {}
    /**
     * ── PART-WAY THROUGH, FROM WHICHEVER DEVICE GOT FURTHEST ────────────────
     * Cross-device resume only worked one way. The app reads ex{N}_progress from
     * the server, so stopping on a laptop and carrying on in the app picked up
     * where you left off. The website read its progress from this browser's own
     * storage and never asked, so the reverse began again at question one: the
     * answers were on the server the whole time and nothing here looked at them.
     *
     * The same hydration every other column gets, with one rule on top. Progress
     * only grows inside an exercise, so the copy with more answers in it is the
     * later one, and it wins. That is a real question rather than a detail: a
     * timestamp would be the obvious tiebreak and it is the wrong one, because
     * the last write is not the furthest along when someone opens an old tab.
     *
     * Reading is where both shapes meet. The website stores { answers, idx } and
     * the app stores the answers alone, so both are unwrapped before they are
     * counted, the same way api/_lib/exercise-progress.js does it on the server.
     * The wrapper is kept when this browser's copy wins, because the idx is what
     * it resumes from.
     */
    try {
      const unwrap = (blob) => {
        if (!blob || typeof blob !== 'object') return null;
        if (blob.answers && typeof blob.answers === 'object') return blob.answers;
        if ('idx' in blob) return null;
        return blob;
      };
      const countAnswers = (a) => {
        if (!a || typeof a !== 'object') return 0;
        let n = 0;
        for (const v of Object.values(a)) {
          if (v == null || v === '') continue;
          if (Array.isArray(v)) { if (v.length) n += 1; continue; }
          if (typeof v === 'object') { n += Object.values(v).filter((x) => x != null && x !== '').length; continue; }
          n += 1;
        }
        return n;
      };
      for (const ex of EXERCISES) {
        if (!ex.progressKey || ex.shape === 'record') continue;
        const server = profile?.[`${ex.key}_progress`];
        if (!server) continue;
        // A finished exercise is not in progress, whatever is left in the column.
        if (profile?.[ex.column] && Object.keys(profile[ex.column]).length) continue;
        let local = null;
        try { local = JSON.parse(localStorage.getItem(ex.progressKey) || 'null'); } catch { local = null; }
        if (countAnswers(unwrap(server)) > countAnswers(unwrap(local))) {
          localStorage.setItem(ex.progressKey, JSON.stringify(server));
        }
      }
    } catch {}

    // Prior-completion snapshots (for retake comparison). These exist only
    // when the user has re-taken an exercise. Stored in localStorage so
    // the retake comparison card can render without a round-trip.
    if (profile?.ex1_answers_prior) {
      try { localStorage.setItem('attune_ex1_prior', JSON.stringify({ answers: profile.ex1_answers_prior, at: profile.ex1_prior_completed_at })); } catch {}
    }
    if (profile?.ex2_answers_prior) {
      try { localStorage.setItem('attune_ex2_prior', JSON.stringify({ answers: profile.ex2_answers_prior, at: profile.ex2_prior_completed_at })); } catch {}
    }
    if (profile?.ex3_answers_prior) {
      try { localStorage.setItem('attune_ex3_prior', JSON.stringify({ answers: profile.ex3_answers_prior, at: profile.ex3_prior_completed_at })); } catch {}
    }
    // Mid-exercise progress (Issue 3.5). Hydrate the per-exercise progress
    // snapshots so a user who started on one device can resume on another.
    // Only restore progress for exercises NOT yet completed (otherwise the
    // completed answer takes precedence).
    if (profile?.ex1_progress && !profile?.ex1_answers) {
      try { localStorage.setItem('attune_ex1_progress', JSON.stringify(profile.ex1_progress)); } catch {}
    }
    if (profile?.ex2_progress && !profile?.ex2_answers) {
      try { localStorage.setItem('attune_ex2_progress', JSON.stringify(profile.ex2_progress)); } catch {}
    }
    if (profile?.ex3_progress && !profile?.ex3_answers) {
      try { localStorage.setItem('attune_ex3_progress', JSON.stringify(profile.ex3_progress)); } catch {}
    }
    // else-remove on every one of these: without it, signing into an account
    // whose server copy is empty leaves the previous account's data on the
    // device, which is the same shape as the bug that made a reset partner
    // keep reading as complete.
    if (profile?.budget_data) {
      try { localStorage.setItem('attune_budget', JSON.stringify(profile.budget_data)); } catch {}
    } else if (read.ok) {
      try { localStorage.removeItem('attune_budget'); } catch {}
    }
    if (profile?.checklist_data) {
      try { localStorage.setItem('attune_checklist', JSON.stringify(profile.checklist_data)); } catch {}
    } else if (read.ok) {
      try { localStorage.removeItem('attune_checklist'); } catch {}
    }
    // The workbook is persisted on the profile as well as the order, so comp
    // accounts (which have no order row) restore it on any device exactly like
    // paid ones. Whichever source has it wins; the order is checked first.
    if (profile?.workbook_url || profile?.workbook_status === 'ready') {
      try {
        const _o = JSON.parse(localStorage.getItem('attune_order') || 'null') || {};
        if (!_o.workbookUrl) {
          _o.workbookUrl = profile.workbook_url || null;
          _o.workbookStatus = profile.workbook_status || 'ready';
          localStorage.setItem('attune_order', JSON.stringify(_o));
        }
        localStorage.setItem('attune_workbook_ready', 'true');
      } catch {}
    }
    // Restore partner session if partner already completed
    if (profile?.partner_profile_id) {
      try {
        // After signInWithPassword, the session is fresh. Pull the
        // access token to authenticate the partner-sync call.
        const { data: { session: authSession } } = await sb.auth.getSession();
        const psRes = await fetch(`/api/partner-sync?partnerProfileId=${encodeURIComponent(profile.partner_profile_id)}`, {
          headers: authSession?.access_token
            ? { Authorization: `Bearer ${authSession.access_token}` }
            : {},
        });
        const ps = await psRes.json();
        if (ps.found && ps.profile) {
          // The invitee inherits the buyer's (Partner A's) relationship
          // status so both partners get the same Ex2 variant.
          if (profile?.joined_via_invite && ps.profile.relationship_status) {
            account.buyerRelationshipStatus = ps.profile.relationship_status;
            try { localStorage.setItem("attune_account", JSON.stringify(account)); } catch {}
          }
        }
        // Mirror of the ex1/ex2/ex3 clearing above: when the partner has no
        // answers on the server (a reset, or they have not finished), drop
        // any cached session so they do not keep reading as complete.
        // The partner session used to be written only when the partner had
        // BOTH ex1 and ex2, and cleared otherwise. That made partner status
        // all-or-nothing: someone who had finished Communication but not
        // Expectations showed as Pending on everything, including the
        // exercise they had actually completed. Per-exercise status was
        // impossible to report accurately.
        //
        // Now it is written whenever the partner has any answers at all, and
        // each field carries its own truth, so every row can report the
        // exercise it is about.
        // conflict_data is NOT in this response and never will be:
        // /api/partner-sync deletes it and sends conflictCompletedAt and
        // conflictPartnerView in its place, because the raw record carries the
        // patterns half that is private to whoever wrote it. Reading
        // ps.profile.conflict_data here asked for a field the endpoint had
        // already removed, so a partner who had finished Conflict Patterns
        // read as having answered nothing.
        const _anyPartnerAnswers = !!(ps.profile?.ex1_answers || ps.profile?.ex2_answers
          || ps.profile?.ex3_answers || ps.profile?.intimacy_data
          || ps.profile?.conflictCompletedAt);
        if (ps.found && !_anyPartnerAnswers) {
          try { localStorage.removeItem('attune_partner_session'); } catch {}
        }
        if (ps.found && _anyPartnerAnswers) {
          localStorage.setItem('attune_partner_session', JSON.stringify({
            name: ps.profile.name,
            ex1: ps.profile.ex1_answers,
            ex2: ps.profile.ex2_answers,
            ex3: ps.profile.ex3_answers,
            // The partner's conflict, in the only shape this side is allowed
            // to have: the sharable view plus when they finished. The previous
            // line read ps.profile.conflict_data, which the endpoint strips,
            // so this was always absent and the Conflict Patterns row read
            // Pending however long ago they finished it.
            ...(ps.profile.conflictCompletedAt
              ? { conflict: { ...(ps.profile.conflictPartnerView || {}), completedAt: ps.profile.conflictCompletedAt } }
              : {}),
            ...(ps.profile.intimacy_data ? { intimacy: ps.profile.intimacy_data } : {}),
            partnerProfileId: profile.partner_profile_id,
            inviteCode: profile.invite_code,
          }));
        }
      } catch {}
    }

    // Restore order from Supabase so pkg features (budget, reflection) work on a new device
    if (!localStorage.getItem('attune_order') && user.email) {
      try {
        // NOTE: this is the one orders query in the app with a hand-written
        // column list rather than ORDER_SELECT. addon_conflict was missing
        // from it, so a granted add-on read as undefined and was stored as
        // false, which is why Partner B never saw the exercise on a fresh
        // sign-in. Any new add-on column has to be added here too.
        const { data: orderRow } = await sb.from('orders')
          .select('id,pkg_key,addon_reflection,addon_budget,addon_checklist,addon_intimacy,addon_conflict,addon_workbook,is_physical,order_num,user_id,workbook_url,workbook_status')
          .eq('buyer_email', user.email)
          .order('created_at', { ascending: false })
          .limit(1)
          .single();
        if (orderRow) {
          localStorage.setItem('attune_order', JSON.stringify({
            pkgKey:          orderRow.pkg_key,
            addonReflection: orderRow.addon_reflection || false,
            addonBudget:     orderRow.addon_budget || false,
            addonChecklist:  orderRow.addon_checklist || false,
            addonIntimacy:     orderRow.addon_intimacy || false,
            addonConflict:     orderRow.addon_conflict || false,
            addonWorkbook:   orderRow.addon_workbook || null,
            isPhysical:      orderRow.is_physical || false,
            orderNum:        orderRow.order_num || null,
            // 10.6 — the workbook's real state lives on the order row. Without
            // these, a login on any other device shows "Generating now" forever,
            // because readiness was only ever a localStorage flag.
            workbookUrl:     orderRow.workbook_url || null,
            workbookStatus:  orderRow.workbook_status || null,
          }));
          if (orderRow.workbook_url || orderRow.workbook_status === 'ready') {
            try { localStorage.setItem('attune_workbook_ready', 'true'); } catch {}
          }
          // Link the order to the auth user so future cross-device logins
          // can find it by user_id (faster + works even if email changes).
          if (!orderRow.user_id) {
            await sb.from('orders').update({ user_id: user.id }).eq('id', orderRow.id).catch(() => {});
          }
        }
      } catch {}
    }
    if (form.partnerEmail.trim()) {
      const inviteUrl = `${window.location.origin}/app?invite=${encodeURIComponent(account.inviteCode)}&from=${encodeURIComponent(form.name.trim())}&pae=${encodeURIComponent(form.email.trim().toLowerCase())}${form.partnerEmail?.trim() ? `&iie=${encodeURIComponent(form.partnerEmail.trim().toLowerCase())}` : ''}`;
      sendEmailWithRetry({
        type: 'partner_invite',
        fromName: form.name.trim(),
        toEmail: form.partnerEmail.trim(),
        toName: form.partnerName.trim() || 'Your partner',
        inviteUrl,
      });
    }

    setLoading(false);
    onSuccess(account);
  };

  const handleLogin = async () => {
    if (!form.email.trim() || !form.password) return setErr("Please enter your email and password.");
    // Client-side rate limiting: lock after 5 failed attempts for 30 seconds
    if (lockedUntil && Date.now() < lockedUntil) {
      const secs = Math.ceil((lockedUntil - Date.now()) / 1000);
      return setErr(`Too many attempts. Please wait ${secs} seconds.`);
    }
    setLoading(true);
    setErr("");

    // ── Supabase auth ────────────────────────────────────────────────────────
    const { supabase: sb, hasSupabase } = await import('./supabase.js');
    if (hasSupabase()) {
      let authData, authErr;
      try {
        const result = await withTimeout(
          sb.auth.signInWithPassword({
            email: form.email.trim().toLowerCase(),
            password: form.password,
          }),
          15000,
          'auth.signInWithPassword'
        );
        authData = result.data;
        authErr = result.error;
      } catch (e) {
        setLoading(false);
        return setErr("Sign-in is taking too long. Check your connection and try again.");
      }
      if (authErr) {
        setLoading(false);
        const attempts = loginAttempts + 1;
        setLoginAttempts(attempts);
        // Trigger shake animation on every failed attempt
        triggerShake();
        if (attempts >= 5) { setLockedUntil(Date.now() + 30000); setLoginAttempts(0); return setErr("Too many failed attempts. Please wait 30 seconds."); }
        // One message, whatever went wrong.
        //
        // This used to sort the failure into three: "Wrong email, no account
        // found", "Wrong password", and "This account hasn't been confirmed
        // yet". Between them they answered a question nobody signed in to ask,
        // which is whether a given address has an Attune account. For a
        // product about someone's relationship, confirming that a particular
        // person is a customer is itself the disclosure.
        //
        // Supabase already returns one generic message; this was undoing that.
        // The unconfirmed case is folded in deliberately: telling an attacker
        // an account exists but is unconfirmed is the same leak with an extra
        // detail attached. Someone who genuinely has not confirmed still has
        // the confirmation email, and the reset link below covers the rest.
        return setErr("That email and password don't match. Check both, or reset your password below.");
      }
      setLoginAttempts(0); // reset on success

      await completeLogin(sb, authData.user);
      return;
    }

    // ── localStorage fallback ────────────────────────────────────────────────
    try {
      const saved = JSON.parse(localStorage.getItem("attune_account") || "null");
      if (saved && saved.email === form.email.trim().toLowerCase()) {
        setLoading(false);
        onSuccess(saved);
      } else {
        setLoading(false);
        setErr("No account found with that email. Please sign up first.");
      }
    } catch { setLoading(false); setErr("Login failed. Please try again."); }
  };

  const handleReset = async () => {
    if (!form.email.trim() || !form.email.includes("@")) return setErr("Please enter a valid email address.");
    setLoading(true);
    setErr("");

    const { supabase: sb, hasSupabase } = await import('./supabase.js');
    if (hasSupabase()) {
      // Use the canonical production origin rather than window.location.origin.
      // If the user is on a non-canonical host (apex vs www, a preview URL),
      // an origin-derived redirect can miss the allow-list and Supabase falls
      // back to the Site URL (the marketing homepage), dropping ?reset=1.
      const _canonicalOrigin = /attune-relationships\.com$/.test(window.location.hostname)
        ? 'https://www.attune-relationships.com'
        : window.location.origin;
      await sb.auth.resetPasswordForEmail(form.email.trim().toLowerCase(), {
        redirectTo: `${_canonicalOrigin}/app?reset=1`,
      });
      // Always show success (don't reveal whether the email exists)
    }
    setLoading(false);
    setResetSent(true);
  };

  const _capsCheck = (e) => { try { setCapsOn(!!(e.getModifierState && e.getModifierState("CapsLock"))); } catch (_) {} };
  // Google and Apple, given equal weight. Neither is the recommended one, and
  // the marks are drawn rather than loaded so the row cannot render as two
  // broken images if a CDN is blocked.
  const providerRow = (verb) => (
    <>
      <div style={{ display: "flex", gap: "0.6rem", marginBottom: "0.9rem" }}>
        {/* The list is shared with the app, so a provider cannot be added to
            one surface and forgotten on the other. Only the styling is local. */}
        {OAUTH_PROVIDERS.map(p0 => {
          const pv = p0.id === 'apple'
            ? { ...p0, bg: '#0E0B07', fg: '#FFFFFF', border: '#0E0B07' }
            : { ...p0, bg: '#FFFDF9', fg: '#0E0B07', border: '#E8DDD0' };
          return (
          <button key={pv.id} type="button" onClick={() => startOAuth(pv.id)} disabled={!!oauthBusy || loading}
            style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: "0.45rem", padding: "0.78rem 0.5rem", borderRadius: 11, border: `1.5px solid ${pv.border}`, background: pv.bg, color: pv.fg, fontFamily: "'DM Sans',sans-serif", fontSize: "0.82rem", fontWeight: 600, cursor: oauthBusy ? "default" : "pointer", opacity: oauthBusy && oauthBusy !== pv.id ? 0.5 : 1 }}>
            {pv.id === 'google' ? (
              <svg width="15" height="15" viewBox="0 0 48 48" aria-hidden="true">
                <path fill="#4285F4" d="M45.1 24.5c0-1.6-.1-3.1-.4-4.5H24v8.5h11.8c-.5 2.7-2 5-4.4 6.6v5.5h7.1c4.1-3.8 6.6-9.4 6.6-16.1z"/>
                <path fill="#34A853" d="M24 46c5.9 0 10.9-2 14.5-5.4l-7.1-5.5c-2 1.3-4.5 2.1-7.4 2.1-5.7 0-10.5-3.8-12.2-9H4.5v5.7C8.1 41.1 15.5 46 24 46z"/>
                <path fill="#FBBC05" d="M11.8 28.2c-.4-1.3-.7-2.7-.7-4.2s.3-2.9.7-4.2v-5.7H4.5A22 22 0 0 0 2 24c0 3.6.9 6.9 2.5 9.9l7.3-5.7z"/>
                <path fill="#EA4335" d="M24 10.3c3.2 0 6.1 1.1 8.4 3.3l6.3-6.3C34.9 3.7 29.9 1.6 24 1.6 15.5 1.6 8.1 6.5 4.5 13.9l7.3 5.7c1.7-5.2 6.5-9.3 12.2-9.3z"/>
              </svg>
            ) : (
              <svg width="14" height="16" viewBox="0 0 14 16" aria-hidden="true" fill="currentColor">
                <path d="M11.6 8.5c0-2 1.6-3 1.7-3.1-.9-1.4-2.4-1.5-2.9-1.6-1.2-.1-2.4.7-3 .7-.6 0-1.6-.7-2.6-.7C3.5 3.8 2.2 4.6 1.5 5.9c-1.4 2.4-.4 6 1 8 .7 1 1.5 2.1 2.5 2 1-.1 1.4-.6 2.6-.6s1.5.6 2.6.6c1.1 0 1.8-1 2.5-2 .8-1.1 1.1-2.2 1.1-2.3 0 0-2.1-.8-2.2-3.1zM9.7 2.6c.5-.7.9-1.6.8-2.6-.8 0-1.8.5-2.4 1.2-.5.6-1 1.6-.8 2.5.9.1 1.8-.4 2.4-1.1z"/>
              </svg>
            )}
            {oauthBusy === pv.id ? 'Opening…' : `${verb} ${pv.label}`}
          </button>
          );
        })}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: "0.7rem", marginBottom: "0.9rem" }}>
        <div style={{ flex: 1, height: 1, background: "#E8DDD0" }} />
        <span style={{ fontSize: "0.7rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif" }}>or</span>
        <div style={{ flex: 1, height: 1, background: "#E8DDD0" }} />
      </div>
    </>
  );

  const inp = (placeholder, key, type = "text", extra = {}) => {
    const isPw = type === "password";
    // Password managers need autocomplete hints to offer to save a credential
    // and to fill it later. Without them iOS never shows the strong-password
    // suggestion or the save prompt, and 1Password and Chrome fill
    // inconsistently. There were none anywhere in the app.
    //
    // 'username' rather than 'email' on the email field: that is the token
    // password managers pair with a password to form a saved credential.
    const autoFill = extra.autoComplete
      || (isPw ? 'current-password' : type === 'email' ? 'username' : undefined);
    return (
      <React.Fragment>
        <input
          type={type}
          placeholder={placeholder}
          autoComplete={autoFill}
          autoCapitalize={type === 'email' ? 'none' : undefined}
          autoCorrect={type === 'email' ? 'off' : undefined}
          spellCheck={type === 'email' ? false : undefined}
          value={form[key]}
          onChange={e => { upd(key, e.target.value); setErr(""); }}
          onKeyDown={isPw ? _capsCheck : undefined}
          onKeyUp={isPw ? _capsCheck : undefined}
          onBlur={isPw ? (() => setCapsOn(false)) : undefined}
          style={{ width: "100%", padding: "0.78rem 1rem", border: `1.5px solid ${err && !form[key] ? "#ef4444" : "#E8DDD0"}`, borderRadius: 11, fontSize: "0.88rem", fontFamily: "'DM Sans', sans-serif", color: "#0E0B07", background: "#FFFDF9", outline: "none", marginBottom: isPw && capsOn ? "0.3rem" : "0.6rem", boxSizing: "border-box" }}
          {...extra}
        />
        {isPw && capsOn && (
          <div style={{ display: "flex", alignItems: "center", gap: "0.35rem", fontSize: "0.72rem", color: "#B5546E", fontFamily: "'DM Sans', sans-serif", margin: "0 0 0.6rem 0.15rem" }}>
            <span style={{ fontSize: "0.8rem", lineHeight: 1 }}>⇪</span> Caps Lock is on
          </div>
        )}
      </React.Fragment>
    );
  };

  // Celebratory welcome landing for gift recipients and physical-card (QR) arrivals.
  // Shown once before the signup form. Gift-aware copy. Normal sign-in/up is unaffected.
  const _isGiftContext = _authIsGift;
  const _showWelcome = !welcomeAck && _authIsGift;
  if (_showWelcome) {
    return (
      <div style={{ position: "fixed", inset: 0, background: "#1e1a35", zIndex: 500, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: isMobile ? "0" : "1rem", overflowY: "auto" }}
        onClick={e => e.target === e.currentTarget && onClose()}>
        <div style={{ background: "#FFFDF9", borderRadius: isMobile ? 0 : 22, padding: isMobile ? "2rem 1.25rem" : "2.5rem 2rem", width: "100%", margin: isMobile ? 0 : "auto", minHeight: isMobile ? "100vh" : "auto", maxWidth: isMobile ? "none" : 440, boxShadow: isMobile ? "none" : "0 32px 80px rgba(0,0,0,0.28)", position: "relative" }}>
          <button onClick={onClose} aria-label="Close" style={{ position: "absolute", top: "1rem", right: "1rem", background: "none", border: "none", fontSize: "1.2rem", cursor: "pointer", color: "#7A6753", lineHeight: 1 }}>✕</button>
          <div style={{ width: 56, height: 56, borderRadius: "50%", background: "linear-gradient(135deg, #E8673A, #1B5FE8)", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: "1.35rem", fontSize: "1.6rem", color: "white" }}>✦</div>
          <div style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: "1.5rem", fontWeight: 700, color: "#0E0B07", marginBottom: "0.5rem", lineHeight: 1.2 }}>Welcome to your Attune experience.</div>
          <p style={{ fontSize: "0.85rem", color: "#7A6753", fontFamily: "'DM Sans', sans-serif", marginBottom: "1.75rem", lineHeight: 1.7 }}>
            {_isGiftContext ? "Someone gave you this as a gift. " : ""}Two assessments. One conversation. Built from your answers.
          </p>
          <button onClick={() => setWelcomeAck(true)}
            style={{ width: "100%", padding: "0.9rem", border: "none", borderRadius: 12, background: "linear-gradient(135deg, #E8673A, #1B5FE8)", color: "white", cursor: "pointer", fontWeight: 700, fontSize: "0.9rem", fontFamily: "'DM Sans', sans-serif", letterSpacing: "0.02em" }}>
            Set up your profile →
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ position: "fixed", inset: 0, background: "#1e1a35", zIndex: 500, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: isMobile ? "0" : "1rem", overflowY: "auto" }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <style>{`@keyframes authShake { 0%,100% { transform: translateX(0); } 15% { transform: translateX(-10px); } 30% { transform: translateX(10px); } 45% { transform: translateX(-8px); } 60% { transform: translateX(8px); } 75% { transform: translateX(-4px); } 90% { transform: translateX(4px); } }`}</style>
      <div style={{ background: "#FFFDF9", borderRadius: isMobile ? 0 : 22, padding: isMobile ? "1.5rem 1.25rem 1.25rem" : "2rem 2rem 1.75rem", width: "100%", margin: isMobile ? 0 : "auto", minHeight: isMobile ? "100vh" : "auto", maxWidth: isMobile ? "none" : 440, boxShadow: isMobile ? "none" : "0 32px 80px rgba(0,0,0,0.28)", position: "relative", animation: shake ? "authShake 0.45s cubic-bezier(.36,.07,.19,.97)" : undefined }}>
        <button onClick={onClose} aria-label="Close" style={{ position: "absolute", top: "1rem", right: "1rem", background: "none", border: "none", fontSize: "1.2rem", cursor: "pointer", color: "#7A6753", lineHeight: 1 }}>✕</button>

        {/* Logo */}
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "1.5rem" }}>
          <AttuneMark width={28} />
          <span style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: "1.05rem", fontWeight: 700, color: "#0E0B07" }}>Attune</span>
        </div>

        {/* Tab switcher */}
        <div style={{ display: "flex", background: "#F3EDE6", borderRadius: 10, padding: "0.22rem", marginBottom: "1.5rem" }}>
          {["signup", "login"].map(t => (
            <button key={t} onClick={() => {
              // On the sign-in page (login context), creating an account means
              // choosing a package first, so send them to the in-page get-started
              // flow. The in-modal signup form is only for post-purchase setup,
              // where the person already has a package (mode === "signup").
              if (t === "signup" && mode !== "signup") { window.location.href = "/start"; return; }
              setTab(t); setErr("");
            }}
              style={{ flex: 1, padding: "0.5rem", borderRadius: 8, border: "none", cursor: "pointer", fontFamily: "'DM Sans', sans-serif", fontSize: "0.82rem", fontWeight: 600, background: tab === t ? "white" : "transparent", color: tab === t ? "#0E0B07" : "#7A6753", boxShadow: tab === t ? "0 1px 4px rgba(0,0,0,0.1)" : "none", transition: "all 0.15s" }}>
              {t === "signup" ? "Create account" : "Sign in"}
            </button>
          ))}
        </div>

        {tab === "signup" ? (
          <>
            <div style={{ fontFamily: "'Playfair Display',Georgia,serif", fontSize: "1.1rem", fontWeight: 700, color: "#0E0B07", marginBottom: "0.35rem" }}>Set up your profile</div>
            <p style={{ fontSize: "0.78rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", marginBottom: "1.25rem", lineHeight: 1.55 }}>Your answers are private until both of you are done. We'll never show your partner what you wrote until results unlock.</p>
            {oauthIdentity ? (
              <div style={{ background: "#F3EDE6", borderRadius: 10, padding: "0.7rem 0.9rem", marginBottom: "1rem", fontSize: "0.75rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", lineHeight: 1.5 }}>
                Signed in with {oauthIdentity.provider === 'apple' ? 'Apple' : 'Google'}
                {oauthIdentity.user?.email ? ` as ${oauthIdentity.user.email}` : ''}. Finish your profile below.
              </div>
            ) : providerRow('Continue with')}
            {inp("Your first name", "name", "text", { autoComplete: 'given-name' })}
            <div style={{ fontSize: "0.7rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", fontWeight: 600, marginBottom: "0.35rem", letterSpacing: "0.04em" }}>Your pronouns</div>
            <div style={{ display: "flex", gap: "0.5rem", marginBottom: "0rem" }}>
              {["she/her", "he/him", "they/them"].map(p => (
                <button key={p} onClick={() => upd("pronouns", form.pronouns === p ? "" : p)}
                  style={{ flex: 1, padding: "0.45rem 0.3rem", borderRadius: 8, border: `1.5px solid ${form.pronouns === p ? "#E8673A" : "#E8DDD0"}`, background: form.pronouns === p ? "#FFF0EB" : "white", color: form.pronouns === p ? "#E8673A" : "#7A6753", fontSize: "0.72rem", fontWeight: 600, cursor: "pointer", fontFamily: "'DM Sans',sans-serif", transition: "all 0.12s", marginBottom: "0.6rem" }}>
                  {p}
                </button>
              ))}
            </div>
            {oauthIdentity ? null : (
              <>
                {inp("Your email", "email", "email")}
                {inp("Choose a password", "password", "password", { autoComplete: 'new-password' })}
              </>
            )}
            <div style={{ borderTop: "1px solid #E8DDD0", margin: "0.75rem 0 0.75rem" }} />
            <p style={{ fontSize: "0.75rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", marginBottom: "0.6rem", fontWeight: 600 }}>Your partner, required before results unlock</p>
            {inp("Partner's first name", "partnerName", "text", { autoComplete: 'off' })}
            <div style={{ fontSize: "0.7rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", fontWeight: 600, marginBottom: "0.35rem", letterSpacing: "0.04em" }}>Partner's pronouns</div>
            <div style={{ display: "flex", gap: "0.5rem", marginBottom: "0rem" }}>
              {["she/her", "he/him", "they/them"].map(p => (
                <button key={p} onClick={() => upd("partnerPronouns", form.partnerPronouns === p ? "" : p)}
                  style={{ flex: 1, padding: "0.45rem 0.3rem", borderRadius: 8, border: `1.5px solid ${form.partnerPronouns === p ? "#1B5FE8" : "#E8DDD0"}`, background: form.partnerPronouns === p ? "#EEF0FF" : "white", color: form.partnerPronouns === p ? "#1B5FE8" : "#7A6753", fontSize: "0.72rem", fontWeight: 600, cursor: "pointer", fontFamily: "'DM Sans',sans-serif", transition: "all 0.12s", marginBottom: "0.6rem" }}>
                  {p}
                </button>
              ))}
            </div>
            {inp("Partner's email. We'll send them an invite", "partnerEmail", "email",
              // Not 'username': this is the partner's address, and a password
              // manager pairing it with this person's password would save the
              // wrong credential.
              { autoComplete: 'off' })}
            <div style={{ background: "#F3EDE6", borderRadius: 10, padding: "0.75rem 1rem", marginBottom: "0.85rem", display: "flex", gap: "0.6rem", alignItems: "flex-start" }}>
              <span style={{ fontSize: "0.82rem", flexShrink: 0 }}>✦</span>
              <p style={{ fontSize: "0.72rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", lineHeight: 1.6, margin: 0 }}>Attune uses your names and pronouns to personalize your results, making the insights feel specific to you two, not generic.</p>
            </div>

            {/* ── Optional demographics ──
                Collected anonymously for aggregate research. Used in admin
                charts to understand who's using Attune and how to serve
                different couple profiles better. All fields optional. */}
            <div style={{ marginBottom: "1rem" }}>
              <div style={{ fontSize: "0.78rem", fontWeight: 600, color: "#0E0B07", fontFamily: "'DM Sans',sans-serif", padding: "0.65rem 0 0.2rem" }}>
                {ABOUT_YOU.title}
              </div>
              <p style={{ fontSize: "0.7rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", lineHeight: 1.6, marginBottom: "0.9rem", marginTop: "0.3rem" }}>
                {ABOUT_YOU.why}
              </p>
              {/* The five questions come from api/_lib/profile-setup-copy.js, which
                  the app's profile setup reads too. They were typed here and
                  nowhere else, so the website asked them and the app did not,
                  and the Demographics page is built on these columns. */}
              {ABOUT_YOU.fields.map(({ key: k, label, options: opts }) => (
                <div key={k} style={{ marginBottom: "0.65rem" }}>
                  <label style={{ fontSize: "0.68rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", display: "block", marginBottom: "0.2rem" }}>{label}</label>
                  <select value={form[k]} onChange={e => upd(k, e.target.value)}
                    style={{ width: "100%", padding: "0.55rem 0.75rem", border: "1.5px solid #E8DDD0", borderRadius: 8, fontSize: "0.8rem", fontFamily: "'DM Sans',sans-serif", color: "#0E0B07", background: "#FFFDF9" }}>
                    {opts.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
                  </select>
                </div>
              ))}
            </div>

            <label style={{ display: "flex", alignItems: "flex-start", gap: "0.6rem", cursor: "pointer", marginBottom: "1.25rem", marginTop: "0.25rem" }}>
              <input type="checkbox" checked={form.emailOptIn} onChange={e => upd("emailOptIn", e.target.checked)}
                style={{ marginTop: "0.2rem", accentColor: "#E8673A", width: 15, height: 15, flexShrink: 0 }} />
              <span style={{ fontSize: "0.72rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", lineHeight: 1.55 }}>
                Send me occasional opportunities to continue relationship growth through Attune.
              </span>
            </label>
            {err && <p style={{ color: "#ef4444", fontSize: "0.75rem", fontFamily: "'DM Sans',sans-serif", marginBottom: "0.75rem" }}>{err}</p>}
            <button onClick={oauthIdentity ? handleOAuthFinish : handleSignup} disabled={loading}
              style={{ width: "100%", padding: "0.9rem", background: "linear-gradient(135deg, #E8673A, #d45a2e)", color: "white", border: "none", borderRadius: 12, fontSize: "0.85rem", fontWeight: 700, cursor: loading ? "default" : "pointer", fontFamily: "'DM Sans',sans-serif", opacity: loading ? 0.7 : 1 }}>
              {loading ? <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", gap: "0.55rem" }}><InlineSpinner /> Creating account…</span> : oauthIdentity ? "Finish setting up →" : "Create account →"}
            </button>
          </>
        ) : tab === "login" ? (
          <>
            <div style={{ fontFamily: "'Playfair Display',Georgia,serif", fontSize: "1.1rem", fontWeight: 700, color: "#0E0B07", marginBottom: "1.25rem" }}>Welcome back</div>
            {providerRow('Sign in with')}
            {inp("Email", "email", "email")}
            {inp("Password", "password", "password")}
            {err && <p style={{ color: "#ef4444", fontSize: "0.75rem", fontFamily: "'DM Sans',sans-serif", marginBottom: "0.75rem" }}>{err}</p>}
            <button onClick={handleLogin} disabled={loading}
              style={{ width: "100%", padding: "0.9rem", background: "#0E0B07", color: "white", border: "none", borderRadius: 12, fontSize: "0.85rem", fontWeight: 700, cursor: loading ? "default" : "pointer", fontFamily: "'DM Sans',sans-serif", opacity: loading ? 0.7 : 1 }}>
              {loading ? <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", gap: "0.55rem" }}><InlineSpinner /> Signing in…</span> : "Sign in →"}
            </button>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "0.85rem" }}>
              <p style={{ fontSize: "0.75rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", margin: 0 }}>
                No account yet?{" "}
                <button onClick={() => { if (mode !== "signup") { window.location.href = "/start"; } else { setTab("signup"); } }} style={{ background: "none", border: "none", color: "#E8673A", fontWeight: 700, cursor: "pointer", fontSize: "0.75rem", fontFamily: "'DM Sans',sans-serif" }}>Get started →</button>
              </p>
              <button onClick={() => { setTab("reset"); setErr(""); setResetSent(false); }} style={{ background: "none", border: "none", color: "#7A6753", fontSize: "0.72rem", cursor: "pointer", fontFamily: "'DM Sans',sans-serif", textDecoration: "underline" }}>Forgot password?</button>
            </div>
          </>
        ) : tab === "reset" ? (
          <>
            {resetSent ? (
              <div style={{ textAlign: "center", padding: "1.5rem 0" }}>
                <div style={{ width: 52, height: 52, borderRadius: "50%", background: "linear-gradient(135deg,#E8673A,#1B5FE8)", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 1rem", fontSize: "1.4rem" }}>✓</div>
                <div style={{ fontFamily: "'Playfair Display',Georgia,serif", fontSize: "1.1rem", fontWeight: 700, color: "#0E0B07", marginBottom: "0.5rem" }}>Check your inbox</div>
                <p style={{ fontSize: "0.82rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", lineHeight: 1.6, marginBottom: "1.5rem" }}>
                  If an account exists for <strong style={{ color: "#0E0B07" }}>{form.email}</strong>, we've sent a reset link. It expires in 30 minutes.
                </p>
                <button onClick={() => { setTab("login"); setErr(""); setResetSent(false); }} style={{ background: "none", border: "none", color: "#E8673A", fontWeight: 700, cursor: "pointer", fontSize: "0.78rem", fontFamily: "'DM Sans',sans-serif" }}>← Back to sign in</button>
              </div>
            ) : (
              <>
                <div style={{ fontFamily: "'Playfair Display',Georgia,serif", fontSize: "1.1rem", fontWeight: 700, color: "#0E0B07", marginBottom: "0.35rem" }}>Reset your password</div>
                <p style={{ fontSize: "0.78rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", marginBottom: "1.25rem", lineHeight: 1.55 }}>Enter the email you used to create your account. We'll send you a link to reset your password.</p>
                {inp("Your email address", "email", "email")}
                {err && <p style={{ color: "#ef4444", fontSize: "0.75rem", fontFamily: "'DM Sans',sans-serif", marginBottom: "0.75rem" }}>{err}</p>}
                <button onClick={handleReset} disabled={loading}
                  style={{ width: "100%", padding: "0.9rem", background: "#0E0B07", color: "white", border: "none", borderRadius: 12, fontSize: "0.85rem", fontWeight: 700, cursor: loading ? "default" : "pointer", fontFamily: "'DM Sans',sans-serif", opacity: loading ? 0.7 : 1 }}>
                  {loading ? "Sending…" : "Send reset link →"}
                </button>
                <p style={{ textAlign: "center", marginTop: "0.85rem", fontSize: "0.75rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif" }}>
                  <button onClick={() => { setTab("login"); setErr(""); }} style={{ background: "none", border: "none", color: "#E8673A", fontWeight: 700, cursor: "pointer", fontSize: "0.75rem", fontFamily: "'DM Sans',sans-serif" }}>← Back to sign in</button>
                </p>
              </>
            )}
          </>
        ) : null}
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// PARTNER B LANDING SCREEN — shown when opening an invite link with no account
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// NEW PASSWORD SCREEN — shown when user arrives via password reset email link
// ─────────────────────────────────────────────────────────────────────────────
function NewPasswordScreen({ onDone }) {
  const [password, setPassword] = React.useState('');
  const [confirm, setConfirm] = React.useState('');
  const [err, setErr] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [done, setDone] = React.useState(false);

  const handleSubmit = async () => {
    if (password.length < 6) return setErr('Password must be at least 6 characters.');
    if (password !== confirm) return setErr('Passwords do not match.');
    setLoading(true);
    setErr('');
    try {
      const { supabase: sb, hasSupabase } = await import('./supabase.js');
      if (hasSupabase()) {
        const { error } = await sb.auth.updateUser({ password });
        if (error) { setLoading(false); return setErr(error.message); }
      }
      setDone(true);
      setLoading(false);
      setTimeout(onDone, 1800);
    } catch { setLoading(false); setErr('Something went wrong. Please try again.'); }
  };

  // Reset form: always a new password, so the manager offers to update the
  // stored credential rather than filling the old one back in.
  const inp = (placeholder, val, onChange, type = 'password') => (
    <input type={type} placeholder={placeholder} autoComplete={type === 'password' ? 'new-password' : 'username'}
      value={val} onChange={e => { onChange(e.target.value); setErr(''); }}
      style={{ width: '100%', padding: '0.78rem 1rem', border: `1.5px solid ${err ? '#ef4444' : '#E8DDD0'}`, borderRadius: 11, fontSize: '0.88rem', fontFamily: "'DM Sans', sans-serif", color: '#0E0B07', background: '#FFFDF9', outline: 'none', marginBottom: '0.6rem', boxSizing: 'border-box' }} />
  );

  return (
    <div style={{ minHeight: '100vh', background: '#F3EDE6', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '2rem 1.25rem', fontFamily: "'DM Sans', sans-serif" }}>
      <link href={FONT_LINK} rel="stylesheet" />
      <div style={{ background: '#FFFDF9', borderRadius: 22, padding: '2.25rem 2rem', width: '100%', maxWidth: 400, boxShadow: '0 24px 64px rgba(0,0,0,0.1)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1.75rem' }}>
          <AttuneMark width={28} />
          <span style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: '0.95rem', fontWeight: 700, color: '#0E0B07' }}>Attune</span>
        </div>
        {done ? (
          <div style={{ textAlign: 'center', padding: '1rem 0' }}>
            <div style={{ width: 52, height: 52, borderRadius: '50%', background: 'linear-gradient(135deg,#10b981,#059669)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem', fontSize: '1.4rem' }}>✓</div>
            <div style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: '1.15rem', fontWeight: 700, color: '#0E0B07', marginBottom: '0.5rem' }}>Password updated.</div>
            <p style={{ fontSize: '0.82rem', color: '#7A6753', lineHeight: 1.6 }}>Signing you in now…</p>
          </div>
        ) : (
          <>
            <div style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: '1.15rem', fontWeight: 700, color: '#0E0B07', marginBottom: '0.35rem' }}>Set a new password</div>
            <p style={{ fontSize: '0.78rem', color: '#7A6753', marginBottom: '1.5rem', lineHeight: 1.55 }}>Choose something you haven't used before.</p>
            {inp('New password', password, setPassword)}
            {inp('Confirm password', confirm, setConfirm)}
            {err && <p style={{ color: '#ef4444', fontSize: '0.75rem', marginBottom: '0.75rem' }}>{err}</p>}
            <button onClick={handleSubmit} disabled={loading}
              style={{ width: '100%', padding: '0.9rem', background: 'linear-gradient(135deg,#E8673A,#1B5FE8)', color: 'white', border: 'none', borderRadius: 12, fontSize: '0.85rem', fontWeight: 700, cursor: loading ? 'default' : 'pointer', opacity: loading ? 0.7 : 1, fontFamily: "'DM Sans', sans-serif" }}>
              {loading ? 'Saving…' : 'Set password →'}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

function PartnerLandingScreen({ inviteFrom, inviteCode, onCreateAccount }) {
  // The invite link carries the email the inviter addressed it to (iie =
  // invitee email). Prefill it so the invitee doesn't retype it, and so it
  // matches the address that gets auto-confirmed. pae is the inviter's own
  // email, kept only to block the invitee from reusing it.
  const _iie = (new URLSearchParams(window.location.search).get('iie') || '').trim().toLowerCase();
  const [form, setForm] = React.useState({ name: '', email: _iie, password: '', ageRange: '', gender: '', relationshipStatus: '', relationshipLength: '', children: '', signupSource: '' });
  const [loading, setLoading] = React.useState(false);
  const [err, setErr] = React.useState('');
  // When signup reports the email already has an account, flip this screen
  // into an inline sign-in (still inside the invite flow) instead of bouncing
  // the invitee to the main sign-in page, where they'd land disconnected from
  // the invite.
  const [existing, setExisting] = React.useState(false);
  const upd = (k, v) => setForm(p => ({ ...p, [k]: v }));

  // Unified signup: creates a real Supabase auth user + profiles row for
  // Partner B (same as Partner A), then calls /api/partner-sync?action=link
  // to wire both partners' partner_profile_id FKs together.
  const handleSubmit = async () => {
    if (!form.name.trim()) return setErr('Please enter your first name.');
    if (!form.email.trim() || !form.email.includes('@')) return setErr('Please enter a valid email.');
    if (!form.password || form.password.length < 6) return setErr('Password must be at least 6 characters.');

    // Block using Partner A's email. Without this, Supabase says "account
    // already exists, try signing in" — which is misleading because signing
    // in would log them in AS Partner A, not as themselves. Each partner
    // needs their own account.
    const _pae = (new URLSearchParams(window.location.search).get('pae') || '').toLowerCase();
    if (_pae && form.email.trim().toLowerCase() === _pae) {
      return setErr("That's your partner's email. Each of you needs your own account, so use a different email.");
    }

    setLoading(true);
    setErr('');

    try {
      const { supabase: sb, hasSupabase } = await import('./supabase.js');

      // Fallback: if Supabase isn't configured (dev without env vars),
      // fall back to the old local-only account so the demo still works.
      if (!hasSupabase()) {
        const acct = {
          email: form.email.trim().toLowerCase(),
          name: form.name.trim(),
          partnerName: inviteFrom,
          inviteCode: inviteCode,
          joinedViaInvite: true,
          createdAt: Date.now(),
        };
        try { localStorage.setItem('attune_account', JSON.stringify(acct)); } catch {}
        setLoading(false);
        onCreateAccount(acct);
        return;
      }

      // Real signup — same flow as Partner A's AuthModal
      const { data: authData, error: authErr } = await sb.auth.signUp({
        email: form.email.trim().toLowerCase(),
        password: form.password,
        options: {
          data: { name: form.name.trim() },
          emailRedirectTo: `${window.location.origin}/app`,
        },
      });
      if (authErr) {
        // "User already registered" can mean two things from this screen:
        // (1) you're trying to sign up as yourself (your own invite), or
        // (2) you genuinely already have an Attune account.
        // Either way, signing in via this partner-landing flow would log
        // them in as Partner A, not as Partner B. Tell them to sign in
        // through the regular sign-in screen instead.
        if (authErr.message.includes('registered') || authErr.message.includes('already')) {
          // This email already has an account. Flip to inline sign-in on this
          // same screen so they attach to the invite, instead of sending them
          // to the main sign-in page. Partner A's email is already blocked
          // above, so this can only be the invitee's own account.
          setExisting(true);
          setErr('');
          setLoading(false);
          return;
        } else {
          setErr(authErr.message);
        }
        setLoading(false);
        return;
      }
      if (!authData?.user) {
        setErr('Signup failed. Please try again.');
        setLoading(false);
        return;
      }

      // Create the profile row via service-role endpoint (same reason as
      // Partner A: when email confirmation is ON, no session = RLS blocks
      // direct upsert). Partner B does NOT get an invite_code of their own.
      // We retry once on failure since the partner_sync link below depends
      // on this row existing.
      let profileCreated = false;
      for (let attempt = 0; attempt < 2 && !profileCreated; attempt++) {
        try {
          const r = await fetch('/api/create-profile', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              userId:              authData.user.id,
              name:                form.name.trim(),
              pronouns:            '',
              partnerName:         inviteFrom || '',
              partnerPronouns:     '',
              partnerEmail:        '',
              emailOptIn:          true,
              inviteCode:          '',  // Partner B has no invite of their own
              joinedViaInvite:     true,
              pkg:                 'core',  // Inherits package via partner link
              ageRange:            form.ageRange || null,
              gender:              form.gender || null,
              relationshipStatus:  form.relationshipStatus || null,
              relationshipLength:  form.relationshipLength || null,
              children:            form.children || null,
              signupSource:        form.signupSource || null,
            }),
          });
          if (r.ok) {
            profileCreated = true;
          } else if (attempt === 1) {
            console.warn('[Attune] Partner B create-profile failed after retry:', await r.text());
          }
        } catch (e) {
          if (attempt === 1) console.warn('[Attune] Partner B create-profile error:', e);
        }
      }

      // Link both partners via /api/partner-sync. Only proceed if profile
      // was created — otherwise the link would update zero rows on Partner
      // B's side and leave the relationship asymmetric.
      let inheritedEntitlements = null;
      if (profileCreated) {
        try {
          // Send the access token when we have one (auto-confirmed signup).
          // partner-sync prefers a verified token; it falls back to matching
          // the invited email for the pending-confirm window.
          const _linkHeaders = { 'Content-Type': 'application/json' };
          if (authData?.session?.access_token) _linkHeaders.Authorization = `Bearer ${authData.session.access_token}`;
          const linkRes = await fetch('/api/partner-sync', {
            method: 'POST',
            headers: _linkHeaders,
            body: JSON.stringify({ action: 'link', inviteCode, partnerBId: authData.user.id }),
          });
          if (!linkRes.ok) {
            const j = await linkRes.json().catch(() => ({}));
            // 409 = invite already used by someone else. We need to surface
            // this to the user, otherwise they end up with a working auth
            // account but no link to Partner A — they'd see a confusing
            // dashboard with no partner data and no way to recover.
            if (linkRes.status === 409) {
              setErr('This invite link has already been used by someone else. If you think this is a mistake, ask your partner to send a fresh link.');
              setLoading(false);
              return;
            }
            // For other server errors, log + surface a generic retry message.
            console.warn('[Attune] Partner link failed:', j.error);
            setErr('Something went wrong linking your accounts. Please try again in a moment.');
            setLoading(false);
            return;
          }
          // Inherit Partner A's package + add-ons so Partner B's account (and
          // the guided exercise flow that runs next) matches their entitlements.
          let _linkJson = null;
          try { _linkJson = await linkRes.json(); } catch {}
          inheritedEntitlements = _linkJson?.inherited || null;
          // When the signup email matches the invited address, partner-sync
          // auto-confirms it. Establish the session right away so the
          // exercises run fully authenticated (saves hit profiles directly).
          if (_linkJson?.emailConfirmed) {
            try { await sb.auth.signInWithPassword({ email: form.email.trim().toLowerCase(), password: form.password }); }
            catch (e) { console.warn('[Attune] post-link sign-in failed, continuing pending-confirm:', e); }
          }
          // Note: partner_joined_notification is sent server-side as part
          // of the link action (Issue 4.9). The endpoint has access to
          // Partner A's email via service role; we don't expose it here.
        } catch (e) {
          console.warn('[Attune] Partner link error:', e);
          setErr('Something went wrong linking your accounts. Please try again in a moment.');
          setLoading(false);
          return;
        }
      } else {
        // Profile creation never succeeded — surface to user so they don't
        // proceed with a broken state silently. This is the rare path
        // where retries didn't help (server down, network broken, etc.)
        setErr('Account creation hit a snag. Please try again in a moment.');
        setLoading(false);
        return;
      }

      // Build the local account object in the standard shape (same as
      // Partner A). joinedViaInvite is the only marker; isPartnerB is gone.
      const acct = {
        id: authData.user.id,
        email: form.email.trim().toLowerCase(),
        name: form.name.trim(),
        partnerName: inviteFrom,
        partnerPronouns: inheritedEntitlements?.partnerPronouns || '',
        inviteCode: inviteCode,         // Retained so the dashboard can look up partner
        joinedViaInvite: true,
        pkg:             inheritedEntitlements?.pkg || 'core',
        addonReflection: !!inheritedEntitlements?.addonReflection,
        addonBudget:     !!inheritedEntitlements?.addonBudget,
        addonChecklist:  !!inheritedEntitlements?.addonChecklist,
        addonIntimacy:     !!inheritedEntitlements?.addonIntimacy,
        addonConflict:     !!inheritedEntitlements?.addonConflict,
        addonWorkbook:   inheritedEntitlements?.addonWorkbook || '',
        createdAt: Date.now(),
      };
      // Clear stale data from any prior user/demo on this browser. Without
      // this, Partner B can inherit Partner A's exercises, workbook flag,
      // partner_session, etc. Single source of truth at module top.
      clearAllUserLocalStorage();
      try { localStorage.setItem('attune_account', JSON.stringify(acct)); } catch {}
      setLoading(false);
      onCreateAccount(acct);
    } catch (e) {
      console.error('[Attune] Partner B signup error:', e);
      setErr('Signup failed. Please try again.');
      setLoading(false);
    }
  };

  // Inline sign-in for an invitee whose email already has an account. Signs
  // them in, then attaches them to Partner A via the same link step signup
  // uses. Idempotent for the same person; a 409 means a different account
  // already claimed this invite.
  const handleSignIn = async () => {
    if (!form.email.trim() || !form.email.includes('@')) return setErr('Please enter a valid email.');
    if (!form.password) return setErr('Please enter your password.');
    setLoading(true);
    setErr('');
    try {
      const { supabase: sb, hasSupabase } = await import('./supabase.js');
      if (!hasSupabase()) { setErr('Sign-in is unavailable right now. Please try again in a moment.'); setLoading(false); return; }
      const { data: si, error: siErr } = await sb.auth.signInWithPassword({ email: form.email.trim().toLowerCase(), password: form.password });
      if (siErr || !si?.user) {
        setErr("That password doesn't match this email. Try again, or reset it from the sign-in page.");
        setLoading(false);
        return;
      }
      let inherited = null;
      try {
        const linkRes = await fetch('/api/partner-sync', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(si.session?.access_token ? { Authorization: `Bearer ${si.session.access_token}` } : {}),
          },
          body: JSON.stringify({ action: 'link', inviteCode, partnerBId: si.user.id }),
        });
        if (!linkRes.ok) {
          if (linkRes.status === 409) {
            setErr('This invite link has already been used by someone else. Ask your partner to send a fresh link.');
            setLoading(false);
            return;
          }
          console.warn('[Attune] invite sign-in link failed:', linkRes.status);
          setErr('Something went wrong joining your partner. Please try again in a moment.');
          setLoading(false);
          return;
        }
        try { inherited = (await linkRes.json())?.inherited || null; } catch {}
      } catch (e) {
        console.warn('[Attune] invite sign-in link error:', e);
        setErr('Something went wrong joining your partner. Please try again in a moment.');
        setLoading(false);
        return;
      }
      const acct = {
        id: si.user.id,
        email: form.email.trim().toLowerCase(),
        name: si.user.user_metadata?.name || form.name.trim() || '',
        partnerName: inviteFrom,
        partnerPronouns: inherited?.partnerPronouns || '',
        inviteCode,
        joinedViaInvite: true,
        pkg: inherited?.pkg || 'core',
        addonReflection: !!inherited?.addonReflection,
        addonBudget: !!inherited?.addonBudget,
        addonChecklist: !!inherited?.addonChecklist,
        addonIntimacy: !!inherited?.addonIntimacy,
        addonConflict: !!inherited?.addonConflict,
        addonWorkbook: inherited?.addonWorkbook || '',
        createdAt: Date.now(),
      };
      clearAllUserLocalStorage();
      try { localStorage.setItem('attune_account', JSON.stringify(acct)); } catch {}
      setLoading(false);
      onCreateAccount(acct);
    } catch (e) {
      console.error('[Attune] invite sign-in error:', e);
      setErr('Sign-in failed. Please try again.');
      setLoading(false);
    }
  };

  const inp = (placeholder, key, type = 'text') => (
    <input type={type} placeholder={placeholder} value={form[key]}
      onChange={e => { upd(key, e.target.value); setErr(''); }}
      style={{ width: '100%', padding: '0.78rem 1rem', border: '1.5px solid #E8DDD0', borderRadius: 11, fontSize: '0.88rem', fontFamily: "'DM Sans', sans-serif", color: '#0E0B07', background: '#FFFDF9', outline: 'none', marginBottom: '0.6rem', boxSizing: 'border-box' }} />
  );

  return (
    <div style={{ minHeight: '100vh', background: '#1e1a35', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '2rem 1.25rem', fontFamily: "'DM Sans', sans-serif" }}>
      <link href={FONT_LINK} rel="stylesheet" />
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '2.5rem' }}>
        <AttuneMark width={32} />
        <span style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: '1.05rem', fontWeight: 700, color: 'white' }}>Attune</span>
      </div>

      <div style={{ background: '#FFFDF9', borderRadius: 24, padding: '2.25rem 2rem', width: '100%', maxWidth: 420, boxShadow: '0 32px 80px rgba(0,0,0,0.45)' }}>
        {/* Invite badge */}
        <div style={{ background: 'linear-gradient(135deg, rgba(232,103,58,0.07), rgba(27,95,232,0.07))', border: '1.5px solid rgba(232,103,58,0.22)', borderRadius: 14, padding: '1rem 1.2rem', marginBottom: '1.75rem', display: 'flex', alignItems: 'center', gap: '0.85rem' }}>
          <div style={{ width: 38, height: 38, borderRadius: '50%', background: 'linear-gradient(135deg, #E8673A, #1B5FE8)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.2" strokeLinecap="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
          </div>
          <div>
            <div style={{ fontSize: '0.62rem', fontWeight: 700, color: '#E8673A', fontFamily: "'DM Sans', sans-serif", letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: '0.2rem' }}>You've been invited</div>
            <div style={{ fontSize: '0.92rem', fontWeight: 700, color: '#0E0B07', fontFamily: "'Playfair Display', Georgia, serif", lineHeight: 1.25 }}>{inviteFrom} invited you to take Attune together</div>
          </div>
        </div>

        <p style={{ fontSize: '0.8rem', color: '#7A6753', fontFamily: "'DM Sans', sans-serif", lineHeight: 1.7, marginBottom: '1.5rem' }}>
          {existing
            ? `You already have an Attune account with this email. Sign in to join ${inviteFrom}. Your answers stay private until you're both done, then your results unlock together.`
            : WAITING.BEFORE_PURCHASE}
        </p>

        {!existing && inp('Your first name', 'name', 'text', { autoComplete: 'given-name' })}
        {inp('Your email', 'email', 'email')}
        {_iie && form.email.trim().toLowerCase() === _iie && (
          <p style={{ fontSize: '0.68rem', color: '#7A6753', fontFamily: "'DM Sans', sans-serif", margin: '-0.35rem 0 0.6rem', lineHeight: 1.4 }}>
            From your invite. Change it if this isn't your email.
          </p>
        )}
        {inp(existing ? 'Password' : 'Password (6+ characters)', 'password', 'password',
          // new-password only when creating: telling a manager 'new' on a
          // sign-in form makes it offer to overwrite a stored credential.
          { autoComplete: existing ? 'current-password' : 'new-password' })}

        {!existing && (
        <div style={{ marginBottom: "1rem" }}>
          {/* From ABOUT_YOU, which this file already imports and which the app
              also renders. Both sentences were typed here as well, and the two
              had already drifted: this said "Tell us about yourself" while the
              module, and the app, said "yourselves". */}
          <div style={{ fontSize: "0.78rem", fontWeight: 600, color: "#0E0B07", fontFamily: "'DM Sans',sans-serif", padding: "0.65rem 0 0.2rem" }}>
            {ABOUT_YOU.title}
          </div>
          <p style={{ fontSize: "0.7rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", lineHeight: 1.6, marginBottom: "0.9rem", marginTop: "0.3rem" }}>
            {ABOUT_YOU.why}
          </p>
          {[
            { k: "ageRange", label: "Your age range", opts: [["", "Prefer not to say"], ["18-24", "18–24"], ["25-34", "25–34"], ["35-44", "35–44"], ["45-54", "45–54"], ["55+", "55 or older"]] },
            { k: "relationshipStatus", label: "Relationship status", opts: [["", "Prefer not to say"], ["dating", "Dating / together"], ["engaged", "Engaged"], ["married", "Married"], ["remarried", "Remarried"], ["partnership", "Domestic partnership"]] },
            { k: "relationshipLength", label: "How long together", opts: [["", "Prefer not to say"], ["<1", "Less than 1 year"], ["1-2", "1–2 years"], ["3-5", "3–5 years"], ["6-10", "6–10 years"], ["11-20", "11–20 years"], ["20+", "20+ years"]] },
            { k: "children", label: "Children", opts: [["", "Prefer not to say"], ["none", "None"], ["1", "1"], ["2", "2"], ["3+", "3 or more"], ["expecting", "Expecting"]] },
            { k: "signupSource", label: "How did you hear about Attune?", opts: [["", "Prefer not to say"], ["friend", "Friend or family"], ["social", "Social media"], ["search", "Search"], ["gift", "Received as a gift"], ["therapist", "Therapist or counselor"], ["other", "Other"]] },
          ].map(({ k, label, opts }) => (
            <div key={k} style={{ marginBottom: "0.65rem" }}>
              <label style={{ fontSize: "0.68rem", color: "#7A6753", fontFamily: "'DM Sans',sans-serif", display: "block", marginBottom: "0.2rem" }}>{label}</label>
              <select value={form[k]} onChange={e => upd(k, e.target.value)}
                style={{ width: "100%", padding: "0.55rem 0.75rem", border: "1.5px solid #E8DDD0", borderRadius: 8, fontSize: "0.8rem", fontFamily: "'DM Sans',sans-serif", color: "#0E0B07", background: "#FFFDF9" }}>
                {opts.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
              </select>
            </div>
          ))}
        </div>
        )}

        {err && <p style={{ color: '#ef4444', fontSize: '0.75rem', fontFamily: "'DM Sans', sans-serif", marginBottom: '0.75rem' }}>{err}</p>}

        <button onClick={existing ? handleSignIn : handleSubmit} disabled={loading}
          style={{ width: '100%', padding: '0.9rem', background: 'linear-gradient(135deg, #E8673A, #1B5FE8)', color: 'white', border: 'none', borderRadius: 12, fontSize: '0.85rem', fontWeight: 700, cursor: loading ? 'default' : 'pointer', fontFamily: "'DM Sans', sans-serif", opacity: loading ? 0.7 : 1, transition: 'opacity 0.2s', marginBottom: '0.85rem' }}>
          {loading
            ? <span style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '0.55rem' }}><InlineSpinner /> {existing ? 'Signing you in…' : 'Setting up your account…'}</span>
            : (existing ? 'Sign in and continue →' : 'Start my exercises →')}
        </button>
        {existing && (
          <p onClick={() => { setExisting(false); setErr(''); }}
            style={{ fontSize: '0.72rem', color: '#1B5FE8', textAlign: 'center', cursor: 'pointer', fontFamily: "'DM Sans', sans-serif", marginBottom: '0.85rem', fontWeight: 600 }}>
            Not your account? Create a new one
          </p>
        )}

        <p style={{ fontSize: '0.68rem', color: '#A66534', textAlign: 'center', fontFamily: "'DM Sans', sans-serif", lineHeight: 1.6 }}>
          Attune uses your names to personalize your results. Your answers are never shared with your partner individually, only as part of your joint results.
        </p>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// PARTNER B EXERCISE FLOW — clean exercise wrapper for invited partner
// ─────────────────────────────────────────────────────────────────────────────
function PartnerBExerciseFlow({ account, onComplete }) {
  const hasReflection = !!(account?.pkg === 'anniversary' || account?.addonReflection);
  const [step, setStep] = React.useState('intro'); // 'intro' | 'ex1' | 'ex2' | 'ex3' | 'done'
  const [ex1, setEx1] = React.useState(null);
  const [ex2, setEx2] = React.useState(null);

  // Browser back-button guard. Without this, pressing back from inside the
  // flow navigates out of the SPA entirely (and the session-restore path
  // then lands on the sign-in screen, reading as "it signed me out"). Push a
  // history entry on mount and, on popstate, step backward within the flow
  // (or send the user to the dashboard) instead of leaving the app.
  React.useEffect(() => {
    try { window.history.pushState({ attuneFlow: 'partnerB' }, ''); } catch {}
    const onPop = () => {
      // Re-push so a second back press is also caught while still in-flow.
      try { window.history.pushState({ attuneFlow: 'partnerB' }, ''); } catch {}
      setStep(s => {
        if (s === 'ex3') return 'ex2';
        if (s === 'ex2') return 'ex1';
        if (s === 'ex1') return 'intro';
        // From intro, leave the flow cleanly by going to the dashboard.
        try { window.location.href = '/app'; } catch {}
        return s;
      });
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  // In the unified model, Partner B saves to their OWN profile row
  // exactly like Partner A. Each exercise completion calls this helper
  // which persists to localStorage + profiles, then advances state.
  // Uses saveExerciseWithRetakeSnapshot to preserve prior-completion
  // answers automatically when this is a retake.
  const saveExercise = async (exNum, answers, extraPatch = {}) => {
    try {
      const { supabase: sb, hasSupabase } = await import('./supabase.js');
      if (hasSupabase() && account?.id) {
        const r = await saveExerciseWithRetakeSnapshot(sb, account.id, exNum, answers, extraPatch);
        if (r?.error && typeof window !== 'undefined' && window.__attuneShowToast) {
          window.__attuneShowToast("Couldn't sync your answers yet. They're saved on this device and will sync when you confirm your email and sign in here.");
        }
      }
    } catch (e) {
      console.warn('[Attune] Partner B save failed, continuing locally:', e);
    }
  };

  const handleEx1Done = async (answers) => {
    setEx1(answers);
    try { localStorage.setItem('attune_ex1', JSON.stringify(answers)); } catch {}
    await saveExercise(1, answers);
    setStep('ex2');
  };

  const handleEx2Done = async (answers) => {
    setEx2(answers);
    try { localStorage.setItem('attune_ex2', JSON.stringify(answers)); } catch {}
    await saveExercise(2, answers);
    if (hasReflection) {
      setStep('ex3');
    } else {
      finishSession(ex1, answers, null);
    }
  };

  const handleEx3Done = async (answers) => {
    try { localStorage.setItem('attune_ex3', JSON.stringify(answers)); } catch {}
    await saveExercise(3, answers, { ex3_completed: true, ex3_completed_at: new Date().toISOString(), ex3_version: ANNIVERSARY_VERSION });
    finishSession(ex1, ex2, answers);
  };

  const finishSession = (ex1Answers, ex2Answers, ex3Answers) => {
    // Legacy-compatible local marker so downstream code that checks for
    // completion still works during the transition.
    const session = {
      inviteCode: account.inviteCode,
      name: account.name,
      ex1: ex1Answers,
      ex2: ex2Answers,
      ...(ex3Answers ? { ex3: ex3Answers } : {}),
      completedAt: Date.now(),
    };
    try { localStorage.setItem('attune_partner_session', JSON.stringify(session)); } catch {}
    onComplete(session);
  };

  if (step === 'intro') return (
    <div style={{ minHeight: '100vh', background: '#1e1a35', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '2rem 1.25rem' }}>
      <link href={FONT_LINK} rel="stylesheet" />
      <div style={{ maxWidth: 480, width: '100%', textAlign: 'center' }}>
        <div style={{ fontSize: '0.62rem', letterSpacing: '0.22em', textTransform: 'uppercase', color: 'rgba(232,103,58,0.8)', fontFamily: "'DM Sans', sans-serif", fontWeight: 700, marginBottom: '1rem' }}>
          Your exercises ({account.name} &amp; {account.partnerName})
        </div>
        <div style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: 'clamp(1.6rem, 5vw, 2.4rem)', fontWeight: 700, color: 'white', lineHeight: 1.1, marginBottom: '1.25rem' }}>
          {hasReflection ? 'Three' : 'Two'} exercises.<br/>Your answers are yours alone.
        </div>
        {/* The sentence that used to sit here enumerated exercises 01, 02 and
            03 and described a product with two or three of them. Ellie: "I'm
            fine to just remove these 2 pieces of prose rather than adjust
            them." The three tiles below it already say what each exercise is,
            so the paragraph was a second telling that could go out of date on
            its own. */}
        <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center', marginBottom: '2.5rem', flexWrap: 'wrap' }}>
          {[{ num: '01', title: 'Communication', color: '#E8673A', desc: (PARTNER_VIEW_ENABLED ? PERSONALITY_QUESTIONS.length * 2 : PERSONALITY_QUESTIONS.length) + ' questions · 10 dimensions' }, { num: '02', title: 'Expectations', color: '#1B5FE8', desc: 'Responsibilities & life' }, ...(hasReflection ? [{ num: '03', title: 'Relationship Reflection', color: '#7C3AED', desc: 'Your story together' }] : [])].map(e => (
            <div key={e.num} style={{ background: 'rgba(255,255,255,0.06)', border: `1px solid ${e.color}33`, borderRadius: 14, padding: '1.1rem 1.4rem', textAlign: 'left', minWidth: 160 }}>
              <div style={{ fontSize: '0.58rem', letterSpacing: '0.18em', color: e.color, fontWeight: 700, fontFamily: "'DM Sans', sans-serif", textTransform: 'uppercase', marginBottom: '0.35rem' }}>Exercise {e.num}</div>
              <div style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: '1rem', fontWeight: 700, color: 'white', marginBottom: '0.25rem' }}>{e.title}</div>
              <div style={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.4)', fontFamily: "'DM Sans', sans-serif" }}>{e.desc}</div>
            </div>
          ))}
        </div>
        <div style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.15)', borderRadius: 12, padding: '1rem 1.25rem', marginBottom: '1.75rem', textAlign: 'left', maxWidth: 400, margin: '0 auto 1.75rem' }}>
          <div style={{ fontSize: '0.6rem', letterSpacing: '0.18em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.4)', fontFamily: "'DM Sans', sans-serif", fontWeight: 700, marginBottom: '0.5rem' }}>Before you start</div>
          <p style={{ fontSize: '0.78rem', color: 'rgba(255,255,255,0.7)', fontFamily: "'DM Sans', sans-serif", lineHeight: 1.65, margin: 0 }}>
            If this is <strong style={{ color: 'white' }}>{account.partnerName}</strong> checking your own partner's view, close this tab to prevent overwriting {account.name}'s results. Each partner uses their own account and their own link.
          </p>
        </div>
        <button onClick={() => setStep('ex1')}
          style={{ background: 'linear-gradient(135deg, #E8673A, #1B5FE8)', color: 'white', border: 'none', borderRadius: 14, padding: '0.9rem 2.5rem', fontSize: '0.85rem', fontWeight: 700, cursor: 'pointer', fontFamily: "'DM Sans', sans-serif", letterSpacing: '0.04em' }}>
          Begin Exercise 01 →
        </button>
      </div>
    </div>
  );

  if (step === 'ex1') return (
    <div style={{ minHeight: '100vh', background: C.warm }}>
      <link href={FONT_LINK} rel="stylesheet" />
      <div style={{ maxWidth: 860, margin: '0 auto', padding: '3rem 2rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '2rem' }}>
          <AttuneMark width={28} />
          <span style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: '0.95rem', fontWeight: 700, color: C.ink }}>Attune</span>
        </div>
        <Exercise01Flow userName={account.name} partnerName={account.partnerName} onComplete={handleEx1Done} skipIntro={true} />
      </div>
    </div>
  );

  if (step === 'ex2') return (
    <div style={{ minHeight: '100vh', background: C.warm }}>
      <link href={FONT_LINK} rel="stylesheet" />
      <div style={{ maxWidth: 860, margin: '0 auto', padding: '3rem 2rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '2rem' }}>
          <AttuneMark width={28} />
          <span style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: '0.95rem', fontWeight: 700, color: C.ink }}>Attune</span>
        </div>
        <ExpectationsExercise userName={account.name} partnerName={account.partnerName} onComplete={handleEx2Done} isAnniversary={["married","remarried"].includes(account.buyerRelationshipStatus || account.relationshipStatus)} />
      </div>
    </div>
  );

  if (step === 'ex3') return (
    <div>
      <div>
        <AnniversaryExercise userName={account.name} partnerName={account.partnerName} partnerPronouns={account.partnerPronouns || ""} onComplete={handleEx3Done} onBack={() => setStep('ex2')} />
      </div>
    </div>
  );

  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// PARTNER B COMPLETION SCREEN — exercises done, waiting or ready
// ─────────────────────────────────────────────────────────────────────────────
function PartnerBCompletionScreen({ partnerAName, partnerBName, partnerADone, partnerAPronouns = "" }) {
  // ── Fire results_viewed email to Partner B (Issue 5.6) ─────────────────
  // The standard results-viewed email only fires for the user who SEES the
  // results page (Partner A in the unified model). Partner B sees this
  // completion screen instead. Without this effect Partner B never gets a
  // notification that the results are ready.
  React.useEffect(() => {
    if (!partnerADone) return;
    const fired = (() => { try { return localStorage.getItem('attune_results_email_sent'); } catch { return null; } })();
    if (fired) return;
    try { localStorage.setItem('attune_results_email_sent', '1'); } catch {}
    (async () => {
      try {
        const acct = (() => { try { return JSON.parse(localStorage.getItem('attune_account') || 'null'); } catch { return null; } })();
        if (!acct?.email) return;
        // Find pkg flags from order/account so the upsell block matches
        // what Partner B already has access to
        const ord = (() => { try { return JSON.parse(localStorage.getItem('attune_order') || 'null'); } catch { return null; } })();
        await fetch('/api/send-email', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            type: 'results_viewed',
            userId: acct.id || null,
            toEmail: acct.email,
            toName: acct.name || partnerBName || '',
            partnerName: acct.partnerName || partnerAName || '',
            // Partner B can't see the couple type until they sign in on
            // Partner A's device, so leave it out of subject line
            coupleType: '',
            portalUrl: window.location.origin + '/app',
            hasReflection: !!(ord?.addon_reflection || acct?.pkg === 'anniversary'),
            hasBudget: !!(ord?.addon_budget || acct?.pkg === 'newlywed'),
            hasWorkbook: !!(ord?.addon_workbook),
            hasIntimacy: !!(ord?.addon_intimacy),
            hasChecklist: !!(ord?.addon_checklist || acct?.pkg === 'newlywed'),
          }),
        });

        // Also fire the workbook flash promo (idempotent on the server).
        try {
          if (!localStorage.getItem('attune_wb_promo_fired') && !(ord?.addonWorkbook || ord?.addon_workbook)) {
            localStorage.setItem('attune_wb_promo_fired', '1');
            const { supabase: _sbp2 } = await import('./supabase.js');
            const { data: { session: _sp2 } } = await _sbp2.auth.getSession();
            await fetch('/api/generate-workbook-promo', {
              method: 'POST', headers: { 'Content-Type': 'application/json', ...(_sp2?.access_token ? { Authorization: `Bearer ${_sp2.access_token}` } : {}) },
              body: JSON.stringify({
                accountEmail: acct.email,
                partnerEmail: acct.partnerEmail || '',
                toName:       acct.name || '',
                partnerName:  acct.partnerName || '',
              }),
            });
          }
        } catch (e) { console.warn('[Attune] workbook promo (partner B) failed:', e); }
      } catch (e) {
        console.warn('[Attune] partner-B results email failed:', e);
      }
    })();
  }, [partnerADone, partnerAName, partnerBName]);

  return (
    <div style={{ minHeight: '100vh', background: '#1e1a35', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '2rem 1.25rem' }}>
      <link href={FONT_LINK} rel="stylesheet" />
      <div style={{ maxWidth: 460, width: '100%', textAlign: 'center' }}>
        {partnerADone ? (
          <>
            <div style={{ width: 64, height: 64, borderRadius: '50%', background: 'linear-gradient(135deg, #10b981, #059669)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem', fontSize: '1.6rem' }}>✓</div>
            <div style={{ fontSize: '0.62rem', letterSpacing: '0.22em', textTransform: 'uppercase', color: '#10b981', fontFamily: "'DM Sans', sans-serif", fontWeight: 700, marginBottom: '0.85rem' }}>All exercises complete</div>
            <div style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: 'clamp(1.5rem, 5vw, 2.2rem)', fontWeight: 700, color: 'white', lineHeight: 1.15, marginBottom: '1.25rem' }}>
              Your results are ready.
            </div>
            <p style={{ fontSize: '0.88rem', color: 'rgba(255,255,255,0.6)', fontFamily: "'DM Sans', sans-serif", lineHeight: 1.75, marginBottom: '2rem' }}>
              Both you and {partnerAName} have completed your exercises. Your results are ready to explore on your own or together with {partnerAName}.
            </p>
            <div style={{ background: 'rgba(16,185,129,0.08)', border: '1px solid rgba(16,185,129,0.25)', borderRadius: 14, padding: '1.1rem 1.4rem', display: 'inline-flex', alignItems: 'center', gap: '0.7rem' }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#10b981" strokeWidth="2" strokeLinecap="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
              <span style={{ fontSize: '0.75rem', color: 'rgba(255,255,255,0.55)', fontFamily: "'DM Sans', sans-serif", lineHeight: 1.5 }}>Results sync automatically when you connect your accounts</span>
            </div>
          </>
        ) : (
          <>
            <div style={{ width: 64, height: 64, borderRadius: '50%', background: 'linear-gradient(135deg, #E8673A33, #1B5FE833)', border: '2px solid rgba(232,103,58,0.3)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem', fontSize: '1.8rem' }}>✦</div>
            <div style={{ fontSize: '0.62rem', letterSpacing: '0.22em', textTransform: 'uppercase', color: 'rgba(232,103,58,0.8)', fontFamily: "'DM Sans', sans-serif", fontWeight: 700, marginBottom: '0.85rem' }}>Your exercises are done</div>
            <div style={{ fontFamily: "'Playfair Display', Georgia, serif", fontSize: 'clamp(1.5rem, 5vw, 2.2rem)', fontWeight: 700, color: 'white', lineHeight: 1.15, marginBottom: '1.25rem' }}>
              Waiting for {partnerAName}.
            </div>
            <p style={{ fontSize: '0.88rem', color: 'rgba(255,255,255,0.6)', fontFamily: "'DM Sans', sans-serif", lineHeight: 1.75, marginBottom: '2rem' }}>
              Your answers have been saved. Results will unlock as soon as {partnerAName} finishes {pronoun(partnerAPronouns, "pos")} exercises. You'll both see everything at the same time.
            </p>
            <div style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 14, padding: '1rem 1.4rem', textAlign: 'left' }}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                {[{ label: partnerBName + "'s exercises", done: true }, { label: partnerAName + "'s exercises", done: false }].map((s, i) => (
                  <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '0.65rem' }}>
                    <div style={{ width: 20, height: 20, borderRadius: '50%', background: s.done ? '#10b981' : 'rgba(255,255,255,0.08)', border: `1.5px solid ${s.done ? '#10b981' : 'rgba(255,255,255,0.2)'}`, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                      {s.done ? <span style={{ color: 'white', fontSize: '0.6rem', fontWeight: 700 }}>✓</span> : <span style={{ color: 'rgba(255,255,255,0.3)', fontSize: '0.62rem' }}>{i + 1}</span>}
                    </div>
                    <span style={{ fontSize: '0.8rem', color: s.done ? 'white' : 'rgba(255,255,255,0.35)', fontFamily: "'DM Sans', sans-serif", fontWeight: s.done ? 600 : 400 }}>{s.label}</span>
                    {s.done && <span style={{ fontSize: '0.65rem', color: '#10b981', fontFamily: "'DM Sans', sans-serif", marginLeft: 'auto' }}>Complete</span>}
                    {!s.done && <span style={{ fontSize: '0.65rem', color: 'rgba(255,255,255,0.25)', fontFamily: "'DM Sans', sans-serif", marginLeft: 'auto' }}>Pending</span>}
                  </div>
                ))}
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}





// ─────────────────────────────────────────────────────────────────────────────
// UPSELL MODAL — shown when users click workbook/reflection cards post-exercise
// ─────────────────────────────────────────────────────────────────────────────
// The add-on query params public/checkout.html actually reads. Anything not on
// this list is silently ignored there: the customer pays the package price and
// never receives the add-on they clicked. UPSELL_PRODUCTS used to carry a
// separate cartParam field with different values ("anniversary" for reflection,
// "newlywed" for checklist), which was unused but sat there looking like the
// field the URL should be built from. Removed, and replaced with this check.
const CHECKOUT_ADDON_PARAMS = ["workbook", "reflection", "budget", "intimacy", "checklist", "conflict"];
function checkoutUrlForAddon(pkg, addon) {
  if (!CHECKOUT_ADDON_PARAMS.includes(addon)) {
    // Loud in development, and never sends a URL that would quietly drop the
    // add-on. Falls back to the plain package checkout.
    console.error(`[Attune] "${addon}" is not an add-on param checkout accepts (${CHECKOUT_ADDON_PARAMS.join(", ")}). Sending package-only checkout instead.`);
    return `/checkout?pkg=${pkg}`;
  }
  return `/checkout?pkg=${pkg}&addon_${addon}=1`;
}

